: _EXT4-CTX  ( vfs -- ctx )  V.BCTX @ ;
: _EXT4-READY?  ( vfs -- flag )
    V.BCTX @ DUP 0= IF DROP FALSE EXIT THEN
    _EXT4-C.READY + @ 0<> ;

\ =====================================================================
\  Checked hardware CRC32C adapter
\ =====================================================================

VARIABLE _EXT4-CRC-STATE

: _EXT4-CRC-START  ( seed -- )  0xFFFFFFFF AND _EXT4-CRC-STATE ! ;

: _EXT4-CRC-STATUS>IOR  ( status -- ior )
    DUP 1 = IF
        DROP 1 0 VFS-IOR-D-BINDING VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    DUP 2 = IF
        DROP 2 VFS-IOR-F-RETRYABLE VFS-IOR-D-BINDING VFS-R-BUSY
        VFS-IOR-MAKE EXIT
    THEN
    DUP IF 0 VFS-IOR-D-BINDING VFS-R-IO VFS-IOR-MAKE THEN ;

: _EXT4-CRC-CAPABILITY  ( -- ior )
    CRYPTO-CAPS@ 1 AND IF 0 ELSE 1 _EXT4-CRC-STATUS>IOR THEN ;

: _EXT4-CRC-ADD  ( addr len -- ior )
    _EXT4-CRC-STATE @ -ROT CRC32C-RAW?
    DUP IF NIP _EXT4-CRC-STATUS>IOR EXIT THEN
    DROP 0xFFFFFFFF AND _EXT4-CRC-STATE ! 0 ;
: _EXT4-CRC@  ( -- crc )  _EXT4-CRC-STATE @ ;

\ =====================================================================
\  Structured checked volume I/O
\ =====================================================================

VARIABLE _EXT4-IO-VFS
VARIABLE _EXT4-IO-VOL
VARIABLE _EXT4-IO-EXPECTED
VARIABLE _EXT4-IO-COMPLETED
VARIABLE _EXT4-IO-BACKEND
VARIABLE _EXT4-IO-FLAGS
VARIABLE _EXT4-IO-REASON

: _EXT4-LATCH-STALE  ( -- )
    _EXT4-IO-VFS @ ?DUP IF VFS-L-STALE SWAP V.LIFECYCLE ! THEN ;

: _EXT4-MAP-IOR  ( backend-ior -- vfs-ior )
    DUP _EXT4-IO-BACKEND !
    0 _EXT4-IO-FLAGS !
    VFS-R-IO _EXT4-IO-REASON !
    DUP IF
        DUP IOR>FLAGS
        DUP IOR-F-RETRYABLE AND IF
            VFS-IOR-F-RETRYABLE _EXT4-IO-FLAGS +!
        THEN
        DUP IOR-F-PARTIAL AND IF
            VFS-IOR-F-PARTIAL _EXT4-IO-FLAGS +!
        THEN
        DUP IOR-F-CORRUPT AND IF
            VFS-IOR-F-CORRUPT _EXT4-IO-FLAGS +!
            VFS-R-CORRUPT _EXT4-IO-REASON !
        THEN
        DUP IOR-F-UNSUPPORTED AND IF
            VFS-R-UNSUPPORTED _EXT4-IO-REASON !
        THEN
        DUP IOR-F-READONLY AND IF
            VFS-IOR-F-READONLY _EXT4-IO-FLAGS +!
            VFS-R-READONLY _EXT4-IO-REASON !
        THEN
        IOR-F-STALE AND IF
            VFS-IOR-F-STALE _EXT4-IO-FLAGS +!
            VFS-R-STALE _EXT4-IO-REASON !
            _EXT4-LATCH-STALE
        THEN
    THEN
    _EXT4-IO-COMPLETED @ _EXT4-IO-EXPECTED @ <> IF
        VFS-IOR-F-PARTIAL _EXT4-IO-FLAGS DUP @ ROT OR SWAP !
    THEN
    _EXT4-IO-BACKEND @ 0=
    _EXT4-IO-COMPLETED @ _EXT4-IO-EXPECTED @ = AND IF
        DROP 0 EXIT
    THEN
    DROP
    _EXT4-IO-BACKEND @ 0xFFFFFFFF AND
    _EXT4-IO-FLAGS @ VFS-IOR-D-VOLUME _EXT4-IO-REASON @ VFS-IOR-MAKE ;

: _EXT4-READ-SECTORS  ( dma lba count -- ior )
    DUP _EXT4-IO-EXPECTED !
    _EXT4-IO-VOL @ VOL-READ
    SWAP _EXT4-IO-COMPLETED ! _EXT4-MAP-IOR ;

: _EXT4-WRITE-SECTORS  ( dma lba count -- ior )
    DUP _EXT4-IO-EXPECTED !
    _EXT4-IO-VOL @ VOL-WRITE
    SWAP _EXT4-IO-COMPLETED ! _EXT4-MAP-IOR ;

: _EXT4-FLUSH  ( -- ior )
    0 _EXT4-IO-EXPECTED ! 0 _EXT4-IO-COMPLETED !
    _EXT4-IO-VOL @ VOL-FLUSH _EXT4-MAP-IOR ;

: _EXT4-CORRUPT  ( detail -- ior )
    VFS-IOR-F-CORRUPT VFS-IOR-D-FORMAT VFS-R-CORRUPT VFS-IOR-MAKE ;
: _EXT4-UNSUPPORTED  ( detail -- ior )
    0 VFS-IOR-D-FORMAT VFS-R-UNSUPPORTED VFS-IOR-MAKE ;
: _EXT4-READONLY  ( detail -- ior )
    VFS-IOR-F-READONLY VFS-IOR-D-FORMAT VFS-R-READONLY VFS-IOR-MAKE ;

\ =====================================================================
\  Probe
\ =====================================================================

90 CONSTANT EXT4-PROBE-SCORE
CREATE _EXT4-PROBE-BUF _EXT4-SB-SIZE ALLOT
VARIABLE _EXT4-PROBE-VOL

: _EXT4-PROBE  ( volume -- score ior )
    _EXT4-PROBE-VOL !
    _EXT4-CRC-CAPABILITY ?DUP IF 0 SWAP EXIT THEN
    _EXT4-PROBE-VOL @ VOL.SECTOR-SIZE _EXT4-SECTOR <> IF
        0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    0 _EXT4-IO-VFS !
    _EXT4-PROBE-VOL @ _EXT4-IO-VOL !
    _EXT4-PROBE-BUF 2 2 _EXT4-READ-SECTORS
    DUP IF 0 SWAP EXIT THEN DROP
    _EXT4-PROBE-BUF _EXT4-SB.MAGIC + W@ _EXT4-MAGIC = IF
        EXT4-PROBE-SCORE
    ELSE
        0
    THEN 0 ;

\ =====================================================================
\  Generic validation helpers
\ =====================================================================

VARIABLE _EXT4-RB-BLOCK
VARIABLE _EXT4-RB-CTX

: _EXT4-READ-BLOCK  ( block ctx -- ior )
    _EXT4-RB-CTX ! _EXT4-RB-BLOCK !
    _EXT4-RB-BLOCK @ _EXT4-RB-CTX @ _EXT4-C.BLOCKS + @ >= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RB-BLOCK @ _EXT4-RB-CTX @ _EXT4-C.SPB + @ *
    _EXT4-RB-CTX @ _EXT4-C.BLOCK + SWAP
    _EXT4-RB-CTX @ _EXT4-C.SPB + @ _EXT4-READ-SECTORS ;

VARIABLE _EXT4-WB-BUFFER
VARIABLE _EXT4-WB-BLOCK
VARIABLE _EXT4-WB-CTX

: _EXT4-WRITE-BLOCK  ( buffer block ctx -- ior )
    _EXT4-WB-CTX ! _EXT4-WB-BLOCK ! _EXT4-WB-BUFFER !
    \ A caller may use these counters as the certificate for this exact
    \ block attempt.  Clear stale evidence even when validation refuses the
    \ request before VOL-WRITE is dispatched.
    0 _EXT4-IO-EXPECTED ! 0 _EXT4-IO-COMPLETED !
    _EXT4-WB-BLOCK @ _EXT4-WB-CTX @ _EXT4-C.BLOCKS + @ >= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-WB-BLOCK @ _EXT4-WB-CTX @ _EXT4-C.SPB + @ *
    _EXT4-WB-BUFFER @ SWAP
    _EXT4-WB-CTX @ _EXT4-C.SPB + @ _EXT4-WRITE-SECTORS ;

: _EXT4-BYTES=?  ( a b len -- flag )
    0 ?DO
        2DUP I + C@ SWAP I + C@ <> IF 2DROP FALSE UNLOOP EXIT THEN
    LOOP 2DROP TRUE ;

: _EXT4-BYTES-ZERO?  ( a len -- flag )
    0 ?DO
        DUP I + C@ IF DROP FALSE UNLOOP EXIT THEN
    LOOP DROP TRUE ;

VARIABLE _EXT4-PO-N
VARIABLE _EXT4-PO-B
: _EXT4-POWER-OF?  ( n base -- flag )
    _EXT4-PO-B ! _EXT4-PO-N !
    BEGIN _EXT4-PO-N @ 1 > WHILE
        _EXT4-PO-N @ _EXT4-PO-B @ MOD IF FALSE EXIT THEN
        _EXT4-PO-N @ _EXT4-PO-B @ / _EXT4-PO-N !
    REPEAT
    _EXT4-PO-N @ 1 = ;

: _EXT4-SPARSE-GROUP?  ( group -- flag )
    DUP 0= OVER 1 = OR IF DROP TRUE EXIT THEN
    DUP 3 _EXT4-POWER-OF? IF DROP TRUE EXIT THEN
    DUP 5 _EXT4-POWER-OF? IF DROP TRUE EXIT THEN
    7 _EXT4-POWER-OF? ;

VARIABLE _EXT4-ATT-V
: _EXT4-ATTACHED?  ( vfs -- flag )
    DUP _EXT4-ATT-V ! V.VOLUME @
    DUP 0= IF DROP FALSE EXIT THEN
    DUP VOL-VALID? 0= IF DROP FALSE EXIT THEN
    DUP VOL-STALE? IF DROP FALSE EXIT THEN
    DUP VOL.COOKIE _EXT4-ATT-V @ V.VOL-COOKIE @ =
    SWAP VOL.MEDIA-GEN _EXT4-ATT-V @ V.MEDIA-GEN @ = AND ;

\ =====================================================================
\  Superblock validation and geometry admission
\ =====================================================================

VARIABLE _EXT4-SV-CTX
VARIABLE _EXT4-SV-SB
VARIABLE _EXT4-SV-STORED
VARIABLE _EXT4-SV-LOG
VARIABLE _EXT4-SV-RO
VARIABLE _EXT4-SV-GROUPS
VARIABLE _EXT4-SV-INCOMPAT
VARIABLE _EXT4-SI-SB
VARIABLE _EXT4-SI-INCOMPAT
VARIABLE _EXT4-SI-RO
VARIABLE _EXT4-SI-STATE
VARIABLE _EXT4-SI-STORED
VARIABLE _EXT4-SI-CALC

: _EXT4-STAMP-SUPER-CHECKSUM  ( sb -- ior )
    DUP _EXT4-SB.CHECKSUM + 0 SWAP L!
    0xFFFFFFFF _EXT4-CRC-START
    DUP _EXT4-SB.CHECKSUM _EXT4-CRC-ADD ?DUP IF NIP EXIT THEN
    _EXT4-CRC@ SWAP _EXT4-SB.CHECKSUM + L! 0 ;

: _EXT4-PREPARE-CLEAN-SUPER  ( sb -- ior )
    DUP _EXT4-SB.INCOMPAT + DUP L@
    _EXT4-INCOMPAT-RECOVER INVERT AND SWAP L!
    1 OVER _EXT4-SB.STATE + W!
    _EXT4-STAMP-SUPER-CHECKSUM ;

\ The completed recovery endpoint additionally retires the modern-orphan
\ authority bit.  Keep this distinct from PREPARE-CLEAN-SUPER: AKW1 activation
\ must authenticate the exact old clean image, including ORPHAN_PRESENT.
: _EXT4-PREPARE-RECOVERED-SUPER  ( sb -- ior )
    DUP _EXT4-PREPARE-CLEAN-SUPER ?DUP IF NIP EXIT THEN
    DUP _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT INVERT AND SWAP L!
    _EXT4-STAMP-SUPER-CHECKSUM ;

: _EXT4-PREPARE-DIRTY-SUPER  ( sb -- ior )
    DUP _EXT4-SB.INCOMPAT + DUP L@
    _EXT4-INCOMPAT-RECOVER OR SWAP L!
    1 OVER _EXT4-SB.STATE + W!
    _EXT4-STAMP-SUPER-CHECKSUM ;

: _EXT4-SUPER-CHECKSUM?  ( sb -- flag ior )
    DUP _EXT4-SB.CHECKSUM + L@ _EXT4-SV-STORED !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-SB.CHECKSUM _EXT4-CRC-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ _EXT4-SV-STORED @ = 0 ;

: _EXT4-SUPER-SEED?  ( sb -- flag ior )
    DUP _EXT4-SB.CSUM-SEED + L@ >R
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-SB.UUID + 16 _EXT4-CRC-ADD ?DUP IF
        R> DROP 0 SWAP EXIT
    THEN
    _EXT4-CRC@ R> = 0 ;

\ Return the checksum of the intended post-recovery primary superblock while
\ restoring every temporarily changed byte.  A durable journal anchor records
\ this value before RECOVER can be cleared across its two-sector write.
: _EXT4-INTENDED-SUPER-CHECKSUM  ( sb -- crc ior )
    DUP _EXT4-SI-SB !
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-SI-INCOMPAT !
    DUP _EXT4-SB.STATE + W@ _EXT4-SI-STATE !
    _EXT4-SB.CHECKSUM + L@ _EXT4-SI-STORED !
    _EXT4-SI-SB @ _EXT4-PREPARE-CLEAN-SUPER
    DUP IF
        _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
        _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
        _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
        0 SWAP EXIT
    THEN DROP
    _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L@ _EXT4-SI-CALC !
    _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
    _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
    _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
    _EXT4-SI-CALC @ 0 ;

: _EXT4-INTENDED-RECOVERED-SUPER-CHECKSUM  ( sb -- crc ior )
    DUP _EXT4-SI-SB !
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-SI-INCOMPAT !
    DUP _EXT4-SB.RO-COMPAT + L@ _EXT4-SI-RO !
    DUP _EXT4-SB.STATE + W@ _EXT4-SI-STATE !
    _EXT4-SB.CHECKSUM + L@ _EXT4-SI-STORED !
    _EXT4-SI-SB @ _EXT4-PREPARE-RECOVERED-SUPER
    DUP IF
        _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
        _EXT4-SI-RO @ _EXT4-SI-SB @ _EXT4-SB.RO-COMPAT + L!
        _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
        _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
        0 SWAP EXIT
    THEN DROP
    _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L@ _EXT4-SI-CALC !
    _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
    _EXT4-SI-RO @ _EXT4-SI-SB @ _EXT4-SB.RO-COMPAT + L!
    _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
    _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
    _EXT4-SI-CALC @ 0 ;

: _EXT4-INTENDED-DIRTY-SUPER-CHECKSUM  ( sb -- crc ior )
    DUP _EXT4-SI-SB !
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-SI-INCOMPAT !
    DUP _EXT4-SB.STATE + W@ _EXT4-SI-STATE !
    _EXT4-SB.CHECKSUM + L@ _EXT4-SI-STORED !
    _EXT4-SI-SB @ _EXT4-PREPARE-DIRTY-SUPER
    DUP IF
        _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
        _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
        _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
        0 SWAP EXIT
    THEN DROP
    _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L@ _EXT4-SI-CALC !
    _EXT4-SI-INCOMPAT @ _EXT4-SI-SB @ _EXT4-SB.INCOMPAT + L!
    _EXT4-SI-STATE @ _EXT4-SI-SB @ _EXT4-SB.STATE + W!
    _EXT4-SI-STORED @ _EXT4-SI-SB @ _EXT4-SB.CHECKSUM + L!
    _EXT4-SI-CALC @ 0 ;

VARIABLE _EXT4-SRP-SB
VARIABLE _EXT4-SRP-RECOVERY

\ These fields must let the next mount reach the redundant recovery witness.
\ Keep the ordinary mount and replay-candidate gates on one predicate path.
: _EXT4-VALIDATE-SUPER-RETRY-EARLY  ( sb recovery -- ior )
    _EXT4-SRP-RECOVERY ! _EXT4-SRP-SB !
    _EXT4-SRP-SB @ _EXT4-SB.STATE + W@ DUP 1 INVERT AND IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    1 <> _EXT4-SRP-RECOVERY @ 0= AND IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SRP-SB @ _EXT4-SB.ERRORS + W@ 2 <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-VALIDATE-SUPER-RETRY-LATE  ( sb -- ior )
    _EXT4-SRP-SB !
    _EXT4-SRP-SB @ _EXT4-SB.INODE-SIZE + W@ 256 = IF
        _EXT4-SRP-SB @ _EXT4-SB.MIN-EXTRA + W@ 32 <
        _EXT4-SRP-SB @ _EXT4-SB.WANT-EXTRA + W@ 32 < OR IF
            EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-SRP-SB @ _EXT4-SB.LOG-FLEX + C@ 4 <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SRP-SB @ _EXT4-SB.FIRST-INO + L@ 11 < IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-SCB-SB
VARIABLE _EXT4-SCB-CTX

\ A checksum-valid image cannot use the prefix-tear exception for counters.
: _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS  ( sb ctx -- ior )
    _EXT4-SCB-CTX ! _EXT4-SCB-SB !
    _EXT4-SCB-SB @ _EXT4-SB.RBLOCKS-HI + L@
    _EXT4-SCB-SB @ _EXT4-SB.FREE-BLOCKS-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SCB-SB @ _EXT4-SB.RBLOCKS-LO + L@
    _EXT4-SCB-CTX @ _EXT4-C.BLOCKS + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SCB-SB @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-SCB-CTX @ _EXT4-C.BLOCKS + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SCB-SB @ _EXT4-SB.FREE-INODES + L@
    _EXT4-SCB-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-VALIDATE-SUPER  ( ctx vfs -- ior )
    DROP _EXT4-SV-CTX !
    _EXT4-SV-CTX @ _EXT4-C.SB + _EXT4-SV-SB !
    0 _EXT4-SV-CTX @ _EXT4-C.RECOVERY + !
    0 _EXT4-SV-CTX @ _EXT4-C.SUPER-TORN + !
    _EXT4-SV-SB @ _EXT4-SB.MAGIC + W@ _EXT4-MAGIC <> IF
        EXT4-D-MAGIC _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        -1 _EXT4-SV-CTX @ _EXT4-C.SUPER-TORN + !
    THEN
    _EXT4-SV-SB @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.REVISION + L@ 1 <
    _EXT4-SV-SB @ _EXT4-SB.CREATOR + L@ 0<> OR IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.COMPAT + L@ _EXT4-COMPAT-V1 <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.INCOMPAT + L@ DUP _EXT4-SV-INCOMPAT !
    _EXT4-INCOMPAT-RECOVER AND IF
        -1 _EXT4-SV-CTX @ _EXT4-C.RECOVERY + !
    THEN
    _EXT4-SV-INCOMPAT @ _EXT4-INCOMPAT-RECOVER INVERT AND
    _EXT4-INCOMPAT-V1 <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.RO-COMPAT + L@
    DUP _EXT4-RO-REFUSED AND IF
        DROP EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-RO-READONLY _EXT4-RO-ORPHAN-PRESENT OR INVERT AND
    _EXT4-SV-RO !
    _EXT4-SV-SB @ _EXT4-SB.INODE-SIZE + W@ DUP
    128 = IF
        DROP _EXT4-SV-RO @ _EXT4-RO-I128-V1 AND
        _EXT4-RO-I128-V1 <>
    ELSE
        256 <> _EXT4-SV-RO @ _EXT4-RO-V1 AND
        _EXT4-RO-V1 <> OR
    THEN IF EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT THEN
    _EXT4-SV-SB @ _EXT4-SV-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-VALIDATE-SUPER-RETRY-EARLY ?DUP IF EXIT THEN
    _EXT4-SV-SB @ _EXT4-SB.LOG-BLOCK + L@ DUP _EXT4-SV-LOG ! 2 > IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.LOG-CLUSTER + L@ _EXT4-SV-LOG @ <> IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    1024 _EXT4-SV-LOG @ LSHIFT DUP
    _EXT4-SV-CTX @ _EXT4-C.BSIZE + !
    512 / _EXT4-SV-CTX @ _EXT4-C.SPB + !
    _EXT4-SV-SB @ _EXT4-SB.BLOCKS-HI + L@ 0<> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.BLOCKS-LO + L@
    _EXT4-SV-CTX @ _EXT4-C.BLOCKS + !
    _EXT4-SV-SB @ _EXT4-SB.FIRST-DATA + L@ DUP
    _EXT4-SV-CTX @ _EXT4-C.FIRST + !
    _EXT4-SV-LOG @ 0= IF 1 <> ELSE 0<> THEN IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-CTX @ _EXT4-C.BLOCKS + @
    _EXT4-SV-CTX @ _EXT4-C.FIRST + @ <= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-CTX @ _EXT4-C.BLOCKS + @
    _EXT4-SV-CTX @ _EXT4-C.SPB + @ *
    _EXT4-IO-VOL @ VOL.SECTORS U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.BPG + L@ DUP
    _EXT4-SV-CTX @ _EXT4-C.BPG + !
    _EXT4-SV-CTX @ _EXT4-C.BSIZE + @ 8 * <> IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.CPG + L@
    _EXT4-SV-CTX @ _EXT4-C.BPG + @ <> IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.IPG + L@ DUP
    _EXT4-SV-CTX @ _EXT4-C.IPG + !
    _EXT4-SV-CTX @ _EXT4-C.BPG + @
    _EXT4-SV-CTX @ _EXT4-C.BSIZE + @ * 16384 / <> IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SV-CTX @ _EXT4-C.BLOCKS + @
    _EXT4-SV-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-SV-CTX @ _EXT4-C.BPG + @ 1- +
    _EXT4-SV-CTX @ _EXT4-C.BPG + @ /
    DUP _EXT4-SV-GROUPS ! _EXT4-SV-CTX @ _EXT4-C.GROUPS + !
    _EXT4-SV-GROUPS @ 0= IF EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    _EXT4-SV-SB @ _EXT4-SB.INODES + L@ DUP
    _EXT4-SV-CTX @ _EXT4-C.INODES + !
    _EXT4-SV-GROUPS @ _EXT4-SV-CTX @ _EXT4-C.IPG + @ * <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.INODE-SIZE + W@
    _EXT4-SV-CTX @ _EXT4-C.ISIZE + !
    _EXT4-SV-SB @ _EXT4-SB.DESC-SIZE + W@ DUP
    _EXT4-SV-CTX @ _EXT4-C.DSIZE + !
    _EXT4-DESC-SIZE <> IF EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    _EXT4-SV-SB @ _EXT4-VALIDATE-SUPER-RETRY-LATE ?DUP IF EXIT THEN
    _EXT4-SV-SB @ _EXT4-SB.CSUM-TYPE + C@ 1 <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.JOURNAL-INO + L@ 8 <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.ORPHAN-INO + L@ DUP
    _EXT4-SV-CTX @ _EXT4-C.ORPHAN-INO + !
    DUP 0= SWAP _EXT4-SV-CTX @ _EXT4-C.INODES + @ > OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SV-SB @ _EXT4-SB.RBLOCKS-LO + L@
    _EXT4-SV-CTX @ _EXT4-C.RESERVED-BLOCKS + !
    _EXT4-SV-SB @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-SV-CTX @ _EXT4-C.FREE-BLOCKS + !
    _EXT4-SV-SB @ _EXT4-SB.FREE-INODES + L@
    _EXT4-SV-CTX @ _EXT4-C.FREE-INODES + !
    \ Prefixes of two checksum-valid home-super candidates can transiently
    \ mix mutable counters.  Their bounds become authoritative only after
    \ replay and strict checksum validation; immutable geometry is witnessed
    \ independently by sparse group 1 before any journal read.
    _EXT4-SV-CTX @ _EXT4-C.SUPER-TORN + @ 0= IF
        _EXT4-SV-SB @ _EXT4-SV-CTX @
        _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS ?DUP IF EXIT THEN
    THEN
    _EXT4-SV-SB @ _EXT4-SB.CSUM-SEED + L@
    _EXT4-SV-CTX @ _EXT4-C.SEED + !
    _EXT4-SV-SB @ _EXT4-SB.UUID + @
    _EXT4-SV-CTX @ _EXT4-C.UUID-LO + !
    _EXT4-SV-SB @ _EXT4-SB.UUID 8 + + @
    _EXT4-SV-CTX @ _EXT4-C.UUID-HI + !
    0 ;

\ =====================================================================
\  Group descriptors and initialized bitmap checksums
\ =====================================================================

VARIABLE _EXT4-GD-GROUP
VARIABLE _EXT4-GD-BASE
VARIABLE _EXT4-GD-CTX
VARIABLE _EXT4-GD-BYTE
VARIABLE _EXT4-GD-BLOCK
VARIABLE _EXT4-GD-OFF
VARIABLE _EXT4-GD-STORED
VARIABLE _EXT4-GD-FLAGS
VARIABLE _EXT4-GD-PTR
VARIABLE _EXT4-GD-SPAN

: _EXT4-GDT-BASE  ( ctx -- block )
    _EXT4-C.BSIZE + @ 1024 = IF 2 ELSE 1 THEN ;

: _EXT4-LOAD-DESC-AT  ( group gdt-base ctx -- ior )
    _EXT4-GD-CTX ! _EXT4-GD-BASE ! _EXT4-GD-GROUP !
    _EXT4-GD-GROUP @ _EXT4-GD-CTX @ _EXT4-C.GROUPS + @ >= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-GROUP @ _EXT4-DESC-SIZE * _EXT4-GD-BYTE !
    _EXT4-GD-BASE @
    _EXT4-GD-BYTE @ _EXT4-GD-CTX @ _EXT4-C.BSIZE + @ / +
    DUP _EXT4-GD-BLOCK ! _EXT4-GD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-GD-BYTE @ _EXT4-GD-CTX @ _EXT4-C.BSIZE + @ MOD
    DUP _EXT4-GD-OFF ! _EXT4-DESC-SIZE +
    _EXT4-GD-CTX @ _EXT4-C.BSIZE + @ > IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-CTX @ _EXT4-C.BLOCK + _EXT4-GD-OFF @ +
    _EXT4-GD-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE CMOVE
    _EXT4-GD-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.CHECKSUM + W@ _EXT4-GD-STORED !
    0 SWAP _EXT4-GD.CHECKSUM + W!
    _EXT4-GD-GROUP @ _EXT4-GD-CTX @ _EXT4-C.TMP + L!
    _EXT4-GD-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-GD-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF
        _EXT4-GD-STORED @ _EXT4-GD-CTX @ _EXT4-C.DESC +
        _EXT4-GD.CHECKSUM + W! EXIT
    THEN
    _EXT4-GD-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE _EXT4-CRC-ADD
    ?DUP IF
        _EXT4-GD-STORED @ _EXT4-GD-CTX @ _EXT4-C.DESC +
        _EXT4-GD.CHECKSUM + W! EXIT
    THEN
    _EXT4-GD-STORED @ _EXT4-GD-CTX @ _EXT4-C.DESC +
    _EXT4-GD.CHECKSUM + W!
    _EXT4-CRC@ 0xFFFF AND _EXT4-GD-STORED @ <> IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.BLOCK-BITMAP-HI + L@ 0<>
    OVER _EXT4-GD.INODE-BITMAP-HI + L@ 0<> OR
    OVER _EXT4-GD.INODE-TABLE-HI + L@ 0<> OR IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.BLOCK-BITMAP-LO + L@ DUP _EXT4-GD-PTR !
    0= _EXT4-GD-PTR @ _EXT4-GD-CTX @ _EXT4-C.BLOCKS + @ >= OR IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.INODE-BITMAP-LO + L@ DUP _EXT4-GD-PTR !
    0= _EXT4-GD-PTR @ _EXT4-GD-CTX @ _EXT4-C.BLOCKS + @ >= OR IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.INODE-TABLE-LO + L@ DUP _EXT4-GD-PTR !
    0= IF DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-GD-CTX @ _EXT4-C.IPG + @
    _EXT4-GD-CTX @ _EXT4-C.ISIZE + @ *
    _EXT4-GD-CTX @ _EXT4-C.BSIZE + @ 1- +
    _EXT4-GD-CTX @ _EXT4-C.BSIZE + @ /
    DUP _EXT4-GD-SPAN !
    _EXT4-GD-PTR @ SWAP
    _EXT4-GD-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.FLAGS + W@ DUP _EXT4-GD-FLAGS ! 7 INVERT AND IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.FREE-BLOCKS-LO + W@
    OVER _EXT4-GD.FREE-BLOCKS-HI + W@ 16 LSHIFT OR
    _EXT4-GD-CTX @ _EXT4-C.BPG + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.FREE-INODES-LO + W@
    OVER _EXT4-GD.FREE-INODES-HI + W@ 16 LSHIFT OR
    _EXT4-GD-CTX @ _EXT4-C.IPG + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.USED-DIRS-LO + W@
    SWAP _EXT4-GD.USED-DIRS-HI + W@ 16 LSHIFT OR
    _EXT4-GD-CTX @ _EXT4-C.IPG + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-LOAD-DESC  ( group ctx -- ior )
    DUP _EXT4-GDT-BASE SWAP _EXT4-LOAD-DESC-AT ;

\ A format checksum proves that a bitmap was not silently altered; it does
\ not prove that a block referenced by an inode or metadata pointer is marked
\ allocated.  Keep that ownership check explicit and reusable by every map.
\ A resident extent root has four format-defined entry slots, used either as
\ depth-zero extents or as child indexes.  A legacy inode has twelve direct
\ slots plus block-size-derived indirect fanout.  Transaction and owner
\ authority use the larger admitted extent-tree geometry as their shared bound.
4 CONSTANT _EXT4-RESIDENT-EXTENT-ENTRY-MAX
_EXT4-NDIRECT CONSTANT _EXT4-LEGACY-DIRECT-RANGE-MAX
VARIABLE _EXT4-MUTATION-OWNER-RANGES
VARIABLE _EXT4-MUTATION-OWNER-RANGE-CAP
VARIABLE _EXT4-MUTATION-OWNER-RANGE-COUNT
VARIABLE _EXT4-MUTATION-OWNER-BOUND-FIRST
VARIABLE _EXT4-MUTATION-OWNER-BOUND-LIMIT
VARIABLE _EXT4-MUTATION-OWNER-INO
VARIABLE _EXT4-MUTATION-PROTOCOL-CTX
VARIABLE _EXT4-MUTATION-PROTOCOL-ACTIVE
VARIABLE _EXT4-MUTATION-PROTOCOL-XT
VARIABLE _EXT4-MUTATION-PROTOCOL-PROOF-XT
VARIABLE _EXT4-MUTATION-EA-REF-ACTIVE
VARIABLE _EXT4-MUTATION-EA-REF-HOME
VARIABLE _EXT4-MUTATION-EA-REF-HITS
VARIABLE _EXT4-MOA-FIRST
VARIABLE _EXT4-MOA-COUNT
VARIABLE _EXT4-MOB-COUNT
VARIABLE _EXT4-MOB-INDEX
VARIABLE _EXT4-MOB-FIRST
VARIABLE _EXT4-MOB-LIMIT
VARIABLE _EXT4-MOB-NEXT-FIRST

VARIABLE _EXT4-BRO-A
VARIABLE _EXT4-BRO-ACOUNT
VARIABLE _EXT4-BRO-B
VARIABLE _EXT4-BRO-BCOUNT

: _EXT4-BLOCK-RANGES-OVERLAP?
  ( first-a count-a first-b count-b -- flag )
    _EXT4-BRO-BCOUNT ! _EXT4-BRO-B !
    _EXT4-BRO-ACOUNT ! _EXT4-BRO-A !
    _EXT4-BRO-ACOUNT @ 0= _EXT4-BRO-BCOUNT @ 0= OR IF FALSE EXIT THEN
    _EXT4-BRO-A @ _EXT4-BRO-B @ _EXT4-BRO-BCOUNT @ + U<
    _EXT4-BRO-B @ _EXT4-BRO-A @ _EXT4-BRO-ACOUNT @ + U< AND ;

: _EXT4-MUTATION-OWNER-RANGE  ( index -- pair-address )
    2 * CELLS _EXT4-MUTATION-OWNER-RANGES @ + ;

: _EXT4-MUTATION-OWNER-RANGES-CLEAR  ( -- )
    0 _EXT4-MUTATION-OWNER-RANGE-COUNT !
    0 _EXT4-MUTATION-OWNER-BOUND-FIRST !
    0 _EXT4-MUTATION-OWNER-BOUND-LIMIT !
    0 _EXT4-MUTATION-OWNER-RANGE-CAP !
    0 _EXT4-MUTATION-OWNER-RANGES ! ;

: _EXT4-MUTATION-OWNER-RANGES-BUSY?  ( -- flag )
    _EXT4-MUTATION-OWNER-RANGES @
    _EXT4-MUTATION-OWNER-RANGE-CAP @ OR
    _EXT4-MUTATION-OWNER-RANGE-COUNT @ OR
    _EXT4-MUTATION-OWNER-BOUND-FIRST @ OR
    _EXT4-MUTATION-OWNER-BOUND-LIMIT @ OR 0<> ;

\ Publish a fail-closed envelope around an already validated exact range
\ vector.  The count is the final publication word.  Candidate map ranges
\ outside this envelope cannot overlap any member; candidates inside it still
\ take the exact pairwise path below.  All admitted ext4 block numbers and
\ lengths fit in one cell, but retain an unsigned wrap check here so malformed
\ internal publication cannot weaken the owner proof.
: _EXT4-MUTATION-OWNER-RANGES-PUBLISH  ( ranges count capacity -- ior )
    _EXT4-MUTATION-OWNER-RANGE-CAP !
    _EXT4-MOB-COUNT ! _EXT4-MUTATION-OWNER-RANGES !
    _EXT4-MUTATION-OWNER-RANGES @ 0=
    _EXT4-MOB-COUNT @ DUP 0= SWAP 0< OR OR
    _EXT4-MUTATION-OWNER-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-MOB-COUNT @ _EXT4-MUTATION-OWNER-RANGE-CAP @ U> OR IF
        _EXT4-MUTATION-OWNER-RANGES-CLEAR
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-MUTATION-OWNER-RANGE DUP @ DUP _EXT4-MOB-FIRST !
    SWAP CELL+ @ DUP 0= IF
        2DROP _EXT4-MUTATION-OWNER-RANGES-CLEAR
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    + DUP _EXT4-MOB-FIRST @ U< IF
        DROP _EXT4-MUTATION-OWNER-RANGES-CLEAR
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOB-LIMIT !
    1 _EXT4-MOB-INDEX !
    BEGIN
        _EXT4-MOB-INDEX @ _EXT4-MOB-COUNT @ U<
    WHILE
        _EXT4-MOB-INDEX @ _EXT4-MUTATION-OWNER-RANGE
        DUP @ _EXT4-MOB-NEXT-FIRST !
        CELL+ @ DUP 0= IF
            DROP _EXT4-MUTATION-OWNER-RANGES-CLEAR
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-MOB-NEXT-FIRST @ +
        DUP _EXT4-MOB-NEXT-FIRST @ U< IF
            DROP _EXT4-MUTATION-OWNER-RANGES-CLEAR
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        DUP _EXT4-MOB-LIMIT @ U> IF
            DUP _EXT4-MOB-LIMIT !
        THEN
        DROP
        _EXT4-MOB-NEXT-FIRST @ _EXT4-MOB-FIRST @ U< IF
            _EXT4-MOB-NEXT-FIRST @ _EXT4-MOB-FIRST !
        THEN
        1 _EXT4-MOB-INDEX +!
    REPEAT
    _EXT4-MOB-FIRST @ _EXT4-MUTATION-OWNER-BOUND-FIRST !
    _EXT4-MOB-LIMIT @ _EXT4-MUTATION-OWNER-BOUND-LIMIT !
    _EXT4-MOB-COUNT @ _EXT4-MUTATION-OWNER-RANGE-COUNT !
    0 ;

\ A target inode is excluded from the other-owner scan, so a scoped complete
\ map audit separately proves that every target data/node range has a safe
\ mutation role and that the selected physical block occurs exactly once as
\ data and never as map metadata.  ACTIVE is the publication word.
VARIABLE _EXT4-MUTATION-MAP-TARGET
VARIABLE _EXT4-MUTATION-MAP-ACTIVE
VARIABLE _EXT4-MUTATION-MAP-HITS
VARIABLE _EXT4-MUTATION-ROLE-XT
VARIABLE _EXT4-MMA-FIRST
VARIABLE _EXT4-MMA-COUNT

\ Normal read validation leaves both mutation-owner ranges and the protocol
\ scope empty.  A bounded mutation proof temporarily publishes them while
\ validating every other allocated inode, turning any overlapping data or
\ map-metadata reference into a corrupt cross-link refusal.  The protocol hook
\ is late-bound after the journal geometry helpers have been defined.
: _EXT4-MUTATION-PROTOCOL-ALIASES?  ( -- flag )
    _EXT4-MUTATION-PROTOCOL-ACTIVE @ 0= IF FALSE EXIT THEN
    _EXT4-MUTATION-PROTOCOL-CTX @ 0=
    _EXT4-MUTATION-PROTOCOL-XT @ 0= OR IF TRUE EXIT THEN
    _EXT4-MOA-FIRST @ _EXT4-MOA-COUNT @
    _EXT4-MUTATION-PROTOCOL-CTX @
    _EXT4-MUTATION-PROTOCOL-XT @ EXECUTE ;

: _EXT4-MUTATION-OWNER-ALIASES?  ( first count -- flag )
    _EXT4-MOA-COUNT ! _EXT4-MOA-FIRST !
    _EXT4-MUTATION-OWNER-RANGE-COUNT @ IF
        _EXT4-MUTATION-OWNER-RANGES @ 0=
        _EXT4-MUTATION-OWNER-RANGE-CAP @ DUP 0= SWAP 0< OR OR
        _EXT4-MUTATION-OWNER-RANGE-COUNT @ DUP 0<
        SWAP _EXT4-MUTATION-OWNER-RANGE-CAP @ U> OR OR IF
            TRUE EXIT
        THEN
        _EXT4-MUTATION-OWNER-BOUND-FIRST @
        _EXT4-MUTATION-OWNER-BOUND-LIMIT @ U< 0= IF TRUE EXIT THEN
        _EXT4-MOA-FIRST @ _EXT4-MUTATION-OWNER-BOUND-LIMIT @ U<
        _EXT4-MUTATION-OWNER-BOUND-FIRST @
        _EXT4-MOA-FIRST @ _EXT4-MOA-COUNT @ + U< AND IF
            _EXT4-MUTATION-OWNER-RANGE-COUNT @ 0 ?DO
                I _EXT4-MUTATION-OWNER-RANGE DUP @ SWAP CELL+ @
                DUP 0= IF 2DROP TRUE UNLOOP EXIT THEN
                _EXT4-MOA-FIRST @ _EXT4-MOA-COUNT @
                _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE UNLOOP EXIT THEN
            LOOP
        THEN
    ELSE
        _EXT4-MUTATION-OWNER-RANGES @
        _EXT4-MUTATION-OWNER-RANGE-CAP @ OR
        _EXT4-MUTATION-OWNER-BOUND-FIRST @ OR
        _EXT4-MUTATION-OWNER-BOUND-LIMIT @ OR IF TRUE EXIT THEN
    THEN
    _EXT4-MUTATION-PROTOCOL-ALIASES? ;

\ The filesystem-wide proof implementation follows the generic inode scanner.
\ Every mutating entry point reaches this fail-closed forward hook only after
\ the complete driver source has bound it.
: _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 = IF DROP 0 EXIT THEN
    _EXT4-MUTATION-PROTOCOL-PROOF-XT @ ?DUP IF
        EXECUTE
    ELSE
        DROP VFS-E-CORRUPT
    THEN ;

: _EXT4-MUTATION-MAP-ALIASES?  ( first count -- flag )
    _EXT4-MMA-COUNT ! _EXT4-MMA-FIRST !
    _EXT4-MUTATION-MAP-ACTIVE @ 0= IF FALSE EXIT THEN
    _EXT4-MUTATION-MAP-TARGET @
    _EXT4-MMA-FIRST @ _EXT4-MMA-COUNT @ + U<
    _EXT4-MMA-FIRST @
    _EXT4-MUTATION-MAP-TARGET @ 1+ U< AND ;

\ The descriptor-wide mutation-role validator is defined after the generic
\ extent parser.  Publish its XT before any JOW client can activate this hook.
: _EXT4-MUTATION-ROLE-RANGE  ( first count ctx -- ior )
    _EXT4-MUTATION-ROLE-XT @ ?DUP IF
        EXECUTE
    ELSE
        2DROP DROP VFS-E-CORRUPT
    THEN ;

VARIABLE _EXT4-BA-BLOCK
VARIABLE _EXT4-BA-CTX
VARIABLE _EXT4-BA-GROUP
VARIABLE _EXT4-BA-INDEX

: _EXT4-BLOCK-ALLOCATED?  ( physical-block ctx -- allocated? ior )
    _EXT4-BA-CTX ! DUP _EXT4-BA-BLOCK !
    DUP _EXT4-BA-CTX @ _EXT4-C.FIRST + @ U<
    SWAP _EXT4-BA-CTX @ _EXT4-C.BLOCKS + @ >= OR IF
        FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-BA-BLOCK @ _EXT4-BA-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-BA-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-BA-GROUP ! _EXT4-BA-INDEX !
    _EXT4-BA-GROUP @ _EXT4-BA-CTX @ _EXT4-LOAD-DESC
    ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF FALSE 0 EXIT THEN
    _EXT4-BA-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-BA-CTX @ _EXT4-READ-BLOCK ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-BA-CTX @ _EXT4-C.BLOCK + _EXT4-BA-INDEX @ 8 / + C@
    1 _EXT4-BA-INDEX @ 8 MOD LSHIFT AND 0<> 0 ;

VARIABLE _EXT4-RA-BLOCK
VARIABLE _EXT4-RA-DETAIL
VARIABLE _EXT4-RA-CTX

: _EXT4-REQUIRE-ALLOCATED-BLOCK  ( physical-block detail ctx -- ior )
    _EXT4-RA-CTX ! _EXT4-RA-DETAIL ! DUP _EXT4-RA-BLOCK !
    _EXT4-RA-CTX @ _EXT4-BLOCK-ALLOCATED? ?DUP IF NIP EXIT THEN
    0= IF _EXT4-RA-DETAIL @ _EXT4-CORRUPT EXIT THEN
    _EXT4-RA-BLOCK @ 1 _EXT4-MUTATION-OWNER-ALIASES? IF
        _EXT4-RA-DETAIL @ _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-RAR-FIRST
VARIABLE _EXT4-RAR-COUNT
VARIABLE _EXT4-RAR-DETAIL
VARIABLE _EXT4-RAR-CTX
VARIABLE _EXT4-RAR-CURRENT
VARIABLE _EXT4-RAR-REMAIN
VARIABLE _EXT4-RAR-GROUP
VARIABLE _EXT4-RAR-INDEX
VARIABLE _EXT4-RAR-CHUNK

: _EXT4-REQUIRE-ALLOCATED-RANGE  ( first count detail ctx -- ior )
    _EXT4-RAR-CTX ! _EXT4-RAR-DETAIL !
    _EXT4-RAR-COUNT ! _EXT4-RAR-FIRST !
    _EXT4-RAR-FIRST @ _EXT4-RAR-COUNT @
    _EXT4-RAR-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RAR-FIRST @ _EXT4-RAR-COUNT @
    _EXT4-MUTATION-OWNER-ALIASES? IF
        _EXT4-RAR-DETAIL @ _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RAR-FIRST @ _EXT4-RAR-CURRENT !
    _EXT4-RAR-COUNT @ _EXT4-RAR-REMAIN !
    BEGIN _EXT4-RAR-REMAIN @ WHILE
        _EXT4-RAR-CURRENT @ _EXT4-RAR-CTX @ _EXT4-C.FIRST + @ -
        _EXT4-RAR-CTX @ _EXT4-C.BPG + @ /MOD
        _EXT4-RAR-GROUP ! _EXT4-RAR-INDEX !
        _EXT4-RAR-GROUP @ _EXT4-RAR-CTX @ _EXT4-LOAD-DESC
        ?DUP IF EXIT THEN
        _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
            _EXT4-RAR-DETAIL @ _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RAR-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@
        _EXT4-RAR-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-RAR-CTX @ _EXT4-C.BPG + @ _EXT4-RAR-INDEX @ -
        _EXT4-RAR-REMAIN @ MIN _EXT4-RAR-CHUNK !
        _EXT4-RAR-CHUNK @ 0 ?DO
            _EXT4-RAR-INDEX @ I + DUP 8 /
            _EXT4-RAR-CTX @ _EXT4-C.BLOCK + + C@
            1 ROT 8 MOD LSHIFT AND 0= IF
                _EXT4-RAR-DETAIL @ _EXT4-CORRUPT UNLOOP EXIT
            THEN
        LOOP
        _EXT4-RAR-CHUNK @ DUP _EXT4-RAR-CURRENT +!
        NEGATE _EXT4-RAR-REMAIN +!
    REPEAT 0 ;

VARIABLE _EXT4-BM-GROUP
VARIABLE _EXT4-BM-CTX
VARIABLE _EXT4-BM-STORED
VARIABLE _EXT4-BM-BLOCK-BITMAP
VARIABLE _EXT4-BM-INODE-BITMAP
VARIABLE _EXT4-BM-INODE-TABLE
VARIABLE _EXT4-BM-INODE-SPAN

: _EXT4-VALIDATE-BITMAPS  ( group ctx -- ior )
    _EXT4-BM-CTX ! _EXT4-BM-GROUP !
    _EXT4-BM-GROUP @ _EXT4-BM-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-BM-CTX @ _EXT4-C.DESC + DUP
        _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-BM-BLOCK-BITMAP !
    DUP _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-BM-INODE-BITMAP !
    DUP _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-BM-INODE-TABLE ! DROP
    _EXT4-BM-CTX @ _EXT4-C.IPG + @ _EXT4-BM-CTX @ _EXT4-C.ISIZE + @ *
    _EXT4-BM-CTX @ _EXT4-C.BSIZE + @ 1- +
    _EXT4-BM-CTX @ _EXT4-C.BSIZE + @ / _EXT4-BM-INODE-SPAN !
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND 0= IF
        _EXT4-BM-CTX @ _EXT4-C.DESC + DUP
        _EXT4-GD.BLOCK-CSUM-LO + W@
        SWAP _EXT4-GD.BLOCK-CSUM-HI + W@ 16 LSHIFT OR
        _EXT4-BM-STORED !
        _EXT4-BM-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
        _EXT4-BM-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-BM-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
        _EXT4-BM-CTX @ _EXT4-C.BLOCK +
        _EXT4-BM-CTX @ _EXT4-C.BPG + @ 8 / _EXT4-CRC-ADD
        ?DUP IF EXIT THEN
        _EXT4-CRC@ _EXT4-BM-STORED @ <> IF
            EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND 0= IF
        _EXT4-BM-CTX @ _EXT4-C.DESC + DUP
        _EXT4-GD.INODE-CSUM-LO + W@
        SWAP _EXT4-GD.INODE-CSUM-HI + W@ 16 LSHIFT OR
        _EXT4-BM-STORED !
        _EXT4-BM-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-BITMAP-LO + L@
        _EXT4-BM-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-BM-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
        _EXT4-BM-CTX @ _EXT4-C.BLOCK +
        _EXT4-BM-CTX @ _EXT4-C.IPG + @ 8 / _EXT4-CRC-ADD
        ?DUP IF EXIT THEN
        _EXT4-CRC@ _EXT4-BM-STORED @ <> IF
            EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    \ An uninitialized block bitmap has no authoritative ownership bits yet.
    \ Descriptor validation already bounds its reserved metadata locations;
    \ ordinary inode pointers into such a group remain rejected by the shared
    \ allocation helper.
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF 0 EXIT THEN
    _EXT4-BM-BLOCK-BITMAP @ EXT4-D-BITMAP-CHECKSUM _EXT4-BM-CTX @
    _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
    _EXT4-BM-INODE-BITMAP @ EXT4-D-BITMAP-CHECKSUM _EXT4-BM-CTX @
    _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
    _EXT4-BM-INODE-TABLE @ _EXT4-BM-INODE-SPAN @
    EXT4-D-BITMAP-CHECKSUM _EXT4-BM-CTX @
    _EXT4-REQUIRE-ALLOCATED-RANGE ;

VARIABLE _EXT4-VG-CTX
VARIABLE _EXT4-VG-FREE-BLOCKS
VARIABLE _EXT4-VG-FREE-INODES
VARIABLE _EXT4-VG-ADD
: _EXT4-VALIDATE-GROUPS  ( ctx -- ior )
    _EXT4-VG-CTX !
    0 _EXT4-VG-FREE-BLOCKS ! 0 _EXT4-VG-FREE-INODES !
    _EXT4-VG-CTX @ _EXT4-C.GROUPS + @ 0 DO
        I _EXT4-VG-CTX @ _EXT4-VALIDATE-BITMAPS ?DUP IF
            UNLOOP EXIT
        THEN
        \ Allocation ownership checks may load the descriptor for a different
        \ physical group under flex_bg; restore the counter source explicitly.
        I _EXT4-VG-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-VG-CTX @ _EXT4-C.DESC + DUP
        _EXT4-GD.FREE-BLOCKS-LO + W@
        SWAP _EXT4-GD.FREE-BLOCKS-HI + W@ 16 LSHIFT OR
        DUP _EXT4-VG-ADD ! _EXT4-VG-FREE-BLOCKS @ +
        DUP _EXT4-VG-ADD @ U< IF
            DROP EXT4-D-GEOMETRY _EXT4-CORRUPT UNLOOP EXIT
        THEN _EXT4-VG-FREE-BLOCKS !
        _EXT4-VG-CTX @ _EXT4-C.DESC + DUP
        _EXT4-GD.FREE-INODES-LO + W@
        SWAP _EXT4-GD.FREE-INODES-HI + W@ 16 LSHIFT OR
        DUP _EXT4-VG-ADD ! _EXT4-VG-FREE-INODES @ +
        DUP _EXT4-VG-ADD @ U< IF
            DROP EXT4-D-GEOMETRY _EXT4-CORRUPT UNLOOP EXIT
        THEN _EXT4-VG-FREE-INODES !
    LOOP
    _EXT4-VG-FREE-BLOCKS @ _EXT4-VG-CTX @ _EXT4-C.FREE-BLOCKS + @ <>
    _EXT4-VG-FREE-INODES @ _EXT4-VG-CTX @ _EXT4-C.FREE-INODES + @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ =====================================================================
\  Sparse-super backup validation
\ =====================================================================

VARIABLE _EXT4-BS-GROUP
VARIABLE _EXT4-BS-CTX
VARIABLE _EXT4-BS-BLOCK
VARIABLE _EXT4-BS-BUF
VARIABLE _EXT4-BS-PRIMARY

VARIABLE _EXT4-BG-BASE
VARIABLE _EXT4-BG-CTX
VARIABLE _EXT4-BG-BLOCK-BITMAP
VARIABLE _EXT4-BG-INODE-BITMAP
VARIABLE _EXT4-BG-INODE-TABLE
VARIABLE _EXT4-JBT-A
VARIABLE _EXT4-JBT-B

: _EXT4-JOURNAL-BACKUP-TUPLE=?  ( a b -- flag )
    _EXT4-JBT-B ! _EXT4-JBT-A !
    _EXT4-JBT-A @ _EXT4-SB.JOURNAL-BACKUP-TYPE + C@
    _EXT4-JBT-B @ _EXT4-SB.JOURNAL-BACKUP-TYPE + C@ =
    _EXT4-JBT-A @ _EXT4-SB.JOURNAL-BLOCKS +
    _EXT4-JBT-B @ _EXT4-SB.JOURNAL-BLOCKS +
    68 _EXT4-BYTES=? AND ;

\ A backup GDT can lag mutable counters and bitmap checksums after ordinary
\ filesystem activity.  Its own descriptor CRC must nevertheless validate,
\ and the immutable metadata locations must still agree with the primary
\ descriptor.  Reuse the primary descriptor parser so every copy receives
\ the same group-number CRC and bounds checks.
: _EXT4-VALIDATE-BACKUP-GDT  ( gdt-base ctx -- ior )
    _EXT4-BG-CTX ! _EXT4-BG-BASE !
    _EXT4-BG-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-BG-CTX @ _EXT4-LOAD-DESC ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-BG-CTX @ _EXT4-C.DESC + DUP
            _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-BG-BLOCK-BITMAP !
        DUP _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-BG-INODE-BITMAP !
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-BG-INODE-TABLE !
        I _EXT4-BG-BASE @ _EXT4-BG-CTX @ _EXT4-LOAD-DESC-AT
        ?DUP IF UNLOOP EXIT THEN
        _EXT4-BG-CTX @ _EXT4-C.DESC + DUP
            _EXT4-GD.BLOCK-BITMAP-LO + L@
            _EXT4-BG-BLOCK-BITMAP @ <> IF
                DROP EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT UNLOOP EXIT
            THEN
        DUP _EXT4-GD.INODE-BITMAP-LO + L@
            _EXT4-BG-INODE-BITMAP @ <> IF
                DROP EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT UNLOOP EXIT
            THEN
        _EXT4-GD.INODE-TABLE-LO + L@
            _EXT4-BG-INODE-TABLE @ <> IF
                EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT UNLOOP EXIT
            THEN
    LOOP
    0 ;

\ Compare the immutable profile fields of one checksum-authenticated copy.
\ Mutable counters, timestamps, state, LAST_ORPHAN, RECOVER, and
\ ORPHAN_PRESENT may legitimately differ; the caller supplies the copy's
\ required group number explicitly.
: _EXT4-SUPER-INVARIANTS?  ( candidate group reference -- flag )
    _EXT4-BS-PRIMARY ! _EXT4-BS-GROUP ! _EXT4-BS-BUF !
    _EXT4-BS-BUF @ _EXT4-SB.MAGIC + W@ _EXT4-MAGIC =
    _EXT4-BS-BUF @ _EXT4-SB.GROUP-NR + W@ _EXT4-BS-GROUP @ = AND
    _EXT4-BS-BUF @ _EXT4-SB.INODES + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.INODES + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.BLOCKS-LO + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.BLOCKS-LO + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.BLOCKS-HI + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.BLOCKS-HI + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.FIRST-DATA + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.FIRST-DATA + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.LOG-BLOCK + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.LOG-BLOCK + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.LOG-CLUSTER + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.LOG-CLUSTER + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.BPG + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.BPG + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.CPG + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.CPG + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.IPG + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.IPG + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.REVISION + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.REVISION + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.CREATOR + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.CREATOR + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.INODE-SIZE + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.INODE-SIZE + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.FIRST-INO + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.FIRST-INO + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.ERRORS + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.ERRORS + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.RESERVED-GDT + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.RESERVED-GDT + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.COMPAT + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.COMPAT + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.INCOMPAT + L@
        _EXT4-INCOMPAT-RECOVER INVERT AND
        _EXT4-BS-PRIMARY @ _EXT4-SB.INCOMPAT + L@
        _EXT4-INCOMPAT-RECOVER INVERT AND = AND
    _EXT4-BS-BUF @ _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT INVERT AND
        _EXT4-BS-PRIMARY @ _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT INVERT AND = AND
    _EXT4-BS-BUF @ _EXT4-SB.DESC-SIZE + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.DESC-SIZE + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.CSUM-TYPE + C@
        _EXT4-BS-PRIMARY @ _EXT4-SB.CSUM-TYPE + C@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.MIN-EXTRA + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.MIN-EXTRA + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.WANT-EXTRA + W@
        _EXT4-BS-PRIMARY @ _EXT4-SB.WANT-EXTRA + W@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.LOG-FLEX + C@
        _EXT4-BS-PRIMARY @ _EXT4-SB.LOG-FLEX + C@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.CSUM-SEED + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.CSUM-SEED + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.JOURNAL-INO + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.JOURNAL-INO + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.JOURNAL-BACKUP-TYPE + C@
        _EXT4-BS-PRIMARY @ _EXT4-SB.JOURNAL-BACKUP-TYPE + C@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.JOURNAL-BLOCKS +
        _EXT4-BS-PRIMARY @ _EXT4-SB.JOURNAL-BLOCKS +
        68 _EXT4-BYTES=? AND
    _EXT4-BS-BUF @ _EXT4-SB.ORPHAN-INO + L@
        _EXT4-BS-PRIMARY @ _EXT4-SB.ORPHAN-INO + L@ = AND
    _EXT4-BS-BUF @ _EXT4-SB.UUID +
        _EXT4-BS-PRIMARY @ _EXT4-SB.UUID + 16 _EXT4-BYTES=? AND ;

: _EXT4-BACKUP-SUPER-FIELDS?  ( backup ctx -- flag )
    _EXT4-BS-CTX !
    _EXT4-BS-GROUP @
    _EXT4-BS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? ;

: _EXT4-VALIDATE-BACKUP-SUPER  ( group ctx -- ior )
    _EXT4-BS-CTX ! DUP _EXT4-BS-GROUP !
    _EXT4-BS-CTX @ _EXT4-C.BPG + @ *
    _EXT4-BS-CTX @ _EXT4-C.FIRST + @ + DUP _EXT4-BS-BLOCK !
    _EXT4-BS-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-BS-CTX @ _EXT4-C.BLOCK + DUP _EXT4-BS-BUF !
    _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    _EXT4-BS-BUF @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    _EXT4-BS-BUF @ _EXT4-BS-CTX @ _EXT4-BACKUP-SUPER-FIELDS? 0= IF
        EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    _EXT4-BS-BLOCK @ 1+ _EXT4-BS-CTX @ _EXT4-VALIDATE-BACKUP-GDT ;

VARIABLE _EXT4-VB-CTX
: _EXT4-VALIDATE-BACKUPS  ( ctx -- ior )
    _EXT4-VB-CTX !
    _EXT4-VB-CTX @ _EXT4-C.GROUPS + @ 1 ?DO
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-VB-CTX @ _EXT4-VALIDATE-BACKUP-SUPER ?DUP IF
                UNLOOP EXIT
            THEN
        THEN
    LOOP 0 ;

\ =====================================================================
\  Inode loading, checksums, and inline extent validation
\ =====================================================================

VARIABLE _EXT4-IR-INO
VARIABLE _EXT4-IR-CTX
VARIABLE _EXT4-IR-GROUP
VARIABLE _EXT4-IR-INDEX
VARIABLE _EXT4-IR-BYTE
VARIABLE _EXT4-IR-BLOCK
VARIABLE _EXT4-IR-OFF
VARIABLE _EXT4-IR-LO
VARIABLE _EXT4-IR-HI
VARIABLE _EXT4-IR-HAS-HI
VARIABLE _EXT4-IR-CALC
VARIABLE _EXT4-IR-TABLE

: _EXT4-IR-RESTORE-CHECKSUM  ( -- )
    _EXT4-IR-LO @ _EXT4-IR-CTX @ _EXT4-C.INODE + _EXT4-I.CSUM-LO + W!
    _EXT4-IR-HAS-HI @ IF
        _EXT4-IR-HI @ _EXT4-IR-CTX @ _EXT4-C.INODE + _EXT4-I.CSUM-HI + W!
    THEN ;

: _EXT4-PREPARE-INODE-LOOKUP  ( inode-number ctx -- ior )
    _EXT4-IR-CTX ! DUP _EXT4-IR-INO !
    DUP 0= SWAP _EXT4-IR-CTX @ _EXT4-C.INODES + @ > OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-IR-INO @ 1-
    _EXT4-IR-CTX @ _EXT4-C.IPG + @ /MOD
    _EXT4-IR-GROUP ! _EXT4-IR-INDEX !
    0 ;

\ Load and checksum one record after its group, allocation bit, and table home
\ have already been authenticated.  The ownership scanner reuses this body so
\ one group-bitmap proof need not be repeated for every set bit.
: _EXT4-LOAD-INODE-RECORD-RAW  ( inode-table -- ior )
    _EXT4-IR-TABLE !
    _EXT4-IR-TABLE @
    _EXT4-IR-INDEX @ _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ *
    DUP _EXT4-IR-BYTE !
    _EXT4-IR-CTX @ _EXT4-C.BSIZE + @ / + DUP _EXT4-IR-BLOCK !
    _EXT4-IR-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-IR-BYTE @ _EXT4-IR-CTX @ _EXT4-C.BSIZE + @ MOD
    DUP _EXT4-IR-OFF ! _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ +
    _EXT4-IR-CTX @ _EXT4-C.BSIZE + @ > IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-IR-CTX @ _EXT4-C.BLOCK + _EXT4-IR-OFF @ +
    _EXT4-IR-CTX @ _EXT4-C.INODE +
    _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-IR-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.CSUM-LO + W@ _EXT4-IR-LO !
    0 OVER _EXT4-I.CSUM-LO + W!
    0 _EXT4-IR-HAS-HI ! 0 _EXT4-IR-HI !
    _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        \ A large inode record may still contain an old-format inode with
        \ i_extra_isize zero and only the low checksum word.  Nonzero extra
        \ geometry must reach and align the high checksum field.
        DUP _EXT4-I.EXTRA-SIZE + W@ ?DUP IF
            DUP 4 < IF
                DROP DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
            DUP 4 MOD IF
                DROP DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
            128 + _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ > IF
                DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
            DUP _EXT4-I.CSUM-HI + W@ _EXT4-IR-HI !
            0 OVER _EXT4-I.CSUM-HI + W!
            -1 _EXT4-IR-HAS-HI !
        THEN
    THEN
    DROP
    _EXT4-IR-INO @ _EXT4-IR-CTX @ _EXT4-C.TMP + L!
    _EXT4-IR-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-IR-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF
        _EXT4-IR-RESTORE-CHECKSUM EXIT
    THEN
    _EXT4-IR-CTX @ _EXT4-C.INODE + _EXT4-I.GENERATION + 4 _EXT4-CRC-ADD
    ?DUP IF _EXT4-IR-RESTORE-CHECKSUM EXIT THEN
    _EXT4-IR-CTX @ _EXT4-C.INODE +
    _EXT4-IR-CTX @ _EXT4-C.ISIZE + @ _EXT4-CRC-ADD
    ?DUP IF _EXT4-IR-RESTORE-CHECKSUM EXIT THEN
    _EXT4-CRC@ _EXT4-IR-CALC !
    _EXT4-IR-RESTORE-CHECKSUM
    _EXT4-IR-HAS-HI @ IF
        _EXT4-IR-HI @ 16 LSHIFT _EXT4-IR-LO @ OR
        _EXT4-IR-CALC @ <>
    ELSE
        _EXT4-IR-CALC @ 0xFFFF AND _EXT4-IR-LO @ <>
    THEN IF EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT THEN
    0 ;

\ Consume the descriptor already present in C.DESC.  Recovery can therefore
\ authenticate inode 8 through a sparse backup GDT without ever consulting a
\ damaged primary descriptor; ordinary inode loading uses the same body.
: _EXT4-LOAD-INODE-FROM-DESC-RAW  ( -- ior )
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-IR-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-IR-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-IR-INDEX @ 8 / _EXT4-IR-CTX @ _EXT4-C.BLOCK + + C@
    1 _EXT4-IR-INDEX @ 8 MOD LSHIFT AND 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-IR-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-LOAD-INODE-RECORD-RAW ;

\ Ordinary readers require i_dtime to be clear.  Orphan recovery instead
\ interprets that field as the bounded legacy next-orphan value, so keep the
\ common allocation, descriptor, and checksum authentication above reusable.
: _EXT4-LOAD-INODE-FROM-DESC  ( -- ior )
    _EXT4-LOAD-INODE-FROM-DESC-RAW ?DUP IF EXIT THEN
    _EXT4-IR-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ IF
        EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-LOAD-INODE  ( inode-number ctx -- ior )
    _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-IR-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-LOAD-INODE-FROM-DESC ;

: _EXT4-LOAD-ORPHAN-INODE  ( inode-number ctx -- ior )
    _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-IR-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-LOAD-INODE-FROM-DESC-RAW ?DUP IF EXIT THEN
    _EXT4-IR-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
    _EXT4-IR-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-EV-CTX
VARIABLE _EXT4-EV-IN
VARIABLE _EXT4-EV-COUNT
VARIABLE _EXT4-EV-MAX
VARIABLE _EXT4-EV-DEPTH
VARIABLE _EXT4-EV-PREV
VARIABLE _EXT4-EV-ENTRY
VARIABLE _EXT4-EV-LOGICAL
VARIABLE _EXT4-EV-LEN
VARIABLE _EXT4-EV-PHYS
VARIABLE _EXT4-EV-BLOCK
VARIABLE _EXT4-EV-STORED
VARIABLE _EXT4-EV-J
VARIABLE _EXT4-EV-OTHER
VARIABLE _EXT4-EV-OTHER-LEN
VARIABLE _EXT4-EV-INDEX
VARIABLE _EXT4-MAP-VALIDATION-LIMIT

: _EXT4-EXTENT-LEN@  ( extent -- blocks )
    4 + W@ DUP 32768 > IF 32768 - THEN ;

: _EXT4-VALIDATE-EXTENT-INDEX-ENTRY  ( index -- ior )
    _EXT4-EV-INDEX !
    _EXT4-EV-LOGICAL @ _EXT4-EV-PREV !
    _EXT4-MAP-VALIDATION-LIMIT @ IF
        _EXT4-EV-LOGICAL @ _EXT4-MAP-VALIDATION-LIMIT @ U< 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-EV-ENTRY @ 8 + W@ IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-EV-ENTRY @ 10 + W@ IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    _EXT4-EV-ENTRY @ 4 + L@ DUP _EXT4-EV-PHYS ! 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-MAX @ 4 <> _EXT4-EV-PHYS @ _EXT4-EV-BLOCK @ = AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-PHYS @ EXT4-D-DATA-MAP _EXT4-EV-CTX @
    _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
    0 _EXT4-EV-J !
    BEGIN _EXT4-EV-J @ _EXT4-EV-INDEX @ < WHILE
        _EXT4-EV-IN @ 12 _EXT4-EV-J @ 12 * + + 4 + L@
        _EXT4-EV-PHYS @ = IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
        1 _EXT4-EV-J +!
    REPEAT 0 ;

: _EXT4-VALIDATE-EXTENT-LEAF-ENTRY  ( index -- ior )
    _EXT4-EV-INDEX !
    _EXT4-EV-ENTRY @ 4 + W@ DUP 0= IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 32768 > IF 32768 - THEN DUP _EXT4-EV-LEN ! 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-LOGICAL @ _EXT4-EV-LEN @ + DUP
    _EXT4-EV-LOGICAL @ U<
    OVER 0xFFFFFFFF U> OR IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN _EXT4-EV-PREV !
    _EXT4-MAP-VALIDATION-LIMIT @ IF
        _EXT4-EV-PREV @ _EXT4-MAP-VALIDATION-LIMIT @ U> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-EV-ENTRY @ 6 + W@ IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-EV-ENTRY @ 8 + L@ DUP _EXT4-EV-PHYS ! 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-PHYS @ _EXT4-EV-LEN @ EXT4-D-DATA-MAP
    _EXT4-EV-CTX @ _EXT4-REQUIRE-ALLOCATED-RANGE ?DUP IF EXIT THEN
    _EXT4-MUTATION-MAP-ACTIVE @ IF
        _EXT4-EV-PHYS @ _EXT4-EV-LEN @ _EXT4-EV-CTX @
        _EXT4-MUTATION-ROLE-RANGE ?DUP IF EXIT THEN
        _EXT4-EV-PHYS @ _EXT4-EV-LEN @
        _EXT4-MUTATION-MAP-ALIASES? IF
            1 _EXT4-MUTATION-MAP-HITS +!
            _EXT4-MUTATION-MAP-HITS @ 1 U> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
        THEN
    THEN
    0 _EXT4-EV-J !
    BEGIN _EXT4-EV-J @ _EXT4-EV-INDEX @ < WHILE
        _EXT4-EV-IN @ 12 _EXT4-EV-J @ 12 * + + DUP
        8 + L@ _EXT4-EV-OTHER !
        _EXT4-EXTENT-LEN@ _EXT4-EV-OTHER-LEN !
        _EXT4-EV-OTHER @ _EXT4-EV-OTHER-LEN @ + _EXT4-EV-PHYS @ U>
        _EXT4-EV-PHYS @ _EXT4-EV-LEN @ + _EXT4-EV-OTHER @ U> AND IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-EV-J +!
    REPEAT 0 ;

\ Validate one resident extent header and every entry it owns.  External
\ children and every data block in a leaf must agree with the allocation
\ bitmap before the pointer can participate in traversal.
: _EXT4-VALIDATE-EXTENT-NODE  ( header expected-max expected-depth ctx -- ior )
    _EXT4-EV-CTX ! _EXT4-EV-DEPTH ! _EXT4-EV-MAX ! _EXT4-EV-IN !
    _EXT4-EV-IN @ W@ _EXT4-EXTENT-MAGIC <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-IN @ 2 + W@ _EXT4-EV-COUNT !
    _EXT4-EV-IN @ 4 + W@ _EXT4-EV-MAX @ <>
    _EXT4-EV-COUNT @ _EXT4-EV-MAX @ U> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-IN @ 6 + W@ DUP _EXT4-EV-DEPTH @ <>
    SWAP _EXT4-MAX-EXTENT-DEPTH U> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-COUNT @ 0=
    _EXT4-EV-DEPTH @ 0<> _EXT4-EV-MAX @ 4 <> OR AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-EV-PREV !
    _EXT4-EV-COUNT @ 0 ?DO
        _EXT4-EV-IN @ 12 I 12 * + + _EXT4-EV-ENTRY !
        _EXT4-EV-ENTRY @ L@ _EXT4-EV-LOGICAL !
        I IF
            _EXT4-EV-PREV @ _EXT4-EV-LOGICAL @ U> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-EV-DEPTH @
            _EXT4-EV-PREV @ _EXT4-EV-LOGICAL @ = AND IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
        _EXT4-EV-DEPTH @ IF
            I _EXT4-VALIDATE-EXTENT-INDEX-ENTRY
        ELSE
            I _EXT4-VALIDATE-EXTENT-LEAF-ENTRY
        THEN ?DUP IF UNLOOP EXIT THEN
    LOOP 0 ;

: _EXT4-VALIDATE-INLINE-EXTENTS  ( ctx -- ior )
    DUP _EXT4-EV-CTX ! _EXT4-C.INODE + _EXT4-I.BLOCK + _EXT4-EV-IN !
    _EXT4-EV-IN @ 6 + W@ DUP _EXT4-MAX-EXTENT-DEPTH U> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-IN @ 4 ROT
    _EXT4-EV-CTX @ _EXT4-VALIDATE-EXTENT-NODE ;

\ Read and authenticate one external extent-tree node.  Its checksum covers
\ inode number/generation plus the node bytes before the four-byte tail.
\ The verified node is copied to DIR-BLOCK so allocation checks may reuse the
\ ordinary BLOCK cache without invalidating the parser's input.
: _EXT4-LOAD-EXTENT-NODE  ( physical-block expected-depth ctx -- ior )
    _EXT4-EV-CTX ! _EXT4-EV-DEPTH ! DUP _EXT4-EV-BLOCK !
    _EXT4-MUTATION-MAP-ACTIVE @ IF
        DROP
        _EXT4-EV-BLOCK @ 1 _EXT4-EV-CTX @
        _EXT4-MUTATION-ROLE-RANGE ?DUP IF EXIT THEN
        _EXT4-EV-BLOCK @ 1 _EXT4-MUTATION-MAP-ALIASES? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-EV-BLOCK @
    THEN
    EXT4-D-DATA-MAP _EXT4-EV-CTX @ _EXT4-REQUIRE-ALLOCATED-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-EV-BLOCK @ _EXT4-EV-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-EV-CTX @ _EXT4-C.BLOCK +
    _EXT4-EV-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-EV-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-EV-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-EV-IN !
    _EXT4-EV-CTX @ _EXT4-C.BSIZE + @ 12 - 12 / _EXT4-EV-MAX !
    _EXT4-EV-MAX @ 12 * 12 + _EXT4-EV-IN @ + L@ _EXT4-EV-STORED !
    _EXT4-IR-INO @ _EXT4-EV-CTX @ _EXT4-C.TMP + L!
    _EXT4-EV-CTX @ _EXT4-C.INODE + _EXT4-I.GENERATION + L@
    _EXT4-EV-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-EV-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-EV-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-EV-IN @ _EXT4-EV-MAX @ 12 * 12 + _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-EV-STORED @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EV-IN @ _EXT4-EV-MAX @ _EXT4-EV-DEPTH @ _EXT4-EV-CTX @
    _EXT4-VALIDATE-EXTENT-NODE ;

VARIABLE _EXT4-ET-CTX
CREATE _EXT4-ET-LOWER 6 CELLS ALLOT
CREATE _EXT4-ET-UPPER 6 CELLS ALLOT
CREATE _EXT4-ET-HAS-UPPER 6 CELLS ALLOT
VARIABLE _EXT4-ET-DEPTH
VARIABLE _EXT4-ET-LAST
VARIABLE _EXT4-ET-ROOT
VARIABLE _EXT4-ET-ROOT-DEPTH
VARIABLE _EXT4-ET-ROOT-COUNT

: _EXT4-ET-LOWER!  ( value depth -- )  CELLS _EXT4-ET-LOWER + ! ;
: _EXT4-ET-LOWER@  ( depth -- value )  CELLS _EXT4-ET-LOWER + @ ;
: _EXT4-ET-UPPER!  ( value depth -- )  CELLS _EXT4-ET-UPPER + ! ;
: _EXT4-ET-UPPER@  ( depth -- value )  CELLS _EXT4-ET-UPPER + @ ;
: _EXT4-ET-HAS!    ( flag depth -- )   CELLS _EXT4-ET-HAS-UPPER + ! ;
: _EXT4-ET-HAS@    ( depth -- flag )   CELLS _EXT4-ET-HAS-UPPER + @ ;

\ Every index key is the exact first logical block in its child.  An upper
\ bound comes from the next sibling key (or is inherited by the last child),
\ preventing a checksummed child from escaping or overlapping its branch.
: _EXT4-ET-CHECK-BOUNDS  ( depth -- ior )
    DUP _EXT4-ET-DEPTH !
    _EXT4-EV-IN @ 12 + L@ SWAP _EXT4-ET-LOWER@ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ET-DEPTH @ _EXT4-ET-HAS@ 0= IF 0 EXIT THEN
    _EXT4-EV-IN @ 2 + W@ 1- 12 * 12 + _EXT4-EV-IN @ +
    DUP _EXT4-ET-LAST !
    _EXT4-ET-DEPTH @ 0= IF
        DUP L@ SWAP _EXT4-EXTENT-LEN@ +
        _EXT4-ET-DEPTH @ _EXT4-ET-UPPER@ U> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    ELSE
        DROP _EXT4-ET-LAST @ L@
        _EXT4-ET-DEPTH @ _EXT4-ET-UPPER@ U< 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN 0 ;

: _EXT4-VALIDATE-EXTENT-SUBTREE  ( physical-block depth -- ior )
    2DUP _EXT4-ET-CTX @ _EXT4-LOAD-EXTENT-NODE ?DUP IF
        >R 2DROP R> EXIT
    THEN
    DUP _EXT4-ET-CHECK-BOUNDS ?DUP IF
        >R 2DROP R> EXIT
    THEN
    DUP 0= IF 2DROP 0 EXIT THEN
    _EXT4-ET-CTX @ _EXT4-C.TREE-BLOCK + 2 + W@ 0 ?DO
        2DUP _EXT4-ET-CTX @ _EXT4-LOAD-EXTENT-NODE ?DUP IF
            >R 2DROP R> UNLOOP EXIT
        THEN
        _EXT4-ET-CTX @ _EXT4-C.TREE-BLOCK + 12 I 12 * + + L@
        OVER 1- _EXT4-ET-LOWER!
        I 1+ _EXT4-EV-COUNT @ < IF
            _EXT4-ET-CTX @ _EXT4-C.TREE-BLOCK +
            12 I 1+ 12 * + + L@
            OVER 1- _EXT4-ET-UPPER!
            TRUE OVER 1- _EXT4-ET-HAS!
        ELSE
            DUP _EXT4-ET-UPPER@ OVER 1- _EXT4-ET-UPPER!
            DUP _EXT4-ET-HAS@ OVER 1- _EXT4-ET-HAS!
        THEN
        _EXT4-ET-CTX @ _EXT4-C.TREE-BLOCK + 12 I 12 * + + 4 + L@
        >R DUP 1- R> SWAP RECURSE ?DUP IF
            >R 2DROP R> UNLOOP EXIT
        THEN
    LOOP 2DROP 0 ;

: _EXT4-VALIDATE-EXTENT-TREE  ( ctx -- ior )
    DUP _EXT4-ET-CTX ! _EXT4-VALIDATE-INLINE-EXTENTS ?DUP IF EXIT THEN
    _EXT4-ET-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK + DUP _EXT4-ET-ROOT !
    6 + W@ DUP _EXT4-ET-ROOT-DEPTH ! 0= IF
        0 EXIT
    THEN
    _EXT4-ET-ROOT @ 2 + W@ DUP _EXT4-ET-ROOT-COUNT ! 0 ?DO
        _EXT4-ET-ROOT @ 12 I 12 * + + L@
        _EXT4-ET-ROOT-DEPTH @ 1- _EXT4-ET-LOWER!
        I 1+ _EXT4-ET-ROOT-COUNT @ < IF
            _EXT4-ET-ROOT @ 12 I 1+ 12 * + + L@
            _EXT4-ET-ROOT-DEPTH @ 1- _EXT4-ET-UPPER!
            TRUE _EXT4-ET-ROOT-DEPTH @ 1- _EXT4-ET-HAS!
        ELSE
            FALSE _EXT4-ET-ROOT-DEPTH @ 1- _EXT4-ET-HAS!
        THEN
        _EXT4-ET-ROOT @ 12 I 12 * + + 4 + L@
        _EXT4-ET-ROOT-DEPTH @ 1- _EXT4-VALIDATE-EXTENT-SUBTREE
        ?DUP IF UNLOOP EXIT THEN
    LOOP 0 ;

VARIABLE _EXT4-MAP-LBLOCK
VARIABLE _EXT4-MAP-CTX
VARIABLE _EXT4-MAP-IN
VARIABLE _EXT4-MAP-ENTRY
VARIABLE _EXT4-MAP-START
VARIABLE _EXT4-MAP-LEN
VARIABLE _EXT4-MAP-RAWLEN
VARIABLE _EXT4-MAP-DEPTH
VARIABLE _EXT4-MAP-CHILD

: _EXT4-MAP-EXTENT-LEAF  ( header -- physical present? ior )
    DUP 2 + W@ 0 ?DO
        DUP 12 I 12 * + + _EXT4-MAP-ENTRY !
        _EXT4-MAP-ENTRY @ L@ _EXT4-MAP-START !
        _EXT4-MAP-ENTRY @ 4 + W@ DUP _EXT4-MAP-RAWLEN !
        DUP 32768 > IF 32768 - THEN _EXT4-MAP-LEN !
        _EXT4-MAP-LBLOCK @ _EXT4-MAP-START @ >=
        _EXT4-MAP-LBLOCK @ _EXT4-MAP-START @ _EXT4-MAP-LEN @ + < AND IF
            DROP
            _EXT4-MAP-RAWLEN @ 32768 > IF 0 FALSE 0 UNLOOP EXIT THEN
            _EXT4-MAP-ENTRY @ 8 + L@
            _EXT4-MAP-LBLOCK @ _EXT4-MAP-START @ - + TRUE 0
            UNLOOP EXIT
        THEN
    LOOP DROP 0 FALSE 0 ;

: _EXT4-MAP-EXTENT  ( logical-block ctx -- physical present? ior )
    _EXT4-MAP-CTX ! _EXT4-MAP-LBLOCK !
    _EXT4-MAP-CTX @ _EXT4-VALIDATE-INLINE-EXTENTS ?DUP IF
        0 FALSE ROT EXIT
    THEN
    _EXT4-MAP-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK + DUP _EXT4-MAP-IN !
    6 + W@ _EXT4-MAP-DEPTH !
    BEGIN _EXT4-MAP-DEPTH @ WHILE
        0 _EXT4-MAP-CHILD !
        _EXT4-MAP-IN @ 2 + W@ 0 ?DO
            _EXT4-MAP-IN @ 12 I 12 * + + DUP L@
            _EXT4-MAP-LBLOCK @ U> IF DROP LEAVE THEN
            4 + L@ _EXT4-MAP-CHILD !
        LOOP
        _EXT4-MAP-CHILD @ 0= IF 0 FALSE 0 EXIT THEN
        _EXT4-MAP-DEPTH @ 1- DUP _EXT4-MAP-DEPTH !
        _EXT4-MAP-CHILD @ SWAP _EXT4-MAP-CTX @
        _EXT4-LOAD-EXTENT-NODE ?DUP IF 0 FALSE ROT EXIT THEN
        _EXT4-MAP-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-MAP-IN !
    REPEAT
    _EXT4-MAP-IN @ _EXT4-MAP-EXTENT-LEAF ;

\ Legacy mappings remain an admitted read format even when the filesystem
\ advertises extents globally.  Validate the complete direct/indirect tree
\ with a depth bound of three and then use the same checked map interface.
VARIABLE _EXT4-LV-CTX
VARIABLE _EXT4-LV-PTRS
VARIABLE _EXT4-LV-CHILD
VARIABLE _EXT4-LV-CHILD-LEVEL
VARIABLE _EXT4-LV-CHILD-BASE
VARIABLE _EXT4-LV-SPAN
VARIABLE _EXT4-LV-ROOT-BASE

: _EXT4-LOAD-LEGACY-POINTER-BLOCK  ( physical-block ctx -- ior )
    DUP _EXT4-LV-CTX ! SWAP DUP >R EXT4-D-DATA-MAP ROT
    _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF R> DROP EXIT THEN
    R> _EXT4-LV-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-LV-CTX @ _EXT4-C.BLOCK +
    _EXT4-LV-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-LV-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 ;

: _EXT4-U-POWER  ( base exponent -- value )
    1 SWAP 0 ?DO OVER * LOOP NIP ;

: _EXT4-VALIDATE-LEGACY-SUBTREE  ( physical-block level logical-base -- ior )
    2 PICK _EXT4-LV-CTX @ _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF
        >R DROP 2DROP R> EXIT
    THEN
    _EXT4-LV-CTX @ _EXT4-C.BSIZE + @ 4 / 0 ?DO
        _EXT4-LV-CTX @ _EXT4-C.TREE-BLOCK + I 4 * + L@ ?DUP IF
            2 PICK 1 > IF
                _EXT4-LV-CHILD !
                OVER 1- DUP _EXT4-LV-CHILD-LEVEL !
                _EXT4-LV-PTRS @ SWAP _EXT4-U-POWER
                _EXT4-LV-SPAN !
                DUP I _EXT4-LV-SPAN @ * + _EXT4-LV-CHILD-BASE !
                _EXT4-MAP-VALIDATION-LIMIT @ IF
                    _EXT4-LV-CHILD-BASE @
                    _EXT4-MAP-VALIDATION-LIMIT @ U< 0= IF
                        DROP 2DROP EXT4-D-DATA-MAP _EXT4-CORRUPT
                        UNLOOP EXIT
                    THEN
                THEN
                _EXT4-LV-CHILD @ _EXT4-LV-CHILD-LEVEL @
                _EXT4-LV-CHILD-BASE @ RECURSE ?DUP IF
                    >R DROP 2DROP R> UNLOOP EXIT
                THEN
                \ Recursion owns the shared tree buffer; restore this parent
                \ only after an actual child traversal, not once per null slot.
                2 PICK _EXT4-LV-CTX @ _EXT4-LOAD-LEGACY-POINTER-BLOCK
                ?DUP IF >R DROP 2DROP R> UNLOOP EXIT THEN
            ELSE
                _EXT4-MAP-VALIDATION-LIMIT @ IF
                    OVER I + _EXT4-MAP-VALIDATION-LIMIT @ U< 0= IF
                        2DROP 2DROP EXT4-D-DATA-MAP _EXT4-CORRUPT
                        UNLOOP EXIT
                    THEN
                THEN
                EXT4-D-DATA-MAP _EXT4-LV-CTX @
                _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF
                    >R DROP 2DROP R> UNLOOP EXIT
                THEN
            THEN
        THEN
    LOOP DROP 2DROP 0 ;

: _EXT4-VALIDATE-LEGACY-MAP  ( ctx -- ior )
    DUP _EXT4-LV-CTX ! _EXT4-C.INODE + _EXT4-I.BLOCK +
    _EXT4-NDIRECT 0 DO
        DUP I 4 * + L@ ?DUP IF
            _EXT4-MAP-VALIDATION-LIMIT @ IF
                I _EXT4-MAP-VALIDATION-LIMIT @ U< 0= IF
                    2DROP EXT4-D-DATA-MAP _EXT4-CORRUPT
                    UNLOOP EXIT
                THEN
            THEN
            EXT4-D-DATA-MAP _EXT4-LV-CTX @
            _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF
                NIP UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-LV-CTX @ _EXT4-C.BSIZE + @ 4 / _EXT4-LV-PTRS !
    _EXT4-NDIRECT _EXT4-LV-ROOT-BASE !
    3 0 DO
        DUP _EXT4-NDIRECT I + 4 * + L@ ?DUP IF
            _EXT4-MAP-VALIDATION-LIMIT @ IF
                _EXT4-LV-ROOT-BASE @
                _EXT4-MAP-VALIDATION-LIMIT @ U< 0= IF
                    2DROP EXT4-D-DATA-MAP _EXT4-CORRUPT
                    UNLOOP EXIT
                THEN
            THEN
            I 1+ _EXT4-LV-ROOT-BASE @
            _EXT4-VALIDATE-LEGACY-SUBTREE ?DUP IF
                NIP UNLOOP EXIT
            THEN
        THEN
        _EXT4-LV-PTRS @ I 1+ _EXT4-U-POWER
        _EXT4-LV-ROOT-BASE +!
    LOOP DROP 0 ;

VARIABLE _EXT4-LM-INDEX
VARIABLE _EXT4-LM-PTR
VARIABLE _EXT4-LM-LEVEL
VARIABLE _EXT4-LM-DIV

: _EXT4-MAP-LEGACY-INDIRECT  ( index root level ctx -- physical present? ior )
    _EXT4-MAP-CTX ! _EXT4-LM-LEVEL ! _EXT4-LM-PTR ! _EXT4-LM-INDEX !
    BEGIN _EXT4-LM-LEVEL @ WHILE
        _EXT4-LM-PTR @ 0= IF 0 FALSE 0 EXIT THEN
        _EXT4-LM-PTR @ _EXT4-MAP-CTX @
        _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF 0 FALSE ROT EXIT THEN
        _EXT4-MAP-CTX @ _EXT4-C.BSIZE + @ 4 /
        _EXT4-LM-LEVEL @ 1- _EXT4-U-POWER DUP _EXT4-LM-DIV !
        _EXT4-LM-INDEX @ SWAP /MOD
        SWAP _EXT4-LM-INDEX !
        4 * _EXT4-MAP-CTX @ _EXT4-C.TREE-BLOCK + + L@ _EXT4-LM-PTR !
        -1 _EXT4-LM-LEVEL +!
    REPEAT
    _EXT4-LM-PTR @ DUP 0= IF DROP 0 FALSE 0 EXIT THEN
    DUP EXT4-D-DATA-MAP _EXT4-MAP-CTX @
    _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF NIP 0 FALSE ROT EXIT THEN
    TRUE 0 ;

: _EXT4-MAP-LEGACY  ( logical-block ctx -- physical present? ior )
    _EXT4-MAP-CTX ! _EXT4-MAP-LBLOCK !
    _EXT4-MAP-LBLOCK @ _EXT4-NDIRECT U< IF
        _EXT4-MAP-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK +
        _EXT4-MAP-LBLOCK @ 4 * + L@ DUP 0= IF DROP 0 FALSE 0 EXIT THEN
        DUP EXT4-D-DATA-MAP _EXT4-MAP-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF NIP 0 FALSE ROT EXIT THEN
        TRUE 0 EXIT
    THEN
    _EXT4-MAP-LBLOCK @ _EXT4-NDIRECT - _EXT4-LM-INDEX !
    _EXT4-MAP-CTX @ _EXT4-C.BSIZE + @ 4 / _EXT4-LV-PTRS !
    3 0 DO
        _EXT4-LV-PTRS @ I 1+ _EXT4-U-POWER DUP _EXT4-LM-DIV !
        _EXT4-LM-INDEX @ OVER U< IF
            DROP
            _EXT4-LM-INDEX @
            _EXT4-MAP-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK +
            _EXT4-NDIRECT I + 4 * + L@
            I 1+ _EXT4-MAP-CTX @ _EXT4-MAP-LEGACY-INDIRECT
            UNLOOP EXIT
        THEN
        _EXT4-LM-INDEX @ SWAP - _EXT4-LM-INDEX !
    LOOP
    0 FALSE EXT4-D-BOUNDS _EXT4-CORRUPT ;

: _EXT4-MAP-BLOCK  ( logical-block ctx -- physical present? ior )
    DUP _EXT4-C.INODE + _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND IF
        _EXT4-MAP-EXTENT
    ELSE
        _EXT4-MAP-LEGACY
    THEN ;

VARIABLE _EXT4-IB-IN
VARIABLE _EXT4-IB-CTX

: _EXT4-DECODE-I-BLOCKS  ( inode ctx -- blocks-512 ior )
    _EXT4-IB-CTX ! _EXT4-IB-IN !
    _EXT4-IB-IN @ _EXT4-I.BLOCKS-HI + W@ 32 LSHIFT
    _EXT4-IB-IN @ _EXT4-I.BLOCKS-LO + L@ OR
    _EXT4-IB-IN @ _EXT4-I.FLAGS + L@ _EXT4-HUGE-FILE-FL AND IF
        _EXT4-IB-CTX @ _EXT4-C.SPB + @ *
    THEN
    DUP _EXT4-IB-CTX @ _EXT4-C.BLOCKS + @
        _EXT4-IB-CTX @ _EXT4-C.SPB + @ * U> IF
        DROP 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-S32@  ( addr -- n )
    L@ DUP 0x80000000 AND IF 0xFFFFFFFF00000000 OR THEN ;

VARIABLE _EXT4-SD-CTX
VARIABLE _EXT4-SD-IN
VARIABLE _EXT4-SD-MODE
VARIABLE _EXT4-SD-RAW
VARIABLE _EXT4-SD-MAJOR
VARIABLE _EXT4-SD-MINOR
VARIABLE _EXT4-SD-INDEX

: _EXT4-I-BLOCK-ZERO-FROM?  ( first-word ctx -- flag )
    _EXT4-SD-CTX ! _EXT4-SD-INDEX !
    BEGIN _EXT4-SD-INDEX @ _EXT4-N-BLOCK-PTRS < WHILE
        _EXT4-SD-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK +
        _EXT4-SD-INDEX @ 4 * + L@ IF FALSE EXIT THEN
        1 _EXT4-SD-INDEX +!
    REPEAT TRUE ;

\ Device inodes use ext4's old encoding in i_block[0] or its new encoding
\ in i_block[1].  Publish a binding-neutral 64-bit major/minor pair while
\ retaining stable unsupported behavior for OPEN on the resulting vnode.
: _EXT4-DECODE-SPECIAL  ( ctx -- rdev ior )
    DUP _EXT4-SD-CTX ! _EXT4-C.INODE + DUP _EXT4-SD-IN !
    _EXT4-I.MODE + W@ 0xF000 AND _EXT4-SD-MODE !
    _EXT4-SD-CTX @ _EXT4-C.R.SIZE + @
    _EXT4-SD-CTX @ _EXT4-C.R.BLOCKS + @ OR IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SD-MODE @ 0x2000 = _EXT4-SD-MODE @ 0x6000 = OR IF
        _EXT4-SD-IN @ _EXT4-I.BLOCK + L@ DUP _EXT4-SD-RAW ! IF
            _EXT4-SD-RAW @ 0xFFFF U> IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-SD-CTX @ _EXT4-I-BLOCK-ZERO-FROM? 0= IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-SD-RAW @ 8 RSHIFT 0xFF AND _EXT4-SD-MAJOR !
            _EXT4-SD-RAW @ 0xFF AND _EXT4-SD-MINOR !
        ELSE
            _EXT4-SD-IN @ _EXT4-I.BLOCK + 4 + L@ _EXT4-SD-RAW !
            2 _EXT4-SD-CTX @ _EXT4-I-BLOCK-ZERO-FROM? 0= IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-SD-RAW @ 0xFFF00 AND 8 RSHIFT _EXT4-SD-MAJOR !
            _EXT4-SD-RAW @ 0xFF AND
            _EXT4-SD-RAW @ 12 RSHIFT 0xFFF00 AND OR _EXT4-SD-MINOR !
            _EXT4-SD-MINOR @ 0xFF AND
            _EXT4-SD-MAJOR @ 8 LSHIFT OR
            _EXT4-SD-MINOR @ 0xFF INVERT AND 12 LSHIFT OR
            _EXT4-SD-RAW @ <> IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-SD-MAJOR @ _EXT4-SD-MINOR @ VFS-RDEV-MAKE 0 EXIT
    THEN
    0 _EXT4-SD-CTX @ _EXT4-I-BLOCK-ZERO-FROM? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 0 ;

\ =====================================================================
\  Root metadata staging and publication
\ =====================================================================

VARIABLE _EXT4-RS-CTX
VARIABLE _EXT4-RS-IN
VARIABLE _EXT4-RS-HI
VARIABLE _EXT4-RS-EXTRA

: _EXT4-STAGE-ROOT  ( ctx -- ior )
    DUP _EXT4-RS-CTX ! _EXT4-C.INODE + _EXT4-RS-IN !
    _EXT4-RS-IN @ _EXT4-I.MODE + W@ DUP 0xF000 AND 0x4000 <> IF
        DROP EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RS-CTX @ _EXT4-C.R.MODE + !
    _EXT4-RS-IN @ _EXT4-I.LINKS + W@ DUP 0= IF
        DROP EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RS-CTX @ _EXT4-C.R.NLINK + !
    _EXT4-RS-IN @ _EXT4-I.SIZE-HI + L@ DUP _EXT4-RS-HI !
    0x80000000 AND IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-RS-HI @ 32 LSHIFT _EXT4-RS-IN @ _EXT4-I.SIZE-LO + L@ OR
    _EXT4-RS-CTX @ _EXT4-C.R.SIZE + !
    _EXT4-RS-IN @ _EXT4-I.UID-HI + W@ 16 LSHIFT
    _EXT4-RS-IN @ _EXT4-I.UID-LO + W@ OR
    _EXT4-RS-CTX @ _EXT4-C.R.UID + !
    _EXT4-RS-IN @ _EXT4-I.GID-HI + W@ 16 LSHIFT
    _EXT4-RS-IN @ _EXT4-I.GID-LO + W@ OR
    _EXT4-RS-CTX @ _EXT4-C.R.GID + !
    _EXT4-RS-IN @ _EXT4-RS-CTX @ _EXT4-DECODE-I-BLOCKS
    ?DUP IF NIP EXIT THEN
    _EXT4-RS-CTX @ _EXT4-C.R.BLOCKS + !
    _EXT4-RS-IN @ _EXT4-I.GENERATION + L@
    _EXT4-RS-CTX @ _EXT4-C.R.GEN + !
    0 _EXT4-RS-CTX @ _EXT4-C.R.RDEV + !
    _EXT4-RS-IN @ _EXT4-I.ATIME + _EXT4-S32@
    _EXT4-RS-CTX @ _EXT4-C.R.ATIME + !
    _EXT4-RS-IN @ _EXT4-I.MTIME + _EXT4-S32@
    _EXT4-RS-CTX @ _EXT4-C.R.MTIME + !
    _EXT4-RS-IN @ _EXT4-I.CTIME + _EXT4-S32@
    _EXT4-RS-CTX @ _EXT4-C.R.CTIME + !
    0 _EXT4-RS-CTX @ _EXT4-C.R.ATIME-NS + !
    0 _EXT4-RS-CTX @ _EXT4-C.R.MTIME-NS + !
    0 _EXT4-RS-CTX @ _EXT4-C.R.CTIME-NS + !
    _EXT4-RS-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-RS-IN @ _EXT4-I.EXTRA-SIZE + W@ 16 < IF
            EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RS-IN @ _EXT4-I.ATIME-EXTRA + L@ DUP _EXT4-RS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-RS-CTX @ _EXT4-C.R.ATIME-NS + !
        _EXT4-RS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-RS-CTX @ _EXT4-C.R.ATIME + +!
        _EXT4-RS-IN @ _EXT4-I.MTIME-EXTRA + L@ DUP _EXT4-RS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-RS-CTX @ _EXT4-C.R.MTIME-NS + !
        _EXT4-RS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-RS-CTX @ _EXT4-C.R.MTIME + +!
        _EXT4-RS-IN @ _EXT4-I.CTIME-EXTRA + L@ DUP _EXT4-RS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-RS-CTX @ _EXT4-C.R.CTIME-NS + !
        _EXT4-RS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-RS-CTX @ _EXT4-C.R.CTIME + +!
    THEN
    _EXT4-RS-IN @ _EXT4-I.FLAGS + L@ DUP 0x50300800 AND IF
        DROP EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-EXTENTS-FL AND IF
        _EXT4-RS-CTX @ _EXT4-VALIDATE-EXTENT-TREE
    ELSE
        _EXT4-RS-CTX @ _EXT4-VALIDATE-LEGACY-MAP
    THEN ;

VARIABLE _EXT4-RP-V
VARIABLE _EXT4-RP-CTX
VARIABLE _EXT4-RP-D
VARIABLE _EXT4-RP-VN

: _EXT4-PUBLISH-ROOT  ( ctx vfs -- )
    _EXT4-RP-V ! _EXT4-RP-CTX !
    _EXT4-RP-V @ V.ROOT @ DUP _EXT4-RP-D ! D.VNODE @ _EXT4-RP-VN !
    VFS-T-DIR _EXT4-RP-VN @ VN.TYPE !
    _EXT4-RP-CTX @ _EXT4-C.R.SIZE + @ _EXT4-RP-VN @ VN.SIZE-LO !
    0 _EXT4-RP-VN @ VN.SIZE-HI !
    _EXT4-RP-CTX @ _EXT4-C.R.MODE + @ _EXT4-RP-VN @ VN.MODE !
    _EXT4-RP-CTX @ _EXT4-C.R.UID + @ _EXT4-RP-VN @ VN.UID !
    _EXT4-RP-CTX @ _EXT4-C.R.GID + @ _EXT4-RP-VN @ VN.GID !
    _EXT4-RP-CTX @ _EXT4-C.R.NLINK + @ _EXT4-RP-VN @ VN.NLINK !
    2 _EXT4-RP-VN @ VN.BID !
    2 _EXT4-RP-VN @ VN.BDATA !
    0 _EXT4-RP-VN @ VN.BDATA 8 + !
    _EXT4-RP-CTX @ _EXT4-C.R.ATIME + @ _EXT4-RP-VN @ VN.ATIME !
    _EXT4-RP-CTX @ _EXT4-C.R.ATIME-NS + @ _EXT4-RP-VN @ VN.ATIME-NS !
    _EXT4-RP-CTX @ _EXT4-C.R.MTIME + @ _EXT4-RP-VN @ VN.MTIME !
    _EXT4-RP-CTX @ _EXT4-C.R.MTIME-NS + @ _EXT4-RP-VN @ VN.MTIME-NS !
    _EXT4-RP-CTX @ _EXT4-C.R.CTIME + @ _EXT4-RP-VN @ VN.CTIME !
    _EXT4-RP-CTX @ _EXT4-C.R.CTIME-NS + @ _EXT4-RP-VN @ VN.CTIME-NS !
    _EXT4-RP-CTX @ _EXT4-C.R.BLOCKS + @ _EXT4-RP-VN @ VN.BLOCKS !
    _EXT4-RP-CTX @ _EXT4-C.R.GEN + @ _EXT4-RP-VN @ VN.GEN !
    _EXT4-RP-CTX @ _EXT4-C.R.RDEV + @ _EXT4-RP-VN @ VN.RDEV ! ;

\ Decode the currently cached inode into the same staging cells used for
\ root publication.  The returned VFS type is not published until every
\ checksum, size, flag, and mapping check has succeeded.
VARIABLE _EXT4-MS-CTX
VARIABLE _EXT4-MS-IN
VARIABLE _EXT4-MS-TYPE
VARIABLE _EXT4-MS-MODE
VARIABLE _EXT4-MS-HI
VARIABLE _EXT4-MS-EXTRA
VARIABLE _EXT4-MS-FLAGS

VARIABLE _EXT4-FS-CTX
VARIABLE _EXT4-FS-IN
VARIABLE _EXT4-FS-EA-SECTORS

\ With EA_INODE refused, a fast symlink has no data sectors beyond the one
\ external xattr block, if present.  Keep staging, reads, and orphan
\ truncatability on this single storage-shape predicate.
: _EXT4-FAST-SYMLINK-STORAGE?  ( ctx type -- flag )
    VFS-T-SYMLINK <> IF DROP FALSE EXIT THEN
    DUP _EXT4-FS-CTX ! _EXT4-C.INODE + _EXT4-FS-IN !
    _EXT4-FS-IN @ _EXT4-I.FILE-ACL-HI + W@ IF FALSE EXIT THEN
    0 _EXT4-FS-EA-SECTORS !
    _EXT4-FS-IN @ _EXT4-I.FILE-ACL-LO + L@ IF
        _EXT4-FS-CTX @ _EXT4-C.SPB + @ _EXT4-FS-EA-SECTORS !
    THEN
    _EXT4-FS-CTX @ _EXT4-C.R.BLOCKS + @
    _EXT4-FS-EA-SECTORS @ = ;

: _EXT4-STAGE-CURRENT-INODE  ( ctx -- type ior )
    DUP _EXT4-MS-CTX ! _EXT4-C.INODE + _EXT4-MS-IN !
    _EXT4-MS-IN @ _EXT4-I.MODE + W@ DUP _EXT4-MS-MODE !
    0xF000 AND CASE
        0x8000 OF VFS-T-FILE    ENDOF
        0x4000 OF VFS-T-DIR     ENDOF
        0xA000 OF VFS-T-SYMLINK ENDOF
        0x1000 OF VFS-T-SPECIAL ENDOF
        0x2000 OF VFS-T-SPECIAL ENDOF
        0x6000 OF VFS-T-SPECIAL ENDOF
        0xC000 OF VFS-T-SPECIAL ENDOF
        DROP 0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
    ENDCASE DUP _EXT4-MS-TYPE ! DROP
    _EXT4-MS-MODE @ _EXT4-MS-CTX @ _EXT4-C.R.MODE + !
    _EXT4-MS-IN @ _EXT4-I.LINKS + W@ DUP 0= IF
        DROP 0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MS-CTX @ _EXT4-C.R.NLINK + !
    _EXT4-MS-IN @ _EXT4-I.SIZE-HI + L@ DUP _EXT4-MS-HI !
    0x80000000 AND IF 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MS-HI @ 32 LSHIFT _EXT4-MS-IN @ _EXT4-I.SIZE-LO + L@ OR
    _EXT4-MS-CTX @ _EXT4-C.R.SIZE + !
    _EXT4-MS-IN @ _EXT4-I.UID-HI + W@ 16 LSHIFT
    _EXT4-MS-IN @ _EXT4-I.UID-LO + W@ OR
    _EXT4-MS-CTX @ _EXT4-C.R.UID + !
    _EXT4-MS-IN @ _EXT4-I.GID-HI + W@ 16 LSHIFT
    _EXT4-MS-IN @ _EXT4-I.GID-LO + W@ OR
    _EXT4-MS-CTX @ _EXT4-C.R.GID + !
    _EXT4-MS-IN @ _EXT4-MS-CTX @ _EXT4-DECODE-I-BLOCKS
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-MS-CTX @ _EXT4-C.R.BLOCKS + !
    _EXT4-MS-IN @ _EXT4-I.FILE-ACL-HI + W@ IF
        0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MS-IN @ _EXT4-I.GENERATION + L@
    _EXT4-MS-CTX @ _EXT4-C.R.GEN + !
    0 _EXT4-MS-CTX @ _EXT4-C.R.RDEV + !
    _EXT4-MS-IN @ _EXT4-I.ATIME + _EXT4-S32@
    _EXT4-MS-CTX @ _EXT4-C.R.ATIME + !
    _EXT4-MS-IN @ _EXT4-I.MTIME + _EXT4-S32@
    _EXT4-MS-CTX @ _EXT4-C.R.MTIME + !
    _EXT4-MS-IN @ _EXT4-I.CTIME + _EXT4-S32@
    _EXT4-MS-CTX @ _EXT4-C.R.CTIME + !
    0 _EXT4-MS-CTX @ _EXT4-C.R.ATIME-NS + !
    0 _EXT4-MS-CTX @ _EXT4-C.R.MTIME-NS + !
    0 _EXT4-MS-CTX @ _EXT4-C.R.CTIME-NS + !
    _EXT4-MS-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-MS-IN @ _EXT4-I.EXTRA-SIZE + W@ 16 < IF
            0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-MS-IN @ _EXT4-I.ATIME-EXTRA + L@ DUP _EXT4-MS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP 0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-MS-CTX @ _EXT4-C.R.ATIME-NS + !
        _EXT4-MS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-MS-CTX @ _EXT4-C.R.ATIME + +!
        _EXT4-MS-IN @ _EXT4-I.MTIME-EXTRA + L@ DUP _EXT4-MS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP 0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-MS-CTX @ _EXT4-C.R.MTIME-NS + !
        _EXT4-MS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-MS-CTX @ _EXT4-C.R.MTIME + +!
        _EXT4-MS-IN @ _EXT4-I.CTIME-EXTRA + L@ DUP _EXT4-MS-EXTRA !
        2 RSHIFT DUP 1000000000 U< 0= IF
            DROP 0 EXT4-D-ROOT-INODE _EXT4-CORRUPT EXIT
        THEN _EXT4-MS-CTX @ _EXT4-C.R.CTIME-NS + !
        _EXT4-MS-EXTRA @ 3 AND 32 LSHIFT
        _EXT4-MS-CTX @ _EXT4-C.R.CTIME + +!
    THEN
    _EXT4-MS-IN @ _EXT4-I.FLAGS + L@ DUP _EXT4-MS-FLAGS !
    0x50300800 AND IF 0 EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT THEN
    _EXT4-MS-FLAGS @ _EXT4-INDEX-FL AND
    _EXT4-MS-TYPE @ VFS-T-DIR <> AND IF
        0 EXT4-D-FEATURE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MS-TYPE @ VFS-T-SPECIAL = IF
        _EXT4-MS-FLAGS @ _EXT4-EXTENTS-FL AND IF
            0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-MS-CTX @ _EXT4-DECODE-SPECIAL
        ?DUP IF NIP 0 SWAP EXIT THEN
        _EXT4-MS-CTX @ _EXT4-C.R.RDEV + !
        _EXT4-MS-TYPE @ 0 EXIT
    THEN
    _EXT4-MS-CTX @ _EXT4-MS-TYPE @ _EXT4-FAST-SYMLINK-STORAGE? IF
        _EXT4-MS-CTX @ _EXT4-C.R.SIZE + @ 60 U> IF
            0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-MS-TYPE @ 0 EXIT
    THEN
    _EXT4-MS-FLAGS @ _EXT4-EXTENTS-FL AND IF
        _EXT4-MS-CTX @ _EXT4-VALIDATE-EXTENT-TREE
    ELSE
        _EXT4-MS-CTX @ _EXT4-VALIDATE-LEGACY-MAP
    THEN
    DUP IF 0 SWAP EXIT THEN DROP
    _EXT4-MS-TYPE @ 0 ;

VARIABLE _EXT4-MP-CTX
VARIABLE _EXT4-MP-D
VARIABLE _EXT4-MP-TYPE
VARIABLE _EXT4-MP-VN

: _EXT4-PUBLISH-STAGED  ( ctx dentry type -- )
    _EXT4-MP-TYPE ! _EXT4-MP-D ! _EXT4-MP-CTX !
    _EXT4-MP-D @ D.VNODE @ _EXT4-MP-VN !
    _EXT4-MP-TYPE @ _EXT4-MP-VN @ VN.TYPE !
    _EXT4-MP-CTX @ _EXT4-C.R.SIZE + @ _EXT4-MP-VN @ VN.SIZE-LO !
    0 _EXT4-MP-VN @ VN.SIZE-HI !
    _EXT4-MP-CTX @ _EXT4-C.R.MODE + @ _EXT4-MP-VN @ VN.MODE !
    _EXT4-MP-CTX @ _EXT4-C.R.UID + @ _EXT4-MP-VN @ VN.UID !
    _EXT4-MP-CTX @ _EXT4-C.R.GID + @ _EXT4-MP-VN @ VN.GID !
    _EXT4-MP-CTX @ _EXT4-C.R.NLINK + @ _EXT4-MP-VN @ VN.NLINK !
    _EXT4-MP-D @ IN.BID @ _EXT4-MP-VN @ VN.BDATA !
    0 _EXT4-MP-VN @ VN.BDATA 8 + !
    _EXT4-MP-CTX @ _EXT4-C.R.ATIME + @ _EXT4-MP-VN @ VN.ATIME !
    _EXT4-MP-CTX @ _EXT4-C.R.ATIME-NS + @ _EXT4-MP-VN @ VN.ATIME-NS !
    _EXT4-MP-CTX @ _EXT4-C.R.MTIME + @ _EXT4-MP-VN @ VN.MTIME !
    _EXT4-MP-CTX @ _EXT4-C.R.MTIME-NS + @ _EXT4-MP-VN @ VN.MTIME-NS !
    _EXT4-MP-CTX @ _EXT4-C.R.CTIME + @ _EXT4-MP-VN @ VN.CTIME !
    _EXT4-MP-CTX @ _EXT4-C.R.CTIME-NS + @ _EXT4-MP-VN @ VN.CTIME-NS !
    _EXT4-MP-CTX @ _EXT4-C.R.BLOCKS + @ _EXT4-MP-VN @ VN.BLOCKS !
    _EXT4-MP-CTX @ _EXT4-C.R.GEN + @ _EXT4-MP-VN @ VN.GEN !
    _EXT4-MP-CTX @ _EXT4-C.R.RDEV + @ _EXT4-MP-VN @ VN.RDEV ! ;

\ =====================================================================
\  Checksummed linear directories and cache population
\ =====================================================================

VARIABLE _EXT4-DV-INO
VARIABLE _EXT4-DV-GEN
VARIABLE _EXT4-DV-CTX
VARIABLE _EXT4-DV-TAIL
VARIABLE _EXT4-DV-STORED

: _EXT4-VALIDATE-DIR-BLOCK  ( dir-inum generation ctx -- ior )
    _EXT4-DV-CTX ! _EXT4-DV-GEN ! _EXT4-DV-INO !
    _EXT4-DV-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-DV-CTX @ _EXT4-C.BSIZE + @ 12 - + DUP _EXT4-DV-TAIL !
    DUP L@ 0<>
    OVER 4 + W@ 12 <> OR
    OVER 6 + C@ 0<> OR
    OVER 7 + C@ 0xDE <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    8 + L@ _EXT4-DV-STORED !
    _EXT4-DV-INO @ _EXT4-DV-CTX @ _EXT4-C.TMP + L!
    _EXT4-DV-GEN @ _EXT4-DV-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-DV-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-DV-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-DV-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-DV-CTX @ _EXT4-C.BSIZE + @ 12 - _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-DV-STORED @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ =====================================================================
\  Checksummed HTree index blocks
\ =====================================================================

VARIABLE _EXT4-DX-CTX
VARIABLE _EXT4-DX-BUF
VARIABLE _EXT4-DX-ENTRY
VARIABLE _EXT4-DX-LIMIT
VARIABLE _EXT4-DX-COUNT
VARIABLE _EXT4-DX-EXPECTED-LIMIT
VARIABLE _EXT4-DX-DIR-BLOCKS
VARIABLE _EXT4-DX-PREV-HASH
VARIABLE _EXT4-DX-HASH
VARIABLE _EXT4-DX-BLOCK
VARIABLE _EXT4-DX-TAIL
VARIABLE _EXT4-DX-STORED
VARIABLE _EXT4-DX-LEVEL
VARIABLE _EXT4-DX-DIRINO
VARIABLE _EXT4-DX-PARINO
VARIABLE _EXT4-DX-GEN
VARIABLE _EXT4-DX-J

: _EXT4-VALIDATE-DX-ENTRIES  ( entry-base expected-limit dir-blocks ctx -- ior )
    _EXT4-DX-CTX ! _EXT4-DX-DIR-BLOCKS !
    _EXT4-DX-EXPECTED-LIMIT ! DUP _EXT4-DX-ENTRY !
    DUP W@ DUP _EXT4-DX-LIMIT ! _EXT4-DX-EXPECTED-LIMIT @ <> IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    2 + W@ DUP _EXT4-DX-COUNT !
    DUP 0= SWAP _EXT4-DX-LIMIT @ U> OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-DX-PREV-HASH !
    _EXT4-DX-COUNT @ 0 ?DO
        I IF
            _EXT4-DX-ENTRY @ I 8 * + L@ DUP _EXT4-DX-HASH !
            0xFFFFFFFE AND DUP _EXT4-DX-PREV-HASH @ U< IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
            THEN
            DUP _EXT4-DX-PREV-HASH @ =
            _EXT4-DX-HASH @ 1 AND 0= AND IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-DX-PREV-HASH !
        THEN
        _EXT4-DX-ENTRY @ I 8 * + 4 + L@ DUP
        0xFF000000 AND IF
            DROP EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
        THEN
        0x00FFFFFF AND DUP _EXT4-DX-BLOCK !
        DUP 0= SWAP _EXT4-DX-DIR-BLOCKS @ >= OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
        THEN
        0 _EXT4-DX-J !
        BEGIN _EXT4-DX-J @ I < WHILE
            _EXT4-DX-ENTRY @ I 8 * + 4 + L@ 0x00FFFFFF AND
            _EXT4-DX-ENTRY @ _EXT4-DX-J @ 8 * + 4 + L@
            0x00FFFFFF AND = IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-DX-J +!
        REPEAT
    LOOP 0 ;

: _EXT4-VALIDATE-DX-CHECKSUM  ( buffer entry-base ctx -- ior )
    _EXT4-DX-CTX ! _EXT4-DX-ENTRY ! _EXT4-DX-BUF !
    _EXT4-DX-ENTRY @ _EXT4-DX-LIMIT @ 8 * + DUP _EXT4-DX-TAIL !
    DUP _EXT4-DX-CTX @ _EXT4-C.BSIZE + @ _EXT4-DX-BUF @ + 8 - <> IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP L@ IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    4 + L@ _EXT4-DX-STORED !
    _EXT4-DX-DIRINO @ _EXT4-DX-CTX @ _EXT4-C.TMP + L!
    _EXT4-DX-GEN @ _EXT4-DX-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-DX-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-DX-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-DX-BUF @
    _EXT4-DX-ENTRY @ _EXT4-DX-BUF @ - _EXT4-DX-COUNT @ 8 * +
    _EXT4-CRC-ADD ?DUP IF EXIT THEN
    0 _EXT4-DX-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-DX-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-DX-CTX @ _EXT4-C.TMP 8 + + 8 _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-DX-STORED @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-VALIDATE-DX-ROOT  ( ctx dir-blocks -- ior )
    _EXT4-DX-DIR-BLOCKS ! DUP _EXT4-DX-CTX !
    _EXT4-C.DIR-BLOCK + DUP _EXT4-DX-BUF !
    DUP L@ _EXT4-DX-DIRINO @ <>
    OVER 4 + W@ 12 <> OR
    OVER 6 + C@ 1 <> OR
    OVER 7 + C@ 2 <> OR
    OVER 8 + C@ [CHAR] . <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP 12 + L@ _EXT4-DX-PARINO @ <>
    OVER 16 + W@ _EXT4-DX-CTX @ _EXT4-C.BSIZE + @ 12 - <> OR
    OVER 18 + C@ 2 <> OR
    OVER 19 + C@ 2 <> OR
    OVER 20 + C@ [CHAR] . <> OR
    OVER 21 + C@ [CHAR] . <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP 24 + L@ IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    DUP 28 + C@ 1 <>
    OVER 29 + C@ 8 <> OR
    OVER 31 + C@ 0<> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP 30 + C@ DUP _EXT4-DX-LEVEL ! 1 U> IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    32 +
    _EXT4-DX-CTX @ _EXT4-C.BSIZE + @ 40 - 8 /
    _EXT4-DX-DIR-BLOCKS @ _EXT4-DX-CTX @
    _EXT4-VALIDATE-DX-ENTRIES ?DUP IF EXIT THEN
    _EXT4-DX-BUF @ _EXT4-DX-ENTRY @ _EXT4-DX-CTX @
    _EXT4-VALIDATE-DX-CHECKSUM ;

: _EXT4-DX-NODE?  ( ctx -- flag )
    DUP _EXT4-DX-CTX ! _EXT4-C.DIR-BLOCK + _EXT4-DX-BUF !
    _EXT4-DX-BUF @ L@ 0=
    _EXT4-DX-BUF @ 4 + W@ _EXT4-DX-CTX @ _EXT4-C.BSIZE + @ = AND
    _EXT4-DX-BUF @ 6 + C@ 0= AND
    _EXT4-DX-BUF @ 7 + C@ 0= AND ;

: _EXT4-VALIDATE-DX-NODE  ( ctx dir-blocks -- ior )
    _EXT4-DX-DIR-BLOCKS ! DUP _EXT4-DX-CTX !
    _EXT4-C.DIR-BLOCK + DUP _EXT4-DX-BUF ! 8 +
    _EXT4-DX-CTX @ _EXT4-C.BSIZE + @ 16 - 8 /
    _EXT4-DX-DIR-BLOCKS @ _EXT4-DX-CTX @
    _EXT4-VALIDATE-DX-ENTRIES ?DUP IF EXIT THEN
    _EXT4-DX-BUF @ _EXT4-DX-ENTRY @ _EXT4-DX-CTX @
    _EXT4-VALIDATE-DX-CHECKSUM ;

VARIABLE _EXT4-DS-PARENT
VARIABLE _EXT4-DS-V
VARIABLE _EXT4-DS-CTX
VARIABLE _EXT4-DS-DIRINO
VARIABLE _EXT4-DS-PARINO
VARIABLE _EXT4-DS-GEN
VARIABLE _EXT4-DS-OFF
VARIABLE _EXT4-DS-LIMIT
VARIABLE _EXT4-DS-DE
VARIABLE _EXT4-DS-REC
VARIABLE _EXT4-DS-NLEN
VARIABLE _EXT4-DS-CINO
VARIABLE _EXT4-DS-DTYPE
VARIABLE _EXT4-DS-TYPE
VARIABLE _EXT4-DS-DENTRY
VARIABLE _EXT4-DS-IOR
VARIABLE _EXT4-DS-DOT
VARIABLE _EXT4-DS-DOTDOT

: _EXT4-DIRENT>TYPE  ( dtype -- type supported? )
    CASE
        0 OF 0 TRUE          ENDOF
        1 OF VFS-T-FILE TRUE ENDOF
        2 OF VFS-T-DIR TRUE  ENDOF
        3 OF VFS-T-SPECIAL TRUE ENDOF
        4 OF VFS-T-SPECIAL TRUE ENDOF
        5 OF VFS-T-SPECIAL TRUE ENDOF
        6 OF VFS-T-SPECIAL TRUE ENDOF
        7 OF VFS-T-SYMLINK TRUE ENDOF
        0 FALSE ROT
    ENDCASE ;

: _EXT4-DIRENT-NAME-VALID?  ( addr len -- flag )
    0 ?DO
        DUP I + C@ DUP 0= SWAP [CHAR] / = OR IF
            DROP FALSE UNLOOP EXIT
        THEN
    LOOP DROP TRUE ;

: _EXT4-SCAN-DIR-BLOCK  ( parent vfs ctx -- ior )
    _EXT4-DS-CTX ! _EXT4-DS-V ! _EXT4-DS-PARENT !
    _EXT4-DS-PARENT @ IN.BID @ _EXT4-DS-DIRINO !
    _EXT4-DS-PARENT @ IN.PARENT @ ?DUP IF IN.BID @ ELSE
        _EXT4-DS-DIRINO @
    THEN _EXT4-DS-PARINO !
    _EXT4-DS-PARENT @ D.VNODE @ VN.GEN @ _EXT4-DS-GEN !
    _EXT4-DS-DIRINO @ _EXT4-DS-GEN @ _EXT4-DS-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    0 _EXT4-DS-OFF !
    _EXT4-DS-CTX @ _EXT4-C.BSIZE + @ 12 - _EXT4-DS-LIMIT !
    BEGIN _EXT4-DS-OFF @ _EXT4-DS-LIMIT @ < WHILE
        _EXT4-DS-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-DS-OFF @ +
        _EXT4-DS-DE !
        _EXT4-DS-DE @ 4 + W@ _EXT4-DS-REC !
        _EXT4-DS-REC @ 8 < _EXT4-DS-REC @ 3 AND 0<> OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _EXT4-DS-OFF @ _EXT4-DS-REC @ + _EXT4-DS-LIMIT @ > IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _EXT4-DS-DE @ 6 + C@ DUP _EXT4-DS-NLEN !
        _EXT4-DS-REC @ 8 - U> IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
        _EXT4-DS-DE @ L@ DUP _EXT4-DS-CINO ! IF
            _EXT4-DS-CINO @ _EXT4-DS-CTX @ _EXT4-C.INODES + @ > IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _EXT4-DS-DE @ 8 + _EXT4-DS-NLEN @
            _EXT4-DIRENT-NAME-VALID? 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _EXT4-DS-NLEN @ 1 =
            _EXT4-DS-DE @ 8 + C@ [CHAR] . = AND IF
                _EXT4-DS-CINO @ _EXT4-DS-DIRINO @ <> IF
                    EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                THEN
                _EXT4-DS-DOT @ IF
                    EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                THEN
                -1 _EXT4-DS-DOT !
            ELSE
                _EXT4-DS-NLEN @ 2 =
                _EXT4-DS-DE @ 8 + C@ [CHAR] . = AND
                _EXT4-DS-DE @ 9 + C@ [CHAR] . = AND IF
                    _EXT4-DS-CINO @ _EXT4-DS-PARINO @ <> IF
                        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-DS-DOTDOT @ IF
                        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN
                    -1 _EXT4-DS-DOTDOT !
                ELSE
                    _EXT4-DS-NLEN @ 0= IF
                        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-DS-DE @ 7 + C@ DUP _EXT4-DS-DTYPE !
                    _EXT4-DIRENT>TYPE 0= IF
                        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN _EXT4-DS-TYPE !
                    _EXT4-DS-CINO @ _EXT4-DS-CTX @ _EXT4-LOAD-INODE
                    ?DUP IF EXIT THEN
                    _EXT4-DS-CTX @ _EXT4-STAGE-CURRENT-INODE
                    _EXT4-DS-IOR ! _EXT4-DS-TYPE !
                    _EXT4-DS-IOR @ ?DUP IF EXIT THEN
                    _EXT4-DS-DTYPE @ IF
                        _EXT4-DS-TYPE @
                        _EXT4-DS-DTYPE @ _EXT4-DIRENT>TYPE DROP <> IF
                            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                        THEN
                    THEN
                    _EXT4-DS-DE @ 8 + _EXT4-DS-NLEN @
                    _EXT4-DS-TYPE @ _EXT4-DS-CINO @
                    _EXT4-DS-CTX @ _EXT4-C.R.GEN + @
                    _EXT4-DS-PARENT @ _EXT4-DS-V @ VFS-CACHE-DENTRY
                    _EXT4-DS-IOR ! _EXT4-DS-DENTRY !
                    _EXT4-DS-IOR @ ?DUP IF EXIT THEN
                    _EXT4-DS-CTX @ _EXT4-DS-DENTRY @ _EXT4-DS-TYPE @
                    _EXT4-PUBLISH-STAGED
                THEN
            THEN
        THEN
        _EXT4-DS-REC @ _EXT4-DS-OFF +!
    REPEAT
    _EXT4-DS-OFF @ _EXT4-DS-LIMIT @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-RD-PARENT
VARIABLE _EXT4-RD-V
VARIABLE _EXT4-RD-CTX
VARIABLE _EXT4-RD-SIZE
VARIABLE _EXT4-RD-BLOCKS
VARIABLE _EXT4-RD-PHYS
VARIABLE _EXT4-RD-PRESENT
VARIABLE _EXT4-RD-IOR
VARIABLE _EXT4-RD-OLD-CHILD
VARIABLE _EXT4-RD-OLD-COUNT
VARIABLE _EXT4-RD-OLD-STR
VARIABLE _EXT4-RD-NODE-EXPECTED
VARIABLE _EXT4-RD-NODE-SEEN
VARIABLE _EXT4-RD-LEAF-EXPECTED
VARIABLE _EXT4-RD-LEAF-SEEN

: _EXT4-RD-ROLLBACK  ( -- )
    BEGIN
        _EXT4-RD-PARENT @ IN.CHILD @ DUP _EXT4-RD-OLD-CHILD @ <>
    WHILE
        DUP _EXT4-RD-PARENT @ _VFS-REMOVE-CHILD
        FALSE _EXT4-RD-V @ _VFS-DENTRY-RELEASE
    REPEAT DROP
    _EXT4-RD-OLD-COUNT @ _EXT4-RD-V @ V.ICOUNT !
    _EXT4-RD-OLD-STR @ _EXT4-RD-V @ V.STR-PTR ! ;

: _EXT4-RD-LOAD-LOGICAL  ( logical-block -- ior )
    _EXT4-RD-PARENT @ IN.BID @ _EXT4-RD-CTX @ _EXT4-LOAD-INODE
    ?DUP IF NIP EXIT THEN
    _EXT4-RD-CTX @ _EXT4-MAP-BLOCK
    _EXT4-RD-IOR ! _EXT4-RD-PRESENT ! _EXT4-RD-PHYS !
    _EXT4-RD-IOR @ ?DUP IF EXIT THEN
    _EXT4-RD-PRESENT @ 0= IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _EXT4-RD-PHYS @ _EXT4-RD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-RD-CTX @ _EXT4-C.BLOCK +
    _EXT4-RD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RD-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 ;

: _EXT4-READDIR-LINEAR  ( -- ior )
    0 _EXT4-DS-DOT ! 0 _EXT4-DS-DOTDOT !
    _EXT4-RD-BLOCKS @ 0 ?DO
        I _EXT4-RD-LOAD-LOGICAL ?DUP IF UNLOOP EXIT THEN
        _EXT4-RD-PARENT @ _EXT4-RD-V @ _EXT4-RD-CTX @
        _EXT4-SCAN-DIR-BLOCK ?DUP IF UNLOOP EXIT THEN
    LOOP
    _EXT4-DS-DOT @ 0= _EXT4-DS-DOTDOT @ 0= OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-READDIR-HTREE  ( -- ior )
    _EXT4-RD-PARENT @ IN.BID @ _EXT4-DX-DIRINO !
    _EXT4-RD-PARENT @ IN.PARENT @ ?DUP IF IN.BID @ ELSE
        _EXT4-DX-DIRINO @
    THEN
    _EXT4-DX-PARINO !
    _EXT4-RD-PARENT @ D.VNODE @ VN.GEN @ _EXT4-DX-GEN !
    0 _EXT4-RD-LOAD-LOGICAL ?DUP IF EXIT THEN
    _EXT4-RD-CTX @ _EXT4-RD-BLOCKS @ _EXT4-VALIDATE-DX-ROOT
    ?DUP IF EXIT THEN
    -1 _EXT4-DS-DOT ! -1 _EXT4-DS-DOTDOT !
    0 _EXT4-RD-NODE-SEEN ! 0 _EXT4-RD-LEAF-SEEN !
    _EXT4-DX-LEVEL @ IF
        _EXT4-DX-COUNT @ _EXT4-RD-NODE-EXPECTED !
        0 _EXT4-RD-LEAF-EXPECTED !
    ELSE
        0 _EXT4-RD-NODE-EXPECTED !
        _EXT4-DX-COUNT @ _EXT4-RD-LEAF-EXPECTED !
    THEN
    _EXT4-RD-BLOCKS @ 1 ?DO
        I _EXT4-RD-LOAD-LOGICAL ?DUP IF UNLOOP EXIT THEN
        _EXT4-RD-CTX @ _EXT4-DX-NODE? IF
            _EXT4-DX-LEVEL @ 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-RD-CTX @ _EXT4-RD-BLOCKS @ _EXT4-VALIDATE-DX-NODE
            ?DUP IF UNLOOP EXIT THEN
            1 _EXT4-RD-NODE-SEEN +!
            _EXT4-RD-LEAF-EXPECTED @ _EXT4-DX-COUNT @ + DUP
            _EXT4-RD-LEAF-EXPECTED @ U< IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT UNLOOP EXIT
            THEN _EXT4-RD-LEAF-EXPECTED !
        ELSE
            1 _EXT4-RD-LEAF-SEEN +!
            _EXT4-RD-PARENT @ _EXT4-RD-V @ _EXT4-RD-CTX @
            _EXT4-SCAN-DIR-BLOCK ?DUP IF UNLOOP EXIT THEN
        THEN
    LOOP
    _EXT4-RD-NODE-SEEN @ _EXT4-RD-NODE-EXPECTED @ <>
    _EXT4-RD-LEAF-SEEN @ _EXT4-RD-LEAF-EXPECTED @ <> OR
    _EXT4-RD-NODE-SEEN @ _EXT4-RD-LEAF-SEEN @ + 1+
        _EXT4-RD-BLOCKS @ <> OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-READDIR-WORK  ( -- ior )
    _EXT4-RD-PARENT @ IN.BID @ _EXT4-RD-CTX @ _EXT4-LOAD-INODE
    ?DUP IF EXIT THEN
    _EXT4-RD-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-RD-IOR ! DUP VFS-T-DIR <> IF
        DROP _EXT4-RD-IOR @ ?DUP IF EXIT THEN VFS-E-NOTDIR EXIT
    THEN DROP
    _EXT4-RD-IOR @ ?DUP IF EXIT THEN
    _EXT4-RD-CTX @ _EXT4-C.R.SIZE + @ DUP _EXT4-RD-SIZE !
    DUP 0= IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    DUP 0x7FFFFFFF U> IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-RD-CTX @ _EXT4-C.BSIZE + @ MOD IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RD-CTX @ _EXT4-C.BSIZE + @ 1- +
    _EXT4-RD-CTX @ _EXT4-C.BSIZE + @ / DUP _EXT4-RD-BLOCKS !
    DROP
    _EXT4-RD-CTX @ _EXT4-C.INODE + _EXT4-I.FLAGS + L@
    _EXT4-INDEX-FL AND IF
        _EXT4-READDIR-HTREE
    ELSE
        _EXT4-READDIR-LINEAR
    THEN
    ;

: _EXT4-READDIR  ( directory vfs -- ior )
    DUP _EXT4-READY? 0= IF 2DROP VFS-E-BUSY EXIT THEN
    _EXT4-RD-V ! _EXT4-RD-PARENT !
    _EXT4-RD-V @ _EXT4-CTX _EXT4-RD-CTX !
    _EXT4-RD-PARENT @ IN.CHILD @ _EXT4-RD-OLD-CHILD !
    _EXT4-RD-V @ V.ICOUNT @ _EXT4-RD-OLD-COUNT !
    _EXT4-RD-V @ V.STR-PTR @ _EXT4-RD-OLD-STR !
    _EXT4-RD-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-RD-V @ _EXT4-IO-VFS !
    _EXT4-READDIR-WORK DUP IF _EXT4-RD-ROLLBACK THEN ;

\ =====================================================================
\  Read-only file and symlink data operations
\ =====================================================================

: _EXT4-PARTIAL-IOR  ( actual ior -- actual ior )
    DUP IF OVER 0> IF VFS-IOR-F-PARTIAL 24 LSHIFT OR THEN THEN ;

VARIABLE _EXT4-DR-BUF
VARIABLE _EXT4-DR-LEN
VARIABLE _EXT4-DR-OFF
VARIABLE _EXT4-DR-IN
VARIABLE _EXT4-DR-V
VARIABLE _EXT4-DR-CTX
VARIABLE _EXT4-DR-TYPE
VARIABLE _EXT4-DR-IOR
VARIABLE _EXT4-DR-REM
VARIABLE _EXT4-DR-ACT
VARIABLE _EXT4-DR-LBLOCK
VARIABLE _EXT4-DR-BOFF
VARIABLE _EXT4-DR-CHUNK
VARIABLE _EXT4-DR-PHYS
VARIABLE _EXT4-DR-PRESENT

: _EXT4-READ-DATA-WORK  ( -- ior )
    _EXT4-DR-IN @ IN.BID @ _EXT4-DR-CTX @ _EXT4-LOAD-INODE
    ?DUP IF EXIT THEN
    _EXT4-DR-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-DR-IOR ! _EXT4-DR-TYPE !
    _EXT4-DR-IOR @ ?DUP IF EXIT THEN
    _EXT4-DR-TYPE @ VFS-T-DIR = IF VFS-E-ISDIR EXIT THEN
    _EXT4-DR-TYPE @ VFS-T-SPECIAL = IF VFS-E-UNSUPPORTED EXIT THEN
    _EXT4-DR-OFF @ _EXT4-DR-CTX @ _EXT4-C.R.SIZE + @ >= IF 0 EXIT THEN
    _EXT4-DR-CTX @ _EXT4-C.R.SIZE + @ _EXT4-DR-OFF @ -
    _EXT4-DR-LEN @ MIN _EXT4-DR-REM !
    _EXT4-DR-CTX @ _EXT4-DR-TYPE @ _EXT4-FAST-SYMLINK-STORAGE? IF
        _EXT4-DR-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK +
        _EXT4-DR-OFF @ + _EXT4-DR-BUF @ _EXT4-DR-REM @ CMOVE
        _EXT4-DR-REM @ _EXT4-DR-ACT +!
        0 EXIT
    THEN
    BEGIN _EXT4-DR-REM @ 0> WHILE
        _EXT4-DR-OFF @ _EXT4-DR-CTX @ _EXT4-C.BSIZE + @ /MOD
        _EXT4-DR-LBLOCK ! _EXT4-DR-BOFF !
        _EXT4-DR-CTX @ _EXT4-C.BSIZE + @ _EXT4-DR-BOFF @ -
        _EXT4-DR-REM @ MIN _EXT4-DR-CHUNK !
        _EXT4-DR-LBLOCK @ _EXT4-DR-CTX @ _EXT4-MAP-BLOCK
        _EXT4-DR-IOR ! _EXT4-DR-PRESENT ! _EXT4-DR-PHYS !
        _EXT4-DR-IOR @ ?DUP IF EXIT THEN
        _EXT4-DR-PRESENT @ IF
            _EXT4-DR-PHYS @ _EXT4-DR-CTX @ _EXT4-READ-BLOCK
            ?DUP IF EXIT THEN
            _EXT4-DR-CTX @ _EXT4-C.BLOCK + _EXT4-DR-BOFF @ +
            _EXT4-DR-BUF @ _EXT4-DR-CHUNK @ CMOVE
        ELSE
            _EXT4-DR-BUF @ _EXT4-DR-CHUNK @ 0 FILL
        THEN
        _EXT4-DR-CHUNK @ DUP _EXT4-DR-ACT +!
        DUP _EXT4-DR-BUF +!
        DUP _EXT4-DR-OFF +!
        NEGATE _EXT4-DR-REM +!
    REPEAT
    0 ;

: _EXT4-READ  ( buffer len offset dentry vfs -- actual ior )
    DUP _EXT4-READY? 0= IF 2DROP 2DROP DROP 0 VFS-E-BUSY EXIT THEN
    _EXT4-DR-V ! _EXT4-DR-IN ! _EXT4-DR-OFF !
    _EXT4-DR-LEN ! _EXT4-DR-BUF !
    _EXT4-DR-OFF @ 0< _EXT4-DR-LEN @ 0< OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-DR-V @ _EXT4-CTX _EXT4-DR-CTX !
    _EXT4-DR-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-DR-V @ _EXT4-IO-VFS !
    0 _EXT4-DR-ACT !
    _EXT4-READ-DATA-WORK _EXT4-DR-IOR !
    _EXT4-DR-ACT @ _EXT4-DR-IOR @ _EXT4-PARTIAL-IOR ;

: _EXT4-OPEN  ( dentry vfs -- cookie ior )
    DUP _EXT4-READY? 0= IF 2DROP 0 VFS-E-BUSY EXIT THEN
    DROP DUP IN.TYPE @ VFS-T-SPECIAL = IF DROP 0 VFS-E-UNSUPPORTED EXIT THEN
    DUP D.VNODE @ VN.GEN @ 32 LSHIFT SWAP IN.BID @ OR 0 ;

: _EXT4-RELEASE  ( cookie dentry vfs -- ior )  DROP 2DROP 0 ;

VARIABLE _EXT4-RL-BUF
VARIABLE _EXT4-RL-CAP
VARIABLE _EXT4-RL-IN
VARIABLE _EXT4-RL-V

: _EXT4-READLINK  ( buffer capacity dentry vfs -- actual ior )
    _EXT4-RL-V ! _EXT4-RL-IN ! _EXT4-RL-CAP ! _EXT4-RL-BUF !
    _EXT4-RL-CAP @ 0= IF
        _EXT4-RL-IN @ IN.SIZE-LO @ 0 EXIT
    THEN
    _EXT4-RL-BUF @ _EXT4-RL-CAP @ 0
    _EXT4-RL-IN @ _EXT4-RL-V @ _EXT4-READ ;

\ =====================================================================
\  In-inode and external-block namespaced xattrs
\ =====================================================================

0xEA020000 CONSTANT _EXT4-XATTR-MAGIC
1024 CONSTANT _EXT4-XATTR-REFCOUNT-MAX

VARIABLE _EXT4-XC-CTX
VARIABLE _EXT4-XC-BLOCK
VARIABLE _EXT4-XC-BUF

\ Restamp one already authenticated external-xattr block after changing only
\ checksum-covered header state.  ext4's metadata checksum covers the 64-bit
\ physical block number followed by the complete block with h_checksum zero.
: _EXT4-STAMP-XATTR-BLOCK  ( buffer physical-block ctx -- ior )
    _EXT4-XC-CTX ! _EXT4-XC-BLOCK ! _EXT4-XC-BUF !
    0 _EXT4-XC-BUF @ 0x10 + L!
    _EXT4-XC-BLOCK @ _EXT4-XC-CTX @ _EXT4-C.TMP + L!
    0 _EXT4-XC-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-XC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-XC-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-XC-BUF @ _EXT4-XC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-XC-BUF @ 0x10 + L! 0 ;

VARIABLE _EXT4-XB-CTX
VARIABLE _EXT4-XB-BLOCK
VARIABLE _EXT4-XB-BUF
VARIABLE _EXT4-XB-STORED

: _EXT4-LOAD-XATTR-BLOCK  ( physical-block ctx -- ior )
    _EXT4-XB-CTX ! DUP _EXT4-XB-BLOCK !
    _EXT4-XB-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-XB-CTX @ _EXT4-C.BLOCK + DUP _EXT4-XB-BUF !
    DUP L@ _EXT4-XATTR-MAGIC <>
    OVER 4 + L@ 0= OR
    OVER 8 + L@ 1 <> OR
    OVER 0x14 + L@ 0<> OR
    OVER 0x18 + L@ 0<> OR
    OVER 0x1C + L@ 0<> OR IF
        DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
    THEN
    DUP 0x10 + L@ _EXT4-XB-STORED !
    0 SWAP 0x10 + L!
    _EXT4-XB-BLOCK @ _EXT4-XB-CTX @ _EXT4-C.TMP + L!
    0 _EXT4-XB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-XB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-XB-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF
        _EXT4-XB-STORED @ _EXT4-XB-BUF @ 0x10 + L! EXIT
    THEN
    _EXT4-XB-BUF @ _EXT4-XB-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF
        _EXT4-XB-STORED @ _EXT4-XB-BUF @ 0x10 + L! EXIT
    THEN
    _EXT4-XB-STORED @ _EXT4-XB-BUF @ 0x10 + L!
    _EXT4-CRC@ _EXT4-XB-STORED @ <> IF
        EXT4-D-XATTR _EXT4-CORRUPT EXIT
    THEN
    0 ;

1 CONSTANT _EXT4-XOP-LIST
2 CONSTANT _EXT4-XOP-GET

VARIABLE _EXT4-XA-OP
VARIABLE _EXT4-XA-CTX
VARIABLE _EXT4-XA-ENTRY
VARIABLE _EXT4-XA-LIMIT
VARIABLE _EXT4-XA-VBASE
VARIABLE _EXT4-XA-VLIMIT
VARIABLE _EXT4-XA-NLEN
VARIABLE _EXT4-XA-ESIZE
VARIABLE _EXT4-XA-VOFF
VARIABLE _EXT4-XA-VSIZE
VARIABLE _EXT4-XA-TOTAL
VARIABLE _EXT4-XA-OUT
VARIABLE _EXT4-XA-EMIT
VARIABLE _EXT4-XA-FOUND
VARIABLE _EXT4-XA-REQ-A
VARIABLE _EXT4-XA-REQ-U
VARIABLE _EXT4-XA-CAP
VARIABLE _EXT4-XA-IOR
VARIABLE _EXT4-XA-INDEX
VARIABLE _EXT4-XA-PREFIX-A
VARIABLE _EXT4-XA-PREFIX-U
VARIABLE _EXT4-XA-FIXED
VARIABLE _EXT4-XA-FIRST
VARIABLE _EXT4-XA-PREV
VARIABLE _EXT4-XA-MIN-VALUE
VARIABLE _EXT4-XA-VSTART
VARIABLE _EXT4-XA-VEND
VARIABLE _EXT4-XA-SCAN
VARIABLE _EXT4-XA-INLINE-FIRST
VARIABLE _EXT4-XA-INLINE-LIMIT
VARIABLE _EXT4-XA-CROSS
VARIABLE _EXT4-XA-FOUND-SIZE
VARIABLE _EXT4-XA-CMP-PREV
VARIABLE _EXT4-XA-CMP-CURR

: _EXT4-XA-SELECT-NS  ( index -- supported? )
    DUP _EXT4-XA-INDEX !
    DUP 1 = IF DROP S" user." _EXT4-XA-PREFIX-U ! _EXT4-XA-PREFIX-A !
        0 _EXT4-XA-FIXED ! TRUE EXIT THEN
    DUP 2 = IF DROP S" system.posix_acl_access"
        _EXT4-XA-PREFIX-U ! _EXT4-XA-PREFIX-A !
        -1 _EXT4-XA-FIXED ! TRUE EXIT THEN
    DUP 3 = IF DROP S" system.posix_acl_default"
        _EXT4-XA-PREFIX-U ! _EXT4-XA-PREFIX-A !
        -1 _EXT4-XA-FIXED ! TRUE EXIT THEN
    DUP 4 = IF DROP S" trusted." _EXT4-XA-PREFIX-U ! _EXT4-XA-PREFIX-A !
        0 _EXT4-XA-FIXED ! TRUE EXIT THEN
    6 = IF S" security." _EXT4-XA-PREFIX-U ! _EXT4-XA-PREFIX-A !
        0 _EXT4-XA-FIXED ! TRUE EXIT THEN
    FALSE ;

: _EXT4-XA-KEY=  ( first second -- flag )
    2DUP 1+ C@ SWAP 1+ C@ <> IF 2DROP FALSE EXIT THEN
    2DUP C@ SWAP C@ <> IF 2DROP FALSE EXIT THEN
    DUP C@ >R 16 + SWAP 16 + R> _EXT4-BYTES=? ;

: _EXT4-XA-ORDERED-AFTER?  ( previous current -- flag )
    _EXT4-XA-CMP-CURR ! _EXT4-XA-CMP-PREV !
    _EXT4-XA-CMP-PREV @ 1+ C@ _EXT4-XA-CMP-CURR @ 1+ C@
    2DUP U< IF 2DROP TRUE EXIT THEN
    U> IF FALSE EXIT THEN
    _EXT4-XA-CMP-PREV @ C@ _EXT4-XA-CMP-CURR @ C@
    2DUP U< IF 2DROP TRUE EXIT THEN
    U> IF FALSE EXIT THEN
    _EXT4-XA-CMP-PREV @ C@ 0 ?DO
        _EXT4-XA-CMP-PREV @ I 16 + + C@
        _EXT4-XA-CMP-CURR @ I 16 + + C@
        2DUP U< IF
            2DROP TRUE UNLOOP EXIT
        THEN
        U> IF FALSE UNLOOP EXIT THEN
    LOOP FALSE ;

: _EXT4-XA-NAME-MATCH?  ( entry -- flag )
    _EXT4-XA-FIXED @ IF
        C@ 0<> IF FALSE EXIT THEN
        _EXT4-XA-REQ-U @ _EXT4-XA-PREFIX-U @ =
        _EXT4-XA-REQ-A @ _EXT4-XA-PREFIX-A @ _EXT4-XA-PREFIX-U @
        _EXT4-BYTES=? AND EXIT
    THEN
    _EXT4-XA-REQ-U @ _EXT4-XA-PREFIX-U @ _EXT4-XA-NLEN @ + <> IF
        DROP FALSE EXIT
    THEN
    _EXT4-XA-REQ-A @ _EXT4-XA-PREFIX-A @ _EXT4-XA-PREFIX-U @
    _EXT4-BYTES=? 0= IF DROP FALSE EXIT THEN
    16 + _EXT4-XA-REQ-A @ _EXT4-XA-PREFIX-U @ +
    _EXT4-XA-NLEN @ _EXT4-BYTES=? ;

: _EXT4-XA-EMIT-NAME  ( entry -- )
    _EXT4-XA-PREFIX-A @ _EXT4-XA-OUT @ _EXT4-XA-PREFIX-U @ CMOVE
    _EXT4-XA-FIXED @ 0= IF
        16 + _EXT4-XA-OUT @ _EXT4-XA-PREFIX-U @ +
        _EXT4-XA-NLEN @ CMOVE
    ELSE DROP THEN
    0 _EXT4-XA-OUT @ _EXT4-XA-PREFIX-U @ _EXT4-XA-NLEN @ + + C!
    _EXT4-XA-PREFIX-U @ _EXT4-XA-NLEN @ + 1+ _EXT4-XA-OUT +! ;

: _EXT4-XA-OVERLAPS-PRIOR?  ( -- flag )
    _EXT4-XA-FIRST @ _EXT4-XA-SCAN !
    BEGIN _EXT4-XA-SCAN @ _EXT4-XA-ENTRY @ < WHILE
        _EXT4-XA-SCAN @ 8 + L@ ?DUP IF
            _EXT4-XA-VBASE @ _EXT4-XA-SCAN @ 2 + W@ + DUP
            ROT +
            _EXT4-XA-VSTART @ U>
            SWAP _EXT4-XA-VEND @ U< AND IF TRUE EXIT THEN
        THEN
        _EXT4-XA-SCAN @ C@ 16 + 3 + 3 INVERT AND _EXT4-XA-SCAN +!
    REPEAT FALSE ;

: _EXT4-XA-INLINE-DUP?  ( external-entry -- flag )
    _EXT4-XA-INLINE-FIRST @ DUP 0= IF 2DROP FALSE EXIT THEN
    _EXT4-XA-SCAN !
    BEGIN _EXT4-XA-SCAN @ 4 + _EXT4-XA-INLINE-LIMIT @ <= WHILE
        _EXT4-XA-SCAN @ L@ 0= IF DROP FALSE EXIT THEN
        DUP _EXT4-XA-SCAN @ _EXT4-XA-KEY= IF DROP TRUE EXIT THEN
        _EXT4-XA-SCAN @ C@ 16 + 3 + 3 INVERT AND _EXT4-XA-SCAN +!
    REPEAT DROP FALSE ;

\ The entry walker is split from the area setup so both LIST passes and GET
\ use one exact structural parser.  A zero u32 terminates the packed entries.
: _EXT4-XA-WALK  ( -- ior )
    _EXT4-XA-ENTRY @ _EXT4-XA-FIRST !
    0 _EXT4-XA-PREV !
    _EXT4-XA-VLIMIT @ _EXT4-XA-MIN-VALUE !
    BEGIN
        _EXT4-XA-ENTRY @ 4 + _EXT4-XA-LIMIT @ > IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-XA-ENTRY @ L@ 0= IF
            _EXT4-XA-ENTRY @ 4 + _EXT4-XA-MIN-VALUE @ U> IF
                EXT4-D-XATTR _EXT4-CORRUPT EXIT
            THEN 0 EXIT
        THEN
        _EXT4-XA-ENTRY @ 16 + _EXT4-XA-LIMIT @ > IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-XA-ENTRY @ C@ _EXT4-XA-NLEN !
        _EXT4-XA-ENTRY @ 1+ C@ _EXT4-XA-SELECT-NS 0= IF
            EXT4-D-XATTR _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-XA-FIXED @ IF
            _EXT4-XA-NLEN @ IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN
        ELSE _EXT4-XA-NLEN @ 0= IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN THEN
        _EXT4-XA-PREV @ IF
            _EXT4-XA-PREV @ _EXT4-XA-ENTRY @ _EXT4-XA-ORDERED-AFTER? 0= IF
                EXT4-D-XATTR _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-XA-CROSS @ IF
            _EXT4-XA-ENTRY @ _EXT4-XA-INLINE-DUP? IF
                EXT4-D-XATTR _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-XA-NLEN @ 16 + 3 + 3 INVERT AND DUP _EXT4-XA-ESIZE !
        _EXT4-XA-ENTRY @ + _EXT4-XA-LIMIT @ > IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-XA-ENTRY @ 4 + L@ IF
            EXT4-D-XATTR _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-XA-ENTRY @ 2 + W@ _EXT4-XA-VOFF !
        _EXT4-XA-ENTRY @ 8 + L@ _EXT4-XA-VSIZE !
        _EXT4-XA-VSIZE @ IF
            _EXT4-XA-VOFF @ 3 AND IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN
            _EXT4-XA-VBASE @ _EXT4-XA-VOFF @ + DUP _EXT4-XA-VSTART !
            DUP _EXT4-XA-VBASE @ U< IF
                DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
            THEN
            _EXT4-XA-VSIZE @ + DUP _EXT4-XA-VEND !
            DUP _EXT4-XA-VLIMIT @ U> IF
                DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
            THEN DROP
            _EXT4-XA-OVERLAPS-PRIOR? IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN
            _EXT4-XA-VSTART @ _EXT4-XA-MIN-VALUE @ U< IF
                _EXT4-XA-VSTART @ _EXT4-XA-MIN-VALUE !
            THEN
        ELSE
            _EXT4-XA-VOFF @ IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN
        THEN
        _EXT4-XA-OP @ _EXT4-XOP-LIST = IF
            _EXT4-XA-PREFIX-U @ _EXT4-XA-NLEN @ + 1+ _EXT4-XA-TOTAL +!
            _EXT4-XA-EMIT @ IF _EXT4-XA-ENTRY @ _EXT4-XA-EMIT-NAME THEN
        ELSE
            _EXT4-XA-ENTRY @ _EXT4-XA-NAME-MATCH? IF
                _EXT4-XA-FOUND @ IF EXT4-D-XATTR _EXT4-CORRUPT EXIT THEN
                -1 _EXT4-XA-FOUND !
                _EXT4-XA-VSIZE @ _EXT4-XA-FOUND-SIZE !
                _EXT4-XA-VSIZE @ _EXT4-XA-CAP @ > IF
                    _EXT4-XA-CAP @ IF VFS-E-OVERFLOW _EXT4-XA-IOR ! THEN
                ELSE _EXT4-XA-CAP @ IF
                    _EXT4-XA-VBASE @ _EXT4-XA-VOFF @ +
                    _EXT4-XA-OUT @ _EXT4-XA-VSIZE @ CMOVE
                THEN
                THEN
            THEN
        THEN
        _EXT4-XA-ENTRY @ _EXT4-XA-PREV !
        _EXT4-XA-ESIZE @ _EXT4-XA-ENTRY +!
    AGAIN ;

: _EXT4-XA-INLINE  ( ctx -- ior )
    DUP _EXT4-XA-CTX ! _EXT4-C.ISIZE + @ 128 <= IF 0 EXIT THEN
    _EXT4-XA-CTX @ _EXT4-C.INODE + _EXT4-I.EXTRA-SIZE + W@
    128 + _EXT4-XA-CTX @ _EXT4-C.INODE + +
    DUP 4 + _EXT4-XA-CTX @ _EXT4-C.INODE +
        _EXT4-XA-CTX @ _EXT4-C.ISIZE + @ + > IF
        DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
    THEN
    DUP L@ 0= IF DROP 0 EXIT THEN
    DUP L@ _EXT4-XATTR-MAGIC <> IF
        DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
    THEN
    4 + DUP _EXT4-XA-ENTRY ! DUP _EXT4-XA-VBASE !
    _EXT4-XA-INLINE-FIRST !
    _EXT4-XA-CTX @ _EXT4-C.INODE +
    _EXT4-XA-CTX @ _EXT4-C.ISIZE + @ +
    DUP _EXT4-XA-LIMIT ! DUP _EXT4-XA-VLIMIT !
    _EXT4-XA-INLINE-LIMIT !
    _EXT4-XA-WALK ;

: _EXT4-XA-EXTERNAL  ( ctx -- ior )
    DUP _EXT4-XA-CTX !
    _EXT4-C.INODE + DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ DUP 0= IF DROP 0 EXIT THEN
    DUP EXT4-D-XATTR _EXT4-XA-CTX @ _EXT4-REQUIRE-ALLOCATED-BLOCK
    ?DUP IF NIP EXIT THEN
    _EXT4-XA-CTX @ _EXT4-LOAD-XATTR-BLOCK ?DUP IF EXIT THEN
    _EXT4-XA-CTX @ _EXT4-C.BLOCK + DUP
    32 + _EXT4-XA-ENTRY !
    DUP _EXT4-XA-VBASE !
    _EXT4-XA-CTX @ _EXT4-C.BSIZE + @ + DUP
    _EXT4-XA-LIMIT ! _EXT4-XA-VLIMIT !
    _EXT4-XA-WALK ;

: _EXT4-XA-SCAN-BOTH  ( ctx -- ior )
    0 _EXT4-XA-INLINE-FIRST ! 0 _EXT4-XA-INLINE-LIMIT !
    0 _EXT4-XA-CROSS !
    DUP _EXT4-XA-INLINE ?DUP IF NIP EXIT THEN
    -1 _EXT4-XA-CROSS !
    _EXT4-XA-EXTERNAL ;

VARIABLE _EXT4-LX-BUF
VARIABLE _EXT4-LX-CAP
VARIABLE _EXT4-LX-IN
VARIABLE _EXT4-LX-V
VARIABLE _EXT4-LX-CTX

: _EXT4-LISTXATTR  ( buffer capacity dentry vfs -- actual ior )
    _EXT4-LX-V ! _EXT4-LX-IN ! _EXT4-LX-CAP ! _EXT4-LX-BUF !
    _EXT4-LX-V @ _EXT4-CTX _EXT4-LX-CTX !
    _EXT4-LX-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-LX-V @ _EXT4-IO-VFS !
    _EXT4-LX-IN @ IN.BID @ _EXT4-LX-CTX @ _EXT4-LOAD-INODE
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _EXT4-LX-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF 0 SWAP EXIT THEN
    _EXT4-LX-CAP @ 0= IF _EXT4-XA-TOTAL @ 0 EXIT THEN
    _EXT4-XA-TOTAL @ _EXT4-LX-CAP @ > IF 0 VFS-E-OVERFLOW EXIT THEN
    _EXT4-LX-BUF @ _EXT4-XA-OUT ! -1 _EXT4-XA-EMIT !
    0 _EXT4-XA-TOTAL !
    _EXT4-LX-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF 0 SWAP EXIT THEN
    _EXT4-XA-TOTAL @ 0 ;

VARIABLE _EXT4-GX-NA
VARIABLE _EXT4-GX-NU
VARIABLE _EXT4-GX-BUF
VARIABLE _EXT4-GX-CAP
VARIABLE _EXT4-GX-IN
VARIABLE _EXT4-GX-V
VARIABLE _EXT4-GX-CTX

: _EXT4-GETXATTR  ( name-a name-u buffer capacity dentry vfs -- actual ior )
    _EXT4-GX-V ! _EXT4-GX-IN ! _EXT4-GX-CAP ! _EXT4-GX-BUF !
    _EXT4-GX-NU ! _EXT4-GX-NA !
    _EXT4-GX-V @ _EXT4-CTX _EXT4-GX-CTX !
    _EXT4-GX-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-GX-V @ _EXT4-IO-VFS !
    _EXT4-GX-IN @ IN.BID @ _EXT4-GX-CTX @ _EXT4-LOAD-INODE
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-XOP-GET _EXT4-XA-OP !
    _EXT4-GX-NA @ _EXT4-XA-REQ-A ! _EXT4-GX-NU @ _EXT4-XA-REQ-U !
    _EXT4-GX-BUF @ _EXT4-XA-OUT ! _EXT4-GX-CAP @ _EXT4-XA-CAP !
    0 _EXT4-XA-FOUND ! 0 _EXT4-XA-FOUND-SIZE ! 0 _EXT4-XA-IOR !
    _EXT4-GX-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF 0 SWAP EXIT THEN
    _EXT4-XA-FOUND @ 0= IF 0 VFS-E-NOENT EXIT THEN
    _EXT4-XA-IOR @ ?DUP IF 0 SWAP EXIT THEN
    _EXT4-XA-FOUND-SIZE @ 0 ;

\ =====================================================================
\  Modern orphan-file block authentication
\ =====================================================================

VARIABLE _EXT4-OV-CTX
VARIABLE _EXT4-OV-INO
VARIABLE _EXT4-OV-IN
VARIABLE _EXT4-OV-GEN
VARIABLE _EXT4-OV-BLOCKS
VARIABLE _EXT4-OV-LOGICAL
VARIABLE _EXT4-OV-PHYS
VARIABLE _EXT4-OV-PRESENT
VARIABLE _EXT4-OV-IOR
VARIABLE _EXT4-OV-TAIL
VARIABLE _EXT4-OV-STORED
VARIABLE _EXT4-OV-HI
VARIABLE _EXT4-OV-SIZE
VARIABLE _EXT4-OV-DEPTH

: _EXT4-PREPARE-ORPHAN-FILE  ( ctx -- ior )
    DUP _EXT4-OV-CTX ! _EXT4-C.ORPHAN-INO + @ DUP _EXT4-OV-INO !
    _EXT4-OV-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-OV-CTX @ _EXT4-C.INODE + DUP _EXT4-OV-IN !
    _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-IN @ _EXT4-I.SIZE-HI + L@ DUP _EXT4-OV-HI !
    0x80000000 AND IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-OV-HI @ 32 LSHIFT
    _EXT4-OV-IN @ _EXT4-I.SIZE-LO + L@ OR DUP _EXT4-OV-SIZE !
    DUP 0= IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-OV-CTX @ _EXT4-C.BSIZE + @ MOD IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-CTX @ _EXT4-C.BSIZE + @ / DUP
    _EXT4-OV-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-BLOCKS !
    _EXT4-OV-IN @ _EXT4-I.GENERATION + L@ _EXT4-OV-GEN !
    \ Recovery mutation is qualified only for extent depth zero/one.  Validate
    \ the complete wider read-profile map before the policy clamp so malformed
    \ depth-two-through-five or legacy authority remains corrupt rather than
    \ being mislabeled unsupported.
    _EXT4-OV-IN @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND IF
        _EXT4-OV-IN @ _EXT4-I.BLOCK + 6 + W@ _EXT4-OV-DEPTH !
        _EXT4-OV-CTX @ _EXT4-VALIDATE-EXTENT-TREE ?DUP IF EXIT THEN
        _EXT4-OV-DEPTH @ 1 U> IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        0
    ELSE
        _EXT4-OV-CTX @ _EXT4-VALIDATE-LEGACY-MAP ?DUP IF EXIT THEN
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED
    THEN ;

\ Read one mapped orphan-file block and authenticate its physical-location-
\ bound tail.  The caller consumes entries before the next media read.
: _EXT4-READ-ORPHAN-BLOCK  ( logical-block ctx -- ior )
    _EXT4-OV-CTX ! DUP _EXT4-OV-LOGICAL !
    _EXT4-OV-BLOCKS @ U< 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-LOGICAL @ _EXT4-OV-CTX @ _EXT4-MAP-BLOCK
    _EXT4-OV-IOR ! _EXT4-OV-PRESENT ! _EXT4-OV-PHYS !
    _EXT4-OV-IOR @ ?DUP IF EXIT THEN
    _EXT4-OV-PRESENT @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-PHYS @ _EXT4-OV-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-CTX @ _EXT4-C.BLOCK +
    _EXT4-OV-CTX @ _EXT4-C.BSIZE + @ 8 - + DUP _EXT4-OV-TAIL !
    DUP L@ _EXT4-ORPHAN-MAGIC <> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    4 + L@ _EXT4-OV-STORED !
    _EXT4-OV-INO @ _EXT4-OV-CTX @ _EXT4-C.TMP + L!
    _EXT4-OV-GEN @ _EXT4-OV-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-OV-PHYS @ _EXT4-OV-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-OV-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-OV-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-OV-CTX @ _EXT4-C.TMP + 16 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-OV-CTX @ _EXT4-C.BLOCK +
    _EXT4-OV-CTX @ _EXT4-C.BSIZE + @ 8 - _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-OV-STORED @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ =====================================================================
\  Internal JBD2 validation and checksum-v3/64-bit replay
\ =====================================================================

VARIABLE _EXT4-BE-A
VARIABLE _EXT4-BE-V

: _EXT4-BE32@  ( addr -- u )
    _EXT4-BE-A !
    _EXT4-BE-A @ C@ 24 LSHIFT
    _EXT4-BE-A @ 1+ C@ 16 LSHIFT OR
    _EXT4-BE-A @ 2 + C@ 8 LSHIFT OR
    _EXT4-BE-A @ 3 + C@ OR ;

: _EXT4-BE32!  ( u addr -- )
    _EXT4-BE-A ! 0xFFFFFFFF AND _EXT4-BE-V !
    _EXT4-BE-V @ 24 RSHIFT _EXT4-BE-A @ C!
    _EXT4-BE-V @ 16 RSHIFT _EXT4-BE-A @ 1+ C!
    _EXT4-BE-V @ 8 RSHIFT _EXT4-BE-A @ 2 + C!
    _EXT4-BE-V @ _EXT4-BE-A @ 3 + C! ;

VARIABLE _EXT4-JC-BUF
VARIABLE _EXT4-JC-CTX
VARIABLE _EXT4-JC-FIELD
VARIABLE _EXT4-JC-STORED
VARIABLE _EXT4-JC-CALC

: _EXT4-JBD2-BLOCK-CHECKSUM?  ( buffer ctx -- flag ior )
    _EXT4-JC-CTX ! _EXT4-JC-BUF !
    _EXT4-JC-BUF @ _EXT4-JC-CTX @ _EXT4-C.BSIZE + @ 4 - +
    DUP _EXT4-JC-FIELD ! _EXT4-BE32@ _EXT4-JC-STORED !
    0 _EXT4-JC-FIELD @ _EXT4-BE32!
    _EXT4-JC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JC-BUF @ _EXT4-JC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF
        _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32! 0 SWAP EXIT
    THEN
    _EXT4-CRC@ _EXT4-JC-CALC !
    _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32!
    _EXT4-JC-CALC @ _EXT4-JC-STORED @ = 0 ;

: _EXT4-JBD2-SUPER-CHECKSUM?  ( buffer -- flag ior )
    DUP _EXT4-JC-BUF ! _EXT4-JS.CHECKSUM + DUP
    _EXT4-JC-FIELD ! _EXT4-BE32@ _EXT4-JC-STORED !
    0 _EXT4-JC-FIELD @ _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JC-BUF @ 1024 _EXT4-CRC-ADD ?DUP IF
        _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32! 0 SWAP EXIT
    THEN
    _EXT4-CRC@ _EXT4-JC-CALC !
    _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32!
    _EXT4-JC-CALC @ _EXT4-JC-STORED @ = 0 ;

: _EXT4-JBD2-COMMIT-CHECKSUM?  ( buffer ctx -- flag ior )
    _EXT4-JC-CTX ! DUP _EXT4-JC-BUF !
    DUP 12 + C@ OVER 13 + C@ OR
    OVER 14 + C@ OR SWAP 15 + C@ OR IF FALSE 0 EXIT THEN
    7 0 DO
        _EXT4-JC-BUF @ 20 + I 4 * + _EXT4-BE32@ IF
            FALSE 0 UNLOOP EXIT
        THEN
    LOOP
    _EXT4-JC-BUF @ 56 + _EXT4-BE32@ 1000000000 U< 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-JC-BUF @ 16 + DUP _EXT4-JC-FIELD !
    _EXT4-BE32@ _EXT4-JC-STORED !
    0 _EXT4-JC-FIELD @ _EXT4-BE32!
    _EXT4-JC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JC-BUF @ _EXT4-JC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF
        _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32! 0 SWAP EXIT
    THEN
    _EXT4-CRC@ _EXT4-JC-CALC !
    _EXT4-JC-STORED @ _EXT4-JC-FIELD @ _EXT4-BE32!
    _EXT4-JC-CALC @ _EXT4-JC-STORED @ = 0 ;

VARIABLE _EXT4-JV-CTX
VARIABLE _EXT4-JV-IN
VARIABLE _EXT4-JV-SIZE
VARIABLE _EXT4-JV-JSB
VARIABLE _EXT4-JV-FEATURES
VARIABLE _EXT4-JV-START
VARIABLE _EXT4-JV-MAP-KEY
VARIABLE _EXT4-JV-MAP-SLOT
VARIABLE _EXT4-JW-CTX
VARIABLE _EXT4-JW-MAXLEN
VARIABLE _EXT4-JW-SLOTS
VARIABLE _EXT4-JW-MAP-BYTES
VARIABLE _EXT4-JW-BYTES
VARIABLE _EXT4-JRW-CTX
VARIABLE _EXT4-JRW-COUNT
VARIABLE _EXT4-JRW-SLOTS
VARIABLE _EXT4-JRW-BYTES

-1 1 RSHIFT 2 CELLS / CONSTANT _EXT4-REVOKE-SLOTS-MAX

\ Recovery workspace survives a failed mount so the same VFS can retry
\ without leaking arena storage.  Treat only the completely empty geometry
\ or a bounded power-of-two table as valid persisted state.
: _EXT4-REVOKE-GEOMETRY?  ( ctx -- flag )
    DUP _EXT4-C.J.REVOKE-TABLE + @
    SWAP _EXT4-C.J.REVOKE-SLOTS + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 2 U< IF 2DROP FALSE EXIT THEN
    DUP _EXT4-REVOKE-SLOTS-MAX U> IF 2DROP FALSE EXIT THEN
    DUP 1- AND 0= NIP ;

\ Allocate the exact journal snapshot and a power-of-two uniqueness table at
\ no more than one-half load.  These are arena capacity, not format limits.
\ A failed mount may be retried on the same VFS, so an existing allocation is
\ accepted only when its complete geometry matches the journal inode exactly.
: _EXT4-ENSURE-JOURNAL-WORKSPACE  ( maxlen ctx -- ior )
    _EXT4-JW-CTX ! DUP _EXT4-JW-MAXLEN !
    DUP 0= IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP 0xFFFFFFFF U> IF
        DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    DROP
    1 _EXT4-JW-SLOTS !
    BEGIN
        _EXT4-JW-SLOTS @ _EXT4-JW-MAXLEN @ 2* U<
    WHILE
        _EXT4-JW-SLOTS @ 2* _EXT4-JW-SLOTS !
    REPEAT
    _EXT4-JW-MAXLEN @ CELLS _EXT4-JW-MAP-BYTES !
    _EXT4-JW-MAP-BYTES @ _EXT4-JW-SLOTS @ CELLS +
    DUP _EXT4-JW-BYTES ! _EXT4-JW-MAP-BYTES @ U< IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JW-CTX @ _EXT4-C.J.MAP + @ IF
        _EXT4-JW-CTX @ _EXT4-C.J.MAP-CAPACITY + @
        _EXT4-JW-MAXLEN @ =
        _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @
        _EXT4-JW-SLOTS @ = AND
        _EXT4-JW-CTX @ _EXT4-C.J.MAP + @ _EXT4-JW-MAP-BYTES @ +
        _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH + @ = AND IF
            0 EXIT
        THEN
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH + @
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-CAPACITY + @ OR
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JW-CTX @ _EXT4-C.ARENA + @
    _EXT4-JW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-JW-CTX @ _EXT4-C.J.MAP + !
    _EXT4-JW-MAP-BYTES @ +
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH + !
    _EXT4-JW-MAXLEN @
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-CAPACITY + !
    _EXT4-JW-SLOTS @
    _EXT4-JW-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + !
    0 ;

\ Revoke recovery needs the latest committed transaction ID for each home
\ block.  Size an open-addressed table from the exact number of committed
\ on-disk records found by preflight.  A half-full power-of-two table makes
\ lookup bounded without imposing a journal-size policy.  One binding reuses
\ its first recovery allocation on retry rather than leaking monotonic arena
\ storage; a writer must negotiate separate transaction workspace.
: _EXT4-ENSURE-REVOKE-WORKSPACE  ( count ctx -- ior )
    _EXT4-JRW-CTX ! DUP _EXT4-JRW-COUNT !
    DROP
    0 _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-READY + !
    _EXT4-JRW-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JRW-COUNT @ -1 1 RSHIFT 2 / U> IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    0 _EXT4-JRW-SLOTS !
    _EXT4-JRW-COUNT @ IF
        1 _EXT4-JRW-SLOTS !
        BEGIN
            _EXT4-JRW-SLOTS @ _EXT4-JRW-COUNT @ 2* U<
        WHILE
            _EXT4-JRW-SLOTS @
            _EXT4-REVOKE-SLOTS-MAX 2 / U> IF
                EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
            THEN
            _EXT4-JRW-SLOTS @ 2* _EXT4-JRW-SLOTS !
        REPEAT
    THEN
    _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-TABLE + @ IF
        _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-SLOTS + @
        _EXT4-JRW-SLOTS @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-TABLE + @
        _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 2* CELLS
        0 FILL
        0 EXIT
    THEN
    _EXT4-JRW-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-JRW-SLOTS @ _EXT4-REVOKE-SLOTS-MAX U> IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JRW-SLOTS @ 2* CELLS _EXT4-JRW-BYTES !
    _EXT4-JRW-CTX @ _EXT4-C.ARENA + @
    _EXT4-JRW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-TABLE + !
    _EXT4-JRW-BYTES @ 0 FILL
    _EXT4-JRW-SLOTS @
    _EXT4-JRW-CTX @ _EXT4-C.J.REVOKE-SLOTS + !
    0 ;

VARIABLE _EXT4-JRH-BLOCK
VARIABLE _EXT4-JRH-SEQUENCE
VARIABLE _EXT4-JRH-CTX
VARIABLE _EXT4-JRH-KEY
VARIABLE _EXT4-JRH-SLOT
VARIABLE _EXT4-JRH-ENTRY

: _EXT4-JOURNAL-TID-AFTER?  ( candidate previous -- flag )
    - 0xFFFFFFFF AND DUP 0<> SWAP 0x80000000 U< AND ;

: _EXT4-REVOKE-ENTRY  ( slot ctx -- entry )
    _EXT4-C.J.REVOKE-TABLE + @ SWAP 2* CELLS + ;

: _EXT4-REVOKE-PUT  ( block sequence ctx -- ior )
    _EXT4-JRH-CTX ! _EXT4-JRH-SEQUENCE ! _EXT4-JRH-BLOCK !
    _EXT4-JRH-BLOCK @ _EXT4-JRH-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JRH-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-TABLE + @ 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JRH-BLOCK @ 1+ _EXT4-JRH-KEY !
    _EXT4-JRH-BLOCK @
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 1- AND
    _EXT4-JRH-SLOT !
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 0 DO
        _EXT4-JRH-SLOT @ _EXT4-JRH-CTX @ _EXT4-REVOKE-ENTRY
        DUP _EXT4-JRH-ENTRY ! @ DUP 0= IF
            DROP
            _EXT4-JRH-KEY @ _EXT4-JRH-ENTRY @ !
            _EXT4-JRH-SEQUENCE @ _EXT4-JRH-ENTRY @ CELL+ !
            0 UNLOOP EXIT
        THEN
        _EXT4-JRH-KEY @ = IF
            _EXT4-JRH-SEQUENCE @
            _EXT4-JRH-ENTRY @ CELL+ @ _EXT4-JOURNAL-TID-AFTER? IF
                _EXT4-JRH-SEQUENCE @ _EXT4-JRH-ENTRY @ CELL+ !
            THEN
            0 UNLOOP EXIT
        THEN
        _EXT4-JRH-SLOT @ 1+
        _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 1- AND
        _EXT4-JRH-SLOT !
    LOOP
    EXT4-D-JOURNAL _EXT4-CORRUPT ;

: _EXT4-JOURNAL-REVOKED?  ( block sequence ctx -- flag )
    _EXT4-JRH-CTX ! _EXT4-JRH-SEQUENCE ! _EXT4-JRH-BLOCK !
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-TABLE + @ 0= IF
        FALSE EXIT
    THEN
    _EXT4-JRH-BLOCK @ 1+ _EXT4-JRH-KEY !
    _EXT4-JRH-BLOCK @
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 1- AND
    _EXT4-JRH-SLOT !
    _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 0 DO
        _EXT4-JRH-SLOT @ _EXT4-JRH-CTX @ _EXT4-REVOKE-ENTRY
        DUP @ DUP 0= IF 2DROP FALSE UNLOOP EXIT THEN
        _EXT4-JRH-KEY @ = IF
            CELL+ @ _EXT4-JRH-SEQUENCE @ SWAP
            _EXT4-JOURNAL-TID-AFTER? 0= UNLOOP EXIT
        THEN
        DROP
        _EXT4-JRH-SLOT @ 1+
        _EXT4-JRH-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ 1- AND
        _EXT4-JRH-SLOT !
    LOOP
    FALSE ;

: _EXT4-JOURNAL-MAP@  ( logical ctx -- physical )
    _EXT4-C.J.MAP + @ SWAP CELLS + @ ;

: _EXT4-JOURNAL-MAP-UNIQUE?  ( physical ctx -- flag )
    _EXT4-JV-CTX ! DUP _EXT4-JV-MAP-KEY !
    _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 1- AND
    _EXT4-JV-MAP-SLOT !
    _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 0 DO
        _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH + @
        _EXT4-JV-MAP-SLOT @ CELLS + DUP @ DUP 0= IF
            DROP _EXT4-JV-MAP-KEY @ SWAP ! TRUE UNLOOP EXIT
        THEN
        _EXT4-JV-MAP-KEY @ = IF DROP FALSE UNLOOP EXIT THEN
        DROP
        _EXT4-JV-MAP-SLOT @ 1+
        _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 1- AND
        _EXT4-JV-MAP-SLOT !
    LOOP
    FALSE ;

VARIABLE _EXT4-JM-CTX
VARIABLE _EXT4-JM-ENTRY
VARIABLE _EXT4-JM-LOGICAL
VARIABLE _EXT4-JM-LEN
VARIABLE _EXT4-JM-RAWLEN
VARIABLE _EXT4-JM-PHYS
VARIABLE _EXT4-JM-I
VARIABLE _EXT4-JP-LOGICAL
VARIABLE _EXT4-JP-PHYS
VARIABLE _EXT4-JP-SLOT
VARIABLE _EXT4-RAB-BLOCK
VARIABLE _EXT4-RAB-CTX

: _EXT4-PRIMARY-SUPER-BLOCK  ( ctx -- block )
    _EXT4-C.BSIZE + @ 1024 = IF 1 ELSE 0 THEN ;

: _EXT4-PRIMARY-SUPER-OFF  ( ctx -- offset )
    _EXT4-C.BSIZE + @ 1024 = IF 0 ELSE 1024 THEN ;

: _EXT4-RECOVERY-FROZEN-BLOCK?  ( physical ctx -- flag )
    _EXT4-RAB-CTX ! _EXT4-RAB-BLOCK !
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.WITNESS-SUPER-BLOCK + @ =
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.WITNESS-GDT-BLOCK + @ >=
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.WITNESS-GDT-BLOCK + @
        _EXT4-RAB-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ + U< AND OR ;

: _EXT4-RECOVERY-AUTHORITY-BLOCK?  ( physical ctx -- flag )
    _EXT4-RAB-CTX ! DUP _EXT4-RAB-BLOCK !
    _EXT4-RAB-CTX @ _EXT4-RECOVERY-FROZEN-BLOCK?
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = OR
    _EXT4-RAB-BLOCK @ _EXT4-RAB-CTX @ _EXT4-GDT-BASE >=
    _EXT4-RAB-BLOCK @ _EXT4-RAB-CTX @ _EXT4-GDT-BASE
        _EXT4-RAB-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ + U< AND OR
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ = OR
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.BLOCK-BITMAP-BLOCK + @ = OR
    _EXT4-RAB-BLOCK @
        _EXT4-RAB-CTX @ _EXT4-C.J.INODE-TABLE-BLOCK + @ = OR ;

: _EXT4-JOURNAL-MAP-PUT  ( logical physical -- ior )
    _EXT4-JP-PHYS ! _EXT4-JP-LOGICAL !
    _EXT4-JP-LOGICAL @ _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JP-PHYS @ 0=
    _EXT4-JP-PHYS @ _EXT4-JM-CTX @ _EXT4-C.BLOCKS + @ U< 0= OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JP-PHYS @ _EXT4-JM-CTX @
    _EXT4-RECOVERY-AUTHORITY-BLOCK? IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JM-CTX @ _EXT4-C.J.MAP + @
    _EXT4-JP-LOGICAL @ CELLS + DUP _EXT4-JP-SLOT ! @ IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JP-PHYS @ _EXT4-JM-CTX @
    _EXT4-JOURNAL-MAP-UNIQUE? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JP-PHYS @ _EXT4-JP-SLOT @ !
    0 ;

: _EXT4-SNAPSHOT-EXTENT-LEAF  ( header -- ior )
    DUP 2 + W@ 0 ?DO
        DUP 12 I 12 * + + DUP _EXT4-JM-ENTRY !
        L@ _EXT4-JM-LOGICAL !
        _EXT4-JM-ENTRY @ 4 + W@ DUP _EXT4-JM-RAWLEN !
        DUP 32768 > IF 32768 - THEN _EXT4-JM-LEN !
        _EXT4-JM-ENTRY @ 6 + W@ IF
            DROP EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JM-RAWLEN @ 32768 > 0= IF
            _EXT4-JM-LOGICAL @
            _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @ U< IF
                _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @
                _EXT4-JM-LOGICAL @ - _EXT4-JM-LEN @ MIN
                _EXT4-JM-LEN !
                _EXT4-JM-ENTRY @ 8 + L@ _EXT4-JM-PHYS !
                0 _EXT4-JM-I !
                BEGIN _EXT4-JM-I @ _EXT4-JM-LEN @ < WHILE
                    _EXT4-JM-LOGICAL @ _EXT4-JM-I @ +
                    _EXT4-JM-PHYS @ _EXT4-JM-I @ +
                    _EXT4-JOURNAL-MAP-PUT ?DUP IF
                        >R DROP R> UNLOOP EXIT
                    THEN
                    1 _EXT4-JM-I +!
                REPEAT
            THEN
        THEN
    LOOP
    DROP 0 ;

: _EXT4-SNAPSHOT-JOURNAL-MAP  ( ctx -- ior )
    DUP _EXT4-JV-CTX ! _EXT4-JM-CTX !
    _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @ _EXT4-JM-CTX @
    _EXT4-ENSURE-JOURNAL-WORKSPACE ?DUP IF EXIT THEN
    _EXT4-JM-CTX @ _EXT4-C.J.MAP + @
    _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @ CELLS 0 FILL
    _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH + @
    _EXT4-JV-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ CELLS 0 FILL
    _EXT4-JM-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB.JOURNAL-BLOCKS + _EXT4-SNAPSHOT-EXTENT-LEAF
    ?DUP IF EXIT THEN
    _EXT4-JM-CTX @ _EXT4-C.J.MAXLEN + @ 0 DO
        I _EXT4-JM-CTX @ _EXT4-JOURNAL-MAP@ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    0 ;

VARIABLE _EXT4-JR-LOGICAL
VARIABLE _EXT4-JR-CTX

: _EXT4-READ-JBLOCK  ( logical ctx -- ior )
    _EXT4-JR-CTX ! DUP _EXT4-JR-LOGICAL !
    _EXT4-JR-CTX @ 0= IF DROP VFS-E-INVALID EXIT THEN
    _EXT4-JR-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JR-LOGICAL @ _EXT4-JR-CTX @ _EXT4-JOURNAL-MAP@
    _EXT4-JR-CTX @ _EXT4-READ-BLOCK ;

VARIABLE _EXT4-JWB-BUF

: _EXT4-WRITE-JBLOCK  ( buffer logical ctx -- ior )
    _EXT4-JR-CTX ! _EXT4-JR-LOGICAL ! _EXT4-JWB-BUF !
    _EXT4-JR-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JWB-BUF @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JR-LOGICAL @
    _EXT4-JR-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JWB-BUF @
    _EXT4-JR-LOGICAL @ _EXT4-JR-CTX @ _EXT4-JOURNAL-MAP@
    _EXT4-JR-CTX @ _EXT4-WRITE-BLOCK ;

VARIABLE _EXT4-JH-CTX

: _EXT4-JOURNAL-DATA?  ( physical ctx -- flag )
    _EXT4-JH-CTX ! DUP _EXT4-JV-MAP-KEY !
    _EXT4-JH-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 1- AND
    _EXT4-JV-MAP-SLOT !
    _EXT4-JH-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 0 DO
        _EXT4-JH-CTX @ _EXT4-C.J.MAP-HASH + @
        _EXT4-JV-MAP-SLOT @ CELLS + @ DUP 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        _EXT4-JV-MAP-KEY @ = IF TRUE UNLOOP EXIT THEN
        _EXT4-JV-MAP-SLOT @ 1+
        _EXT4-JH-CTX @ _EXT4-C.J.MAP-HASH-SLOTS + @ 1- AND
        _EXT4-JV-MAP-SLOT !
    LOOP
    FALSE ;

VARIABLE _EXT4-JA-BUF
VARIABLE _EXT4-JA-CTX
VARIABLE _EXT4-JA-LOGICAL
VARIABLE _EXT4-JA-EXPECTED
VARIABLE _EXT4-JA-ANCHOR
VARIABLE _EXT4-JA-FEATURES
VARIABLE _EXT4-JA-LOCATED
VARIABLE _EXT4-JA-CLEANUP
VARIABLE _EXT4-JA-MAGIC
VARIABLE _EXT4-JA-OLD-FEATURES
VARIABLE _EXT4-JA-PREFIX-OK
VARIABLE _EXT4-JZ-BUF
VARIABLE _EXT4-PM-NEW
VARIABLE _EXT4-PM-OLD
VARIABLE _EXT4-PM-TORN
VARIABLE _EXT4-PM-LEN
VARIABLE _EXT4-PM-OLD-PHASE
VARIABLE _EXT4-AR-BUF

\ AKR1 uses the six activation-private words as three value/complement pairs
\ so its checksummed anchor can authenticate the exact predecessor of a torn
\ primary write.  AKG1 names an active predecessor; AKE1 names an empty one.
\ The stored full-block CRC also covers padding above the 1024-byte JBD2
\ superblock on 2 KiB and 4 KiB journals.  An all-zero tuple remains a valid
\ witnessed anchor but cannot authorize predecessor-prefix reconstruction.
: _EXT4-JBD2-RESET-PREDECESSOR?  ( buffer -- flag )
    _EXT4-AR-BUF !
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@ DUP
    0= IF
        DROP
        _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32@
        _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@ OR
        _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32@ OR
        _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32@ OR
        _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32@ OR
        0= EXIT
    THEN
    DUP _EXT4-JBD2-ACTIVE-RESET-MAGIC =
    OVER _EXT4-JBD2-EMPTY-RESET-MAGIC = OR 0= IF
        DROP FALSE EXIT
    THEN
    INVERT 0xFFFFFFFF AND
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32@
    <> IF FALSE EXIT THEN
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@ DUP
    INVERT 0xFFFFFFFF AND
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32@
    <> IF DROP FALSE EXIT THEN DROP
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32@ DUP
    INVERT 0xFFFFFFFF AND
    _EXT4-AR-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32@
    = NIP ;

: _EXT4-JBD2-WITNESS?  ( buffer ctx -- flag )
    _EXT4-JA-CTX ! _EXT4-JA-BUF !
    _EXT4-JW-NONE _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-JA-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-JA-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32@
    DUP _EXT4-JA-MAGIC ! 0= IF
        _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32@
        _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L@ OR
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32@ OR 0=
        EXIT
    THEN
    _EXT4-JA-MAGIC @ _EXT4-JBD2-RECOVERY-MAGIC <>
    _EXT4-JA-MAGIC @ _EXT4-JBD2-ACTIVATION-MAGIC <> AND IF
        FALSE EXIT
    THEN
    _EXT4-JA-BUF @ _EXT4-JS.START + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32@
    DUP _EXT4-JA-EXPECTED ! INVERT 0xFFFFFFFF AND
    _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32@ <> IF
        FALSE EXIT
    THEN
    _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32@
    DUP _EXT4-JA-ANCHOR ! INVERT 0xFFFFFFFF AND
    _EXT4-JA-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32@ <> IF
        FALSE EXIT
    THEN
    _EXT4-JA-ANCHOR @ 0=
    _EXT4-JA-ANCHOR @ _EXT4-JA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        FALSE EXIT
    THEN
    _EXT4-JA-MAGIC @ _EXT4-JBD2-ACTIVATION-MAGIC = IF
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@ DUP
        INVERT 0xFFFFFFFF AND
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR +
        _EXT4-BE32@ <> IF DROP FALSE EXIT THEN
        _EXT4-JA-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@
        DUP _EXT4-JA-OLD-FEATURES !
        DUP 0= OVER _EXT4-JBD2-I-RECOVERY = OR
        SWAP _EXT4-JBD2-I-RECOVERY-REVOKE = OR 0= IF FALSE EXIT THEN
        _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32@
        _EXT4-JA-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JA-OLD-FEATURES @ IF
            _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L@
            4 <> IF FALSE EXIT THEN
        ELSE
            _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L@
            _EXT4-JA-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM +
            _EXT4-BE32@ OR IF FALSE EXIT THEN
        THEN
        _EXT4-JW-ACTIVATION
    ELSE
        _EXT4-JA-BUF @ _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
            FALSE EXIT
        THEN
        _EXT4-JW-RECOVERY
    THEN
    _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + !
    _EXT4-JA-EXPECTED @
    _EXT4-JA-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    _EXT4-JA-ANCHOR @ _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + !
    TRUE ;

VARIABLE _EXT4-AW-CTX

: _EXT4-ACTIVATION-CHECKSUMS?  ( ctx -- flag ior )
    DUP _EXT4-AW-CTX ! _EXT4-C.SB +
    DUP _EXT4-INTENDED-SUPER-CHECKSUM
    ?DUP IF NIP NIP 0 SWAP EXIT THEN
    _EXT4-AW-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + @ =
    SWAP _EXT4-INTENDED-DIRTY-SUPER-CHECKSUM
    ?DUP IF NIP NIP 0 SWAP EXIT THEN
    _EXT4-AW-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + @ = AND 0 ;

: _EXT4-JOURNAL-WITNESS-SUPER?  ( ctx -- flag ior )
    DUP _EXT4-C.J.WITNESS + @ _EXT4-JW-ACTIVATION = IF
        _EXT4-ACTIVATION-CHECKSUMS? EXIT
    THEN
    DUP _EXT4-C.J.WITNESS + @ _EXT4-JW-RECOVERY <> IF
        DROP FALSE 0 EXIT
    THEN
    DUP _EXT4-C.SB + _EXT4-INTENDED-RECOVERED-SUPER-CHECKSUM
    ?DUP IF NIP NIP 0 SWAP EXIT THEN
    SWAP _EXT4-C.J.WITNESS-CHECKSUM + @ = 0 ;

: _EXT4-JBD2-PRIMARY-USABLE?  ( buffer ctx -- flag ior )
    _EXT4-JA-CTX ! DUP _EXT4-JA-BUF !
    DUP _EXT4-JS.MAGIC + _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
    OVER _EXT4-JS.TYPE + _EXT4-BE32@ _EXT4-JBD2-SUPER-V2 <> OR IF
        DROP FALSE 0 EXIT
    THEN
    DUP _EXT4-JS.INCOMPAT + _EXT4-BE32@ DUP 0= IF
        2DROP TRUE 0 EXIT
    THEN
    DUP _EXT4-JBD2-I-RECOVERY =
    OVER _EXT4-JBD2-I-RECOVERY-REVOKE = OR IF
        2DROP
        _EXT4-JA-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF
            NIP 0 SWAP EXIT
        THEN 0= IF FALSE 0 EXIT THEN
        _EXT4-JA-BUF @ _EXT4-JA-CTX @ _EXT4-JBD2-WITNESS? 0 EXIT
    THEN
    2DROP TRUE 0 ;

: _EXT4-JBD2-ANCHOR-BLOCK?  ( logical ctx -- flag ior )
    _EXT4-JA-CTX ! _EXT4-JA-LOGICAL !
    _EXT4-JA-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JA-BUF !
    DUP _EXT4-JS.MAGIC + _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
    OVER _EXT4-JS.TYPE + _EXT4-BE32@ _EXT4-JBD2-SUPER-V2 <> OR
    OVER _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ 0<> OR IF
        DROP FALSE 0 EXIT
    THEN DROP
    _EXT4-JA-BUF @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-JA-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JS.FIRST + _EXT4-BE32@
    DUP 0= OVER _EXT4-JA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        DROP FALSE 0 EXIT
    THEN
    DUP _EXT4-JA-LOGICAL @ U> IF DROP FALSE 0 EXIT THEN
    _EXT4-JA-CTX @ _EXT4-C.J.FIRST + !
    _EXT4-JA-BUF @ _EXT4-JS.START + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JS.COMPAT + _EXT4-BE32@
    _EXT4-JA-BUF @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ OR IF
        FALSE 0 EXIT
    THEN
    _EXT4-JA-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@ DUP
    _EXT4-JA-FEATURES !
    _EXT4-JBD2-I-RECOVERY =
    _EXT4-JA-FEATURES @ _EXT4-JBD2-I-RECOVERY-REVOKE = OR 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-JA-BUF @ _EXT4-JS.UUID +
    _EXT4-JA-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF FALSE 0 EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-JA-BUF @ _EXT4-JA-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + @ 0= IF FALSE 0 EXIT THEN
    _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-JA-LOGICAL @ <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-JA-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-JA-LOGICAL @ <> IF FALSE 0 EXIT THEN
    _EXT4-JA-CTX @ _EXT4-JOURNAL-WITNESS-SUPER? ;

: _EXT4-ZERO-JOURNAL-WITNESS  ( buffer -- ior )
    _EXT4-JZ-BUF !
    0 _EXT4-JZ-BUF @ _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L!
    0 _EXT4-JZ-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    0 _EXT4-JZ-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JZ-BUF @ 1024 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-JZ-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32! 0 ;

: _EXT4-STAMP-JOURNAL-SUPER-CHECKSUM  ( buffer -- ior )
    DUP _EXT4-JZ-BUF ! _EXT4-JS.CHECKSUM + 0 SWAP _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JZ-BUF @ 1024 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-JZ-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32! 0 ;

VARIABLE _EXT4-JIC-BUF
VARIABLE _EXT4-JIC-CTX

: _EXT4-JOURNAL-IMAGE-CRC  ( buffer ctx -- crc ior )
    _EXT4-JIC-CTX ! _EXT4-JIC-BUF !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JIC-BUF @ _EXT4-JIC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

VARIABLE _EXT4-AG-CTX
VARIABLE _EXT4-AG-BUF
VARIABLE _EXT4-AG-LOGICAL
VARIABLE _EXT4-AG-FIRST
VARIABLE _EXT4-AG-START

\ An Akashic-emitted active journal has a standard checksum-v3 superblock
\ copied at the ring block immediately before s_start.  Its s_head remains
\ that guard block, equal to the preceding empty primary's s_head, so even an
\ early sequential-prefix tear in the primary retains an exact locator.
: _EXT4-JBD2-ACTIVE-GUARD?  ( logical ctx -- flag ior )
    _EXT4-AG-CTX ! _EXT4-AG-LOGICAL !
    _EXT4-AG-CTX @ _EXT4-C.RECOVERY + @ 0= IF FALSE 0 EXIT THEN
    _EXT4-AG-CTX @ _EXT4-C.BLOCK + DUP _EXT4-AG-BUF !
    DUP _EXT4-JS.MAGIC + _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
    OVER _EXT4-JS.TYPE + _EXT4-BE32@ _EXT4-JBD2-SUPER-V2 <> OR
    OVER _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ 0<> OR IF
        DROP FALSE 0 EXIT
    THEN DROP
    _EXT4-AG-BUF @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-AG-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-AG-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.FIRST + _EXT4-BE32@ DUP
    _EXT4-AG-FIRST ! 0= IF FALSE 0 EXIT THEN
    _EXT4-AG-FIRST @ _EXT4-AG-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-AG-LOGICAL @ _EXT4-AG-FIRST @ U<
    _EXT4-AG-LOGICAL @ _EXT4-AG-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
        FALSE 0 EXIT
    THEN
    _EXT4-AG-BUF @ _EXT4-JS.START + _EXT4-BE32@
    _EXT4-AG-START !
    _EXT4-AG-LOGICAL @ 1+ DUP
    _EXT4-AG-CTX @ _EXT4-C.J.MAXLEN + @ >= IF
        DROP _EXT4-AG-FIRST @
    THEN _EXT4-AG-START @ <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-AG-LOGICAL @ <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.ERRNO + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.COMPAT + _EXT4-BE32@
    _EXT4-AG-BUF @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ OR IF
        FALSE 0 EXIT
    THEN
    _EXT4-AG-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-JBD2-I-RECOVERY-REVOKE <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.UUID +
    _EXT4-AG-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.NR-USERS + _EXT4-BE32@ 1 <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-AG-BUF @ _EXT4-JS.DYNSUPER + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@ 4 <> IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-AG-BUF @ _EXT4-AG-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-AG-CTX @ _EXT4-C.J.WITNESS + @ IF FALSE 0 EXIT THEN
    _EXT4-AG-FIRST @ _EXT4-AG-CTX @ _EXT4-C.J.FIRST + !
    TRUE 0 ;

VARIABLE _EXT4-AGO-BUF

: _EXT4-ACTIVE-GUARD-OLD-PRIMARY  ( active-buffer old-buffer -- ior )
    DUP _EXT4-AGO-BUF !
    OVER _EXT4-AGO-BUF @ _EXT4-AG-CTX @ _EXT4-C.BSIZE + @ CMOVE
    DUP _EXT4-JS.SEQUENCE + _EXT4-BE32@ 1-
    0xFFFFFFFF AND _EXT4-AGO-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    0 _EXT4-AGO-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-AGO-BUF @ _EXT4-STAMP-JOURNAL-SUPER-CHECKSUM ?DUP IF
        >R 2DROP R> EXIT
    THEN
    2DROP 0 ;

VARIABLE _EXT4-ARO-RESET
VARIABLE _EXT4-ARO-OLD
VARIABLE _EXT4-ARO-LOGICAL
VARIABLE _EXT4-ARO-CTX
VARIABLE _EXT4-ARO-SEQUENCE
VARIABLE _EXT4-ARO-RESET-SEQUENCE

\ Reconstruct the exact standard active primary authenticated by an AKG1
\ reset anchor.  The sequence relation proves that this is the immediately
\ preceding transaction epoch; the stored full-block CRC proves all bytes,
\ including journal-block padding not covered by the JBD2 checksum.
: _EXT4-ACTIVE-RESET-OLD-JOURNAL?  ( reset old logical ctx -- flag ior )
    _EXT4-ARO-CTX ! _EXT4-ARO-LOGICAL ! _EXT4-ARO-OLD !
    _EXT4-ARO-RESET !
    _EXT4-ARO-RESET @ _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-ARO-RESET @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF FALSE 0 EXIT THEN
    _EXT4-ARO-RESET @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@
    _EXT4-ARO-SEQUENCE !
    _EXT4-ARO-RESET @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-ARO-RESET-SEQUENCE !
    _EXT4-ARO-SEQUENCE @ 1+ 0xFFFFFFFF AND
    _EXT4-ARO-RESET-SEQUENCE @ =
    _EXT4-ARO-SEQUENCE @ 2 + 0xFFFFFFFF AND
    _EXT4-ARO-RESET-SEQUENCE @ = OR 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-ARO-RESET @ _EXT4-ARO-OLD @
    _EXT4-ARO-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-ARO-SEQUENCE @
    _EXT4-ARO-OLD @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    _EXT4-ARO-LOGICAL @ 1+ DUP
    _EXT4-ARO-CTX @ _EXT4-C.J.MAXLEN + @ >= IF
        DROP _EXT4-ARO-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-ARO-OLD @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-ARO-LOGICAL @
    _EXT4-ARO-OLD @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-ARO-OLD @ _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF
        0 SWAP EXIT
    THEN
    _EXT4-ARO-OLD @ _EXT4-ARO-CTX @ _EXT4-JOURNAL-IMAGE-CRC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-ARO-RESET @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE +
    _EXT4-BE32@ = 0 ;

VARIABLE _EXT4-ERO-RESET
VARIABLE _EXT4-ERO-OLD
VARIABLE _EXT4-ERO-CTX
VARIABLE _EXT4-ERO-HEAD

\ Reconstruct the exact standard empty primary authenticated by an AKE1 reset
\ anchor.  The old sequence is exactly reset.sequence-1; AKE1 stores the old
\ raw head (including the normalized-first zero spelling) and full-block CRC.
\ All other predecessor bytes are inherited from the reset image.
: _EXT4-EMPTY-RESET-OLD-JOURNAL?  ( reset old ctx -- flag ior )
    _EXT4-ERO-CTX ! _EXT4-ERO-OLD ! _EXT4-ERO-RESET !
    _EXT4-ERO-RESET @ _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-ERO-RESET @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-EMPTY-RESET-MAGIC <> IF FALSE 0 EXIT THEN
    _EXT4-ERO-RESET @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@
    DUP _EXT4-ERO-HEAD !
    DUP 0= IF
        DROP _EXT4-ERO-CTX @ _EXT4-C.J.FIRST + @
    ELSE
        DUP _EXT4-ERO-CTX @ _EXT4-C.J.FIRST + @ U<
        SWAP _EXT4-ERO-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
            FALSE 0 EXIT
        THEN
        _EXT4-ERO-HEAD @
    THEN
    _EXT4-ERO-RESET @ _EXT4-JS.HEAD + _EXT4-BE32@ <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-ERO-RESET @ _EXT4-ERO-OLD @
    _EXT4-ERO-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-ERO-RESET @ _EXT4-JS.SEQUENCE + _EXT4-BE32@ 1-
    0xFFFFFFFF AND
    _EXT4-ERO-OLD @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    0 _EXT4-ERO-OLD @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-ERO-HEAD @
    _EXT4-ERO-OLD @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-ERO-OLD @ _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF
        0 SWAP EXIT
    THEN
    _EXT4-ERO-OLD @ _EXT4-ERO-CTX @ _EXT4-JOURNAL-IMAGE-CRC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-ERO-RESET @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE +
    _EXT4-BE32@ = 0 ;

VARIABLE _EXT4-AJO-BUF
VARIABLE _EXT4-AJO-FEATURES
VARIABLE _EXT4-AJO-HEAD
VARIABLE _EXT4-AJO-CSUM-TYPE
VARIABLE _EXT4-AJO-CHECKSUM

: _EXT4-ACTIVATION-OLD-JOURNAL  ( activation-anchor -- ior )
    DUP _EXT4-AJO-BUF !
    DUP _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32@
    _EXT4-AJO-FEATURES !
    DUP _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32@ _EXT4-AJO-HEAD !
    DUP _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L@ _EXT4-AJO-CSUM-TYPE !
    _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32@ _EXT4-AJO-CHECKSUM !
    _EXT4-AJO-BUF @ _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-AJO-FEATURES @
    _EXT4-AJO-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    _EXT4-AJO-HEAD @ _EXT4-AJO-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-AJO-CSUM-TYPE @ _EXT4-AJO-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    _EXT4-AJO-CHECKSUM @
    _EXT4-AJO-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32! 0 ;

\ True only when torn is one sequential write prefix from new followed by the
\ untouched suffix from old.  Equal bytes do not force the transition point.
: _EXT4-PREFIX-MERGE?  ( new old torn len -- flag )
    _EXT4-PM-LEN ! _EXT4-PM-TORN ! _EXT4-PM-OLD ! _EXT4-PM-NEW !
    0 _EXT4-PM-OLD-PHASE !
    _EXT4-PM-LEN @ 0 ?DO
        _EXT4-PM-NEW @ I + C@ _EXT4-PM-OLD @ I + C@ = IF
            _EXT4-PM-TORN @ I + C@
            _EXT4-PM-NEW @ I + C@ <> IF FALSE UNLOOP EXIT THEN
        ELSE
            _EXT4-PM-OLD-PHASE @ IF
                _EXT4-PM-TORN @ I + C@
                _EXT4-PM-OLD @ I + C@ <> IF FALSE UNLOOP EXIT THEN
            ELSE
                _EXT4-PM-TORN @ I + C@
                _EXT4-PM-NEW @ I + C@ <> IF
                    _EXT4-PM-TORN @ I + C@
                    _EXT4-PM-OLD @ I + C@ <> IF FALSE UNLOOP EXIT THEN
                    -1 _EXT4-PM-OLD-PHASE !
                THEN
            THEN
        THEN
    LOOP
    TRUE ;

: _EXT4-ACTIVATION-PREFIX?  ( ctx -- flag ior )
    DUP _EXT4-AW-CTX !
    DUP _EXT4-C.SB + OVER _EXT4-C.DIR-BLOCK + _EXT4-SB-SIZE CMOVE
    DUP _EXT4-C.SB + OVER _EXT4-C.TREE-BLOCK + _EXT4-SB-SIZE CMOVE
    DUP _EXT4-C.DIR-BLOCK + _EXT4-PREPARE-CLEAN-SUPER
    ?DUP IF NIP 0 SWAP EXIT THEN
    DUP _EXT4-C.TREE-BLOCK + _EXT4-PREPARE-DIRTY-SUPER
    ?DUP IF NIP 0 SWAP EXIT THEN
    DUP _EXT4-C.TREE-BLOCK +
    SWAP _EXT4-C.DIR-BLOCK +
    _EXT4-AW-CTX @ _EXT4-C.SB +
    _EXT4-SB-SIZE _EXT4-PREFIX-MERGE? 0 ;

\ A torn primary may name one exact anchor.  Never search the ring: an older
\ epoch can contain a perfectly checksummed reset copy with no authority over
\ the current committed prefix.
: _EXT4-SELECT-JOURNAL-ANCHOR  ( ctx -- ior )
    _EXT4-JA-CTX !
    0 _EXT4-JA-CLEANUP !
    _EXT4-JA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-JA-CTX @
    _EXT4-JBD2-WITNESS? IF
        _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + @ IF
            _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + @ DUP _EXT4-JA-LOCATED !
            _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
            _EXT4-JS.HEAD + _EXT4-BE32@ <> IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JA-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
            ?DUP IF NIP EXIT THEN 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
        ELSE
            -1 _EXT4-JA-CLEANUP !
        THEN
    ELSE
        -1 _EXT4-JA-CLEANUP !
    THEN
    _EXT4-JA-CLEANUP @ IF
        _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JS.HEAD + _EXT4-BE32@ DUP
        _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JS.FIRST + _EXT4-BE32@ U< IF
            DROP _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
            _EXT4-JS.FIRST + _EXT4-BE32@
        THEN DUP _EXT4-JA-LOCATED !
        DUP 0= SWAP _EXT4-JA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JA-CTX @ _EXT4-SNAPSHOT-JOURNAL-MAP
    ?DUP IF EXIT THEN
    _EXT4-JA-LOCATED @ _EXT4-JA-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JA-LOCATED @ _EXT4-JA-CTX @
    _EXT4-JBD2-ACTIVE-GUARD? ?DUP IF NIP EXIT THEN IF
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-ACTIVE-GUARD-OLD-PRIMARY ?DUP IF EXIT THEN
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.BSIZE + @
        _EXT4-PREFIX-MERGE? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JA-LOCATED @ _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + !
        _EXT4-JC-ACTIVE _EXT4-JA-CTX @ _EXT4-C.J.CLEANUP + !
        -1 _EXT4-JA-CTX @ _EXT4-C.J.PRIMARY-TORN + !
        0 EXIT
    THEN
    _EXT4-JA-LOCATED @ _EXT4-JA-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JA-CLEANUP @ IF
        0 _EXT4-JA-PREFIX-OK !
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ CMOVE
        _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-ZERO-JOURNAL-WITNESS
        ?DUP IF EXIT THEN
        _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JA-CTX @ _EXT4-C.BSIZE + @
        _EXT4-PREFIX-MERGE? IF
            -1 _EXT4-JA-PREFIX-OK !
            _EXT4-JC-STANDARD
            _EXT4-JA-CTX @ _EXT4-C.J.CLEANUP + !
        THEN
        _EXT4-JA-PREFIX-OK @ 0=
        _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + @
        _EXT4-JW-ACTIVATION = AND IF
            _EXT4-JA-CTX @ _EXT4-C.BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ CMOVE
            _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-ACTIVATION-OLD-JOURNAL ?DUP IF EXIT THEN
            _EXT4-JA-CTX @ _EXT4-C.BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.BSIZE + @
            _EXT4-PREFIX-MERGE? IF
                -1 _EXT4-JA-PREFIX-OK !
                _EXT4-JC-ANCHOR
                _EXT4-JA-CTX @ _EXT4-C.J.CLEANUP + !
            THEN
        THEN
        _EXT4-JA-PREFIX-OK @ 0=
        _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + @
        _EXT4-JW-RECOVERY = AND
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
        _EXT4-JBD2-ACTIVE-RESET-MAGIC = AND IF
            _EXT4-JA-CTX @ _EXT4-C.BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JA-LOCATED @ _EXT4-JA-CTX @
            _EXT4-ACTIVE-RESET-OLD-JOURNAL? ?DUP IF NIP EXIT THEN IF
                _EXT4-JA-CTX @ _EXT4-C.BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.BSIZE + @
                _EXT4-PREFIX-MERGE? IF
                    -1 _EXT4-JA-PREFIX-OK !
                    _EXT4-JC-NONE
                    _EXT4-JA-CTX @ _EXT4-C.J.CLEANUP + !
                THEN
            THEN
        THEN
        _EXT4-JA-PREFIX-OK @ 0=
        _EXT4-JA-CTX @ _EXT4-C.J.WITNESS + @
        _EXT4-JW-RECOVERY = AND
        _EXT4-JA-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
        _EXT4-JBD2-EMPTY-RESET-MAGIC = AND IF
            _EXT4-JA-CTX @ _EXT4-C.BLOCK +
            _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JA-CTX @ _EXT4-EMPTY-RESET-OLD-JOURNAL?
            ?DUP IF NIP EXIT THEN IF
                _EXT4-JA-CTX @ _EXT4-C.BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.TREE-BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
                _EXT4-JA-CTX @ _EXT4-C.BSIZE + @
                _EXT4-PREFIX-MERGE? IF
                    -1 _EXT4-JA-PREFIX-OK !
                    _EXT4-JC-NONE
                    _EXT4-JA-CTX @ _EXT4-C.J.CLEANUP + !
                THEN
            THEN
        THEN
        _EXT4-JA-PREFIX-OK @ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    -1 _EXT4-JA-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    0 ;

VARIABLE _EXT4-DAG-CTX
VARIABLE _EXT4-DAG-GUARD

\ An intact active primary remains the authority when reset publication has
\ already begun to reuse its guard.  The standard active shape self-locates
\ the guard in s_head; exact guard equality is required only when the primary
\ itself is torn and therefore needs the clean-to-active prefix proof.
: _EXT4-DETECT-ACTIVE-JOURNAL-GUARD  ( ctx -- ior )
    _EXT4-DAG-CTX !
    _EXT4-DAG-CTX @ _EXT4-C.J.START + @ 0= IF 0 EXIT THEN
    _EXT4-DAG-CTX @ _EXT4-C.J.WITNESS + @ IF 0 EXIT THEN
    _EXT4-DAG-CTX @ _EXT4-C.J.CLEANUP + @ IF 0 EXIT THEN
    _EXT4-DAG-CTX @ _EXT4-C.J.HEAD + @ DUP _EXT4-DAG-GUARD !
    DUP 0= IF DROP 0 EXIT THEN
    DUP _EXT4-DAG-CTX @ _EXT4-C.J.FIRST + @ U<
    SWAP _EXT4-DAG-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
        0 EXIT
    THEN
    _EXT4-DAG-GUARD @ _EXT4-DAG-CTX @
    _EXT4-JBD2-ACTIVE-GUARD? ?DUP IF NIP EXIT THEN 0= IF 0 EXIT THEN
    _EXT4-DAG-GUARD @ _EXT4-DAG-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JC-ACTIVE _EXT4-DAG-CTX @ _EXT4-C.J.CLEANUP + !
    0 ;

\ A usable primary witness is mutable only after its exact anchor is present.
\ The checksummed 1024-byte superblocks must match.  A mismatch confined to
\ larger-block padding is a torn primary reset and is refreshed from the
\ anchor before the ext4 clear; otherwise full equality establishes the old
\ side of the cleanup-prefix proof.
: _EXT4-VALIDATE-JOURNAL-ANCHOR-COPY  ( ctx -- ior )
    _EXT4-JA-CTX !
    _EXT4-JA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JA-CTX @ _EXT4-SNAPSHOT-JOURNAL-MAP
    ?DUP IF EXIT THEN
    _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-JA-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JA-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-JA-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.BLOCK +
    1024 _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JA-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        -1 _EXT4-JA-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    THEN
    0 ;

VARIABLE _EXT4-JVL-IOR

: _EXT4-VALIDATE-JOURNAL-INODE-MAP  ( ctx -- ior )
    DUP _EXT4-C.J.MAXLEN + @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-VALIDATE-EXTENT-TREE _EXT4-JVL-IOR !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JVL-IOR @ ;

VARIABLE _EXT4-JB-SB
VARIABLE _EXT4-JB-IN

VARIABLE _EXT4-JBR-CTX
VARIABLE _EXT4-JBR-ROOT
VARIABLE _EXT4-JBR-COUNT
VARIABLE _EXT4-JBR-ENTRY
VARIABLE _EXT4-JBR-LOGICAL
VARIABLE _EXT4-JBR-LEN
VARIABLE _EXT4-JBR-PHYS
VARIABLE _EXT4-JBR-INDEX
VARIABLE _EXT4-JBR-I
VARIABLE _EXT4-JBR-OTHER
VARIABLE _EXT4-JBR-OTHER-LEN

\ The standard ext4 journal backup is a checksum-covered redundant copy of
\ inode 8's complete i_block root plus size.  It omits flags, generation, and
\ external-node authentication, so the recovery profile deliberately pins
\ inode 8 to generation zero and a self-contained extent root.
: _EXT4-JOURNAL-BACKUP-MATCHES-INODE-AT?  ( sb ctx -- flag )
    _EXT4-C.INODE + _EXT4-JB-IN !
    _EXT4-JB-SB !
    _EXT4-JB-SB @ _EXT4-SB.JOURNAL-BACKUP-TYPE + C@
        _EXT4-JOURNAL-BACKUP-BLOCKS =
    _EXT4-JB-SB @ _EXT4-SB.JOURNAL-BLOCKS +
        _EXT4-JB-IN @ _EXT4-I.BLOCK + 60 _EXT4-BYTES=? AND
    _EXT4-JB-SB @ _EXT4-SB.JOURNAL-BLOCKS 60 + + L@
        _EXT4-JB-IN @ _EXT4-I.SIZE-HI + L@ = AND
    _EXT4-JB-SB @ _EXT4-SB.JOURNAL-BLOCKS 64 + + L@
        _EXT4-JB-IN @ _EXT4-I.SIZE-LO + L@ = AND
    _EXT4-JB-IN @ _EXT4-I.GENERATION + L@ 0= AND
    _EXT4-JB-IN @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<> AND ;

\ Validate the tuple without consulting the primary GDT, allocation bitmaps,
\ or inode table.  Exact, gapless coverage makes this root independently
\ decodable during a retry; physical non-overlap makes every logical journal
\ block unambiguous before the ordinary allocation-aware validation runs.
: _EXT4-VALIDATE-JOURNAL-BACKUP-ROOT-AT  ( root ctx -- ior )
    _EXT4-JBR-CTX ! DUP _EXT4-JBR-ROOT !
    W@ _EXT4-EXTENT-MAGIC <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JBR-ROOT @ 2 + W@ DUP _EXT4-JBR-COUNT !
    DUP 0= SWAP 4 U> OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JBR-ROOT @ 4 + W@ 4 <>
    _EXT4-JBR-ROOT @ 6 + W@ 0<> OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JBR-LOGICAL !
    _EXT4-JBR-COUNT @ 0 ?DO
        _EXT4-JBR-ROOT @ 12 I 12 * + + DUP _EXT4-JBR-ENTRY !
        L@ _EXT4-JBR-LOGICAL @ <> IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JBR-ENTRY @ 4 + W@ DUP _EXT4-JBR-LEN !
        DUP 0= SWAP 32768 U> OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JBR-ENTRY @ 6 + W@ IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JBR-ENTRY @ 8 + L@ _EXT4-JBR-PHYS !
        _EXT4-JBR-PHYS @ 0=
        _EXT4-JBR-PHYS @ _EXT4-JBR-CTX @ _EXT4-C.FIRST + @ U< OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JBR-PHYS @ _EXT4-JBR-LEN @
        _EXT4-JBR-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-JBR-INDEX !
        0 _EXT4-JBR-I !
        BEGIN _EXT4-JBR-I @ _EXT4-JBR-INDEX @ < WHILE
            _EXT4-JBR-ROOT @ 12 _EXT4-JBR-I @ 12 * + + DUP
            8 + L@ _EXT4-JBR-OTHER !
            4 + W@ _EXT4-JBR-OTHER-LEN !
            _EXT4-JBR-OTHER @ _EXT4-JBR-OTHER-LEN @ +
                _EXT4-JBR-PHYS @ U>
            _EXT4-JBR-PHYS @ _EXT4-JBR-LEN @ +
                _EXT4-JBR-OTHER @ U> AND IF
                EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-JBR-I +!
        REPEAT
        _EXT4-JBR-LOGICAL @ _EXT4-JBR-LEN @ + DUP
        _EXT4-JBR-LOGICAL @ U< IF
            DROP EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        DUP _EXT4-JBR-CTX @ _EXT4-C.J.MAXLEN + @ U> IF
            DROP EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JBR-LOGICAL !
    LOOP
    _EXT4-JBR-LOGICAL @
    _EXT4-JBR-CTX @ _EXT4-C.J.MAXLEN + @ <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JO-CTX
VARIABLE _EXT4-JO-ROOT
VARIABLE _EXT4-JO-FIRST
VARIABLE _EXT4-JO-COUNT
VARIABLE _EXT4-JO-END
VARIABLE _EXT4-JO-ENTRY
VARIABLE _EXT4-JO-JFIRST
VARIABLE _EXT4-JO-JLEN
VARIABLE _EXT4-JO-GROUP
VARIABLE _EXT4-JO-BLOCK-BITMAP
VARIABLE _EXT4-JO-INODE-BITMAP
VARIABLE _EXT4-JO-INODE-TABLE
VARIABLE _EXT4-JO-INODE-SPAN
VARIABLE _EXT4-JO-SPARSE-SUPER

\ Prove one descriptor- or geometry-authenticated metadata interval disjoint
\ from every physical interval in the already validated depth-0 tuple.
: _EXT4-JOURNAL-RANGE-DISJOINT  ( first count ctx -- ior )
    _EXT4-JO-CTX ! _EXT4-JO-COUNT ! _EXT4-JO-FIRST !
    _EXT4-JO-FIRST @ _EXT4-JO-COUNT @
    _EXT4-JO-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JO-FIRST @ _EXT4-JO-COUNT @ + _EXT4-JO-END !
    _EXT4-JO-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB.JOURNAL-BLOCKS + DUP _EXT4-JO-ROOT !
    2 + W@ 0 ?DO
        _EXT4-JO-ROOT @ 12 I 12 * + + DUP _EXT4-JO-ENTRY !
        8 + L@ _EXT4-JO-JFIRST !
        _EXT4-JO-ENTRY @ 4 + W@ _EXT4-JO-JLEN !
        _EXT4-JO-JFIRST @ _EXT4-JO-JLEN @
        _EXT4-JO-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JO-JFIRST @ _EXT4-JO-END @ U<
        _EXT4-JO-FIRST @
        _EXT4-JO-JFIRST @ _EXT4-JO-JLEN @ + U< AND IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    0 ;

\ Group 1's checksum-authenticated backup GDT names every flex_bg metadata
\ range.  Check those ranges plus every deterministic sparse-super, GDT, and
\ reserved-GDT interval before consulting a bitmap or reading the journal.
: _EXT4-VALIDATE-JOURNAL-OWNERSHIP  ( ctx -- ior )
    _EXT4-JO-CTX !
    _EXT4-JO-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-JO-GROUP !
        _EXT4-JO-GROUP @
        _EXT4-JO-CTX @ _EXT4-C.J.WITNESS-GDT-BLOCK + @
        _EXT4-JO-CTX @ _EXT4-LOAD-DESC-AT ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-JO-CTX @ _EXT4-C.DESC + DUP
            _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-JO-BLOCK-BITMAP !
        DUP _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-JO-INODE-BITMAP !
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-JO-INODE-TABLE !
        _EXT4-GD-SPAN @ _EXT4-JO-INODE-SPAN !
        _EXT4-JO-BLOCK-BITMAP @ 1 _EXT4-JO-CTX @
        _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF UNLOOP EXIT THEN
        _EXT4-JO-INODE-BITMAP @ 1 _EXT4-JO-CTX @
        _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF UNLOOP EXIT THEN
        _EXT4-JO-INODE-TABLE @ _EXT4-JO-INODE-SPAN @ _EXT4-JO-CTX @
        _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF UNLOOP EXIT THEN
        _EXT4-JO-GROUP @ _EXT4-SPARSE-GROUP? IF
            _EXT4-JO-GROUP @ _EXT4-JO-CTX @ _EXT4-C.BPG + @ *
            _EXT4-JO-CTX @ _EXT4-C.FIRST + @ +
            DUP _EXT4-JO-SPARSE-SUPER !
            1 _EXT4-JO-CTX @ _EXT4-JOURNAL-RANGE-DISJOINT
            ?DUP IF UNLOOP EXIT THEN
            _EXT4-JO-SPARSE-SUPER @ 1+
            _EXT4-JO-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @
            _EXT4-JO-CTX @ _EXT4-C.J.WITNESS-SUPER +
            _EXT4-SB.RESERVED-GDT + W@ +
            _EXT4-JO-CTX @ _EXT4-JOURNAL-RANGE-DISJOINT
            ?DUP IF UNLOOP EXIT THEN
        THEN
    LOOP
    0 ;

VARIABLE _EXT4-RW-CTX
VARIABLE _EXT4-RW-SUPER-BLOCK
VARIABLE _EXT4-RW-GDT-BLOCK

\ Group 1 is the deterministic independent sparse-super witness required by
\ the writable profile.  Its checksum-valid superblock authenticates the
\ primary's immutable fields and tuple; its checksum-valid group-0 backup
\ descriptor locates the live inode bitmap/table without reading primary GDT.
: _EXT4-LOAD-RECOVERY-WITNESS  ( ctx -- ior )
    DUP _EXT4-RW-CTX !
    _EXT4-C.GROUPS + @ 1 <= IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-RW-CTX @ _EXT4-C.FIRST + @
    _EXT4-RW-CTX @ _EXT4-C.BPG + @ + DUP _EXT4-RW-SUPER-BLOCK !
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-SUPER-BLOCK + !
    _EXT4-RW-SUPER-BLOCK @ 1+ DUP _EXT4-RW-GDT-BLOCK !
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-GDT-BLOCK + !
    _EXT4-RW-CTX @ _EXT4-C.GROUPS + @ _EXT4-DESC-SIZE *
    _EXT4-RW-CTX @ _EXT4-C.BSIZE + @ 1- +
    _EXT4-RW-CTX @ _EXT4-C.BSIZE + @ /
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + !
    _EXT4-RW-GDT-BLOCK @
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @
    _EXT4-RW-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RW-SUPER-BLOCK @ _EXT4-RW-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-RW-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-RW-CTX @ _EXT4-C.SB +
    _EXT4-JOURNAL-BACKUP-TUPLE=? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP 1 _EXT4-RW-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        DROP EXT4-D-BACKUP-SUPER _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB-SIZE CMOVE
    8 _EXT4-RW-CTX @ _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    0 _EXT4-RW-GDT-BLOCK @ _EXT4-RW-CTX @ _EXT4-LOAD-DESC-AT
    ?DUP IF EXIT THEN
    _EXT4-RW-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-RW-CTX @ _EXT4-C.J.BLOCK-BITMAP-BLOCK + !
    _EXT4-RW-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-RW-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + !
    _EXT4-RW-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-RW-CTX @ _EXT4-C.J.INODE-TABLE-BASE + !
    _EXT4-LOAD-INODE-FROM-DESC ?DUP IF EXIT THEN
    _EXT4-RW-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-RW-CTX @ _EXT4-JOURNAL-BACKUP-MATCHES-INODE-AT? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-VALIDATE-JOURNAL  ( ctx -- ior )
    _EXT4-JV-CTX !
    0 _EXT4-JV-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    0 _EXT4-JV-CTX @ _EXT4-C.J.ANCHOR + !
    0 _EXT4-JV-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-JV-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-JV-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-JV-CTX @ _EXT4-C.J.CLEANUP + !
    _EXT4-JV-CTX @ _EXT4-LOAD-RECOVERY-WITNESS ?DUP IF EXIT THEN
    \ A replay tag may legitimately name the inode-table block shared with
    \ neighboring inodes.  Preserve its exact inode-8 byte range so preflight
    \ can allow the block without allowing the journal map to rewrite itself.
    _EXT4-IR-BLOCK @ _EXT4-JV-CTX @ _EXT4-C.J.INODE-TABLE-BLOCK + !
    _EXT4-IR-OFF @ _EXT4-JV-CTX @ _EXT4-C.J.INODE-TABLE-OFF + !
    _EXT4-JV-CTX @ _EXT4-C.INODE + DUP _EXT4-JV-IN !
    DUP _EXT4-I.FILE-ACL-HI + W@
    SWAP _EXT4-I.FILE-ACL-LO + L@ OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-IN @
    _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-IN @ _EXT4-I.SIZE-HI + L@ 32 LSHIFT
    _EXT4-JV-IN @ _EXT4-I.SIZE-LO + L@ OR DUP _EXT4-JV-SIZE !
    0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-JV-SIZE @ _EXT4-JV-CTX @ _EXT4-C.BSIZE + @ MOD IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-SIZE @ _EXT4-JV-CTX @ _EXT4-C.BSIZE + @ /
    DUP 0xFFFFFFFF U> IF
        DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-JV-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-CTX @ _EXT4-C.J.MAXLEN + !
    _EXT4-JV-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB.JOURNAL-BLOCKS + _EXT4-JV-CTX @
    _EXT4-VALIDATE-JOURNAL-BACKUP-ROOT-AT ?DUP IF EXIT THEN
    _EXT4-JV-CTX @ _EXT4-VALIDATE-JOURNAL-OWNERSHIP ?DUP IF EXIT THEN
    _EXT4-JV-CTX @ _EXT4-C.J.STRICT + @ IF
        _EXT4-JV-CTX @ _EXT4-VALIDATE-JOURNAL-INODE-MAP
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JV-CTX @ _EXT4-SNAPSHOT-JOURNAL-MAP
    ?DUP IF EXIT THEN
    0 _EXT4-JV-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JV-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JV-JSB !
    _EXT4-JV-CTX @ _EXT4-JBD2-PRIMARY-USABLE? ?DUP IF NIP EXIT THEN 0= IF
        _EXT4-JV-CTX @ _EXT4-SELECT-JOURNAL-ANCHOR ?DUP IF EXIT THEN
        _EXT4-JV-CTX @ _EXT4-C.BLOCK + _EXT4-JV-JSB !
    THEN
    _EXT4-JV-JSB @ DUP _EXT4-JS.MAGIC + _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
    OVER _EXT4-JS.TYPE + _EXT4-BE32@ _EXT4-JBD2-SUPER-V2 <> OR
    OVER _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ 0<> OR IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN DROP
    _EXT4-JV-JSB @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.BSIZE + @ <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.J.MAXLEN + @ <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.FIRST + _EXT4-BE32@ DUP
    0= OVER _EXT4-JV-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-CTX @ _EXT4-C.J.FIRST + !
    _EXT4-JV-JSB @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.J.SEQUENCE + !
    _EXT4-JV-JSB @ _EXT4-JS.START + _EXT4-BE32@ DUP _EXT4-JV-START !
    _EXT4-JV-CTX @ _EXT4-C.J.START + !
    _EXT4-JV-JSB @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JV-JSB @ _EXT4-JS.MAX-TRANSACTION + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.J.MAX-TRANSACTION + !
    _EXT4-JV-JSB @ _EXT4-JS.MAX-TRANS-DATA + _EXT4-BE32@
    _EXT4-JV-CTX @ _EXT4-C.J.MAX-TRANS-DATA + !
    _EXT4-JV-START @ IF
        _EXT4-JV-START @ _EXT4-JV-CTX @ _EXT4-C.J.FIRST + @ U<
        _EXT4-JV-START @ _EXT4-JV-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.ERRNO + _EXT4-BE32@ IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.COMPAT + _EXT4-BE32@ IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ IF
        EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.UUID +
    _EXT4-JV-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-JV-JSB @ _EXT4-JS.NR-USERS + _EXT4-BE32@ 1 <>
    _EXT4-JV-JSB @ _EXT4-JS.DYNSUPER + _EXT4-BE32@ 0<> OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-JSB @ _EXT4-JS.INCOMPAT + _EXT4-BE32@ DUP
    _EXT4-JV-FEATURES ! _EXT4-JV-CTX @ _EXT4-C.J.FEATURES + !
    _EXT4-JV-FEATURES @ IF
        _EXT4-JV-FEATURES @ _EXT4-JBD2-I-RECOVERY =
        _EXT4-JV-FEATURES @ _EXT4-JBD2-I-RECOVERY-REVOKE = OR 0= IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE + C@
        _EXT4-JBD2-CRC32C <>
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 1+ + C@ 0<> OR
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 2 + + C@ 0<> OR
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 3 + + C@ 0<> OR
        _EXT4-JV-JSB @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ 0<> OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JV-JSB @ _EXT4-JBD2-SUPER-CHECKSUM?
        ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        0xFFFFFFFF _EXT4-CRC-START
        _EXT4-JV-JSB @ _EXT4-JS.UUID + 16 _EXT4-CRC-ADD
        ?DUP IF EXIT THEN
        _EXT4-CRC@ _EXT4-JV-CTX @ _EXT4-C.J.SEED + !
    ELSE
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE + C@
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 1+ + C@ OR
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 2 + + C@ OR
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM-TYPE 3 + + C@ OR
        _EXT4-JV-JSB @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ OR
        _EXT4-JV-JSB @ _EXT4-JS.CHECKSUM + _EXT4-BE32@ OR IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        0 _EXT4-JV-CTX @ _EXT4-C.J.SEED + !
    THEN
    _EXT4-JV-JSB @ _EXT4-JV-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JV-CTX @ _EXT4-C.J.WITNESS + @ IF
        _EXT4-JV-FEATURES @ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JV-START @ IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
        _EXT4-JV-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-JV-CTX @ _EXT4-C.J.FIRST + @ U< IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JV-JSB @ _EXT4-JS.HEAD + _EXT4-BE32@
        _EXT4-JV-CTX @ _EXT4-C.J.ANCHOR + @ <> IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JV-START @ 0= IF
        _EXT4-JV-JSB @ _EXT4-JS.HEAD + _EXT4-BE32@ DUP IF
            DUP _EXT4-JV-CTX @ _EXT4-C.J.FIRST + @ U<
            OVER _EXT4-JV-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
                DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
        THEN DROP
    THEN
    _EXT4-JV-CTX @ _EXT4-C.SUPER-TORN + @ IF
        _EXT4-JV-CTX @ _EXT4-C.J.WITNESS + @ IF
            _EXT4-JV-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
            ?DUP IF NIP EXIT THEN 0= IF
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
        ELSE
            \ An active committed log can repair a prefix-torn home super.
            \ Without one, only the private reset witness authorizes cleanup.
            _EXT4-JV-CTX @ _EXT4-C.J.START + @ 0= IF
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
        THEN
    THEN
    _EXT4-JV-CTX @ _EXT4-C.RECOVERY + @ IF
        _EXT4-JV-FEATURES @ 0= IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
    ELSE
        _EXT4-JV-START @ IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    THEN
    _EXT4-JV-CTX @ _EXT4-C.J.PRIMARY-TORN + @ 0= IF
        _EXT4-JV-CTX @ _EXT4-C.J.WITNESS + @ IF
            _EXT4-JV-CTX @ _EXT4-VALIDATE-JOURNAL-ANCHOR-COPY
            ?DUP IF EXIT THEN
        THEN
    THEN
    _EXT4-JV-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION = IF
        _EXT4-JV-FEATURES @ _EXT4-JBD2-I-RECOVERY-REVOKE <> IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JV-CTX @ _EXT4-ACTIVATION-CHECKSUMS?
        ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JV-CTX @ _EXT4-ACTIVATION-PREFIX?
        ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JV-CTX @ _EXT4-DETECT-ACTIVE-JOURNAL-GUARD ?DUP IF EXIT THEN
    _EXT4-JV-CTX @ _EXT4-SNAPSHOT-JOURNAL-MAP ?DUP IF EXIT THEN
    \ Map validation is finished, so TREE-BLOCK can freeze the authenticated
    \ journal inode until both scan passes finish.  This avoids relying on the
    \ mutable general-purpose inode cache during replay preflight.
    _EXT4-JV-CTX @ _EXT4-C.INODE +
    _EXT4-JV-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JV-CTX @ _EXT4-C.ISIZE + @ CMOVE
    0 ;

VARIABLE _EXT4-JN-BLOCK
VARIABLE _EXT4-JN-CTX

: _EXT4-JOURNAL-NEXT  ( logical ctx -- next )
    _EXT4-JN-CTX ! _EXT4-JN-BLOCK !
    _EXT4-JN-BLOCK @ 1+ DUP
    _EXT4-JN-CTX @ _EXT4-C.J.MAXLEN + @ >= IF
        DROP _EXT4-JN-CTX @ _EXT4-C.J.FIRST + @
    THEN ;

VARIABLE _EXT4-JADV-POS
VARIABLE _EXT4-JADV-COUNT
VARIABLE _EXT4-JADV-CTX

: _EXT4-JOURNAL-ADVANCE  ( logical count ctx -- logical )
    _EXT4-JADV-CTX ! _EXT4-JADV-COUNT ! _EXT4-JADV-POS !
    _EXT4-JADV-COUNT @ 0 ?DO
        _EXT4-JADV-POS @ _EXT4-JADV-CTX @ _EXT4-JOURNAL-NEXT
        _EXT4-JADV-POS !
    LOOP
    _EXT4-JADV-POS @ ;

\ =====================================================================
\  Private arena-bounded JBD2 transaction staging
\ =====================================================================
\
\ This layer owns complete metadata and ordered-data after-images before any
\ transaction media mutation.  The downstream private emitter consumes the
\ same bounded tables through activation, barriers, and commit while retaining
\ them for authenticated checkpoint.  A persistent production profile lives
\ in its caller-owned dedicated arena and serves contained credit requests;
\ mount-only recovery writers instead use a scoped ordinary-arena tail that is
\ scrubbed and rolled back before mount publication.

