1 CONSTANT _EXT4-JWR-STORE-MOUNT
2 CONSTANT _EXT4-JWR-STORE-DEDICATED

\ A production writer profile owns the first and only allocation in a
\ dedicated caller arena.  Internal mount-time recovery writers instead own
\ the current tail of the ordinary mount arena.  STORE-KIND prevents a
\ damaged arena handle from silently downgrading either ownership contract.
\ Revalidate the live arena descriptor, exact allocation endpoint, and
\ dedicated-backing separation whenever writer shape is used.
: _EXT4-JWR-PROFILE-STORAGE?  ( writer -- flag )
    DUP _EXT4-JWS-WRITER ! _EXT4-JWR.CTX + @ DUP
    _EXT4-JWS-CTX ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.J.WRITER-ARENA + @ DUP
    _EXT4-JWS-ARENA ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ 4 CELLS MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.SOURCE @ DUP 0< SWAP 2 > OR IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.BASE @ DUP _EXT4-JWS-BASE ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.SIZE @ DUP _EXT4-JWS-SIZE !
    DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.PTR @ DUP _EXT4-JWS-END ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ 7 AND _EXT4-JWS-END @ 7 AND OR IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @ MSPAN-NONWRAPPING? 0= IF
        FALSE EXIT
    THEN
    _EXT4-JWS-ARENA @ 4 CELLS _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @
    MSPAN-OVERLAP? IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BASE @ U< IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWR.TOTAL + @ DUP _EXT4-JWS-BYTES !
    _EXT4-JWS-WRITER @ SWAP MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BYTES @ + DUP
    _EXT4-JWS-END @ <> IF DROP FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @ + U> IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.ARENA + @ DUP
    _EXT4-JWS-MOUNT-ARENA ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ DUP
    _EXT4-JWR-STORE-MOUNT = IF
        DROP _EXT4-JWS-ARENA @ _EXT4-JWS-MOUNT-ARENA @ = EXIT
    THEN
    _EXT4-JWR-STORE-DEDICATED <> IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ _EXT4-JWS-MOUNT-ARENA @ = IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BASE @ <> IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-ARENA @ A.BASE @ DUP
    _EXT4-JWS-MOUNT-BASE ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-ARENA @ A.SIZE @ DUP
    _EXT4-JWS-MOUNT-SIZE ! DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-BASE @ 7 AND IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-BASE @ _EXT4-JWS-MOUNT-SIZE @
    MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @
    _EXT4-JWS-MOUNT-BASE @ _EXT4-JWS-MOUNT-SIZE @
    MSPAN-OVERLAP? 0= ;

: _EXT4-JWV-EXPECT  ( address -- )
    _EXT4-JWV-CURSOR @ <> IF 0 _EXT4-JWV-OK ! THEN ;

: _EXT4-JWV-ADVANCE  ( count bytes-per-item -- )
    * _EXT4-JWV-CURSOR +! ;

: _EXT4-JWR-SHAPE?  ( writer -- flag )
    _EXT4-JWV-WRITER !
    _EXT4-JWV-WRITER @ 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAGIC + @
    _EXT4-JWR-MAGIC <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.SELF + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWR-SIZE U< IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JWV-CTX ! 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-JWR-CONTEXT? 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR-PROFILE-STORAGE? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ DUP 1024 =
    OVER 2048 = OR SWAP 4096 = OR 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWV-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ DUP 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @
    _EXT4-JWV-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @ 0<
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @ 0< OR
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @ 0< OR IF
        FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWR-MEASURE _EXT4-JWV-IOR ! _EXT4-JWV-BYTES !
    _EXT4-JWV-IOR @ IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-BYTES @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JWM-META-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JWM-DATA-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JWM-REVOKE-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    _EXT4-JWM-CP-RANGE-CAP @ <> IF FALSE EXIT THEN
    -1 _EXT4-JWV-OK !
    _EXT4-JWV-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWV-CURSOR !
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-B + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    2 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-CURSOR @
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-WRITER @ + <> IF 0 _EXT4-JWV-OK ! THEN
    _EXT4-JWV-OK @ ;

: _EXT4-JWR-COUNTS?  ( capacity credit used active -- flag )
    _EXT4-JWV-ACTIVE ! _EXT4-JWV-USED !
    _EXT4-JWV-CREDIT ! _EXT4-JWV-CAP !
    _EXT4-JWV-CAP @ 0< _EXT4-JWV-CREDIT @ 0< OR
    _EXT4-JWV-USED @ 0< OR _EXT4-JWV-ACTIVE @ 0< OR IF FALSE EXIT THEN
    _EXT4-JWV-CREDIT @ _EXT4-JWV-CAP @ U>
    _EXT4-JWV-USED @ _EXT4-JWV-CREDIT @ U> OR
    _EXT4-JWV-ACTIVE @ _EXT4-JWV-USED @ U> OR 0= ;

: _EXT4-JWV-RING-POS?  ( logical -- flag )
    DUP _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ U< IF DROP FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< ;

: _EXT4-JWR-ZERO-CP-DELETE-RANGES  ( writer -- )
    DUP _EXT4-JWR.CP-DELETE-RANGES + @
    SWAP _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS 0 FILL ;

: _EXT4-JWR-CP-DELETE-RANGES-ZERO?  ( writer -- flag )
    DUP _EXT4-JWR.CP-DELETE-RANGES + @
    SWAP _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS
    _EXT4-BYTES-ZERO? ;

: _EXT4-JWR-CLEAR-CP-AUTHORITY  ( writer -- )
    DUP _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JWR.CP-MODE +
    _EXT4-JWR-SIZE _EXT4-JWR.CP-MODE - 0 FILL ;

: _EXT4-JWR-TRANSACTION-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.DATA-CREDIT + @ OR
    OVER _EXT4-JWR.REVOKE-CREDIT + @ OR
    OVER _EXT4-JWR.META-USED + @ OR
    OVER _EXT4-JWR.DATA-USED + @ OR
    OVER _EXT4-JWR.REVOKE-USED + @ OR
    OVER _EXT4-JWR.META-ACTIVE + @ OR
    OVER _EXT4-JWR.DATA-ACTIVE + @ OR
    OVER _EXT4-JWR.REVOKE-ACTIVE + @ OR
    OVER _EXT4-JWR.LOG-RESERVED + @ OR
    OVER _EXT4-JWR.TX-START + @ OR
    OVER _EXT4-JWR.TX-CURSOR + @ OR
    OVER _EXT4-JWR.TX-TID + @ OR
    OVER _EXT4-JWR.CP-MODE + @ OR
    OVER _EXT4-JWR.CP-EPOCH + @ OR
    OVER _EXT4-JWR.CP-O-INO + @ OR
    OVER _EXT4-JWR.CP-O-LOGICAL + @ OR
    OVER _EXT4-JWR.CP-O-SLOT + @ OR
    OVER _EXT4-JWR.CP-O-HOME + @ OR
    OVER _EXT4-JWR.CP-O-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-HOME + @ OR
    OVER _EXT4-JWR.CP-TARGET-OFF + @ OR
    OVER _EXT4-JWR.CP-TARGET-CRC + @ OR
    OVER _EXT4-JWR.CP-ORPHAN-CRC + @ OR
    OVER _EXT4-JWR.CP-TARGET-ENTRIES + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-OFF + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-SUPER-CRC + @ OR
    OVER _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ OR
    OVER _EXT4-JWR.CP-DELETE-BLOCKS + @ OR
    OVER _EXT4-JWR-CP-DELETE-RANGES
    2 PICK _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS
    _EXT4-BYTES-ZERO? 0= OR
    OVER _EXT4-JWR.CP-EA-HOME + @ OR
    OVER _EXT4-JWR.CP-DATA-MAP-KIND + @ OR
    OVER _EXT4-JWR.CP-PRE-ACTIVE + @ OR
    OVER _EXT4-JWR.CP-PRE-MODERN + @ OR
    OVER _EXT4-JWR.CP-PRE-LEGACY + @ OR
    OVER _EXT4-JWR.CP-EA-ACTION + @ OR
    OVER _EXT4-JWR.CP-EA-REFCOUNT + @ OR
    SWAP _EXT4-JWR.CP-EA-CRC + @ OR 0= ;

: _EXT4-JWR-IDLE-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR-TRANSACTION-CLEAN?
    SWAP _EXT4-JWR.PHASE + @ 0= AND ;

VARIABLE _EXT4-JWV-LOG-EXPECTED
VARIABLE _EXT4-JWV-LOG-IOR
VARIABLE _EXT4-JWV-RES-META
VARIABLE _EXT4-JWV-RES-REVOKE
VARIABLE _EXT4-JWV-RES-WRITER

: _EXT4-JWV-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JWV-LOG-ADD?  ( nonnegative-u -- flag )
    _EXT4-JWV-LOG-EXPECTED @ SWAP _EXT4-UADD?
    _EXT4-JWV-LOG-IOR ! _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-LOG-IOR @ 0= ;

: _EXT4-JWR-RESERVATION-COUNTS?
  ( meta-count revoke-count writer -- flag )
    _EXT4-JWV-RES-WRITER ! _EXT4-JWV-RES-REVOKE !
    _EXT4-JWV-RES-META !
    _EXT4-JWV-RES-META @ _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-RES-META @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @
    32 - _EXT4-JBD2-TAG3-SIZE /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-REVOKE @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @ 20 - 8 /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    2 _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-JWV-LOG-EXPECTED @ = ;

: _EXT4-JWR-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.REVOKE-CREDIT + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWR-ACTUAL-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-ACTIVE + @
    OVER _EXT4-JWR.REVOKE-ACTIVE + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWP-ACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-GUARD-PRESEED >=
    SWAP _EXT4-JWP-GUARD-RETIRE <= AND ;

: _EXT4-JWP-EMISSION?  ( phase -- flag )
    DUP _EXT4-JWP-ORDERED-DATA >=
    SWAP _EXT4-JWP-COMMIT-FLUSH <= AND ;

: _EXT4-JWP-CHECKPOINT?  ( phase -- flag )
    DUP _EXT4-JWP-CHECKPOINT-PREFLIGHT >=
    SWAP _EXT4-JWP-CHECKPOINT-FINAL-PROOF <= AND ;

: _EXT4-JWP-DEACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-DEACTIVATE-PREFLIGHT >=
    SWAP _EXT4-JWP-DEACTIVATE-FINAL-PROOF <= AND ;

VARIABLE _EXT4-JCA-WRITER
VARIABLE _EXT4-JCA-MODE
VARIABLE _EXT4-JCA-TARGET-HOME
VARIABLE _EXT4-JCA-BITMAP-HOME
VARIABLE _EXT4-JCA-GDT-HOME
VARIABLE _EXT4-JCA-TARGET-ENTRIES
VARIABLE _EXT4-JCA-RANGE-COUNT
VARIABLE _EXT4-JCA-RANGE-CAP
VARIABLE _EXT4-JCA-RANGE-INDEX
VARIABLE _EXT4-JCA-OTHER-INDEX
VARIABLE _EXT4-JCA-DATA-FIRST
VARIABLE _EXT4-JCA-DATA-COUNT
VARIABLE _EXT4-JCA-DATA-BLOCKS
VARIABLE _EXT4-JCA-DATA-SUM
VARIABLE _EXT4-JCA-EA-HOME
VARIABLE _EXT4-JCA-EA-ACTION
VARIABLE _EXT4-JCA-EA-REFCOUNT
VARIABLE _EXT4-JCA-EA-CRC
VARIABLE _EXT4-JCA-DATA-MAP-KIND
VARIABLE _EXT4-JCA-MAP-ENTRIES
VARIABLE _EXT4-JCA-MAP-DATA-CAP
VARIABLE _EXT4-JCA-MAP-INDEX
VARIABLE _EXT4-JCA-REVOKE-COUNT
VARIABLE _EXT4-JCA-REVOKE-INDEX
VARIABLE _EXT4-JCA-REVOKE-HOME
VARIABLE _EXT4-JCA-PRE-ACTIVE
VARIABLE _EXT4-JCA-PRE-MODERN
VARIABLE _EXT4-JCA-PRE-LEGACY

: _EXT4-JCA-DATA-RANGES?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @ DUP
    _EXT4-JCA-RANGE-CAP ! DUP 0= SWAP 0< OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ DUP
    _EXT4-JCA-RANGE-COUNT !
    DUP 0< SWAP _EXT4-JCA-RANGE-CAP @ U> OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @ DUP
    _EXT4-JCA-DATA-BLOCKS !
    DUP 0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-RANGE-COUNT @ 0= IF
        IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES
        _EXT4-JCA-RANGE-CAP @ 2* CELLS
        _EXT4-BYTES-ZERO?
        EXIT
    THEN
    0= IF FALSE EXIT THEN
    0 _EXT4-JCA-DATA-SUM !
    0 _EXT4-JCA-RANGE-INDEX !
    BEGIN
        _EXT4-JCA-RANGE-INDEX @ _EXT4-JCA-RANGE-COUNT @ U<
    WHILE
        _EXT4-JCA-RANGE-INDEX @ _EXT4-JCA-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE DUP @ _EXT4-JCA-DATA-FIRST !
        CELL+ @ DUP _EXT4-JCA-DATA-COUNT !
        DUP 0= SWAP 32768 U> OR IF FALSE EXIT THEN
        _EXT4-JCA-DATA-FIRST @ DUP 0= IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.FIRST + @ U< IF
            FALSE EXIT
        THEN
        _EXT4-JCA-DATA-FIRST @ _EXT4-JCA-DATA-COUNT @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @
        BLOCK-RANGE? 0= IF FALSE EXIT THEN
        _EXT4-JCA-DATA-SUM @ _EXT4-JCA-DATA-COUNT @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP _EXT4-JCA-DATA-SUM !
        0 _EXT4-JCA-OTHER-INDEX !
        BEGIN
            _EXT4-JCA-OTHER-INDEX @ _EXT4-JCA-RANGE-INDEX @ U<
        WHILE
            _EXT4-JCA-DATA-FIRST @ _EXT4-JCA-DATA-COUNT @
            _EXT4-JCA-OTHER-INDEX @ _EXT4-JCA-WRITER @
            _EXT4-JWR-CP-DELETE-RANGE DUP @ SWAP CELL+ @
            _EXT4-BLOCK-RANGES-OVERLAP? IF FALSE EXIT THEN
            1 _EXT4-JCA-OTHER-INDEX +!
        REPEAT
        1 _EXT4-JCA-RANGE-INDEX +!
    REPEAT
    _EXT4-JCA-DATA-SUM @ _EXT4-JCA-DATA-BLOCKS @ <> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES
    _EXT4-JCA-RANGE-COUNT @ 2* CELLS +
    _EXT4-JCA-RANGE-CAP @ _EXT4-JCA-RANGE-COUNT @ -
    2* CELLS _EXT4-BYTES-ZERO? ;

\ Validate the independent external-xattr authority without consuming a data
\ range slot.  RELEASE has no retained header state.  REFDEC binds the durable
\ post-decrement refcount and exact retained-image CRC while keeping the home
\ allocated.  Every present home remains disjoint from the data vector.
: _EXT4-JCA-EA-HOME?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-HOME + @ DUP
    _EXT4-JCA-EA-HOME ! DUP 0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-ACTION + @ DUP
    _EXT4-JCA-EA-ACTION ! DUP 0< IF 2DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ DUP
    _EXT4-JCA-EA-REFCOUNT ! DUP 0< IF 2DROP DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-CRC + @ DUP
    _EXT4-JCA-EA-CRC ! DUP 0< OVER 0xFFFFFFFF U> OR IF
        2DROP 2DROP FALSE EXIT
    THEN
    2DROP 2DROP
    _EXT4-JCA-EA-HOME @ 0= IF
        _EXT4-JCA-EA-ACTION @ _EXT4-JEA-NONE =
        _EXT4-JCA-EA-REFCOUNT @ 0= AND
        _EXT4-JCA-EA-CRC @ 0= AND EXIT
    THEN
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        _EXT4-JCA-EA-REFCOUNT @
        _EXT4-JCA-EA-CRC @ OR IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-EA-ACTION @ _EXT4-JEA-REFDEC <> IF FALSE EXIT THEN
        _EXT4-JCA-EA-REFCOUNT @ DUP 0= IF DROP FALSE EXIT THEN
        _EXT4-XATTR-REFCOUNT-MAX U< 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-EA-HOME @
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.FIRST + @ U< IF DROP FALSE EXIT THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF DROP FALSE EXIT THEN
    DROP
    _EXT4-JCA-RANGE-COUNT @ 0 ?DO
        _EXT4-JCA-EA-HOME @ 1
        I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE
        DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-OVERLAP? IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

\ Bind deletion authority to the inode representation that produced its exact
\ range vector.  Legacy direct slots stay as singleton ranges in logical-slot
\ order; an arbitrary coalesced range is not an equivalent direct-map proof.
: _EXT4-JCA-DELETE-DATA-MAP?  ( -- flag )
    0 _EXT4-JCA-MAP-ENTRIES !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @ DUP
    _EXT4-JCA-DATA-MAP-KIND !
    _EXT4-JDM-INLINE-EXTENTS = IF
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF FALSE EXIT THEN
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ = EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @ _EXT4-JDM-DEPTH1-LEAVES = IF
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ U> IF
            FALSE EXIT
        THEN
        _EXT4-JCA-RANGE-COUNT @ _EXT4-JCA-TARGET-ENTRIES @ -
        DUP _EXT4-JCA-MAP-ENTRIES !
        DUP 0= SWAP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-JCA-MAP-ENTRIES @ U< IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 12 - 12 /
        _EXT4-JCA-MAP-ENTRIES @ _EXT4-UMUL?
        DUP IF 2DROP FALSE EXIT THEN DROP _EXT4-JCA-MAP-DATA-CAP !
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-JCA-MAP-DATA-CAP @ U> IF FALSE EXIT THEN
        0 _EXT4-JCA-MAP-INDEX !
        BEGIN
            _EXT4-JCA-MAP-INDEX @ _EXT4-JCA-MAP-ENTRIES @ U<
        WHILE
            _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-MAP-INDEX @ +
            _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE
            CELL+ @ 1 <> IF FALSE EXIT THEN
            1 _EXT4-JCA-MAP-INDEX +!
        REPEAT
        TRUE EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @
    _EXT4-JDM-LEGACY-SINGLE-INDIRECT = IF
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ U> IF
            FALSE EXIT
        THEN
        _EXT4-JCA-RANGE-COUNT @ _EXT4-JCA-TARGET-ENTRIES @ -
        DUP _EXT4-JCA-MAP-ENTRIES ! 1 <> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 4 /
        _EXT4-LEGACY-DIRECT-RANGE-MAX _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP _EXT4-JCA-MAP-DATA-CAP !
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-JCA-MAP-DATA-CAP @ U> IF FALSE EXIT THEN
        _EXT4-JCA-TARGET-ENTRIES @ 0 ?DO
            I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE CELL+ @
            1 <> IF FALSE UNLOOP EXIT THEN
        LOOP
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE CELL+ @ 1 = EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @
    _EXT4-JDM-LEGACY-SPARSE-DOUBLE = IF
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ U> IF
            FALSE EXIT
        THEN
        _EXT4-JCA-RANGE-COUNT @ _EXT4-JCA-TARGET-ENTRIES @ -
        DUP _EXT4-JCA-MAP-ENTRIES !
        DUP 1 U< SWAP
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 4 / 2 + U> OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 4 /
        _EXT4-JCA-MAP-ENTRIES @ 1- _EXT4-UMUL?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-LEGACY-DIRECT-RANGE-MAX _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP _EXT4-JCA-MAP-DATA-CAP !
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-JCA-MAP-DATA-CAP @ U> IF FALSE EXIT THEN
        _EXT4-JCA-RANGE-COUNT @ 0 ?DO
            I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE CELL+ @
            1 <> IF FALSE UNLOOP EXIT THEN
        LOOP
        TRUE EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @
    _EXT4-JDM-LEGACY-SPARSE-TRIPLE = IF
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-LEGACY-DIRECT-RANGE-MAX U> IF FALSE EXIT THEN
        _EXT4-JCA-TARGET-ENTRIES @ 1 _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JCA-RANGE-COUNT @ <> IF FALSE EXIT THEN
        1 _EXT4-JCA-MAP-ENTRIES !
        _EXT4-JCA-RANGE-COUNT @ 0 ?DO
            I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE CELL+ @
            1 <> IF FALSE UNLOOP EXIT THEN
        LOOP
        TRUE EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @
    _EXT4-JDM-LEGACY-SPARSE-TRIPLE-CHILD = IF
        _EXT4-JCA-TARGET-ENTRIES @ IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME @ IF FALSE EXIT THEN
        _EXT4-JCA-RANGE-COUNT @ 2 <> IF FALSE EXIT THEN
        2 _EXT4-JCA-MAP-ENTRIES !
        _EXT4-JCA-RANGE-COUNT @ 0 ?DO
            I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE CELL+ @
            1 <> IF FALSE UNLOOP EXIT THEN
        LOOP
        TRUE EXIT
    THEN
    _EXT4-JCA-DATA-MAP-KIND @ _EXT4-JDM-LEGACY-DIRECT <> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-TARGET-ENTRIES @
    _EXT4-LEGACY-DIRECT-RANGE-MAX U> IF FALSE EXIT THEN
    _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ <> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-RANGE-COUNT @ 0 ?DO
        I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE CELL+ @
        1 <> IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

: _EXT4-JCA-REVOKE-ENTRY?  ( index home -- flag )
    _EXT4-JCA-REVOKE-HOME ! _EXT4-JCA-REVOKE-INDEX !
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JCA-REVOKE-INDEX @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * +
    DUP @ _EXT4-JCA-REVOKE-HOME @ =
    SWAP CELL+ @ _EXT4-JE-ACTIVE = AND ;

\ DELETE-DATA-MAP? derives the trailing map count from the typed checkpoint
\ vector.  Recheck that relationship before it can drive generic revoke
\ storage.
: _EXT4-JCA-TYPED-MAP-ENTRIES?  ( -- flag )
    _EXT4-JCA-DATA-MAP-KIND @ DUP _EXT4-JDM-DEPTH1-LEAVES = IF
        DROP _EXT4-JCA-MAP-ENTRIES @ DUP 0=
        SWAP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR 0= EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SINGLE-INDIRECT = IF
        DROP _EXT4-JCA-MAP-ENTRIES @ 1 = EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-DOUBLE = IF
        DROP _EXT4-JCA-MAP-ENTRIES @ DUP 1 U<
        SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 4 / 2 +
        U> OR 0= EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-TRIPLE = IF
        DROP _EXT4-JCA-MAP-ENTRIES @ 1 =
        _EXT4-JCA-TARGET-ENTRIES @
        _EXT4-LEGACY-DIRECT-RANGE-MAX U> 0= AND EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-TRIPLE-CHILD = IF
        DROP _EXT4-JCA-MAP-ENTRIES @ 2 =
        _EXT4-JCA-TARGET-ENTRIES @ 0= AND
        _EXT4-JCA-EA-HOME @ 0= AND EXIT
    THEN
    DUP _EXT4-JDM-INLINE-EXTENTS =
    SWAP _EXT4-JDM-LEGACY-DIRECT = OR IF
        _EXT4-JCA-MAP-ENTRIES @ 0= EXIT
    THEN
    FALSE ;

\ Bind generic revoke storage back to the typed deletion authority retained
\ in the checkpoint certificate.  Every trailing map singleton is revoked in
\ vector order; a released xattr follows all map metadata.
: _EXT4-JCA-DELETE-REVOKES?  ( -- flag )
    _EXT4-JCA-TYPED-MAP-ENTRIES? 0= IF FALSE EXIT THEN
    _EXT4-JCA-MAP-ENTRIES @ _EXT4-JCA-REVOKE-COUNT !
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        1 _EXT4-JCA-REVOKE-COUNT +!
    THEN
    _EXT4-JCA-REVOKE-COUNT @
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-REVOKE-COUNT @ DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <>
    OVER _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @ <> OR
    SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
        FALSE EXIT
    THEN
    0 _EXT4-JCA-MAP-INDEX !
    BEGIN
        _EXT4-JCA-MAP-INDEX @ _EXT4-JCA-MAP-ENTRIES @ U<
    WHILE
        _EXT4-JCA-MAP-INDEX @
        _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-MAP-INDEX @ +
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE @
        _EXT4-JCA-REVOKE-ENTRY? 0= IF
            FALSE EXIT
        THEN
        1 _EXT4-JCA-MAP-INDEX +!
    REPEAT
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        _EXT4-JCA-MAP-ENTRIES @
        _EXT4-JCA-EA-HOME @ _EXT4-JCA-REVOKE-ENTRY? 0= IF
            FALSE EXIT
        THEN
    THEN
    TRUE ;

: _EXT4-JCPM-ORPHAN-MODERN?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-FINAL =
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-LEGACY?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-LEGACY-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-DATA-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-FINAL?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-MORE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-MORE =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-FINAL?
    SWAP _EXT4-JCPM-ORPHAN-MORE? OR ;

: _EXT4-JCA-REVOKES?  ( -- flag )
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCA-DELETE-REVOKES? EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR 0= ;

\ An orphan-cleanup certificate is arena-owned transaction state, not a global
\ permission bit.  Its typed ranges and revoke vector are exact transaction
\ authority; raw locators and staged images are authenticated again at
\ checkpoint.
: _EXT4-JWR-CP-AUTHORITY?  ( writer -- flag )
    DUP _EXT4-JCA-WRITER !
    0 _EXT4-JCA-MAP-ENTRIES !
    0 _EXT4-JCA-MAP-DATA-CAP !
    0 _EXT4-JCA-MAP-INDEX !
    _EXT4-JDM-NONE _EXT4-JCA-DATA-MAP-KIND !
    _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCA-MODE ! _EXT4-JCPM-NONE = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH +
        _EXT4-JWR-SIZE _EXT4-JWR.CP-EPOCH - _EXT4-BYTES-ZERO?
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES-ZERO? AND EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.EPOCH + @ <> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-INO + @ DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0< IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 8 - 4 / U< 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ ?DUP IF
            DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
                DROP FALSE EXIT
            THEN
            _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK <> IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-TARGET-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JCA-TARGET-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @
    DUP 0< OVER _EXT4-JCA-WRITER @
    _EXT4-JWR.CP-DELETE-RANGE-CAP + @ U> OR IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-TARGET-ENTRIES !
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? IF
        _EXT4-JCA-DATA-RANGES? 0= IF FALSE EXIT THEN
        _EXT4-JCA-RANGE-COUNT @ 0= IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME? 0= IF FALSE EXIT THEN
        _EXT4-JCA-DELETE-DATA-MAP? 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
            _EXT4-JCA-TARGET-ENTRIES @ IF FALSE EXIT THEN
            _EXT4-JCA-DATA-RANGES? 0= IF FALSE EXIT THEN
            _EXT4-JCA-RANGE-COUNT @ IF FALSE EXIT THEN
            _EXT4-JCA-EA-HOME? 0= IF FALSE EXIT THEN
            _EXT4-JCA-DELETE-DATA-MAP? 0= IF FALSE EXIT THEN
        ELSE
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @
            _EXT4-JDM-NONE <> IF FALSE EXIT THEN
            _EXT4-JCA-TARGET-ENTRIES @
            _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF FALSE EXIT THEN
            _EXT4-JCA-TARGET-ENTRIES @ 0=
            _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN?
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0= OR AND IF
                _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ IF
                    FALSE EXIT
                THEN
            THEN
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-HOME + @
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-ACTION + @ OR
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ OR
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-CRC + @ OR IF
                FALSE EXIT
            THEN
        THEN
    THEN
    _EXT4-JCA-REVOKES? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.ISIZE + @ U< IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ DUP
        _EXT4-JCA-BITMAP-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-BITMAP-HOME @ _EXT4-JCA-TARGET-HOME @ =
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ DUP
        _EXT4-JCA-GDT-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-BITMAP-HOME @ =
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-TARGET-HOME @ = OR
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK =
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME @ ?DUP IF
            DUP _EXT4-JCA-TARGET-HOME @ =
            OVER _EXT4-JCA-BITMAP-HOME @ = OR
            OVER _EXT4-JCA-GDT-HOME @ = OR
            OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
            SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
        _EXT4-DESC-SIZE U< IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? 0= IF
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT +
            _EXT4-JWR.CP-EA-HOME _EXT4-JWR.CP-DELETE-RANGE-COUNT -
            _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME +
        _EXT4-JWR.CP-PRE-ACTIVE _EXT4-JWR.CP-INODE-BITMAP-HOME -
        _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ DUP
    _EXT4-JCA-PRE-ACTIVE ! DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ DUP
    _EXT4-JCA-PRE-MODERN ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ DUP
    _EXT4-JCA-PRE-LEGACY ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-ACTIVE @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-PRE-LEGACY @ _EXT4-JCA-PRE-ACTIVE @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-LEGACY @ _EXT4-UADD?
    DUP IF 2DROP FALSE EXIT THEN DROP
    _EXT4-JCA-PRE-ACTIVE @ <> IF FALSE EXIT THEN
    _EXT4-JCA-PRE-ACTIVE @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.INODES + @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCA-PRE-MODERN @ 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-PRE-LEGACY @ 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCA-PRE-ACTIVE @ 1 <> IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MORE? 0= IF FALSE EXIT THEN
        _EXT4-JCA-PRE-ACTIVE @ 1 U> 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.PHASE + @ DUP
        _EXT4-JWP-EMISSION? SWAP _EXT4-JWP-CHECKPOINT? OR EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = OVER _EXT4-JWR-EMITTING = OR
    OVER _EXT4-JWR-COMMITTED = OR
    SWAP _EXT4-JWR-CHECKPOINTING = OR ;

: _EXT4-JWR-RUNTIME?  ( writer -- flag )
    DUP _EXT4-JWV-WRITER !
    _EXT4-JWR.STATE + @ DUP _EXT4-JWV-STATE !
    DUP 0< SWAP _EXT4-JWR-DEACTIVATING U> OR IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.PHASE + @ _EXT4-JWV-PHASE !
    _EXT4-JWV-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF FALSE EXIT THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ 0= IF FALSE EXIT THEN
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ IF FALSE EXIT THEN
        _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? 0= IF
                FALSE EXIT
            THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? 0= IF
                FALSE EXIT
            THEN
        ELSE
            _EXT4-JWV-PHASE @ IF FALSE EXIT THEN
        THEN THEN THEN THEN
    THEN
    0 _EXT4-JWV-COMMITTED-SHAPE !
    _EXT4-JWV-STATE @ _EXT4-JWR-COMMITTED =
    _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? AND OR IF
        -1 _EXT4-JWV-COMMITTED-SHAPE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
            FALSE EXIT
        THEN
    ELSE _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND IF
            _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
                FALSE EXIT
            THEN
        THEN
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ - 1-
    _EXT4-JWV-RING-CAP !
    _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
        <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.ANCHOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.COMMITTED + @
        1 <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.NEXT-SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
        0xFFFFFFFF AND <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.WITNESS + @ DUP IF
            _EXT4-JW-RECOVERY <> IF FALSE EXIT THEN
            _EXT4-JWV-PHASE @
            _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR < IF FALSE EXIT THEN
        ELSE
            DROP
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.PRIMARY-TORN + @ IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.SUPER-TORN + @ IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @ IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-IDLE = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-IDLE-CLEAN? EXIT
    THEN
    0 _EXT4-JWV-TX-ACTIVE !
    _EXT4-JWV-STATE @ _EXT4-JWR-STAGING =
    _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = OR IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? AND IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-TX-ACTIVE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-RESERVATION? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-ACTUAL-RESERVATION? 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-ADVANCE
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 1+
        0xFFFFFFFF AND
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    \ The only remaining states are activation/deactivation, or a fault in one
    \ of those clean-transaction protocols, whose invariant was proved above.
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
    _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND OR ;

: _EXT4-JWR-VALID?  ( writer -- flag )
    DUP _EXT4-JWR-SHAPE? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWR-RUNTIME? ;

VARIABLE _EXT4-JWN-META
VARIABLE _EXT4-JWN-DATA
VARIABLE _EXT4-JWN-REVOKE
VARIABLE _EXT4-JWN-CTX
VARIABLE _EXT4-JWN-BSIZE
VARIABLE _EXT4-JWN-MAXLEN
VARIABLE _EXT4-JWN-FIRST
VARIABLE _EXT4-JWN-HEAD
VARIABLE _EXT4-JWN-FREE
VARIABLE _EXT4-JWN-BYTES
VARIABLE _EXT4-JWN-IOR
VARIABLE _EXT4-JWN-WRITER
VARIABLE _EXT4-JWN-CURSOR

: _EXT4-JWR-MATCH?  ( writer -- flag )
    DUP _EXT4-JWR-VALID? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-JWN-CTX @ =
    OVER _EXT4-JWR.BSIZE + @ _EXT4-JWN-BSIZE @ = AND
    OVER _EXT4-JWR.MAXLEN + @ _EXT4-JWN-MAXLEN @ = AND
    OVER _EXT4-JWR.FIRST + @ _EXT4-JWN-FIRST @ = AND
    OVER _EXT4-JWR.META-CAP + @ _EXT4-JWN-META @ U< 0= AND
    OVER _EXT4-JWR.DATA-CAP + @ _EXT4-JWN-DATA @ U< 0= AND
    SWAP _EXT4-JWR.REVOKE-CAP + @ _EXT4-JWN-REVOKE @ U< 0= AND ;

: _EXT4-JWR-ZERO-OWNED  ( writer -- )
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-HASH + @
    OVER _EXT4-JWR.META-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.DATA-HASH + @
    OVER _EXT4-JWR.DATA-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.REVOKE-HASH + @
    OVER _EXT4-JWR.REVOKE-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JWR-ZERO-CP-DELETE-RANGES ;

: _EXT4-JWR-REBASE-IDLE  ( writer -- writer )
    DUP _EXT4-JWR-ZERO-OWNED
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 OVER _EXT4-JWR.PHASE + !
    _EXT4-JWN-HEAD @ DUP 2 PICK _EXT4-JWR.HEAD + !
    OVER _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ OVER _EXT4-JWR.FREE + !
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    OVER _EXT4-JWR.NEXT-TID + ! ;

\ Validate and retain one requested capacity tuple in the shared constructor
\ state.  Allocation policy is deliberately separate: production profiles use
\ a fresh dedicated arena, while pre-publication recovery uses a scoped tail
\ allocation from the ordinary mount arena.
: _EXT4-JWR-PREPARE  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JWN-CTX ! _EXT4-JWN-REVOKE !
    _EXT4-JWN-DATA ! _EXT4-JWN-META !
    _EXT4-JWN-CTX @ _EXT4-JWR-CONTEXT? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JWN-CTX @ _EXT4-C.BSIZE + @ _EXT4-JWN-BSIZE !
    _EXT4-JWN-META @ _EXT4-JWN-DATA @ _EXT4-JWN-REVOKE @
    _EXT4-JWN-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JWN-IOR ! _EXT4-JWN-BYTES !
    _EXT4-JWN-IOR @ ?DUP IF EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.MAXLEN + @ _EXT4-JWN-MAXLEN !
    _EXT4-JWN-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JWN-FIRST !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-FIRST @ - DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN
    1- _EXT4-JWN-FREE !
    _EXT4-JWN-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JWN-FIRST @
    ELSE
        DUP _EXT4-JWN-FIRST @ U<
        OVER _EXT4-JWN-MAXLEN @ U< 0= OR IF
            DROP VFS-E-INVALID EXIT
        THEN
    THEN _EXT4-JWN-HEAD ! 0 ;

\ Construct one complete writer layout at an already-owned exact span.  This
\ word neither allocates nor publishes the context pointer.
: _EXT4-JWR-BUILD-AT  ( address -- writer ior )
    DUP _EXT4-JWN-WRITER ! _EXT4-JWN-BYTES @ 0 FILL
    _EXT4-JWR-MAGIC _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
    _EXT4-JWN-WRITER @ DUP _EXT4-JWR.SELF + !
    _EXT4-JWN-CTX @ _EXT4-JWN-WRITER @ _EXT4-JWR.CTX + !
    _EXT4-JWN-BYTES @ _EXT4-JWN-WRITER @ _EXT4-JWR.TOTAL + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-WRITER @ _EXT4-JWR.BSIZE + !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-WRITER @ _EXT4-JWR.MAXLEN + !
    _EXT4-JWN-FIRST @ _EXT4-JWN-WRITER @ _EXT4-JWR.FIRST + !
    _EXT4-JWN-META @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-CAP + !
    _EXT4-JWM-META-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-SLOTS + !
    _EXT4-JWN-DATA @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-CAP + !
    _EXT4-JWM-DATA-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-SLOTS + !
    _EXT4-JWN-REVOKE @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-CAP + !
    _EXT4-JWM-REVOKE-SLOTS @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-SLOTS + !
    _EXT4-JWN-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWN-CURSOR !
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.META-ENTRIES + !
    _EXT4-JWN-META @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-ENTRIES + !
    _EXT4-JWN-DATA @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + !
    _EXT4-JWN-REVOKE @ _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-HASH + !
    _EXT4-JWM-META-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-HASH + !
    _EXT4-JWM-DATA-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-HASH + !
    _EXT4-JWM-REVOKE-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-IMAGES + !
    _EXT4-JWN-META @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-IMAGES + !
    _EXT4-JWN-DATA @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-A + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-B + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.CP-DELETE-RANGES + !
    _EXT4-JWM-CP-RANGE-CAP @
    _EXT4-JWN-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + !
    _EXT4-JWM-CP-RANGE-CAP @ 2 CELLS * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWN-BYTES @ + <> IF
        0 _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWN-HEAD @ DUP _EXT4-JWN-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JWN-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ _EXT4-JWN-WRITER @ _EXT4-JWR.FREE + !
    \ Linux advances past a clean superblock's persisted tail sequence when
    \ it initializes the next running transaction, including 32-bit wrap.
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JWN-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWN-WRITER @ 0 ;

VARIABLE _EXT4-JAL-META
VARIABLE _EXT4-JAL-DATA
VARIABLE _EXT4-JAL-REVOKE
VARIABLE _EXT4-JAL-KIND
VARIABLE _EXT4-JAL-ARENA
VARIABLE _EXT4-JAL-CTX
VARIABLE _EXT4-JAL-MARK
VARIABLE _EXT4-JAL-ALLOCATION
VARIABLE _EXT4-JAL-WRITER
VARIABLE _EXT4-JAL-IOR

: _EXT4-JWR-ALLOCATE-ROLLBACK  ( -- )
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + !
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-STORE-KIND + !
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JAL-ALLOCATION @ ?DUP IF _EXT4-JWN-BYTES @ 0 FILL THEN
    _EXT4-JAL-ARENA @ _EXT4-JAL-MARK @ ARENA-ROLLBACK ;

\ Allocate exactly once in an explicitly selected store.  The caller has
\ already applied any dedicated-arena admission policy; this shared boundary
\ still proves live bounds and publishes storage kind/arena before publishing
\ the writer pointer last.
: _EXT4-JWR-ALLOCATE-IN
  ( meta-cap data-cap revoke-cap store-kind arena ctx -- writer ior )
    _EXT4-JAL-CTX ! _EXT4-JAL-ARENA ! _EXT4-JAL-KIND !
    _EXT4-JAL-REVOKE ! _EXT4-JAL-DATA ! _EXT4-JAL-META !
    0 _EXT4-JAL-ALLOCATION ! 0 _EXT4-JAL-WRITER !
    _EXT4-JAL-META @ _EXT4-JAL-DATA @ _EXT4-JAL-REVOKE @
    _EXT4-JAL-CTX @ _EXT4-JWR-PREPARE ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ OR
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + @ OR IF
        0 VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JAL-KIND @ _EXT4-JWR-STORE-MOUNT = IF
        _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.ARENA + @ <> IF
            0 VFS-E-INVALID EXIT
        THEN
    ELSE
        _EXT4-JAL-KIND @ _EXT4-JWR-STORE-DEDICATED <> IF
            0 VFS-E-INVALID EXIT
        THEN
        _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.ARENA + @ = IF
            0 VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-JAL-ARENA @ DUP 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ DUP 0= IF 2DROP 0 VFS-E-INVALID EXIT THEN
    DUP 7 AND IF 2DROP 0 VFS-E-INVALID EXIT THEN DROP
    DUP A.SIZE @ DUP 0< SWAP 0= OR IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ OVER A.SIZE @ MSPAN-NONWRAPPING? 0= IF
        DROP 0 VFS-E-INVALID EXIT
    THEN
    DUP A.PTR @ DUP _EXT4-JAL-MARK ! DUP 7 AND IF
        2DROP 0 VFS-E-INVALID EXIT
    THEN
    OVER A.BASE @ U< IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ OVER A.SIZE @ + _EXT4-JAL-MARK @ U< IF
        DROP 0 VFS-E-INVALID EXIT
    THEN DROP
    _EXT4-JWN-BYTES @ 7 AND IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JAL-MARK @ _EXT4-JWN-BYTES @ MSPAN-NONWRAPPING? 0= IF
        0 VFS-E-NOMEM EXIT
    THEN
    _EXT4-JAL-ARENA @ A.BASE @ _EXT4-JAL-ARENA @ A.SIZE @ +
    _EXT4-JAL-MARK @ _EXT4-JWN-BYTES @ + U< IF
        0 VFS-E-NOMEM EXIT
    THEN
    _EXT4-JAL-ARENA @ _EXT4-JWN-BYTES @ ARENA-ALLOT?
    IF DROP 0 VFS-E-NOMEM EXIT THEN
    DUP _EXT4-JAL-ALLOCATION ! DUP _EXT4-JAL-WRITER !
    _EXT4-JAL-MARK @ <> IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAL-WRITER @ _EXT4-JWR-BUILD-AT
    _EXT4-JAL-IOR ! _EXT4-JAL-WRITER !
    _EXT4-JAL-IOR @ IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 _EXT4-JAL-IOR @ EXIT
    THEN
    _EXT4-JAL-KIND @ _EXT4-JAL-CTX @
    _EXT4-C.J.WRITER-STORE-KIND + !
    _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JAL-WRITER @ _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + !
    _EXT4-JAL-WRITER @ _EXT4-JWR-VALID? 0= IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAL-WRITER @ 0 ;

VARIABLE _EXT4-JAM-META
VARIABLE _EXT4-JAM-DATA
VARIABLE _EXT4-JAM-REVOKE
VARIABLE _EXT4-JAM-CTX

: _EXT4-JWR-ALLOCATE-MOUNT
  ( meta-cap data-cap revoke-cap ctx -- writer ior )
    _EXT4-JAM-CTX ! _EXT4-JAM-REVOKE !
    _EXT4-JAM-DATA ! _EXT4-JAM-META !
    _EXT4-JAM-META @ _EXT4-JAM-DATA @ _EXT4-JAM-REVOKE @
    _EXT4-JWR-STORE-MOUNT _EXT4-JAM-CTX @ _EXT4-C.ARENA + @
    _EXT4-JAM-CTX @ _EXT4-JWR-ALLOCATE-IN ;

\ Consume an already configured writer profile.  A larger profile serves any
\ componentwise-contained request; an insufficient profile is a bounded-space
\ refusal and never selects new geometry or consumes another arena span.
: _EXT4-JWR-ENSURE  ( meta-cap data-cap revoke-cap ctx -- writer ior )
    _EXT4-JWR-PREPARE ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF
        DROP 0 VFS-E-NOSPC EXIT
    THEN
    DUP _EXT4-JWR-VALID? 0= IF DROP 0 VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JWR-MATCH? 0= IF DROP 0 VFS-E-NOSPC EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        DROP 0 VFS-E-BUSY EXIT
    THEN
    DUP _EXT4-JWR.FAULT + @ IF DROP 0 VFS-E-BUSY EXIT THEN
    _EXT4-JWR-REBASE-IDLE 0 ;

VARIABLE _EXT4-JMR-CTX
VARIABLE _EXT4-JMR-WRITER
VARIABLE _EXT4-JMR-HEAD
VARIABLE _EXT4-JMR-FREE
VARIABLE _EXT4-JMR-WRITE-ACTIVE

\ Rebase only after publication has been withdrawn and strict validation has
\ authenticated an empty standard journal.  Mount recovery supplies a clean
\ endpoint; a live checkpoint supplies the equally standard RECOVER-set,
\ write-active endpoint so later transactions do not repeat AKW1 activation.
: _EXT4-JWR-REBASE-ENDPOINT  ( ctx write-active? -- ior )
    _EXT4-JMR-WRITE-ACTIVE ! _EXT4-JMR-CTX !
    _EXT4-JMR-WRITE-ACTIVE @ IF
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @ 0=
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JMR-CTX @ _EXT4-C.SB + DUP
        _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.START + @
    _EXT4-JMR-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.SUPER-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER-CURRENT + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF DROP 0 EXIT THEN
    DUP _EXT4-JMR-WRITER ! _EXT4-JWR-SHAPE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ - 1- DUP 0< IF
        DROP VFS-E-CORRUPT EXIT
    THEN _EXT4-JMR-FREE !
    _EXT4-JMR-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @
    ELSE
        DUP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ U<
        OVER _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN _EXT4-JMR-HEAD !
    _EXT4-JMR-WRITER @ _EXT4-JWR-ZERO-OWNED
    _EXT4-JMR-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.FAULT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-START + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-CURSOR + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-TID + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JMR-HEAD @ DUP _EXT4-JMR-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JMR-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JMR-FREE @ _EXT4-JMR-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JMR-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JMR-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWR-IDLE _EXT4-JMR-WRITER @ _EXT4-JWR.STATE + !
    0 ;

\ A failed mount preserves the one arena allocation and all of its bytes for
\ diagnosis or retry, but never republishes it as a usable transaction.  Only
\ the final authenticated clean endpoint may scrub those retained bytes.
: _EXT4-JWR-REBASE-MOUNTED  ( ctx -- ior )
    0 _EXT4-JWR-REBASE-ENDPOINT ;

: _EXT4-JWR-REBASE-WRITE-ACTIVE  ( ctx -- ior )
    -1 _EXT4-JWR-REBASE-ENDPOINT ;

VARIABLE _EXT4-JHL-HOME
VARIABLE _EXT4-JHL-ENTRIES
VARIABLE _EXT4-JHL-STRIDE
VARIABLE _EXT4-JHL-HASH
VARIABLE _EXT4-JHL-SLOTS
VARIABLE _EXT4-JHL-USED
VARIABLE _EXT4-JHL-SLOT
VARIABLE _EXT4-JHL-INDEX
VARIABLE _EXT4-JHL-IOR

: _EXT4-JTX-HASH-FIND
  ( home entries entry-cells hash slots used -- index found? ior )
    _EXT4-JHL-USED ! _EXT4-JHL-SLOTS ! _EXT4-JHL-HASH !
    _EXT4-JHL-STRIDE !
    _EXT4-JHL-ENTRIES ! _EXT4-JHL-HOME !
    _EXT4-JHL-SLOTS @ 0= IF 0 FALSE 0 EXIT THEN
    _EXT4-JHL-HOME @ _EXT4-JHL-SLOTS @ 1- AND _EXT4-JHL-SLOT !
    _EXT4-JHL-SLOTS @ 0 ?DO
        _EXT4-JHL-HASH @ _EXT4-JHL-SLOT @ CELLS + @ DUP 0= IF
            DROP 0 FALSE 0 UNLOOP EXIT
        THEN
        1- DUP _EXT4-JHL-INDEX !
        _EXT4-JHL-USED @ U< 0= IF
            0 FALSE VFS-E-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JHL-INDEX @ _EXT4-JHL-STRIDE @ *
        CELLS _EXT4-JHL-ENTRIES @ + @
        _EXT4-JHL-HOME @ = IF
            _EXT4-JHL-INDEX @ TRUE 0 UNLOOP EXIT
        THEN
        _EXT4-JHL-SLOT @ 1+ _EXT4-JHL-SLOTS @ 1- AND
        _EXT4-JHL-SLOT !
    LOOP
    0 FALSE 0 ;

VARIABLE _EXT4-JHI-HOME
VARIABLE _EXT4-JHI-INDEX
VARIABLE _EXT4-JHI-HASH
VARIABLE _EXT4-JHI-SLOTS
VARIABLE _EXT4-JHI-SLOT

: _EXT4-JTX-HASH-INSERT  ( home index hash slots -- ior )
    _EXT4-JHI-SLOTS ! _EXT4-JHI-HASH !
    _EXT4-JHI-INDEX ! _EXT4-JHI-HOME !
    _EXT4-JHI-SLOTS @ 0= IF VFS-E-NOSPC EXIT THEN
    _EXT4-JHI-HOME @ _EXT4-JHI-SLOTS @ 1- AND _EXT4-JHI-SLOT !
    _EXT4-JHI-SLOTS @ 0 ?DO
        _EXT4-JHI-HASH @ _EXT4-JHI-SLOT @ CELLS + DUP @ 0= IF
            _EXT4-JHI-INDEX @ 1+ SWAP ! 0 UNLOOP EXIT
        THEN
        DROP
        _EXT4-JHI-SLOT @ 1+ _EXT4-JHI-SLOTS @ 1- AND
        _EXT4-JHI-SLOT !
    LOOP
    VFS-E-NOSPC ;

: _EXT4-JTX-ENTRY  ( index entries entry-cells -- entry )
    ROT * CELLS + ;

VARIABLE _EXT4-JIC-BUFFER
VARIABLE _EXT4-JIC-WRITER

: _EXT4-JTX-IMAGE-CRC  ( buffer writer -- crc ior )
    _EXT4-JIC-WRITER ! _EXT4-JIC-BUFFER !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JIC-BUFFER @
    _EXT4-JIC-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

: _EXT4-JTX-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JTX-TAGS/BLOCK-SIZE  ( block-size -- tags )
    32 - _EXT4-JBD2-TAG3-SIZE / ;

: _EXT4-JTX-REVOKES/BLOCK-SIZE  ( block-size -- revokes )
    20 - 8 / ;

: _EXT4-JTX-TAGS/BLOCK  ( writer -- tags )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-TAGS/BLOCK-SIZE ;

: _EXT4-JTX-REVOKES/BLOCK  ( writer -- revokes )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-REVOKES/BLOCK-SIZE ;

VARIABLE _EXT4-JLG-META
VARIABLE _EXT4-JLG-REVOKE
VARIABLE _EXT4-JLG-WRITER
VARIABLE _EXT4-JLG-BSIZE
VARIABLE _EXT4-JLG-TOTAL
VARIABLE _EXT4-JLG-ADD

: _EXT4-JTX-LOG-ADD  ( u -- ior )
    _EXT4-JLG-ADD !
    _EXT4-JLG-TOTAL @ _EXT4-JLG-ADD @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JLG-TOTAL ! 0 ;

: _EXT4-JTX-LOG-BLOCKS-FOR
  ( meta-credit revoke-credit block-size -- blocks ior )
    _EXT4-JLG-BSIZE ! _EXT4-JLG-REVOKE ! _EXT4-JLG-META !
    _EXT4-JLG-META @ 0< _EXT4-JLG-REVOKE @ 0< OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-BSIZE @ 1024 =
    _EXT4-JLG-BSIZE @ 2048 = OR
    _EXT4-JLG-BSIZE @ 4096 = OR 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JLG-META @ _EXT4-JLG-TOTAL !
    _EXT4-JLG-META @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-TAGS/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-REVOKE @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-REVOKES/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    \ One block holds the standard active-super guard outside the JBD2
    \ record stream, and one holds the transaction commit.  The ring's
    \ separately excluded spare remains available as an exact terminator.
    2 _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-TOTAL @ 0 ;

: _EXT4-JTX-LOG-BLOCKS  ( meta-credit revoke-credit writer -- blocks ior )
    DUP _EXT4-JLG-WRITER ! _EXT4-JWR-VALID? 0= IF
        2DROP 0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JTX-LOG-BLOCKS-FOR ;

VARIABLE _EXT4-JPC-META
VARIABLE _EXT4-JPC-DATA
VARIABLE _EXT4-JPC-REVOKE
VARIABLE _EXT4-JPC-CTX
VARIABLE _EXT4-JPC-BSIZE
VARIABLE _EXT4-JPC-BYTES
VARIABLE _EXT4-JPC-LOG
VARIABLE _EXT4-JPC-FREE
VARIABLE _EXT4-JPC-IOR

\ Prove that one requested profile and transaction can fit the authenticated
\ journal.  Storage admission is separate so a dedicated production arena is
\ never constrained by unrelated free space in the mount/VFS arena.
: _EXT4-JTX-PREFLIGHT-JOURNAL
  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JPC-CTX ! _EXT4-JPC-REVOKE !
    _EXT4-JPC-DATA ! _EXT4-JPC-META !
    _EXT4-JPC-CTX @ _EXT4-JWR-GEOMETRY? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.BSIZE + @ _EXT4-JPC-BSIZE !
    _EXT4-JPC-META @ _EXT4-JPC-DATA @ _EXT4-JPC-REVOKE @
    _EXT4-JPC-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JPC-IOR ! _EXT4-JPC-BYTES !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-META @ _EXT4-JPC-REVOKE @ _EXT4-JPC-BSIZE @
    _EXT4-JTX-LOG-BLOCKS-FOR _EXT4-JPC-IOR ! _EXT4-JPC-LOG !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JPC-CTX @ _EXT4-C.J.FIRST + @ - DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN
    1- DUP _EXT4-JPC-FREE ! 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-LOG @ _EXT4-JPC-FREE @ U> IF VFS-E-NOSPC EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        _EXT4-JPC-LOG @ 1- SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JPC-DATA @ SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    0 ;

\ Internal preflight additionally proves that an existing profile contains
\ the request, or that the ordinary mount arena can hold a not-yet-allocated
\ temporary recovery writer.  This word still performs no allocation.
: _EXT4-JTX-PREFLIGHT-CAPACITY
  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JTX-PREFLIGHT-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.WRITER + @ ?DUP IF
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.META-CAP + @ _EXT4-JPC-META @ U<
        OVER _EXT4-JWR.DATA-CAP + @ _EXT4-JPC-DATA @ U< OR
        SWAP _EXT4-JWR.REVOKE-CAP + @ _EXT4-JPC-REVOKE @ U< OR IF
            VFS-E-NOSPC EXIT
        THEN
        0 EXIT
    THEN
    _EXT4-JPC-BYTES @ _EXT4-JPC-CTX @ _EXT4-C.ARENA + @ ARENA-FREE
    U> IF VFS-E-NOMEM EXIT THEN
    0 ;

VARIABLE _EXT4-EWB-META
VARIABLE _EXT4-EWB-DATA
VARIABLE _EXT4-EWB-REVOKE
VARIABLE _EXT4-EWB-V
VARIABLE _EXT4-EWB-CTX

\ Return the exact storage required by one caller-selected capacity tuple,
\ but only when that complete tuple also fits the authenticated journal's
\ ring and advertised transaction limits.
: EXT4-WRITER-WORKSPACE-BYTES?
  ( meta-cap data-cap revoke-cap vfs -- bytes ior )
    _EXT4-EWB-V ! _EXT4-EWB-REVOKE !
    _EXT4-EWB-DATA ! _EXT4-EWB-META !
    _EXT4-EWB-V @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-EWB-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-EWB-V @ V.BCTX @ DUP _EXT4-EWB-CTX ! 0= IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-EWB-V @ _EXT4-ATTACHED? 0= IF 0 VFS-E-STALE EXIT THEN
    _EXT4-EWB-V @ _EXT4-READY? 0= IF 0 VFS-E-STALE EXIT THEN
    _EXT4-EWB-META @ _EXT4-EWB-DATA @ _EXT4-EWB-REVOKE @
    _EXT4-EWB-CTX @ _EXT4-JTX-PREFLIGHT-JOURNAL
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JPC-BYTES @ 0 ;

VARIABLE _EXT4-BWA-ARENA
VARIABLE _EXT4-BWA-META
VARIABLE _EXT4-BWA-DATA
VARIABLE _EXT4-BWA-REVOKE
VARIABLE _EXT4-BWA-V
VARIABLE _EXT4-BWA-CTX
VARIABLE _EXT4-BWA-BYTES
VARIABLE _EXT4-BWA-IOR
VARIABLE _EXT4-BWA-BASE
VARIABLE _EXT4-BWA-SIZE
VARIABLE _EXT4-BWA-MOUNT-ARENA
VARIABLE _EXT4-BWA-MOUNT-BASE
VARIABLE _EXT4-BWA-MOUNT-SIZE
VARIABLE _EXT4-BWA-MOUNT-PTR

\ Bind one fresh, caller-owned arena as the persistent production profile.
\ The backing region is exclusive through clean unmount; the driver owns its
\ bump pointer and rejects overlap with the complete VFS/mount arena.
: EXT4-BIND-WRITER-ARENA?
  ( arena meta-cap data-cap revoke-cap vfs -- ior )
    _EXT4-BWA-V ! _EXT4-BWA-REVOKE ! _EXT4-BWA-DATA !
    _EXT4-BWA-META ! _EXT4-BWA-ARENA !
    _EXT4-BWA-ARENA @ 0= _EXT4-BWA-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-META @ _EXT4-BWA-DATA @ _EXT4-BWA-REVOKE @ _EXT4-BWA-V @
    EXT4-WRITER-WORKSPACE-BYTES? _EXT4-BWA-IOR ! _EXT4-BWA-BYTES !
    _EXT4-BWA-IOR @ ?DUP IF EXIT THEN
    _EXT4-BWA-V @ V.BCTX @ DUP _EXT4-BWA-CTX ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWA-V @ V.FLAGS @ VFS-F-DIRTY AND IF VFS-E-BUSY EXIT THEN
    _EXT4-BWA-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.SUPER-TORN + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-ARENA + @ OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-BWA-ARENA @ _EXT4-BWA-V @ V.ARENA @ = IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ 4 CELLS MSPAN-NONWRAPPING? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.SOURCE @ DUP 0< SWAP 2 > OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.BASE @ DUP _EXT4-BWA-BASE ! 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-BASE @ 7 AND IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-ARENA @ A.SIZE @ DUP _EXT4-BWA-SIZE !
    DUP 0< SWAP 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @ MSPAN-NONWRAPPING? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.PTR @ _EXT4-BWA-BASE @ <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-BWA-ARENA @ 4 CELLS _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @
    MSPAN-OVERLAP? IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-BYTES @ _EXT4-BWA-SIZE @ U> IF VFS-E-NOMEM EXIT THEN
    _EXT4-BWA-V @ V.ARENA @ DUP _EXT4-BWA-MOUNT-ARENA ! 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-BWA-MOUNT-ARENA @ A.BASE @ DUP
    _EXT4-BWA-MOUNT-BASE ! 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ 7 AND IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-ARENA @ A.SIZE @ DUP
    _EXT4-BWA-MOUNT-SIZE ! DUP 0< SWAP 0= OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-ARENA @ A.PTR @ DUP _EXT4-BWA-MOUNT-PTR !
    _EXT4-BWA-MOUNT-BASE @ U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-NONWRAPPING? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @ +
    _EXT4-BWA-MOUNT-PTR @ U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-OVERLAP? IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-ARENA @ 4 CELLS
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-OVERLAP? IF
        _EXT4-BWA-ARENA @ _EXT4-BWA-MOUNT-BASE @ U< IF
            VFS-E-INVALID EXIT
        THEN
        _EXT4-BWA-ARENA @ 4 CELLS + _EXT4-BWA-MOUNT-PTR @ U> IF
            VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-BWA-META @ _EXT4-BWA-DATA @ _EXT4-BWA-REVOKE @
    _EXT4-JWR-STORE-DEDICATED _EXT4-BWA-ARENA @ _EXT4-BWA-CTX @
    _EXT4-JWR-ALLOCATE-IN _EXT4-BWA-IOR ! DROP
    _EXT4-BWA-IOR @ ;

VARIABLE _EXT4-JRD-CTX
VARIABLE _EXT4-JRD-WRITER
VARIABLE _EXT4-JRD-ARENA
VARIABLE _EXT4-JRD-BYTES

\ Retire only a clean dedicated profile.  Unpublish authority before
\ scrubbing, then return the exclusive arena to its original fresh mark.
: _EXT4-JWR-RELEASE-DEDICATED  ( ctx -- ior )
    DUP _EXT4-JRD-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ DUP 0= IF
        DROP _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + @
        _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + @ OR IF VFS-E-CORRUPT EXIT THEN
        0 EXIT
    THEN
    _EXT4-JWR-STORE-MOUNT = IF 0 EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + @ DUP
    _EXT4-JRD-WRITER ! 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + @ DUP
    _EXT4-JRD-ARENA ! 0= IF VFS-E-CORRUPT EXIT THEN
    \ A no-write profile still has current authority here; successful dirty
    \ deactivation has deliberately withdrawn it before rebasing the writer
    \ to the clean mounted endpoint.  Validate the complete shape and runtime
    \ directly so both authenticated release paths are accepted.
    _EXT4-JRD-WRITER @ _EXT4-JWR-SHAPE? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR-RUNTIME? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR.TOTAL + @ _EXT4-JRD-BYTES !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JRD-WRITER @ _EXT4-JRD-BYTES @ 0 FILL
    _EXT4-JRD-ARENA @ _EXT4-JRD-WRITER @ ARENA-ROLLBACK
    0 ;

: _EXT4-JTX-CLEAR-HASHES  ( writer -- )
    DUP _EXT4-JWR.META-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.META-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.DATA-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.DATA-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.REVOKE-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.REVOKE-HASH + @ SWAP CELLS 0 FILL
    THEN
    DROP ;

VARIABLE _EXT4-JB-META
VARIABLE _EXT4-JB-DATA
VARIABLE _EXT4-JB-REVOKE
VARIABLE _EXT4-JB-WRITER
VARIABLE _EXT4-JB-LOG
VARIABLE _EXT4-JB-IOR

: _EXT4-JTX-BEGIN
  ( meta-credit data-credit revoke-credit writer -- transaction ior )
    _EXT4-JB-WRITER ! _EXT4-JB-REVOKE !
    _EXT4-JB-DATA ! _EXT4-JB-META !
    _EXT4-JB-WRITER @ _EXT4-JWR-VALID? 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        0 VFS-E-BUSY EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.FAULT + @ IF 0 VFS-E-BUSY EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    _EXT4-JB-META @ 0< _EXT4-JB-DATA @ 0< OR
    _EXT4-JB-REVOKE @ 0< OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-REVOKE @
    _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-META @ _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @
    _EXT4-JTX-LOG-BLOCKS _EXT4-JB-IOR ! _EXT4-JB-LOG !
    _EXT4-JB-IOR @ IF 0 _EXT4-JB-IOR @ EXIT THEN
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.FREE + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        \ s_max_transaction bounds JBD2 records; the private guard is not a
        \ record and therefore does not consume that advertised limit.
        _EXT4-JB-LOG @ 1- SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JB-DATA @ SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JTX-CLEAR-HASHES
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CREDIT + !
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JB-LOG @ NEGATE _EXT4-JB-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JB-WRITER @ _EXT4-JWR.HEAD + @ DUP
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-START + !
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JB-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-TID + !
    1 _EXT4-JB-WRITER @ _EXT4-JWR.EPOCH + +!
    _EXT4-JWR-STAGING _EXT4-JB-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JB-WRITER @ 0 ;

VARIABLE _EXT4-JHV-HOME
VARIABLE _EXT4-JHV-WRITER

: _EXT4-JTX-HOME?  ( home writer -- flag )
    _EXT4-JHV-WRITER ! _EXT4-JHV-HOME !
    _EXT4-JHV-HOME @
    _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JHV-HOME @ _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JOURNAL-DATA? 0= ;

: _EXT4-JWR-META-ENTRY  ( index writer -- entry )
    _EXT4-JWR.META-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-DATA-ENTRY  ( index writer -- entry )
    _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-REVOKE-ENTRY  ( index writer -- entry )
    _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-META-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.META-IMAGES + @ + ;

: _EXT4-JWR-DATA-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.DATA-IMAGES + @ + ;

VARIABLE _EXT4-JTV-WRITER
VARIABLE _EXT4-JTV-ENTRIES
VARIABLE _EXT4-JTV-STRIDE
VARIABLE _EXT4-JTV-HASH
VARIABLE _EXT4-JTV-SLOTS
VARIABLE _EXT4-JTV-USED
VARIABLE _EXT4-JTV-ACTIVE
VARIABLE _EXT4-JTV-ALLOW-CANCELLED
VARIABLE _EXT4-JTV-COUNT
VARIABLE _EXT4-JTV-INDEX
VARIABLE _EXT4-JTV-ENTRY
VARIABLE _EXT4-JTV-IOR

: _EXT4-JTX-TABLE-VALID?
  ( entries entry-cells hash slots used active allow-cancelled? writer -- flag )
    _EXT4-JTV-WRITER ! _EXT4-JTV-ALLOW-CANCELLED !
    _EXT4-JTV-ACTIVE ! _EXT4-JTV-USED ! _EXT4-JTV-SLOTS !
    _EXT4-JTV-HASH ! _EXT4-JTV-STRIDE ! _EXT4-JTV-ENTRIES !
    0 _EXT4-JTV-COUNT !
    _EXT4-JTV-USED @ 0 ?DO
        I _EXT4-JTV-INDEX !
        I _EXT4-JTV-STRIDE @ * CELLS _EXT4-JTV-ENTRIES @ +
        DUP _EXT4-JTV-ENTRY !
        DUP @ _EXT4-JTV-WRITER @ _EXT4-JTX-HOME? 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP 1 _EXT4-JTV-COUNT +!
        ELSE
            _EXT4-JE-CANCELLED <>
            _EXT4-JTV-ALLOW-CANCELLED @ 0= OR IF
                FALSE UNLOOP EXIT
            THEN
        THEN
        _EXT4-JTV-ENTRY @ @
        _EXT4-JTV-ENTRIES @ _EXT4-JTV-STRIDE @
        _EXT4-JTV-HASH @ _EXT4-JTV-SLOTS @ _EXT4-JTV-USED @
        _EXT4-JTX-HASH-FIND _EXT4-JTV-IOR !
        _EXT4-JTV-IOR @ IF 2DROP FALSE UNLOOP EXIT THEN
        0= IF DROP FALSE UNLOOP EXIT THEN
        _EXT4-JTV-INDEX @ <> IF FALSE UNLOOP EXIT THEN
    LOOP
    _EXT4-JTV-COUNT @ _EXT4-JTV-ACTIVE @ = ;

: _EXT4-JTX-TABLES-VALID?  ( writer -- flag )
    _EXT4-JTV-WRITER !
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    -1 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    0 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    -1 _EXT4-JTV-WRITER @ _EXT4-JTX-TABLE-VALID? ;

: _EXT4-JTX-ACTIVE?  ( writer -- ior )
    DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-BUSY EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING <> IF
        DROP VFS-E-BUSY EXIT
    THEN
    DUP _EXT4-JTX-TABLES-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DROP 0 ;

\ Publishing checkpoint authority freezes the complete retained transaction.
\ It remains abortable and emittable, but no generic or typed mutation may
\ change an image after the certificate CRCs and plan identity are sealed.
: _EXT4-JTX-MUTABLE?  ( writer -- ior )
    DUP _EXT4-JTX-ACTIVE? ?DUP IF NIP EXIT THEN
    _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    0 ;

VARIABLE _EXT4-JTM-BUFFER
VARIABLE _EXT4-JTM-HOME
VARIABLE _EXT4-JTM-WRITER
VARIABLE _EXT4-JTM-INDEX
VARIABLE _EXT4-JTM-ENTRY
VARIABLE _EXT4-JTM-IMAGE
VARIABLE _EXT4-JTM-NEW
VARIABLE _EXT4-JTM-CRC
VARIABLE _EXT4-JTM-REVOKE-INDEX
VARIABLE _EXT4-JTM-REVOKE-FOUND

: _EXT4-JTX-META-PUT  ( buffer home transaction -- ior )
    _EXT4-JTM-WRITER ! _EXT4-JTM-HOME ! _EXT4-JTM-BUFFER !
    _EXT4-JTM-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTM-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTM-HOME @ _EXT4-JTM-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTM-REVOKE-FOUND !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTM-REVOKE-INDEX !
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTM-REVOKE-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTM-NEW !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-INDEX !
    ELSE
        DROP
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JTM-INDEX !
        -1 _EXT4-JTM-NEW !
    THEN
    _EXT4-JTM-NEW @ 0= IF
        _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JTM-ENTRY !
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    THEN
    \ Authenticate the caller-owned image before publishing a new hash slot
    \ or replacing an existing retained after-image.  A hardware error must
    \ leave the transaction byte-for-byte unchanged.
    _EXT4-JTM-BUFFER @ _EXT4-JTM-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JTM-CRC !
    _EXT4-JTM-NEW @ IF
        _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JTM-ENTRY !
        _EXT4-JTM-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTM-HOME @ _EXT4-JTM-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTM-ENTRY @ ! EXIT
        THEN
    THEN
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JTM-ENTRY !
    DROP
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JTM-IMAGE !
    _EXT4-JTM-BUFFER @ SWAP
    _EXT4-JTM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTM-CRC @ _EXT4-JTM-ENTRY @ 2 CELLS + !
    _EXT4-JTM-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTM-ENTRY @ CELL+ !
    _EXT4-JTM-NEW @ IF 1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + +! THEN
    _EXT4-JTM-REVOKE-FOUND @ IF
        _EXT4-JTM-REVOKE-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

VARIABLE _EXT4-JMA-SOURCE
VARIABLE _EXT4-JMA-HOME
VARIABLE _EXT4-JMA-WRITER
VARIABLE _EXT4-JMA-INDEX
VARIABLE _EXT4-JMA-ENTRY
VARIABLE _EXT4-JMA-IMAGE
VARIABLE _EXT4-JMA-SCRATCH

\ Acquire a private editing copy of one authenticated metadata block.  A
\ second typed edit of the same home must start from the retained transaction
\ after-image, not from stale media, or the later full-block PUT would silently
\ discard the earlier edit.  The writer-owned image remains immutable while
\ the caller edits SCRATCH-A, so its stored CRC continues to authenticate both
\ transaction preflight and abort until META-REPLACE atomically installs the
\ new complete after-image.
: _EXT4-JTX-META-ACQUIRE
  ( authenticated-source home transaction -- afterimage ior )
    _EXT4-JMA-WRITER ! _EXT4-JMA-HOME ! _EXT4-JMA-SOURCE !
    _EXT4-JMA-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JMA-SOURCE @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JMA-HOME @ _EXT4-JMA-WRITER @ _EXT4-JTX-HOME? 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JMA-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JMA-SCRATCH !
    _EXT4-JMA-HOME @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP 0 _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JMA-INDEX !
        _EXT4-JMA-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JMA-ENTRY ! CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JMA-INDEX @ _EXT4-JMA-WRITER @ _EXT4-JWR-META-IMAGE
            DUP _EXT4-JMA-IMAGE !
            _EXT4-JMA-WRITER @ _EXT4-JTX-IMAGE-CRC
            ?DUP IF NIP 0 SWAP EXIT THEN
            _EXT4-JMA-ENTRY @ 2 CELLS + @ <> IF
                0 VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JMA-IMAGE @
        ELSE
            _EXT4-JE-CANCELLED <> IF 0 VFS-E-CORRUPT EXIT THEN
            _EXT4-JMA-SOURCE @
        THEN
    ELSE
        DROP _EXT4-JMA-SOURCE @
    THEN
    _EXT4-JMA-SCRATCH @
    _EXT4-JMA-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JMA-SCRATCH @ 0 ;

\ Publish one complete scratch after-image through the ordinary conflict,
\ credit, revoke-cancellation, and image-CRC authority of META-PUT.
: _EXT4-JTX-META-REPLACE  ( afterimage home transaction -- ior )
    _EXT4-JTX-META-PUT ;

VARIABLE _EXT4-JTD-BUFFER
VARIABLE _EXT4-JTD-HOME
VARIABLE _EXT4-JTD-WRITER
VARIABLE _EXT4-JTD-INDEX
VARIABLE _EXT4-JTD-ENTRY
VARIABLE _EXT4-JTD-IMAGE
VARIABLE _EXT4-JTD-NEW
VARIABLE _EXT4-JTD-CRC

: _EXT4-JTX-DATA-PUT  ( buffer home transaction -- ior )
    _EXT4-JTD-WRITER ! _EXT4-JTD-HOME ! _EXT4-JTD-BUFFER !
    _EXT4-JTD-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTD-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTD-HOME @ _EXT4-JTD-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    0 _EXT4-JTD-NEW !
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-INDEX !
    ELSE
        DROP
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
        _EXT4-JTD-INDEX !
        -1 _EXT4-JTD-NEW !
    THEN
    _EXT4-JTD-NEW @ 0= IF
        _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JTD-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE <> IF VFS-E-CORRUPT EXIT THEN
    THEN
    \ As with metadata, compute the checked CRC while every writer-owned
    \ entry, hash slot, counter, and retained image still names the old state.
    _EXT4-JTD-BUFFER @ _EXT4-JTD-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JTD-CRC !
    _EXT4-JTD-NEW @ IF
        _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JTD-ENTRY !
        _EXT4-JTD-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTD-HOME @ _EXT4-JTD-INDEX @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTD-ENTRY @ ! EXIT
        THEN
    THEN
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
    DUP _EXT4-JTD-ENTRY !
    DROP
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-IMAGE
    DUP _EXT4-JTD-IMAGE !
    _EXT4-JTD-BUFFER @ SWAP
    _EXT4-JTD-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTD-CRC @ _EXT4-JTD-ENTRY @ 2 CELLS + !
    _EXT4-JTD-NEW @ IF
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + +!
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ACTIVE + +!
        _EXT4-JE-ACTIVE _EXT4-JTD-ENTRY @ CELL+ !
    THEN
    0 ;

VARIABLE _EXT4-JTR-HOME
VARIABLE _EXT4-JTR-WRITER
VARIABLE _EXT4-JTR-INDEX
VARIABLE _EXT4-JTR-ENTRY
VARIABLE _EXT4-JTR-NEW
VARIABLE _EXT4-JTR-META-INDEX
VARIABLE _EXT4-JTR-META-FOUND

: _EXT4-JTX-REVOKE  ( home transaction -- ior )
    _EXT4-JTR-WRITER ! _EXT4-JTR-HOME !
    _EXT4-JTR-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTR-HOME @ _EXT4-JTR-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTR-META-FOUND !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTR-META-INDEX !
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTR-META-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTR-NEW !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-INDEX !
    ELSE
        DROP
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @ DUP
        _EXT4-JTR-INDEX ! _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        DUP _EXT4-JTR-ENTRY !
        _EXT4-JTR-HOME @ OVER ! 0 SWAP CELL+ !
        _EXT4-JTR-HOME @ _EXT4-JTR-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTR-ENTRY @ ! EXIT
        THEN
        -1 _EXT4-JTR-NEW !
    THEN
    _EXT4-JTR-INDEX @ _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
    DUP _EXT4-JTR-ENTRY !
    _EXT4-JTR-NEW @ 0= IF
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    ELSE
        DROP
    THEN
    _EXT4-JTR-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTR-ENTRY @ CELL+ !
    _EXT4-JTR-NEW @ IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + +!
    THEN
    _EXT4-JTR-META-FOUND @ IF
        _EXT4-JTR-META-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

: _EXT4-JTX-DATA-ZERO  ( home transaction -- ior )
    DUP _EXT4-JTX-MUTABLE? ?DUP IF NIP NIP EXIT THEN
    DUP _EXT4-JWR.SCRATCH-B + @
    OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ ROT ROT _EXT4-JTX-DATA-PUT ;

: _EXT4-JTX-CLEAR-STAGED  ( writer -- )
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JTX-CLEAR-HASHES
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 SWAP _EXT4-JWR.PHASE + ! ;

VARIABLE _EXT4-JAB-WRITER
VARIABLE _EXT4-JAB-FREE
VARIABLE _EXT4-JAB-IOR

: _EXT4-JTX-ABORT  ( transaction -- ior )
    DUP _EXT4-JAB-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-UADD? _EXT4-JAB-IOR ! _EXT4-JAB-FREE !
    _EXT4-JAB-IOR @ IF _EXT4-JAB-IOR @ EXIT THEN
    _EXT4-JAB-FREE @
    _EXT4-JAB-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.FIRST + @ - 1- U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAB-FREE @ _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JAB-WRITER @ _EXT4-JTX-CLEAR-STAGED
    _EXT4-JWR-IDLE _EXT4-JAB-WRITER @ _EXT4-JWR.STATE + !
    0 ;

VARIABLE _EXT4-JS-CTX
VARIABLE _EXT4-JS-POS
VARIABLE _EXT4-JS-SEQUENCE
VARIABLE _EXT4-JS-LEFT
VARIABLE _EXT4-JS-PASS
VARIABLE _EXT4-JS-DONE
VARIABLE _EXT4-JS-TYPE
VARIABLE _EXT4-JS-DESC
VARIABLE _EXT4-JS-OFF
VARIABLE _EXT4-JS-LIMIT
VARIABLE _EXT4-JS-TAG
VARIABLE _EXT4-JS-FLAGS
VARIABLE _EXT4-JS-HOME
VARIABLE _EXT4-JS-TAG-CHECKSUM
VARIABLE _EXT4-JS-LAST
VARIABLE _EXT4-JS-COMMIT-CURSOR
VARIABLE _EXT4-JS-CURRENT
VARIABLE _EXT4-JS-FIRST
VARIABLE _EXT4-JS-TX-REVOKES
VARIABLE _EXT4-JS-REVOKE-COUNT
VARIABLE _EXT4-JS-REVOKE-OFF
VARIABLE _EXT4-JS-REVOKE-HIGH
VARIABLE _EXT4-JS-REVOKE-BLOCK

VARIABLE _EXT4-JSB-WRITER
VARIABLE _EXT4-JSB-META-INDEX
VARIABLE _EXT4-JSB-META-BOUND
VARIABLE _EXT4-JSB-REVOKE-INDEX
VARIABLE _EXT4-JSB-REVOKE-BOUND
VARIABLE _EXT4-JSB-PAYLOAD
VARIABLE _EXT4-JSB-HOME
VARIABLE _EXT4-JSB-ENTRY
VARIABLE _EXT4-JSB-IOR

: _EXT4-JSCAN-FULL?  ( pass -- flag )
    DUP _EXT4-JSCAN-PREFLIGHT =
    SWAP _EXT4-JSCAN-BINDING = OR ;

: _EXT4-JSCAN-BIND-BEGIN  ( writer -- )
    _EXT4-JSB-WRITER !
    0 _EXT4-JSB-META-INDEX !
    0 _EXT4-JSB-META-BOUND !
    0 _EXT4-JSB-REVOKE-INDEX !
    0 _EXT4-JSB-REVOKE-BOUND ! ;

\ Compare the logical, unescaped descriptor stream in the same deterministic
\ order used by emission.  Cancelled retained entries never entered the log.
: _EXT4-JSCAN-BIND-METADATA  ( payload home -- ior )
    _EXT4-JSB-HOME ! _EXT4-JSB-PAYLOAD !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    BEGIN
        _EXT4-JSB-META-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JSB-PAYLOAD @
            _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
            _EXT4-JWR-META-IMAGE
            _EXT4-JSB-WRITER @ _EXT4-JWR.BSIZE + @
            _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
            1 _EXT4-JSB-META-INDEX +!
            1 _EXT4-JSB-META-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-META-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Revoke records are emitted in retained insertion order as well.  Equality
\ with the next admissible retained home rejects duplicates, omissions, and
\ any reordered or substituted revoke identity without allocating a seen set.
: _EXT4-JSCAN-BIND-REVOKE  ( home -- ior )
    _EXT4-JSB-HOME !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    _EXT4-JSB-HOME @ _EXT4-JSB-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    BEGIN
        _EXT4-JSB-REVOKE-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JSB-REVOKE-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-REVOKE-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            1 _EXT4-JSB-REVOKE-INDEX +!
            1 _EXT4-JSB-REVOKE-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-REVOKE-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Always withdraw the transient binding publication, including after a scan
\ error.  On success every active retained identity must have appeared once.
: _EXT4-JSCAN-BIND-FINISH  ( scan-ior -- ior )
    _EXT4-JSB-IOR !
    _EXT4-JSB-IOR @ 0= _EXT4-JSB-WRITER @ 0<> AND IF
        _EXT4-JSB-META-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
        _EXT4-JSB-REVOKE-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
            VFS-E-CORRUPT _EXT4-JSB-IOR !
        THEN
    THEN
    0 _EXT4-JSB-WRITER !
    _EXT4-JSB-IOR @ ;

: _EXT4-JSCAN-READ-NEXT  ( -- ior )
    _EXT4-JS-LEFT @ 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-JS-POS @ DUP _EXT4-JS-CURRENT !
    _EXT4-JS-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JS-POS @ _EXT4-JS-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JS-POS !
    -1 _EXT4-JS-LEFT +!
    0 ;

: _EXT4-JBD2-TAG-CHECKSUM?  ( buffer stored -- flag ior )
    _EXT4-JC-STORED ! _EXT4-JC-BUF !
    _EXT4-JS-SEQUENCE @
    _EXT4-JS-CTX @ _EXT4-C.TMP + _EXT4-BE32!
    _EXT4-JS-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JS-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF
        0 SWAP EXIT
    THEN
    _EXT4-JC-BUF @ _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ _EXT4-JC-STORED @ = 0 ;

VARIABLE _EXT4-JIP-BUF
VARIABLE _EXT4-JIP-HOME
VARIABLE _EXT4-JIP-CTX
VARIABLE _EXT4-RPC-SB
VARIABLE _EXT4-RPC-CTX
VARIABLE _EXT4-RGD-DESC
VARIABLE _EXT4-RGD-CTX
VARIABLE _EXT4-RGD-STORED
VARIABLE _EXT4-RGD-CALC
VARIABLE _EXT4-RAP-BUF
VARIABLE _EXT4-RAP-HOME
VARIABLE _EXT4-RAP-CTX

: _EXT4-PRIMARY-SUPER-CANDIDATE?  ( sb ctx -- flag ior )
    _EXT4-RPC-CTX ! _EXT4-RPC-SB !
    _EXT4-RPC-SB @ _EXT4-SUPER-CHECKSUM? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SUPER-SEED? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SB.INCOMPAT + L@
    _EXT4-INCOMPAT-RECOVER AND 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ -1 _EXT4-VALIDATE-SUPER-RETRY-EARLY IF
        FALSE 0 EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-VALIDATE-SUPER-RETRY-LATE IF
        FALSE 0 EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-RPC-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ 0
    _EXT4-RPC-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SUPER-INVARIANTS? 0 ;

: _EXT4-PRIMARY-GDT-CANDIDATE?  ( block ctx -- flag ior )
    _EXT4-RGD-CTX ! DUP _EXT4-RGD-DESC !
    DUP _EXT4-GD.BLOCK-BITMAP-HI + L@
    OVER _EXT4-GD.INODE-BITMAP-HI + L@ OR
    OVER _EXT4-GD.INODE-TABLE-HI + L@ OR IF DROP FALSE 0 EXIT THEN
    DUP _EXT4-GD.BLOCK-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.BLOCK-BITMAP-BLOCK + @ <>
    OVER _EXT4-GD.INODE-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ <> OR
    OVER _EXT4-GD.INODE-TABLE-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-TABLE-BASE + @ <> OR IF
        DROP FALSE 0 EXIT
    THEN
    DUP _EXT4-GD.CHECKSUM + W@ _EXT4-RGD-STORED !
    0 SWAP _EXT4-GD.CHECKSUM + W!
    0 _EXT4-RGD-CTX @ _EXT4-C.TMP + L!
    _EXT4-RGD-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RGD-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF
        _EXT4-RGD-STORED @ _EXT4-RGD-DESC @ _EXT4-GD.CHECKSUM + W!
        0 SWAP EXIT
    THEN
    _EXT4-RGD-DESC @ _EXT4-DESC-SIZE _EXT4-CRC-ADD ?DUP IF
        _EXT4-RGD-STORED @ _EXT4-RGD-DESC @ _EXT4-GD.CHECKSUM + W!
        0 SWAP EXIT
    THEN
    _EXT4-CRC@ 0xFFFF AND _EXT4-RGD-CALC !
    _EXT4-RGD-STORED @ _EXT4-RGD-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-RGD-CALC @ _EXT4-RGD-STORED @ = 0 ;

: _EXT4-JOURNAL-INODE-PRESERVED?  ( payload home ctx -- flag )
    _EXT4-JIP-CTX ! _EXT4-JIP-HOME ! _EXT4-JIP-BUF !
    _EXT4-JIP-HOME @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-BLOCK + @ <> IF TRUE EXIT THEN
    _EXT4-JIP-BUF @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-OFF + @ +
    _EXT4-JIP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JIP-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? ;

\ A valid JBD2 checksum authenticates bytes but does not authorize changing
\ the bootstrap chain.  Hard-frozen sparse copies are never home targets;
\ mutable primary metadata may change only while retaining the exact fields,
\ allocation bit, or inode slice needed by the next retry.
: _EXT4-RECOVERY-AUTHORITY-PRESERVED?  ( payload home ctx -- flag ior )
    _EXT4-RAP-CTX ! _EXT4-RAP-HOME ! _EXT4-RAP-BUF !
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-RECOVERY-FROZEN-BLOCK? IF FALSE 0 EXIT THEN
    _EXT4-RAP-BUF @ _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-JOURNAL-INODE-PRESERVED? 0= IF FALSE 0 EXIT THEN
    _EXT4-RAP-HOME @
    _EXT4-RAP-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ = IF
        _EXT4-RAP-BUF @ _EXT4-JOURNAL-INODE 1- 8 / + C@
        1 _EXT4-JOURNAL-INODE 1- 8 MOD LSHIFT AND 0= IF FALSE 0 EXIT THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-CANDIDATE? ?DUP IF
            NIP 0 SWAP EXIT
        THEN 0= IF
            FALSE 0 EXIT
        THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-GDT-BASE = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @
        _EXT4-PRIMARY-GDT-CANDIDATE? ?DUP IF NIP 0 SWAP EXIT THEN
        0= IF FALSE 0 EXIT THEN
    THEN
    TRUE 0 ;

\ A checksum-v3/64-bit revoke block carries a byte count followed by exact
\ big-endian 64-bit home-block numbers and a checksum tail.  Preflight counts
\ records provisionally until the transaction commit is authenticated; the
\ revoke pass records the latest committed sequence for each block.
: _EXT4-JSCAN-REVOKE  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @
    _EXT4-JBD2-I-REVOKE AND 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    12 + _EXT4-BE32@ DUP _EXT4-JS-REVOKE-COUNT !
    DUP 16 U< IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    U> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    16 - DUP 8 MOD IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    8 / _EXT4-JS-REVOKE-COUNT !
    _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? IF
        _EXT4-JS-TX-REVOKES @ _EXT4-JS-REVOKE-COUNT @ + DUP
        _EXT4-JS-TX-REVOKES @ U< IF
            DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TX-REVOKES !
        _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
        16 _EXT4-JS-REVOKE-OFF !
        _EXT4-JS-REVOKE-COUNT @ 0 ?DO
            _EXT4-JS-CTX @ _EXT4-C.BLOCK +
            _EXT4-JS-REVOKE-OFF @ + DUP
            _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
            4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
            _EXT4-JS-REVOKE-HIGH @ IF
                EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
            THEN
            _EXT4-JS-REVOKE-BLOCK @ _EXT4-JSCAN-BIND-REVOKE
            ?DUP IF UNLOOP EXIT THEN
            8 _EXT4-JS-REVOKE-OFF +!
        LOOP
        0 EXIT
    THEN
    _EXT4-JS-PASS @ _EXT4-JSCAN-REVOKES <> IF 0 EXIT THEN
    16 _EXT4-JS-REVOKE-OFF !
    _EXT4-JS-REVOKE-COUNT @ 0 ?DO
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-REVOKE-OFF @ + DUP
        _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
        4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
        _EXT4-JS-REVOKE-HIGH @ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-CTX @
        _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
        _EXT4-REVOKE-PUT ?DUP IF UNLOOP EXIT THEN
        8 _EXT4-JS-REVOKE-OFF +!
    LOOP
    0 ;

: _EXT4-JSCAN-DESCRIPTOR  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK + DUP _EXT4-JS-DESC !
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    _EXT4-JS-LIMIT !
    12 _EXT4-JS-OFF ! 0 _EXT4-JS-LAST !
    BEGIN _EXT4-JS-LAST @ 0= WHILE
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE +
        _EXT4-JS-LIMIT @ U> IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
        _EXT4-JS-DESC @ _EXT4-JS-OFF @ + DUP _EXT4-JS-TAG !
        _EXT4-BE32@ DUP _EXT4-JS-HOME !
        _EXT4-JS-CTX @ _EXT4-C.BLOCKS + @ >= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 4 + _EXT4-BE32@ DUP _EXT4-JS-FLAGS !
        _EXT4-JBD2-F-ALL INVERT AND IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 8 + _EXT4-BE32@ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TAG @ 12 + _EXT4-BE32@ _EXT4-JS-TAG-CHECKSUM !
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE + _EXT4-JS-OFF !
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-SAME-UUID AND 0= IF
            _EXT4-JS-OFF @ 16 + _EXT4-JS-LIMIT @ U> IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            \ The tag UUID is an opaque per-client identity field, not the
            \ journal superblock UUID.  Recovery uses its flag for tag
            \ layout; the descriptor checksum authenticates its bytes.
            16 _EXT4-JS-OFF +!
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-TAG-CHECKSUM @
        _EXT4-JBD2-TAG-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        \ Tag checksums cover the escaped on-disk form.  Reconstruct the
        \ logical home image before comparing or writing it.
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-ESCAPE AND IF
            _EXT4-JBD2-MAGIC
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-BE32!
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @ _EXT4-JS-CTX @
        _EXT4-RECOVERY-AUTHORITY-PRESERVED? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
        _EXT4-JSCAN-BIND-METADATA ?DUP IF EXIT THEN
        \ A checksum-torn primary super is admitted provisionally so this
        \ authenticated payload can be inspected.  Do not grant replay
        \ authority until the enclosing transaction's commit is verified.
        _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT =
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = AND IF
            _EXT4-JS-SEQUENCE @ 1+
            _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
        THEN
        _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
            _EXT4-JS-HOME @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
            _EXT4-JOURNAL-REVOKED? IF
                1 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + +!
            ELSE
                _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
                _EXT4-JS-CTX @ _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
                1 _EXT4-JS-CTX @ _EXT4-C.J.HOME-WRITES + +!
            THEN
        THEN
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-LAST AND IF
            -1 _EXT4-JS-LAST !
        THEN
    REPEAT
    0 ;

: _EXT4-JSCAN-FINISH  ( -- ior )
    \ A descriptor without its authenticated commit is only an incomplete
    \ tail.  Never let its provisional repair claim survive this scan.
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND
    _EXT4-JS-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JS-COMMIT-CURSOR @ _EXT4-JS-CTX @ _EXT4-C.J.CURSOR + !
    0 ;

: _EXT4-JSCAN  ( pass ctx -- ior )
    _EXT4-JS-CTX ! _EXT4-JS-PASS !
    _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
        _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-READY + @ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JS-CTX @ _EXT4-C.J.START + @ _EXT4-JS-POS !
    _EXT4-JS-CTX @ _EXT4-C.J.SEQUENCE + @ _EXT4-JS-SEQUENCE !
    _EXT4-JS-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ - _EXT4-JS-LEFT !
    0 _EXT4-JS-DONE !
    0 _EXT4-JS-TX-REVOKES !
    _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
        0 _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + !
    THEN
    BEGIN
        _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
            _EXT4-JS-DONE @
            _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + @ >= IF 0 EXIT THEN
        THEN
        _EXT4-JS-LEFT @ 0= IF
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JS-DONE @ IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
        _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
        OVER 8 + _EXT4-BE32@ _EXT4-JS-SEQUENCE @ <> OR IF
            DROP
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        4 + _EXT4-BE32@ _EXT4-JS-TYPE !
        _EXT4-JS-TYPE @ _EXT4-JBD2-DESCRIPTOR = IF
            _EXT4-JSCAN-DESCRIPTOR ?DUP IF EXIT THEN
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-COMMIT = IF
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-CTX @
            _EXT4-JBD2-COMMIT-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-JS-DONE +!
            _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
                _EXT4-JS-DONE @
                _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @
                _EXT4-JS-TX-REVOKES @ + DUP
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @ U< IF
                    DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
                THEN
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
                _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @ IF
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
                THEN
                0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
                0 _EXT4-JS-TX-REVOKES !
            THEN
            _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND _EXT4-JS-SEQUENCE !
            _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-REVOKE = IF
            _EXT4-JSCAN-REVOKE ?DUP IF EXIT THEN
        ELSE
            _EXT4-JS-TYPE @ _EXT4-JBD2-SUPER-V2 =
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? AND IF
                _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JS-FIRST !
                _EXT4-JS-CURRENT @ _EXT4-JS-CTX @
                _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN IF
                    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @
                    _EXT4-JS-FIRST @ =
                    _EXT4-JA-FEATURES @
                    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @ = AND
                    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
                    _EXT4-JS.SEQUENCE + _EXT4-BE32@
                    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND = AND IF
                        _EXT4-JSCAN-FINISH EXIT
                    THEN
                THEN
            THEN
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN THEN THEN
    AGAIN ;

VARIABLE _EXT4-RM-CTX

: _EXT4-RECOVERY-MEDIA  ( ctx -- ior )
    _EXT4-RM-CTX !
    _EXT4-RM-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-READONLY AND IF EXT4-D-RECOVERY _EXT4-READONLY EXIT THEN
    _EXT4-IO-VOL @ VOL.FLAGS VOL-F-READONLY AND IF
        VOL-E-READONLY VFS-IOR-F-READONLY
        VFS-IOR-D-VOLUME VFS-R-READONLY VFS-IOR-MAKE EXIT
    THEN
    _EXT4-IO-VOL @ VOL.BD BD.CAPS 0x06 AND 0x06 <> IF
        0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    0 ;

VARIABLE _EXT4-RJ-CTX
VARIABLE _EXT4-RJ-V
VARIABLE _EXT4-RJ-PHYS
VARIABLE _EXT4-RJ-ANCHOR
VARIABLE _EXT4-RJ-OLD-SEQUENCE
VARIABLE _EXT4-RJ-OLD-HEAD
VARIABLE _EXT4-RJ-OLD-CRC
VARIABLE _EXT4-RJ-EMPTY-PREDECESSOR
VARIABLE _EXT4-RJ-PREDECESSOR-MAGIC
VARIABLE _EXT4-RJ-PREDECESSOR-VALUE

: _EXT4-PREPARE-CLEAR  ( ctx -- ior )
    DUP _EXT4-RJ-CTX !
    _EXT4-C.SB + _EXT4-PREPARE-RECOVERED-SUPER ;

: _EXT4-STAMP-JOURNAL-RESET  ( ctx -- ior )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-EMPTY-PREDECESSOR !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.SEQUENCE + _EXT4-BE32@ _EXT4-RJ-OLD-SEQUENCE !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.HEAD + _EXT4-BE32@ _EXT4-RJ-OLD-HEAD !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JOURNAL-IMAGE-CRC ?DUP IF NIP EXIT THEN
    _EXT4-RJ-OLD-CRC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-ANCHOR !
    ELSE
        _EXT4-RJ-CTX @ _EXT4-C.J.CURSOR + @ _EXT4-RJ-ANCHOR !
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32@ 0= IF
            _EXT4-RJ-OLD-SEQUENCE @ 1+ 0xFFFFFFFF AND
            _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @ = IF
                _EXT4-RJ-OLD-HEAD @ DUP 0= IF
                    DROP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @
                ELSE
                    DUP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @ U<
                    OVER _EXT4-RJ-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
                        DROP 0
                    THEN
                THEN
                _EXT4-RJ-ANCHOR @ = IF
                    -1 _EXT4-RJ-EMPTY-PREDECESSOR !
                THEN
            THEN
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.SEQUENCE + _EXT4-BE32!
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-RECOVERY-MAGIC
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    \ AKR1 authenticates the clean super image deterministically derived from
    \ the durable current super.  This is unchanged after PREPARE-CLEAR and
    \ also lets a live checkpoint retire AKG1 while deliberately retaining
    \ the standard RECOVER-set endpoint for the next transaction.
    _EXT4-RJ-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-RECOVERED-SUPER-CHECKSUM ?DUP IF NIP EXIT THEN
    DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @ DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    0 _EXT4-RJ-PREDECESSOR-MAGIC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-JBD2-ACTIVE-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
        _EXT4-RJ-OLD-SEQUENCE @ _EXT4-RJ-PREDECESSOR-VALUE !
    ELSE
        _EXT4-RJ-EMPTY-PREDECESSOR @ IF
            _EXT4-JBD2-EMPTY-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
            _EXT4-RJ-OLD-HEAD @ _EXT4-RJ-PREDECESSOR-VALUE !
        THEN
    THEN
    _EXT4-RJ-PREDECESSOR-MAGIC @ ?DUP IF
        DUP _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        _EXT4-RJ-PREDECESSOR-VALUE @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        _EXT4-RJ-OLD-CRC @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    ELSE
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.CHECKSUM + _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + 1024 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.CHECKSUM + _EXT4-BE32! 0 ;

VARIABLE _EXT4-AJS-BUF
VARIABLE _EXT4-AJS-GUARD
VARIABLE _EXT4-AJS-CTX
VARIABLE _EXT4-AJS-OLD
VARIABLE _EXT4-AJS-NEW

: _EXT4-STAMP-JOURNAL-ACTIVATION  ( buffer guard ctx -- ior )
    _EXT4-AJS-CTX ! _EXT4-AJS-GUARD ! _EXT4-AJS-BUF !
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    0 _EXT4-AJS-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-AJS-GUARD @ _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-AJS-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB + _EXT4-INTENDED-SUPER-CHECKSUM
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-AJS-OLD !
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-OLD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-DIRTY-SUPER-CHECKSUM ?DUP IF NIP EXIT THEN
    DUP _EXT4-AJS-NEW !
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-NEW @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-JBD2-ACTIVATION-MAGIC
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    0 _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-AJS-BUF @ 1024 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32! 0 ;

: _EXT4-RESET-JOURNAL  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        0 _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        0 _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + !
        _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF 0 EXIT THEN
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
        _EXT4-JBD2-ACTIVE-GUARD? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-STAMP-JOURNAL-RESET ?DUP IF EXIT THEN
    \ Preseed the whole anchor block with the intended image but invalid byte
    \ zero.  After that flush, the valid write changes only byte zero, so any
    \ applied prefix is either still invalid or already the exact anchor.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + C!
    _EXT4-RJ-ANCHOR @
    _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ;

: _EXT4-WRITE-CLEARED-SUPER  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS ;

\ Return journal block zero to a stock JBD2 superblock only after the witness's
\ authenticated ext4 endpoint is durable, and before retiring its anchor.
: _EXT4-CLEAR-JOURNAL-WITNESS  ( ctx -- ior )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JBD2-WITNESS? 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
    ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    \ Freeze the raw primary before the anchor reread.  With the authenticated
    \ ext4 endpoint already durable, witness authority may be withdrawn only if
    \ the named anchor is still exact and the complete primary block equals
    \ it; a checksum-valid 1024-byte prefix is insufficient on larger media.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF NIP EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-JDW-CTX

\ A live checkpoint or mount-time retained-orphan resume may retire AKG1
\ without first clearing ext4 RECOVER.  The on-media reset predecessor tuple,
\ not a same-session cleanup enum, proves that the witness came from an active
\ journal.  This matters after remount, where validation reconstructs the
\ witness but deliberately does not retain the emitter's in-memory enum.
: _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY  ( ctx -- ior )
    DUP _EXT4-JDW-CTX ! _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SUPER-TORN + @ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JDW-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-RECOVERY <> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.START + _EXT4-BE32@ IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-JDW-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF NIP EXIT THEN
    0 _EXT4-JDW-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-RA-CTX
VARIABLE _EXT4-RA-LOGICAL

\ Zeroing byte zero first makes every applied prefix cease to be a valid JBD2
\ superblock.  Once the standard primary is durable this slot has no authority.
: _EXT4-RETIRE-JOURNAL-ANCHOR  ( ctx -- ior )
    _EXT4-RA-CTX !
    _EXT4-RA-CTX @ _EXT4-C.J.WITNESS + @ IF
        _EXT4-RA-CTX @ _EXT4-C.J.ANCHOR + @
    ELSE
        _EXT4-RA-CTX @ _EXT4-C.J.CURSOR + @
    THEN DUP _EXT4-RA-LOGICAL !
    _EXT4-RA-CTX @ _EXT4-C.J.FIRST + @ U<
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-JOURNAL-MAP@
    _EXT4-RA-CTX @ _EXT4-WRITE-BLOCK ;

VARIABLE _EXT4-JWF-IOR
VARIABLE _EXT4-JWF-WRITER

: _EXT4-JWR-LATCH-FAULT  ( ior writer -- ior )
    _EXT4-JWF-WRITER ! _EXT4-JWF-IOR !
    _EXT4-JWF-IOR @ 0= IF 0 EXIT THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ 0= IF
        _EXT4-JWF-IOR @ _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + !
    THEN
    _EXT4-JWR-FAULTED _EXT4-JWF-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-IO-VFS @ ?DUP IF
        DUP V.FLAGS DUP @ VFS-F-RO OR VFS-F-DIRTY OR SWAP ! DROP
    THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ ;

VARIABLE _EXT4-JAP-BUF
VARIABLE _EXT4-JAP-WRITER
VARIABLE _EXT4-JAP-CTX
VARIABLE _EXT4-JAP-HEAD
VARIABLE _EXT4-JAP-EXPECTED-HEAD
VARIABLE _EXT4-JAP-EXPECTED-NEXT

\ Bind a fresh clean-primary reread to an exact validated journal endpoint.
\ A feature-zero JBD2 superblock has no checksum, so generic usability alone
\ cannot prevent stale geometry or identity from being newly authenticated.
: _EXT4-ACTIVATION-PRIMARY?
  ( buffer ctx expected-head expected-next-tid -- flag ior )
    _EXT4-JAP-EXPECTED-NEXT ! _EXT4-JAP-EXPECTED-HEAD !
    _EXT4-JAP-CTX ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @ _EXT4-JS.MAGIC + _EXT4-BE32@
    _EXT4-JBD2-MAGIC <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.TYPE + _EXT4-BE32@
    _EXT4-JBD2-SUPER-V2 <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.FIRST + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JAP-EXPECTED-NEXT @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.START + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.START + @ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@ DUP _EXT4-JAP-HEAD !
    _EXT4-JAP-CTX @ _EXT4-C.J.HEAD + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-HEAD @ DUP 0= IF
        DROP _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-JAP-EXPECTED-HEAD @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.ERRNO + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.COMPAT + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.UUID +
    _EXT4-JAP-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.NR-USERS + _EXT4-BE32@ 1 <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.DYNSUPER + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANSACTION + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANS-DATA + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ IF
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@ 4 <> IF
            FALSE 0 EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ IF
            FALSE 0 EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF
            NIP 0 SWAP EXIT
        THEN 0= IF FALSE 0 EXIT THEN
    ELSE
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ OR
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@ OR IF
            FALSE 0 EXIT
        THEN
    THEN
    _EXT4-JAP-BUF @ _EXT4-JAP-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.WITNESS + @ 0= 0 ;

: _EXT4-JWR-ACTIVATION-PRIMARY?  ( buffer writer -- flag ior )
    _EXT4-JAP-WRITER ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @
    _EXT4-JAP-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-ACTIVATION-PRIMARY? ;

VARIABLE _EXT4-JWA-WRITER
VARIABLE _EXT4-JWA-CTX
VARIABLE _EXT4-JWA-GUARD
VARIABLE _EXT4-JAC-CTX
VARIABLE _EXT4-JAC-GUARD
VARIABLE _EXT4-JAC-SUPER
VARIABLE _EXT4-JAC-SCRATCH
VARIABLE _EXT4-JAC-WRITER

: _EXT4-JAC-PHASE  ( phase -- )
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR.PHASE + !
    ELSE
        DROP
    THEN ;

: _EXT4-JAC-FAULT  ( ior -- ior )
    DUP 0= IF EXIT THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-LATCH-FAULT EXIT
    THEN
    \ Mount owns writer-free activation failures.  Its next attempt must be
    \ able to resolve the durable AKW1 prefix without retaining a synthetic
    \ read-only latch that would poison later private-writer use.
    ;

\ Perform the witnessed clean-journal activation using caller-owned block
\ buffers.  The private writer supplies its retained scratch pair during
\ ordinary mutation; mount-time orphan recovery borrows DIR-BLOCK/TREE-BLOCK,
\ avoiding a one-off arena allocation that would freeze later writer credits.
\ All checks before ACTIVATING are non-mutating.  Every later failure leaves
\ AKW1 or a standard recovery endpoint for the next mount.
: _EXT4-ACTIVATE-CLEAN-JOURNAL
  ( ctx guard super-buffer scratch-buffer writer|0 -- ior )
    _EXT4-JAC-WRITER ! _EXT4-JAC-SCRATCH ! _EXT4-JAC-SUPER !
    _EXT4-JAC-GUARD ! _EXT4-JAC-CTX !
    _EXT4-JAC-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-STAMP-JOURNAL-ACTIVATION ?DUP IF EXIT THEN
    _EXT4-JAC-SUPER @ _EXT4-JBD2-SUPER-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-ACTIVATING SWAP _EXT4-JWR.STATE + !
    THEN
    _EXT4-JWP-GUARD-PRESEED _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-SCRATCH @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JAC-SCRATCH @ C!
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PRIMARY _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-EXT4-SUPER _EXT4-JAC-PHASE
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-PREPARE-DIRTY-SUPER
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-SB.CHECKSUM + L@
    _EXT4-AJS-NEW @ <> IF VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PROOF _EXT4-JAC-PHASE
    0 _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP _EXT4-JAC-FAULT EXIT THEN 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-SB.CHECKSUM + L@ _EXT4-AJS-NEW @ <> IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JWP-WITNESS-CLEAR _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-ZERO-JOURNAL-WITNESS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD-RETIRE _EXT4-JAC-PHASE
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JAC-CTX @ _EXT4-C.J.FEATURES + !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JAC-SUPER @ _EXT4-JS.UUID + 16 _EXT4-CRC-ADD
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-CRC@ _EXT4-JAC-CTX @ _EXT4-C.J.SEED + !
    _EXT4-JAC-SUPER @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAC-CTX @ _EXT4-C.J.SEQUENCE + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.START + !
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JW-NONE _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.ANCHOR + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-IO-VFS @ ?DUP IF
        VFS-F-DIRTY SWAP V.FLAGS DUP @ ROT OR SWAP !
    THEN
    _EXT4-JAC-SUPER @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWP-NONE OVER _EXT4-JWR.PHASE + !
        _EXT4-JWR-IDLE SWAP _EXT4-JWR.STATE + !
    THEN
    0 ;

: _EXT4-JWR-ACTIVATE  ( writer -- ior )
    DUP _EXT4-JWA-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JWA-CTX !
    _EXT4-C.RECOVERY + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JWA-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    0 _EXT4-JWA-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.BLOCK + _EXT4-JWA-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.HEAD + @ DUP _EXT4-JWA-GUARD !
    DUP _EXT4-JWA-WRITER @ _EXT4-JWR.FIRST + @ U<
    SWAP _EXT4-JWA-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-CTX @
    _EXT4-JWA-GUARD @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JWA-WRITER @
    _EXT4-ACTIVATE-CLEAN-JOURNAL ;

\ =====================================================================
\  Private one-transaction JBD2 emission
\ =====================================================================
\
\ The public mutation surface remains disabled.  This layer turns one fully
\ staged transaction into an ordered, checksum-v3 JBD2 commit and deliberately
\ stops in COMMITTED state with all after-images retained for checkpointing.

VARIABLE _EXT4-JEC-BUF
VARIABLE _EXT4-JEC-CTX
VARIABLE _EXT4-JEC-FIELD
VARIABLE _EXT4-JEC-TID

: _EXT4-JBD2-STAMP-BLOCK-CHECKSUM  ( buffer ctx -- ior )
    _EXT4-JEC-CTX ! DUP _EXT4-JEC-BUF !
    _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ 4 - + _EXT4-JEC-FIELD !
    0 _EXT4-JEC-FIELD @ _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-JEC-FIELD @ _EXT4-BE32! 0 ;

: _EXT4-JBD2-STAMP-COMMIT-CHECKSUM  ( buffer ctx -- ior )
    _EXT4-JEC-CTX ! DUP _EXT4-JEC-BUF !
    16 + _EXT4-JEC-FIELD !
    0 _EXT4-JEC-FIELD @ _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-JEC-FIELD @ _EXT4-BE32! 0 ;

: _EXT4-JBD2-EMIT-TAG-CHECKSUM  ( payload tid ctx -- crc ior )
    _EXT4-JEC-CTX ! _EXT4-JEC-TID ! _EXT4-JEC-BUF !
    _EXT4-JEC-TID @ _EXT4-JEC-CTX @ _EXT4-C.TMP + _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

VARIABLE _EXT4-JEE-SOURCE
VARIABLE _EXT4-JEE-DEST
VARIABLE _EXT4-JEE-WRITER

: _EXT4-JTX-ESCAPED-COPY  ( source dest writer -- flags )
    _EXT4-JEE-WRITER ! _EXT4-JEE-DEST ! _EXT4-JEE-SOURCE !
    _EXT4-JEE-SOURCE @ _EXT4-JEE-DEST @
    _EXT4-JEE-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEE-DEST @ _EXT4-BE32@ _EXT4-JBD2-MAGIC = IF
        0 _EXT4-JEE-DEST @ _EXT4-BE32!
        _EXT4-JBD2-F-ESCAPE EXIT
    THEN
    0 ;

VARIABLE _EXT4-JEH-TYPE
VARIABLE _EXT4-JEH-BUF
VARIABLE _EXT4-JEH-WRITER

: _EXT4-JTX-HEADER!  ( type buffer writer -- )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF ! _EXT4-JEH-TYPE !
    _EXT4-JBD2-MAGIC _EXT4-JEH-BUF @ _EXT4-BE32!
    _EXT4-JEH-TYPE @ _EXT4-JEH-BUF @ 4 + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ 8 + _EXT4-BE32! ;

: _EXT4-JTX-BUILD-COMMIT  ( buffer writer -- ior )
    DUP _EXT4-JEH-WRITER ! SWAP DUP _EXT4-JEH-BUF !
    SWAP _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JBD2-COMMIT _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @
    _EXT4-JTX-HEADER!
    _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JBD2-STAMP-COMMIT-CHECKSUM ;

: _EXT4-JTX-STAMP-ACTIVE-SUPER  ( buffer writer -- ior )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF !
    _EXT4-JEH-BUF @ _EXT4-ZERO-JOURNAL-WITNESS
    ?DUP IF EXIT THEN
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
    _EXT4-JEH-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JEH-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-JEH-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-JEH-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-JEH-BUF @ _EXT4-STAMP-JOURNAL-SUPER-CHECKSUM ;

VARIABLE _EXT4-JEP-WRITER
VARIABLE _EXT4-JEP-CTX
VARIABLE _EXT4-JEP-INDEX
VARIABLE _EXT4-JEP-INNER
VARIABLE _EXT4-JEP-ENTRY
VARIABLE _EXT4-JEP-IMAGE
VARIABLE _EXT4-JEP-HOME
VARIABLE _EXT4-JEP-ACTUAL
VARIABLE _EXT4-JEP-IOR
VARIABLE _EXT4-JEP-SENTINEL

: _EXT4-JTX-PREFLIGHT-IMAGES  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JEP-CTX !
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JEP-IMAGE @ _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
            _EXT4-RECOVERY-AUTHORITY-PRESERVED? ?DUP IF NIP EXIT THEN 0= IF
                VFS-E-CORRUPT EXIT
            THEN
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-DATA-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
        THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
        _EXT4-RECOVERY-AUTHORITY-BLOCK? IF VFS-E-INVALID EXIT THEN
        0 _EXT4-JEP-INNER !
        BEGIN
            _EXT4-JEP-INNER @
            _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
        WHILE
            _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
            _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
            ELSE DROP THEN
            1 _EXT4-JEP-INNER +!
        REPEAT
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        @ 0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 ;

: _EXT4-JTX-PREFLIGHT  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JEP-CTX !
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.PRIMARY-TORN + @
    _EXT4-JEP-CTX @ _EXT4-C.J.CLEANUP + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SUPER-TORN + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JEP-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    8 _EXT4-JEP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.INODE +
    _EXT4-JEP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JEP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-JEP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JTX-LOG-BLOCKS
    _EXT4-JEP-IOR ! _EXT4-JEP-ACTUAL !
    _EXT4-JEP-IOR @ IF _EXT4-JEP-IOR @ EXIT THEN
    _EXT4-JEP-ACTUAL @ 2 U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-ACTUAL @
    _EXT4-JEP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEP-ACTUAL @ _EXT4-JEP-CTX @ _EXT4-JOURNAL-ADVANCE
    DUP _EXT4-JEP-SENTINEL !
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @ = IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JEP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.BLOCK + _EXT4-JEP-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JEM-WRITER
VARIABLE _EXT4-JEM-CTX
VARIABLE _EXT4-JEM-CURSOR
VARIABLE _EXT4-JEM-COMMIT
VARIABLE _EXT4-JEM-SENTINEL
VARIABLE _EXT4-JEM-ACTUAL
VARIABLE _EXT4-JEM-INDEX
VARIABLE _EXT4-JEM-SCAN
VARIABLE _EXT4-JEM-BATCH-START
VARIABLE _EXT4-JEM-BATCH-END
VARIABLE _EXT4-JEM-COUNT
VARIABLE _EXT4-JEM-OFF
VARIABLE _EXT4-JEM-LAST-TAG
VARIABLE _EXT4-JEM-ENTRY
VARIABLE _EXT4-JEM-TAG
VARIABLE _EXT4-JEM-FLAGS
VARIABLE _EXT4-JEM-OLD-RESERVED

: _EXT4-JEM-FAULT  ( ior -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JEM-ADVANCE  ( -- )
    _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CURSOR ! ;

: _EXT4-JTX-EMIT-ORDERED-DATA  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JWP-ORDERED-DATA
            _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-IMAGE
            _EXT4-JEM-ENTRY @ @ _EXT4-JEM-CTX @ _EXT4-WRITE-BLOCK
            ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-META  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JEM-PREPARE-META-PAYLOAD  ( index -- flags )
    _EXT4-JEM-WRITER @ _EXT4-JWR-META-IMAGE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-ESCAPED-COPY ;

: _EXT4-JTX-EMIT-METADATA  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-META
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-DESCRIPTOR SWAP _EXT4-JEM-WRITER @
        _EXT4-JTX-HEADER!
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-START !
        0 _EXT4-JEM-COUNT ! 12 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-TAGS/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-INDEX @ _EXT4-JEM-PREPARE-META-PAYLOAD
                _EXT4-JEM-FLAGS !
                _EXT4-JEM-COUNT @ IF
                    _EXT4-JEM-FLAGS @ _EXT4-JBD2-F-SAME-UUID OR
                    _EXT4-JEM-FLAGS !
                THEN
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ + DUP _EXT4-JEM-TAG !
                _EXT4-JEM-ENTRY @ @ OVER _EXT4-BE32!
                _EXT4-JEM-FLAGS @ OVER 4 + _EXT4-BE32!
                0 OVER 8 + _EXT4-BE32!
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
                _EXT4-JEM-CTX @ _EXT4-JBD2-EMIT-TAG-CHECKSUM
                ?DUP IF NIP NIP _EXT4-JEM-FAULT EXIT THEN
                SWAP 12 + _EXT4-BE32!
                _EXT4-JEM-COUNT @ 0= IF
                    _EXT4-JEM-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
                    _EXT4-JEM-TAG @ _EXT4-JBD2-TAG3-SIZE +
                    16 MOVE
                THEN
                _EXT4-JEM-TAG @ _EXT4-JEM-LAST-TAG !
                _EXT4-JBD2-TAG3-SIZE _EXT4-JEM-OFF +!
                _EXT4-JEM-COUNT @ 0= IF 16 _EXT4-JEM-OFF +! THEN
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-END !
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-LAST-TAG @ 4 + DUP _EXT4-BE32@
        _EXT4-JBD2-F-LAST OR SWAP _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JWP-DESCRIPTOR _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
        _EXT4-JEM-BATCH-START @ _EXT4-JEM-SCAN !
        BEGIN
            _EXT4-JEM-SCAN @ _EXT4-JEM-BATCH-END @ U<
        WHILE
            _EXT4-JEM-SCAN @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-SCAN @ _EXT4-JEM-PREPARE-META-PAYLOAD DROP
                _EXT4-JWP-PAYLOAD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
                ?DUP IF _EXT4-JEM-FAULT EXIT THEN
                _EXT4-JEM-ADVANCE
            THEN
            1 _EXT4-JEM-SCAN +!
        REPEAT
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-REVOKE  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JTX-EMIT-REVOKES  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-REVOKE
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-REVOKE SWAP _EXT4-JEM-WRITER @ _EXT4-JTX-HEADER!
        0 _EXT4-JEM-COUNT ! 16 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-REVOKES/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ +
                0 OVER _EXT4-BE32!
                _EXT4-JEM-ENTRY @ @ SWAP 4 + _EXT4-BE32!
                8 _EXT4-JEM-OFF +!
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-COUNT @ 8 * 16 +
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ 12 + _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JWP-REVOKE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
    REPEAT
    0 ;

: _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-CURSOR @ _EXT4-JEM-COMMIT !
    _EXT4-JWP-COMMIT-PRESEED _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    DUP _EXT4-JEM-CURSOR ! _EXT4-JEM-SENTINEL @ <> IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JWP-SENTINEL _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-BODY-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-INSTALL-ACTIVE-SUPER  ( -- ior )
    _EXT4-JWP-ACTIVE-GUARD-PRESEED
    _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK + _EXT4-JEM-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF
        NIP _EXT4-JEM-FAULT EXIT
    THEN 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-STAMP-ACTIVE-SUPER
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-GUARD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-PRIMARY _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    0 _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-WRITE-COMMIT  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-COMMIT _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-COMMIT-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-PUBLISH-COMMITTED  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    DUP _EXT4-JEM-OLD-RESERVED ! _EXT4-JEM-ACTUAL @ U< IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-OLD-RESERVED @ _EXT4-JEM-ACTUAL @ -
    _EXT4-JEM-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JEM-ACTUAL @ _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JEM-SENTINEL @ DUP
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 1+
    0xFFFFFFFF AND _EXT4-JEM-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CTX @ _EXT4-C.J.START + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEM-CTX @ _EXT4-C.J.SEQUENCE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @ DUP
    _EXT4-JEM-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JEM-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-C.J.CURSOR + !
    1 _EXT4-JEM-CTX @ _EXT4-C.J.COMMITTED + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND _EXT4-JEM-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JC-ACTIVE _EXT4-JEM-CTX @ _EXT4-C.J.CLEANUP + !
    _EXT4-JWP-NONE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-COMMITTED _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR-VALID? 0= IF
        _EXT4-JWP-COMMIT-FLUSH
        _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-EMIT  ( transaction -- ior )
    DUP _EXT4-JEM-WRITER ! _EXT4-JTX-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JEM-CTX !
    _EXT4-JEP-ACTUAL @ _EXT4-JEM-ACTUAL !
    _EXT4-JEP-SENTINEL @ _EXT4-JEM-SENTINEL !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JEM-CURSOR !
    _EXT4-JWR-EMITTING _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-EMIT-ORDERED-DATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-METADATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-REVOKES ?DUP IF EXIT THEN
    _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL ?DUP IF EXIT THEN
    _EXT4-JTX-INSTALL-ACTIVE-SUPER ?DUP IF EXIT THEN
    _EXT4-JTX-WRITE-COMMIT ?DUP IF EXIT THEN
    _EXT4-JTX-PUBLISH-COMMITTED ;

\ =====================================================================
\  Unified legacy/modern orphan recovery preflight
\ =====================================================================
\
\ Orphan state is authoritative only after committed JBD2 after-images have
\ reached home.  Mount therefore calls this through VALIDATE-REST after replay
\ and strict reload.  Two passes first derive the exact union count, then fill
\ one arena-backed open-addressed plan.  Each occupied slot authenticates an
\ inode and retains only protocol locators that can be reauthenticated before
\ later cleanup: legacy { inode, next } or modern { logical block, slot }.
\ Discovery itself never mutates an inode, orphan-file block, or legacy link.
\ Mounted cleanup qualifies the whole union, then drains one deterministic,
\ sealed record per transaction without imposing a record-count policy cap.

VARIABLE _EXT4-OW-CTX
VARIABLE _EXT4-OW-COUNT
VARIABLE _EXT4-OW-REQUIRED
VARIABLE _EXT4-OW-BYTES
VARIABLE _EXT4-MRW-CTX
VARIABLE _EXT4-MRW-REQUIRED
VARIABLE _EXT4-MRW-BYTES
VARIABLE _EXT4-OCW-CTX
VARIABLE _EXT4-OCW-REQUIRED
VARIABLE _EXT4-OCW-BYTES

4 CONSTANT _EXT4-ORPHAN-RECORD-CELLS
_EXT4-ORPHAN-RECORD-CELLS CELLS CONSTANT _EXT4-ORPHAN-RECORD-SIZE
0 CONSTANT _EXT4-OE.INO
1 CELLS CONSTANT _EXT4-OE.KIND
2 CELLS CONSTANT _EXT4-OE.LOCATOR-A
3 CELLS CONSTANT _EXT4-OE.LOCATOR-B
1 CONSTANT _EXT4-OK-LEGACY
2 CONSTANT _EXT4-OK-MODERN

_EXT4-NONNEG-MAX _EXT4-ORPHAN-RECORD-SIZE /
CONSTANT _EXT4-ORPHAN-SLOTS-MAX

\ Retain the shared 2P+16 authority budget: all direct and single-indirect data
\ plus one complete double-indirect child, its three map homes, and one xattr.
\ Additional sparse children are admitted by actual occupancy within the same
\ workspace.  Resident depth-one fanout is smaller at every mounted block size.
: _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY  ( ctx -- capacity ior )
    DUP 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-C.BSIZE + @ _EXT4-DELETE-RANGE-CAPACITY ;

: _EXT4-MUTATION-RANGE-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.MUTATION-RANGES + @
    SWAP _EXT4-C.MUTATION-RANGE-CAP + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 0< IF 2DROP FALSE EXIT THEN
    2 _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    MSPAN-NONWRAPPING? ;

: _EXT4-ENSURE-MUTATION-RANGE-WORKSPACE  ( ctx -- ior )
    DUP _EXT4-MRW-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MRW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-MRW-REQUIRED !
    _EXT4-MRW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + @ IF
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
        _EXT4-MRW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + @
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
        2 * CELLS 0 FILL
        0 EXIT
    THEN
    _EXT4-MRW-REQUIRED @ 2 _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP EXIT THEN DROP _EXT4-MRW-BYTES !
    _EXT4-MRW-CTX @ _EXT4-C.ARENA + @
    _EXT4-MRW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + !
    _EXT4-MRW-BYTES @ 0 FILL
    _EXT4-MRW-REQUIRED @
    _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + !
    0 ;

: _EXT4-OWNER-CERT-RANGE-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.OWNER-CERT-RANGES + @
    SWAP _EXT4-C.OWNER-CERT-RANGE-CAP + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 0< IF 2DROP FALSE EXIT THEN
    2 _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    MSPAN-NONWRAPPING? ;

: _EXT4-ENSURE-OWNER-CERT-RANGE-WORKSPACE  ( ctx -- ior )
    DUP _EXT4-OCW-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-OCW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-OCW-REQUIRED !
    _EXT4-OCW-CTX @ _EXT4-OWNER-CERT-RANGE-WORKSPACE? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGES + @ IF
        _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGE-CAP + @
        _EXT4-OCW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGES + @
        _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGE-CAP + @
        2 * CELLS 0 FILL
        0 EXIT
    THEN
    _EXT4-OCW-REQUIRED @ 2 _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP EXIT THEN DROP _EXT4-OCW-BYTES !
    _EXT4-OCW-CTX @ _EXT4-C.ARENA + @
    _EXT4-OCW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGES + !
    _EXT4-OCW-BYTES @ 0 FILL
    _EXT4-OCW-REQUIRED @
    _EXT4-OCW-CTX @ _EXT4-C.OWNER-CERT-RANGE-CAP + !
    0 ;

: _EXT4-ORPHAN-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.O.TABLE + @
    SWAP _EXT4-C.O.SLOTS + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 2 U< IF 2DROP FALSE EXIT THEN
    DUP _EXT4-ORPHAN-SLOTS-MAX U> IF 2DROP FALSE EXIT THEN
    DUP 1- AND 0= NIP ;

\ Allocate a half-full power-of-two uniqueness table from the caller's arena.
\ Failed-mount retries reuse and clear the original allocation.  A retry that
\ needs a larger table fails without consuming a second monotonic allocation.
: _EXT4-ENSURE-ORPHAN-WORKSPACE  ( active-count ctx -- ior )
    _EXT4-OW-CTX ! DUP _EXT4-OW-COUNT ! DROP
    _EXT4-OW-CTX @ _EXT4-ENSURE-MUTATION-RANGE-WORKSPACE
    ?DUP IF EXIT THEN
    _EXT4-OW-CTX @ _EXT4-ENSURE-OWNER-CERT-RANGE-WORKSPACE
    ?DUP IF EXIT THEN
    _EXT4-OW-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OW-COUNT @ _EXT4-HASH-SLOTS
    DUP IF NIP EXIT THEN DROP _EXT4-OW-REQUIRED !
    _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @ IF
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-OW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-ORPHAN-RECORD-SIZE * 0 FILL
        0 EXIT
    THEN
    _EXT4-OW-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-SLOTS-MAX U> IF
        EXT4-D-ORPHAN-FILE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-RECORD-SIZE * _EXT4-OW-BYTES !
    _EXT4-OW-CTX @ _EXT4-C.ARENA + @
    _EXT4-OW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-OW-CTX @ _EXT4-C.O.TABLE + !
    _EXT4-OW-BYTES @ 0 FILL
    _EXT4-OW-REQUIRED @ _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + !
    0 ;

VARIABLE _EXT4-OH-CTX
VARIABLE _EXT4-OH-INO
VARIABLE _EXT4-OH-KIND
VARIABLE _EXT4-OH-A
VARIABLE _EXT4-OH-B
VARIABLE _EXT4-OH-SLOT

: _EXT4-ORPHAN-TABLE-ENTRY  ( slot ctx -- address )
    _EXT4-C.O.TABLE + @ SWAP _EXT4-ORPHAN-RECORD-SIZE * + ;

: _EXT4-ORPHAN-TABLE-PUT  ( inode kind locator-a locator-b ctx -- ior )
    _EXT4-OH-CTX ! _EXT4-OH-B ! _EXT4-OH-A !
    _EXT4-OH-KIND ! _EXT4-OH-INO !
    _EXT4-OH-INO @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OH-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-OH-B @ IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    ELSE
        _EXT4-OH-KIND @ _EXT4-OK-MODERN <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ DUP 0= IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    1- _EXT4-OH-INO @ SWAP AND _EXT4-OH-SLOT !
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        _EXT4-OH-SLOT @ _EXT4-OH-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP @ DUP 0= IF
            DROP
            _EXT4-OH-INO @ OVER _EXT4-OE.INO + !
            _EXT4-OH-KIND @ OVER _EXT4-OE.KIND + !
            _EXT4-OH-A @ OVER _EXT4-OE.LOCATOR-A + !
            _EXT4-OH-B @ SWAP _EXT4-OE.LOCATOR-B + !
            0 UNLOOP EXIT
        THEN
        NIP _EXT4-OH-INO @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OH-SLOT @ 1+
        _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 1- AND
        _EXT4-OH-SLOT !
    LOOP
    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT ;

VARIABLE _EXT4-OP-CTX
VARIABLE _EXT4-OP-COUNT
VARIABLE _EXT4-OP-ENTRIES
VARIABLE _EXT4-OL-CTX
VARIABLE _EXT4-OL-CURRENT
VARIABLE _EXT4-OL-NEXT
VARIABLE _EXT4-OL-COUNT
VARIABLE _EXT4-OL-LIMIT
VARIABLE _EXT4-OL-SLOW
VARIABLE _EXT4-OL-FAST
VARIABLE _EXT4-OS-CTX
VARIABLE _EXT4-OS-INO
VARIABLE _EXT4-ON-CTX
VARIABLE _EXT4-ON-INO

: _EXT4-ORPHAN-INODE-NUMBER?  ( inode-number ctx -- flag )
    _EXT4-ON-CTX ! _EXT4-ON-INO !
    _EXT4-ON-INO @
    _EXT4-ON-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0=
    _EXT4-ON-INO @ _EXT4-ON-CTX @ _EXT4-C.INODES + @ U> 0= AND ;

: _EXT4-LEGACY-ORPHAN-NEXT  ( inode-number ctx -- next ior )
    _EXT4-OS-CTX ! DUP _EXT4-OS-INO !
    _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OS-INO @ _EXT4-OS-CTX @
    _EXT4-LOAD-ORPHAN-INODE DUP IF 0 SWAP EXIT THEN DROP
    _EXT4-OS-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ DUP IF
        DUP _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
            DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Floyd's constant-space pass rejects cycles before the exact counting pass.
\ This avoids making a short malformed loop consume the whole inode-count
\ bound while retaining an allocation-free first pass.
: _EXT4-VALIDATE-LEGACY-TERMINATION  ( ctx -- ior )
    DUP _EXT4-OL-CTX ! _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
    DUP _EXT4-OL-SLOW ! _EXT4-OL-FAST !
    BEGIN
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-SLOW @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-SLOW !
        _EXT4-OL-FAST @ _EXT4-OL-SLOW @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    AGAIN ;

\ Count the legacy singly linked list without allocating cycle state.  No
\ valid chain can visit more distinct inode numbers than FIRST_INO..INODES;
\ crossing that geometry-derived bound proves nontermination.  The second
\ pass inserts into the shared uniqueness plan and therefore identifies the
\ repeated inode directly.
: _EXT4-COUNT-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    DUP _EXT4-VALIDATE-LEGACY-TERMINATION ?DUP IF NIP EXIT THEN
    DUP _EXT4-C.INODES + @
    OVER _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ - 1+
    _EXT4-OL-LIMIT !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    0 _EXT4-OL-COUNT !
    BEGIN _EXT4-OL-CURRENT @ WHILE
        _EXT4-OL-COUNT @ _EXT4-OL-LIMIT @ U< 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP EXIT THEN
        DROP _EXT4-OL-NEXT !
        1 _EXT4-OL-COUNT +!
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    REPEAT
    _EXT4-OL-COUNT @ _EXT4-OL-CTX @
    _EXT4-C.O.LEGACY-ACTIVE + !
    0 ;

: _EXT4-COUNT-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    0 _EXT4-OP-COUNT !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OP-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                    UNLOOP UNLOOP EXIT
                THEN
                1 _EXT4-OP-COUNT +!
            THEN
        LOOP
    LOOP
    _EXT4-OP-COUNT @ _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 ;

: _EXT4-INDEX-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OK-MODERN J I _EXT4-OP-CTX @
                _EXT4-ORPHAN-TABLE-PUT ?DUP IF
                    UNLOOP UNLOOP EXIT
                THEN
            THEN
        LOOP
    LOOP
    0 ;

: _EXT4-INDEX-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    _EXT4-OL-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0 ?DO
        _EXT4-OL-CURRENT @ 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP UNLOOP EXIT THEN
        DROP _EXT4-OL-NEXT !
        _EXT4-OL-CURRENT @ _EXT4-OK-LEGACY
        _EXT4-OL-NEXT @ 0 _EXT4-OL-CTX @
        _EXT4-ORPHAN-TABLE-PUT ?DUP IF UNLOOP EXIT THEN
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    LOOP
    _EXT4-OL-CURRENT @ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-OI-CTX
VARIABLE _EXT4-OI-INO
VARIABLE _EXT4-OI-IN
VARIABLE _EXT4-OI-NLINK
VARIABLE _EXT4-OI-TYPE
VARIABLE _EXT4-OI-IOR

\ ext4_orphan_get() admits allocated, checksum-valid inodes at or above
\ s_first_ino.  Linked entries must be truncatable; unlinked entries may be
\ any valid inode type because cleanup deletes them.  STAGE-CURRENT-INODE
\ already owns the complete type/size/flag/map checks.  For an unlinked inode
\ only, temporarily substitute a nonzero link count in the authenticated cache
\ while running that read-only validator, then restore the original bytes.
: _EXT4-VALIDATE-ACTIVE-ORPHAN  ( inode-number ctx -- ior )
    _EXT4-OI-CTX ! DUP _EXT4-OI-INO !
    DUP _EXT4-OI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U<
    OVER _EXT4-OI-CTX @ _EXT4-C.INODES + @ U> OR IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-OI-INO @ _EXT4-OI-CTX @ _EXT4-LOAD-ORPHAN-INODE ?DUP IF
        EXIT
    THEN
    _EXT4-OI-CTX @ _EXT4-C.INODE + DUP _EXT4-OI-IN !
    _EXT4-I.LINKS + W@ DUP _EXT4-OI-NLINK ! 0= IF
        1 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-OI-IOR ! _EXT4-OI-TYPE !
    _EXT4-OI-NLINK @ 0= IF
        0 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-IOR @ ?DUP IF EXIT THEN
    _EXT4-OI-NLINK @ IF
        _EXT4-OI-TYPE @ VFS-T-FILE =
        _EXT4-OI-TYPE @ VFS-T-DIR = OR
        _EXT4-OI-TYPE @ VFS-T-SYMLINK = OR 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OI-CTX @ _EXT4-OI-TYPE @ _EXT4-FAST-SYMLINK-STORAGE? IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

VARIABLE _EXT4-OQ-CTX
VARIABLE _EXT4-OQ-RECORD

: _EXT4-ORPHAN-RECORD?  ( record ctx -- flag )
    _EXT4-OQ-CTX ! DUP _EXT4-OQ-RECORD !
    DUP _EXT4-OE.INO + @ _EXT4-OQ-CTX @
    _EXT4-ORPHAN-INODE-NUMBER? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        DUP _EXT4-OE.LOCATOR-B + @ IF DROP FALSE EXIT THEN
        _EXT4-OE.LOCATOR-A + @ ?DUP IF
            _EXT4-OQ-CTX @ _EXT4-ORPHAN-INODE-NUMBER?
        ELSE
            TRUE
        THEN EXIT
    THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        DUP _EXT4-OE.LOCATOR-A + @ _EXT4-OV-BLOCKS @ U<
        SWAP _EXT4-OE.LOCATOR-B + @
        _EXT4-OQ-CTX @ _EXT4-C.BSIZE + @ 8 - 4 / U< AND
        EXIT
    THEN
    DROP FALSE ;

VARIABLE _EXT4-OM-RECORD
VARIABLE _EXT4-OM-CTX
VARIABLE _EXT4-OM-BASE
VARIABLE _EXT4-OM-OFF
VARIABLE _EXT4-OM-INO
VARIABLE _EXT4-OM-SLOT
VARIABLE _EXT4-OM-ENTRY

\ Cleanup authority belongs to the exact retained discovery plan, not to a
\ caller-authored record that merely copies its four cells.
: _EXT4-ORPHAN-PLAN-MEMBER?  ( record ctx -- flag )
    _EXT4-OM-CTX ! _EXT4-OM-RECORD !
    _EXT4-OM-RECORD @ 0= _EXT4-OM-CTX @ 0= OR IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-C.O.TABLE + @ DUP _EXT4-OM-BASE !
    _EXT4-OM-RECORD @ U> IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ _EXT4-OM-BASE @ - DUP _EXT4-OM-OFF !
    _EXT4-ORPHAN-RECORD-SIZE MOD IF FALSE EXIT THEN
    _EXT4-OM-OFF @
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @
    _EXT4-ORPHAN-RECORD-SIZE * U< 0= IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ @ DUP 0= IF DROP FALSE EXIT THEN
    _EXT4-OM-INO !
    _EXT4-OM-INO @
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 1- AND _EXT4-OM-SLOT !
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        _EXT4-OM-SLOT @ _EXT4-OM-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OM-ENTRY ! @ DUP 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        _EXT4-OM-INO @ = IF
            _EXT4-OM-ENTRY @ _EXT4-OM-RECORD @ = UNLOOP EXIT
        THEN
        _EXT4-OM-SLOT @ 1+
        _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 1- AND
        _EXT4-OM-SLOT !
    LOOP
    FALSE ;

VARIABLE _EXT4-ORA-RECORD
VARIABLE _EXT4-ORA-CTX
VARIABLE _EXT4-ORA-INO
VARIABLE _EXT4-ORA-KIND

\ Reauthenticate both the retained discovery record and the current media
\ locator, then leave the checksum-valid target inode in C.INODE.  This is a
\ read-only authority check; staged transaction images never stand in for the
\ plan or for the raw orphan chain that the plan names.
: _EXT4-REAUTH-ORPHAN-PLAN-RECORD  ( plan-record ctx -- ior )
    _EXT4-ORA-CTX ! _EXT4-ORA-RECORD !
    _EXT4-ORA-RECORD @ 0= _EXT4-ORA-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-ORA-INO !
    _EXT4-ORA-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-ORA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-ORA-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-ORA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-ORA-CTX @ _EXT4-C.BLOCK +
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-ORA-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-ORA-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-ORA-INO @ _EXT4-ORA-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-ORA-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-ORA-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-VALIDATE-INDEXED-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OQ-RECORD ! @ ?DUP IF
            _EXT4-OQ-RECORD @ _EXT4-OP-CTX @
            _EXT4-ORPHAN-RECORD? 0= IF
                DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-OP-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF
                UNLOOP EXIT
            THEN
            _EXT4-OQ-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN =
            _EXT4-OP-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0<> AND IF
                _EXT4-OP-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
                THEN
            THEN
        THEN
    LOOP
    0 ;

\ Build and authenticate the complete legacy/modern union without deciding
\ whether a caller is allowed to continue past a nonempty recovery plan.
\ Public mount validation retains the policy boundary below; sealed cleanup
\ checkpointing uses this core and proves one exact writer-owned selection.
: _EXT4-AUTHENTICATE-ORPHAN-PLAN  ( ctx -- ior )
    _EXT4-OP-CTX !
    0 _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
    _EXT4-OP-CTX @ _EXT4-COUNT-LEGACY-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-COUNT-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ _EXT4-UADD?
    DUP IF
        2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN DROP
    DUP _EXT4-OP-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    _EXT4-OP-CTX @
    _EXT4-ENSURE-ORPHAN-WORKSPACE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-LEGACY-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-VALIDATE-INDEXED-ORPHANS ?DUP IF EXIT THEN
    ELSE
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND IF
            -1 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
        THEN
    THEN
    0 ;

\ =====================================================================
\  Typed, non-emitting orphan-recovery metadata after-images
\ =====================================================================
\
\ These private builders stop at the transaction-staging boundary.  They
\ reauthenticate every plan locator against media, compose same-home edits in
\ writer scratch, and restamp the affected ext4 checksum before replacing the
\ complete retained after-image.  They neither activate nor emit a journal
\ transaction and therefore grant no cleanup or public-write authority by
\ themselves.

VARIABLE _EXT4-RI-INODE
VARIABLE _EXT4-RI-INO
VARIABLE _EXT4-RI-CTX
VARIABLE _EXT4-RI-EXTRA
VARIABLE _EXT4-RI-HAS-HI
VARIABLE _EXT4-RI-CALC

: _EXT4-RESTAMP-INODE  ( inode inode-number ctx -- ior )
    _EXT4-RI-CTX ! _EXT4-RI-INO ! _EXT4-RI-INODE !
    _EXT4-RI-INODE @ 0= _EXT4-RI-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-RI-INO @ 0=
    _EXT4-RI-INO @ _EXT4-RI-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ 128 U< IF
        EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-RI-HAS-HI !
    _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-RI-INODE @ _EXT4-I.EXTRA-SIZE + W@
        DUP _EXT4-RI-EXTRA ! 4 U< IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RI-EXTRA @ 4 MOD IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RI-EXTRA @ 128 +
        _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ U> IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        -1 _EXT4-RI-HAS-HI !
    THEN
    0 _EXT4-RI-INODE @ _EXT4-I.CSUM-LO + W!
    _EXT4-RI-HAS-HI @ IF
        0 _EXT4-RI-INODE @ _EXT4-I.CSUM-HI + W!
    THEN
    _EXT4-RI-INO @ _EXT4-RI-CTX @ _EXT4-C.TMP + L!
    _EXT4-RI-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RI-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-RI-INODE @ _EXT4-I.GENERATION + 4 _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-RI-INODE @ _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ DUP _EXT4-RI-CALC !
    _EXT4-RI-INODE @ _EXT4-I.CSUM-LO + W!
    _EXT4-RI-HAS-HI @ IF
        _EXT4-RI-CALC @ 16 RSHIFT
        _EXT4-RI-INODE @ _EXT4-I.CSUM-HI + W!
    THEN
    0 ;

VARIABLE _EXT4-ITM-SECONDS
VARIABLE _EXT4-ITM-NSEC
VARIABLE _EXT4-ITM-INODE
VARIABLE _EXT4-ITM-CTX
VARIABLE _EXT4-ITM-LOW
VARIABLE _EXT4-ITM-SIGNED
VARIABLE _EXT4-ITM-EPOCH
VARIABLE _EXT4-ITM-EXTRA

\ Encode one explicit timestamp into both mtime and ctime without consulting
\ an ambiguous ambient clock.  Ext4 decodes the low word as signed and then
\ adds the extra field's two epoch bits, so derive those bits from the
\ sign-extended low word rather than from a logical seconds shift.
: _EXT4-SET-INODE-MTIME-CTIME  ( seconds nsec inode ctx -- ior )
    _EXT4-ITM-CTX ! _EXT4-ITM-INODE !
    _EXT4-ITM-NSEC ! _EXT4-ITM-SECONDS !
    _EXT4-ITM-CTX @ 0= _EXT4-ITM-INODE @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ITM-NSEC @ 0<
    _EXT4-ITM-NSEC @ 1000000000 U< 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ DUP 128 =
    SWAP 256 = OR 0= IF
        EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ITM-SECONDS @ -2147483648 <
    _EXT4-ITM-SECONDS @ 15032385535 > OR IF
        VFS-E-OVERFLOW EXIT
    THEN
    _EXT4-ITM-SECONDS @ 0xFFFFFFFF AND DUP _EXT4-ITM-LOW !
    DUP 0x80000000 AND IF 0xFFFFFFFF00000000 OR THEN
    _EXT4-ITM-SIGNED !
    _EXT4-ITM-SECONDS @ _EXT4-ITM-SIGNED @ - 32 RSHIFT
    DUP _EXT4-ITM-EPOCH ! 3 U> IF VFS-E-OVERFLOW EXIT THEN
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ 128 = IF
        _EXT4-ITM-NSEC @ _EXT4-ITM-EPOCH @ OR IF
            VFS-E-OVERFLOW EXIT
        THEN
        0 _EXT4-ITM-EXTRA !
    ELSE
        \ This first writable slice follows live-inode staging's modern
        \ profile: all three extra timestamps and the high checksum exist.
        \ Old-format 256-byte records with extra_isize zero remain readable
        \ but are not silently upgraded by a data overwrite.
        _EXT4-ITM-INODE @ _EXT4-I.EXTRA-SIZE + W@
        DUP 16 U< IF DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT THEN
        DUP 4 MOD IF DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT THEN
        128 + _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ U> IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-ITM-NSEC @ 2 LSHIFT _EXT4-ITM-EPOCH @ OR
        _EXT4-ITM-EXTRA !
    THEN
    _EXT4-ITM-LOW @ _EXT4-ITM-INODE @ _EXT4-I.CTIME + L!
    _EXT4-ITM-LOW @ _EXT4-ITM-INODE @ _EXT4-I.MTIME + L!
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-ITM-EXTRA @
        _EXT4-ITM-INODE @ _EXT4-I.CTIME-EXTRA + L!
        _EXT4-ITM-EXTRA @
        _EXT4-ITM-INODE @ _EXT4-I.MTIME-EXTRA + L!
    THEN
    0 ;

VARIABLE _EXT4-ROB-BLOCK
VARIABLE _EXT4-ROB-PHYS
VARIABLE _EXT4-ROB-INO
VARIABLE _EXT4-ROB-GEN
VARIABLE _EXT4-ROB-CTX
VARIABLE _EXT4-ROB-TAIL

: _EXT4-RESTAMP-ORPHAN-BLOCK
  ( block physical orphan-inode generation ctx -- ior )
    _EXT4-ROB-CTX ! _EXT4-ROB-GEN ! _EXT4-ROB-INO !
    _EXT4-ROB-PHYS ! _EXT4-ROB-BLOCK !
    _EXT4-ROB-BLOCK @ 0= _EXT4-ROB-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.ORPHAN-INO + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-PHYS @
    _EXT4-ROB-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-PHYS @ 0xFFFFFFFF U>
    _EXT4-ROB-GEN @ 0xFFFFFFFF U> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-BLOCK @ _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - +
    DUP _EXT4-ROB-TAIL ! L@ _EXT4-ORPHAN-MAGIC <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.TMP + L!
    _EXT4-ROB-GEN @ _EXT4-ROB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-ROB-PHYS @ _EXT4-ROB-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-ROB-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-ROB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-ROB-CTX @ _EXT4-C.TMP + 16 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-ROB-BLOCK @
    _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@
    _EXT4-ROB-TAIL @ 4 + L!
    0 ;

VARIABLE _EXT4-OCV-STORED

: _EXT4-ORPHAN-BLOCK-CHECKSUM?
  ( block physical orphan-inode generation ctx -- flag ior )
    _EXT4-ROB-CTX ! _EXT4-ROB-GEN ! _EXT4-ROB-INO !
    _EXT4-ROB-PHYS ! _EXT4-ROB-BLOCK !
    _EXT4-ROB-BLOCK @ 0= _EXT4-ROB-CTX @ 0= OR IF FALSE 0 EXIT THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.ORPHAN-INO + @ <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-ROB-PHYS @
    _EXT4-ROB-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF FALSE 0 EXIT THEN
    _EXT4-ROB-PHYS @ 0xFFFFFFFF U>
    _EXT4-ROB-GEN @ 0xFFFFFFFF U> OR IF FALSE 0 EXIT THEN
    _EXT4-ROB-BLOCK @ _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - + DUP
    L@ _EXT4-ORPHAN-MAGIC <> IF DROP FALSE 0 EXIT THEN
    4 + L@ _EXT4-OCV-STORED !
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.TMP + L!
    _EXT4-ROB-GEN @ _EXT4-ROB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-ROB-PHYS @ _EXT4-ROB-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-ROB-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-ROB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-ROB-CTX @ _EXT4-C.TMP + 16 _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-ROB-BLOCK @
    _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ _EXT4-OCV-STORED @ = 0 ;

VARIABLE _EXT4-JOI-NEW
VARIABLE _EXT4-JOI-RECORD
VARIABLE _EXT4-JOI-WRITER
VARIABLE _EXT4-JOI-CTX
VARIABLE _EXT4-JOI-INO
VARIABLE _EXT4-JOI-KIND
VARIABLE _EXT4-JOI-HOME
VARIABLE _EXT4-JOI-OFF
VARIABLE _EXT4-JOI-IMAGE
VARIABLE _EXT4-JOI-SNAPSHOT

: _EXT4-JTX-STAGE-ORPHAN-INODE
  ( inode-afterimage plan-record transaction -- ior )
    _EXT4-JOI-WRITER ! _EXT4-JOI-RECORD ! _EXT4-JOI-NEW !
    _EXT4-JOI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOI-NEW @ 0= _EXT4-JOI-RECORD @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOI-CTX !
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    \ Preserve natural C.INODE, C.BLOCK, and SCRATCH-A caller inputs before
    \ locator reauthentication overwrites those caches.  SCRATCH-B remains
    \ private and unused by non-emitting transaction staging.
    _EXT4-JOI-WRITER @ _EXT4-JWR.SCRATCH-B + @ DUP
    _EXT4-JOI-SNAPSHOT !
    _EXT4-JOI-NEW @ SWAP
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOI-INO !
    _EXT4-JOI-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOI-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOI-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JOI-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-JOI-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOI-CTX @ _EXT4-C.BLOCK +
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-JOI-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-INO @ _EXT4-JOI-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-JOI-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-I.GENERATION + L@
    _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.GENERATION + L@ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-IR-BLOCK @ _EXT4-JOI-HOME !
    _EXT4-IR-OFF @ _EXT4-JOI-OFF !
    _EXT4-JOI-CTX @ _EXT4-C.BLOCK + _EXT4-JOI-HOME @
    _EXT4-JOI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOI-IMAGE !
    \ Different records in one table block compose, but a second full-record
    \ replacement of this same inode must not silently discard its predecessor.
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.INODE +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ + _EXT4-JOI-INO @
    _EXT4-JOI-CTX @ _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _EXT4-JOI-IMAGE @ _EXT4-JOI-HOME @ _EXT4-JOI-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JOS-RECORD
VARIABLE _EXT4-JOS-WRITER
VARIABLE _EXT4-JOS-CTX
VARIABLE _EXT4-JOS-INO
VARIABLE _EXT4-JOS-HOME
VARIABLE _EXT4-JOS-GEN
VARIABLE _EXT4-JOS-ORPHAN-INO
VARIABLE _EXT4-JOS-SLOT
VARIABLE _EXT4-JOS-IMAGE
VARIABLE _EXT4-JOS-EA

\ =====================================================================
\  Typed, non-emitting block-free accounting after-images
\ =====================================================================

VARIABLE _EXT4-GBC-GROUP
VARIABLE _EXT4-GBC-CTX
VARIABLE _EXT4-GBC-START

: _EXT4-GROUP-BLOCK-COUNT  ( group ctx -- blocks ior )
    _EXT4-GBC-CTX ! DUP _EXT4-GBC-GROUP !
    _EXT4-GBC-CTX @ 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-GBC-GROUP @
    _EXT4-GBC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        DROP 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-GBC-GROUP @ _EXT4-GBC-CTX @ _EXT4-C.BPG + @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP
    _EXT4-GBC-CTX @ _EXT4-C.FIRST + @ _EXT4-UADD?
    DUP IF NIP 0 SWAP EXIT THEN DROP DUP _EXT4-GBC-START !
    _EXT4-GBC-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GBC-CTX @ _EXT4-C.BLOCKS + @ _EXT4-GBC-START @ -
    _EXT4-GBC-CTX @ _EXT4-C.BPG + @ MIN 0 ;

VARIABLE _EXT4-GBR-GROUP
VARIABLE _EXT4-GBR-CTX
VARIABLE _EXT4-GBR-COUNT

\ Return the exact half-open physical interval owned by one block group.
\ Reuse the canonical short-last-group calculation and keep every address
\ operation checked so sizing cannot wrap malformed geometry into a match.
: _EXT4-GROUP-BLOCK-RANGE  ( group ctx -- first count ior )
    _EXT4-GBR-CTX ! _EXT4-GBR-GROUP !
    _EXT4-GBR-GROUP @ _EXT4-GBR-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP 0 0 ROT EXIT THEN DROP _EXT4-GBR-COUNT !
    _EXT4-GBR-GROUP @
    _EXT4-GBR-CTX @ _EXT4-C.BPG + @ _EXT4-UMUL?
    DUP IF NIP 0 0 ROT EXIT THEN DROP
    _EXT4-GBR-CTX @ _EXT4-C.FIRST + @ _EXT4-UADD?
    DUP IF NIP 0 0 ROT EXIT THEN DROP
    _EXT4-GBR-COUNT @ 0 ;

VARIABLE _EXT4-GDC-DESC
VARIABLE _EXT4-GDC-GROUP
VARIABLE _EXT4-GDC-CTX
VARIABLE _EXT4-GDC-STORED
VARIABLE _EXT4-GDC-CALC

: _EXT4-GROUP-DESC-CHECKSUM?  ( descriptor group ctx -- flag ior )
    _EXT4-GDC-CTX ! _EXT4-GDC-GROUP ! _EXT4-GDC-DESC !
    _EXT4-GDC-DESC @ 0= _EXT4-GDC-CTX @ 0= OR IF FALSE 0 EXIT THEN
    _EXT4-GDC-GROUP @
    _EXT4-GDC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF FALSE 0 EXIT THEN
    _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W@ _EXT4-GDC-STORED !
    0 _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-GROUP @ _EXT4-GDC-CTX @ _EXT4-C.TMP + L!
    _EXT4-GDC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-GDC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF
        _EXT4-GDC-STORED @ _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
        0 SWAP EXIT
    THEN
    _EXT4-GDC-DESC @ _EXT4-DESC-SIZE _EXT4-CRC-ADD ?DUP IF
        _EXT4-GDC-STORED @ _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
        0 SWAP EXIT
    THEN
    _EXT4-CRC@ 0xFFFF AND _EXT4-GDC-CALC !
    _EXT4-GDC-STORED @ _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-CALC @ _EXT4-GDC-STORED @ = 0 ;

: _EXT4-RESTAMP-GROUP-DESC  ( descriptor group ctx -- ior )
    _EXT4-GDC-CTX ! _EXT4-GDC-GROUP ! _EXT4-GDC-DESC !
    _EXT4-GDC-DESC @ 0= _EXT4-GDC-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-GDC-GROUP @
    _EXT4-GDC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-GROUP @ _EXT4-GDC-CTX @ _EXT4-C.TMP + L!
    _EXT4-GDC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-GDC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-GDC-DESC @ _EXT4-DESC-SIZE _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@ 0xFFFF AND
    _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    0 ;

VARIABLE _EXT4-MWH-CTX
VARIABLE _EXT4-MWH-FIRST
VARIABLE _EXT4-MWH-COUNT

\ Prove that the primary super/GDT homes this operation will replace are not
\ also named as allocation metadata by any authenticated descriptor.  Read
\ admission alone permits flex_bg placement, so writable admission must make
\ this anti-alias invariant explicit before publishing an after-image.
: _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN _EXT4-MWH-CTX !
    _EXT4-MWH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _EXT4-MWH-FIRST !
    _EXT4-MWH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ 1+
    _EXT4-MWH-COUNT !
    _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @ _EXT4-MWH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-MWH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MWH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    0 ;

VARIABLE _EXT4-MBH-HOME
VARIABLE _EXT4-MBH-OWNER
VARIABLE _EXT4-MBH-CTX
VARIABLE _EXT4-MBH-FOUND
VARIABLE _EXT4-MBH-BASE
VARIABLE _EXT4-MBH-COUNT

\ A block bitmap that will be replaced must have exactly one descriptor
\ owner and must be disjoint from every inode bitmap/table, sparse-super
\ interval, and journal extent.  Otherwise one valid-looking free operation
\ could silently mutate unrelated metadata through a checksum-valid alias.
: _EXT4-VALIDATE-BLOCK-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MBH-CTX ! _EXT4-MBH-OWNER ! _EXT4-MBH-HOME !
    _EXT4-MBH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MBH-OWNER @
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MBH-FOUND !
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MBH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-MBH-HOME @ = IF
            I _EXT4-MBH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MBH-FOUND +!
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MBH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MBH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MBH-BASE !
            1 _EXT4-MBH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MBH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MBH-COUNT !
            _EXT4-MBH-HOME @ 1
            _EXT4-MBH-BASE @ _EXT4-MBH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MBH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MIH-HOME
VARIABLE _EXT4-MIH-OWNER
VARIABLE _EXT4-MIH-CTX
VARIABLE _EXT4-MIH-FOUND
VARIABLE _EXT4-MIH-BASE
VARIABLE _EXT4-MIH-COUNT

\ An inode bitmap that will be replaced has one exact descriptor owner.  It
\ may share neither another allocation role nor an inode-table or sparse-copy
\ interval, and it may not overlap the journal.  These mutation-side proofs
\ are deliberately stronger than checksum-valid read admission.
: _EXT4-VALIDATE-INODE-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MIH-CTX ! _EXT4-MIH-OWNER ! _EXT4-MIH-HOME !
    _EXT4-MIH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MIH-OWNER @
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MIH-FOUND !
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MIH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-MIH-HOME @ = IF
            I _EXT4-MIH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MIH-FOUND +!
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MIH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MIH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MIH-BASE !
            1 _EXT4-MIH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MIH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MIH-COUNT !
            _EXT4-MIH-HOME @ 1
            _EXT4-MIH-BASE @ _EXT4-MIH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MIH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MTH-HOME
VARIABLE _EXT4-MTH-OWNER
VARIABLE _EXT4-MTH-CTX
VARIABLE _EXT4-MTH-FOUND
VARIABLE _EXT4-MTH-BASE
VARIABLE _EXT4-MTH-COUNT

\ An inode-table page that will be replaced must belong to exactly one
\ authenticated group table.  It may not also name an allocation bitmap,
\ another group's table, sparse-super/GDT storage, or a journal extent.
: _EXT4-VALIDATE-INODE-TABLE-HOME  ( home owner-group ctx -- ior )
    _EXT4-MTH-CTX ! _EXT4-MTH-OWNER ! _EXT4-MTH-HOME !
    _EXT4-MTH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MTH-OWNER @
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MTH-FOUND !
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MTH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            I _EXT4-MTH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MTH-FOUND +!
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MTH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MTH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MTH-BASE !
            1 _EXT4-MTH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MTH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MTH-COUNT !
            _EXT4-MTH-HOME @ 1
            _EXT4-MTH-BASE @ _EXT4-MTH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MTH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-FRS-FIRST
VARIABLE _EXT4-FRS-COUNT
VARIABLE _EXT4-FRS-CTX
VARIABLE _EXT4-FRS-GROUP
VARIABLE _EXT4-FRS-BASE
VARIABLE _EXT4-FRS-META-COUNT

\ Reject every journal or descriptor/geometry-authenticated static metadata
\ overlap before a mutation changes any transaction-owned after-image.
\ flex_bg means a group's bitmap/table may reside outside that group's nominal
\ interval, so the complete descriptor set is authoritative here.
: _EXT4-VALIDATE-MUTATION-RANGE-TARGETS  ( first count ctx -- ior )
    _EXT4-FRS-CTX ! _EXT4-FRS-COUNT ! _EXT4-FRS-FIRST !
    _EXT4-FRS-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-CTX @ _EXT4-C.FIRST + @ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
    _EXT4-FRS-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-FRS-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-FRS-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-FRS-GROUP !
        I _EXT4-FRS-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-GROUP @ _EXT4-SPARSE-GROUP? IF
            _EXT4-FRS-GROUP @ _EXT4-FRS-CTX @ _EXT4-C.BPG + @ *
            _EXT4-FRS-CTX @ _EXT4-C.FIRST + @ + _EXT4-FRS-BASE !
            1
            _EXT4-FRS-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-FRS-CTX @ _EXT4-C.SB + _EXT4-SB.RESERVED-GDT + W@ +
            _EXT4-FRS-META-COUNT !
            _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
            _EXT4-FRS-BASE @ _EXT4-FRS-META-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    0 ;

VARIABLE _EXT4-FRV-RANGES
VARIABLE _EXT4-FRV-RANGE-COUNT
VARIABLE _EXT4-FRV-RANGE-CAP
VARIABLE _EXT4-FRV-RANGE-INDEX
VARIABLE _EXT4-FRV-CTX
VARIABLE _EXT4-FRV-GROUP
VARIABLE _EXT4-FRV-BASE
VARIABLE _EXT4-FRV-META-COUNT
VARIABLE _EXT4-FRV-QUERY-FIRST
VARIABLE _EXT4-FRV-QUERY-COUNT

: _EXT4-FRV-RANGE  ( index -- pair-address )
    2* CELLS _EXT4-FRV-RANGES @ + ;

: _EXT4-FRV-RANGES-ALIAS?  ( first count -- flag )
    _EXT4-FRV-QUERY-COUNT ! _EXT4-FRV-QUERY-FIRST !
    _EXT4-FRV-QUERY-COUNT @ 0= IF TRUE EXIT THEN
    _EXT4-FRV-RANGE-COUNT @ DUP 0=
    SWAP 0< OR _EXT4-FRV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-FRV-RANGE-COUNT @ _EXT4-FRV-RANGE-CAP @ U> OR IF
        TRUE EXIT
    THEN
    _EXT4-FRV-RANGE-COUNT @ 0 ?DO
        I _EXT4-FRV-RANGE DUP @ SWAP CELL+ @
        DUP 0= IF 2DROP TRUE UNLOOP EXIT THEN
        _EXT4-FRV-QUERY-FIRST @ _EXT4-FRV-QUERY-COUNT @
        _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE UNLOOP EXIT THEN
    LOOP
    FALSE ;

\ Validate a complete inline extent vector without repeating geometry work
\ for each member.  Bounds and journal separation remain exact per range;
\ primary mutation homes and the flex_bg descriptor set are authenticated
\ once, then every static metadata interval is compared with every pair.
: _EXT4-VALIDATE-MUTATION-RANGES-TARGETS
  ( ranges range-count capacity ctx -- ior )
    _EXT4-FRV-CTX ! _EXT4-FRV-RANGE-CAP !
    _EXT4-FRV-RANGE-COUNT ! _EXT4-FRV-RANGES !
    _EXT4-FRV-CTX @ 0= _EXT4-FRV-RANGES @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-FRV-RANGE-COUNT @ DUP 0= SWAP 0< OR
    _EXT4-FRV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-FRV-RANGE-COUNT @ _EXT4-FRV-RANGE-CAP @ U> OR IF
        VFS-E-INVALID EXIT
    THEN
    0 _EXT4-FRV-RANGE-INDEX !
    BEGIN
        _EXT4-FRV-RANGE-INDEX @ _EXT4-FRV-RANGE-COUNT @ U<
    WHILE
        _EXT4-FRV-RANGE-INDEX @ _EXT4-FRV-RANGE DUP @
        _EXT4-FRS-FIRST ! CELL+ @ _EXT4-FRS-COUNT !
        _EXT4-FRS-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
        _EXT4-FRS-FIRST @ _EXT4-FRV-CTX @ _EXT4-C.FIRST + @ U< IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRV-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-FRV-CTX @
        _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
        1 _EXT4-FRV-RANGE-INDEX +!
    REPEAT
    _EXT4-FRV-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-FRV-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-FRV-GROUP !
        I _EXT4-FRV-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-FRV-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-FRV-RANGES-ALIAS? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRV-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-FRV-RANGES-ALIAS? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRV-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-FRV-RANGES-ALIAS? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRV-GROUP @ _EXT4-SPARSE-GROUP? IF
            _EXT4-FRV-GROUP @ _EXT4-FRV-CTX @ _EXT4-C.BPG + @ *
            _EXT4-FRV-CTX @ _EXT4-C.FIRST + @ + _EXT4-FRV-BASE !
            1 _EXT4-FRV-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-FRV-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-FRV-META-COUNT !
            _EXT4-FRV-BASE @ _EXT4-FRV-META-COUNT @
            _EXT4-FRV-RANGES-ALIAS? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    0 ;

' _EXT4-VALIDATE-MUTATION-RANGE-TARGETS
_EXT4-MUTATION-ROLE-XT !

\ Authenticate the complete raw modern-slot mutation target without acquiring
\ a transaction image.  The descriptor-wide mutation scan clobbers C.BLOCK,
\ so restore the orphan-file mapping and slot after that scan.  On success the
\ exact physical home, generation, owner, slot, and raw block remain current.
: _EXT4-JOS-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOS-INO !
    _EXT4-JOS-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOS-EA !
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JOS-SLOT !
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-PHYS @ DUP _EXT4-JOS-HOME !
    _EXT4-JOS-EA @ = _EXT4-JOS-EA @ 0<> AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-GEN @ _EXT4-JOS-GEN !
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO !
    _EXT4-JOS-HOME @ 1 _EXT4-JOS-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JOS-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JOS-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Clearing a modern orphan slot mutates an ordinary mapped file block, so its
\ read-side checksum is necessary but not sufficient authority.  Prove the
\ exact physical home is writable non-static storage and disjoint from the
\ target's retained external xattr before publishing its after-image.
: _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
  ( plan-record transaction -- ior )
    _EXT4-JOS-WRITER ! _EXT4-JOS-RECORD !
    _EXT4-JOS-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JOS-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOS-CTX !
    _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-HOME @
    _EXT4-JOS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOS-IMAGE !
    _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L!
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-ORPHAN-INO @
    _EXT4-JOS-GEN @ _EXT4-JOS-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-LBB-GROUP
VARIABLE _EXT4-LBB-CTX
VARIABLE _EXT4-LBB-HOME
VARIABLE _EXT4-LBB-STORED

: _EXT4-LOAD-BLOCK-BITMAP  ( group ctx -- bitmap-home ior )
    _EXT4-LBB-CTX ! DUP _EXT4-LBB-GROUP !
    _EXT4-LBB-GROUP @ _EXT4-LBB-CTX @ _EXT4-LOAD-DESC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
        DROP 0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-LBB-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.BLOCK-BITMAP-LO + L@ DUP _EXT4-LBB-HOME !
    SWAP _EXT4-GD.BLOCK-CSUM-LO + W@
    _EXT4-LBB-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-CSUM-HI + W@
    16 LSHIFT OR _EXT4-LBB-STORED ! DROP
    _EXT4-LBB-HOME @ _EXT4-LBB-CTX @ _EXT4-READ-BLOCK
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-LBB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-LBB-CTX @ _EXT4-C.BLOCK +
    _EXT4-LBB-CTX @ _EXT4-C.BPG + @ 8 / _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ _EXT4-LBB-STORED @ <> IF
        0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-LBB-HOME @ 0 ;

VARIABLE _EXT4-LIB-GROUP
VARIABLE _EXT4-LIB-CTX
VARIABLE _EXT4-LIB-HOME
VARIABLE _EXT4-LIB-STORED

: _EXT4-LOAD-INODE-BITMAP  ( group ctx -- bitmap-home ior )
    _EXT4-LIB-CTX ! DUP _EXT4-LIB-GROUP !
    _EXT4-LIB-GROUP @ _EXT4-LIB-CTX @ _EXT4-LOAD-DESC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF
        DROP 0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-LIB-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.INODE-BITMAP-LO + L@ DUP _EXT4-LIB-HOME !
    SWAP _EXT4-GD.INODE-CSUM-LO + W@
    _EXT4-LIB-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-CSUM-HI + W@
    16 LSHIFT OR _EXT4-LIB-STORED ! DROP
    _EXT4-LIB-HOME @ _EXT4-LIB-CTX @ _EXT4-READ-BLOCK
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-LIB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-LIB-CTX @ _EXT4-C.BLOCK +
    _EXT4-LIB-CTX @ _EXT4-C.IPG + @ 8 / _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ _EXT4-LIB-STORED @ <> IF
        0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-LIB-HOME @ 0 ;

VARIABLE _EXT4-BBC-BUFFER
VARIABLE _EXT4-BBC-CTX

: _EXT4-BLOCK-BITMAP-CRC  ( bitmap ctx -- crc ior )
    _EXT4-BBC-CTX ! _EXT4-BBC-BUFFER !
    _EXT4-BBC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-BBC-BUFFER @ _EXT4-BBC-CTX @ _EXT4-C.BPG + @ 8 /
    _EXT4-CRC-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

VARIABLE _EXT4-IBC-BUFFER
VARIABLE _EXT4-IBC-CTX

: _EXT4-INODE-BITMAP-CRC  ( bitmap ctx -- crc ior )
    _EXT4-IBC-CTX ! _EXT4-IBC-BUFFER !
    _EXT4-IBC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-IBC-BUFFER @ _EXT4-IBC-CTX @ _EXT4-C.IPG + @ 8 /
    _EXT4-CRC-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

VARIABLE _EXT4-BRS-BUFFER
VARIABLE _EXT4-BRS-FIRST
VARIABLE _EXT4-BRS-COUNT
VARIABLE _EXT4-BRS-BIT
VARIABLE _EXT4-BRS-ADDR

: _EXT4-BIT-RANGE-SET?  ( bitmap first-bit count -- flag )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP 8 /
        _EXT4-BRS-BUFFER @ + C@
        1 ROT 8 MOD LSHIFT AND 0= IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

: _EXT4-BIT-RANGE-CLEAR?  ( bitmap first-bit count -- flag )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP 8 /
        _EXT4-BRS-BUFFER @ + C@
        1 ROT 8 MOD LSHIFT AND IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

: _EXT4-CLEAR-BIT-RANGE  ( bitmap first-bit count -- )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP _EXT4-BRS-BIT ! 8 /
        _EXT4-BRS-BUFFER @ + DUP _EXT4-BRS-ADDR ! C@
        1 _EXT4-BRS-BIT @ 8 MOD LSHIFT INVERT AND
        _EXT4-BRS-ADDR @ C!
    LOOP ;

: _EXT4-SET-BIT-RANGE  ( bitmap first-bit count -- )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP _EXT4-BRS-BIT ! 8 /
        _EXT4-BRS-BUFFER @ + DUP _EXT4-BRS-ADDR ! C@
        1 _EXT4-BRS-BIT @ 8 MOD LSHIFT OR
        _EXT4-BRS-ADDR @ C!
    LOOP ;

VARIABLE _EXT4-JPS-WRITER
VARIABLE _EXT4-JPS-CTX
VARIABLE _EXT4-JPS-HOME
VARIABLE _EXT4-JPS-OFF
VARIABLE _EXT4-JPS-RAW
VARIABLE _EXT4-JPS-RAW-CRC
VARIABLE _EXT4-JPS-IMAGE
VARIABLE _EXT4-JPS-SUPER

\ Return a private editing copy of the primary-super block, composing with an
\ earlier transaction after-image when one exists.  Both the raw source and
\ the effective image are authenticated before the caller may edit mutable
\ fields; this is the common authority used by allocation accounting and by
\ the legacy-orphan head transition.
: _EXT4-JTX-ACQUIRE-PRIMARY-SUPER
  ( transaction -- ior )
    0 _EXT4-JPS-HOME ! 0 _EXT4-JPS-OFF ! 0 _EXT4-JPS-RAW !
    0 _EXT4-JPS-RAW-CRC ! 0 _EXT4-JPS-IMAGE ! 0 _EXT4-JPS-SUPER !
    DUP _EXT4-JPS-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JPS-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JPS-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP _EXT4-JPS-HOME !
    _EXT4-JPS-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-OFF DUP _EXT4-JPS-OFF !
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + + _EXT4-JPS-RAW !
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-C.SB + 1024
    _EXT4-BYTES=? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SB.CHECKSUM + L@ _EXT4-JPS-RAW-CRC !
    _EXT4-JPS-RAW @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + _EXT4-JPS-HOME @
    _EXT4-JPS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JPS-IMAGE !
    _EXT4-JPS-IMAGE @ _EXT4-JPS-OFF @ + _EXT4-JPS-SUPER !
    _EXT4-JPS-SUPER @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-JPS-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JFB-FIRST
VARIABLE _EXT4-JFB-COUNT
VARIABLE _EXT4-JFB-WRITER
VARIABLE _EXT4-JFB-CTX
VARIABLE _EXT4-JFB-CURRENT
VARIABLE _EXT4-JFB-REMAIN
VARIABLE _EXT4-JFB-GROUP
VARIABLE _EXT4-JFB-INDEX
VARIABLE _EXT4-JFB-CHUNK
VARIABLE _EXT4-JFB-GROUP-BLOCKS
VARIABLE _EXT4-JFB-BITMAP-HOME
VARIABLE _EXT4-JFB-GDT-HOME
VARIABLE _EXT4-JFB-GDT-OFF
VARIABLE _EXT4-JFB-IMAGE
VARIABLE _EXT4-JFB-DESC
VARIABLE _EXT4-JFB-BITMAP-CRC
VARIABLE _EXT4-JFB-NEW-BITMAP-CRC
VARIABLE _EXT4-JFB-FREE
VARIABLE _EXT4-JFB-NEW-FREE
VARIABLE _EXT4-JFB-SUPER-HOME
VARIABLE _EXT4-JFB-SUPER
VARIABLE _EXT4-JFB-IOR
VARIABLE _EXT4-JFB-PUBLISHED
VARIABLE _EXT4-JFB-ABORT-IOR

\ Once this operation publishes its first complete metadata image, any later
\ failure is transaction-fatal.  Abort immediately so a caller cannot emit a
\ descriptor/bitmap prefix without the matching aggregate superblock update.
\ If local abort invariants themselves fail, latch an explicit faulted state.
: _EXT4-JFB-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFB-IOR !
    _EXT4-JFB-PUBLISHED @ IF
        _EXT4-JFB-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFB-ABORT-IOR ! IF
            _EXT4-JFB-ABORT-IOR @
            _EXT4-JFB-WRITER @ _EXT4-JWR.FAULT + !
            _EXT4-JWR-FAULTED
            _EXT4-JFB-WRITER @ _EXT4-JWR.STATE + !
        THEN
    THEN
    _EXT4-JFB-IOR @ ;

: _EXT4-JFB-RESET-WALK  ( -- )
    _EXT4-JFB-FIRST @ _EXT4-JFB-CURRENT !
    _EXT4-JFB-COUNT @ _EXT4-JFB-REMAIN ! ;

: _EXT4-JFB-NEXT-CHUNK  ( -- ior )
    _EXT4-JFB-CURRENT @ _EXT4-JFB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JFB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JFB-GROUP ! _EXT4-JFB-INDEX !
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFB-GROUP-BLOCKS !
    _EXT4-JFB-INDEX @ _EXT4-JFB-GROUP-BLOCKS @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-GROUP-BLOCKS @ _EXT4-JFB-INDEX @ -
    _EXT4-JFB-REMAIN @ MIN DUP 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFB-CHUNK !
    0 ;

: _EXT4-JFB-ADVANCE  ( -- )
    _EXT4-JFB-CHUNK @ DUP _EXT4-JFB-CURRENT +!
    NEGATE _EXT4-JFB-REMAIN +! ;

: _EXT4-JFB-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.BLOCK-CSUM-LO + W@
    SWAP _EXT4-GD.BLOCK-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE@  ( descriptor -- blocks )
    DUP _EXT4-GD.FREE-BLOCKS-LO + W@
    SWAP _EXT4-GD.FREE-BLOCKS-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE!  ( blocks descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-BLOCKS-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-BLOCKS-HI + W! ;

: _EXT4-JFB-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.BLOCK-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.BLOCK-CSUM-HI + W! ;

: _EXT4-JFB-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-BLOCK-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-BITMAP-CRC@
    _EXT4-JFB-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE@ DUP _EXT4-JFB-FREE !
    _EXT4-JFB-CHUNK @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    _EXT4-JFB-GROUP-BLOCKS @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ DUP _EXT4-JFB-GDT-HOME !
    _EXT4-JFB-BITMAP-HOME @ = IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-OFF @ _EXT4-JFB-GDT-OFF !
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-GDT-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-GDT-OFF @ + _EXT4-JFB-DESC !
    _EXT4-JFB-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFB-PREFLIGHT-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    \ The anti-alias scan leaves the descriptor table in C.BLOCK; restore and
    \ reauthenticate the actual bitmap before consulting any allocation bit.
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR !
    _EXT4-JFB-IOR @ IF DROP _EXT4-JFB-IOR @ EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ;

\ A vector caller has already proved this touched group's raw bitmap home
\ unique and disjoint from every static role.  Reload that raw home, then keep
\ the scalar allocation, retained-image, effective-descriptor, and checksum
\ checks intact for the exact member being staged.
: _EXT4-JFB-PREFLIGHT-GROUP-AFTER-HOME  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ;

: _EXT4-JFB-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFB-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFB-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFB-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFB-IMAGE !
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFB-COUNT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    DUP 0xFFFFFFFF U>
    SWAP _EXT4-JFB-CTX @ _EXT4-C.BLOCKS + @ U> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-PREFLIGHT-AFTER-TARGETS  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-PREFLIGHT-GROUP ?DUP IF EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-ACQUIRE-SUPER ;

: _EXT4-JFB-PREFLIGHT-AFTER-VECTOR-TARGETS  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-PREFLIGHT-GROUP-AFTER-HOME ?DUP IF EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-ACQUIRE-SUPER ;

: _EXT4-JFB-PREFLIGHT  ( -- ior )
    _EXT4-JFB-FIRST @ _EXT4-JFB-COUNT @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JFB-PREFLIGHT-AFTER-TARGETS ;

: _EXT4-JFB-STAGE-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    DUP _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-NEW-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @ _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JFB-NEW-BITMAP-CRC @ _EXT4-JFB-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-GDT-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

: _EXT4-JFB-STAGE-SUPER  ( -- ior )
    _EXT4-JFB-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JFB-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-SUPER-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

: _EXT4-JFB-STAGE-PREFLIGHTED  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-STAGE-GROUP ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-STAGE-SUPER ?DUP IF
        _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ Stage only allocation accounting for a nonempty physical block range.  The
\ caller still owns map removal, i_blocks changes, and any metadata revoke.
\ All semantic checks finish before the first table replacement.  A later
\ internal credit/conflict failure automatically aborts the whole transaction
\ so no partial accounting prefix remains eligible for emission.
: _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
  ( first-block count transaction -- ior )
    _EXT4-JFB-WRITER ! _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    0 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFB-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFB-CTX !
    _EXT4-JFB-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFB-STAGE-PREFLIGHTED ;

: _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS
  ( first-block count transaction -- ior )
    _EXT4-JFB-WRITER ! _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    0 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFB-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFB-CTX !
    _EXT4-JFB-PREFLIGHT-AFTER-VECTOR-TARGETS ?DUP IF EXIT THEN
    _EXT4-JFB-STAGE-PREFLIGHTED ;

VARIABLE _EXT4-JBV-RANGES
VARIABLE _EXT4-JBV-RANGE-COUNT
VARIABLE _EXT4-JBV-RANGE-CAP
VARIABLE _EXT4-JBV-RANGE-INDEX
VARIABLE _EXT4-JBV-WRITER
VARIABLE _EXT4-JBV-CTX
VARIABLE _EXT4-JBV-GROUP
VARIABLE _EXT4-JBV-GROUP-FIRST
VARIABLE _EXT4-JBV-GROUP-COUNT
VARIABLE _EXT4-JBV-BITMAP-HOME
VARIABLE _EXT4-JBV-IOR
VARIABLE _EXT4-JBV-RUN-FIRST
VARIABLE _EXT4-JBV-RUN-COUNT
VARIABLE _EXT4-JBV-NEXT-FIRST
VARIABLE _EXT4-JBV-NEXT-COUNT

: _EXT4-JBV-VALIDATE-BITMAP-HOMES  ( -- ior )
    _EXT4-JBV-RANGES @ _EXT4-FRV-RANGES !
    _EXT4-JBV-RANGE-COUNT @ _EXT4-FRV-RANGE-COUNT !
    _EXT4-JBV-RANGE-CAP @ _EXT4-FRV-RANGE-CAP !
    0 _EXT4-JBV-GROUP !
    BEGIN
        _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @ _EXT4-GROUP-BLOCK-RANGE
        _EXT4-JBV-IOR ! _EXT4-JBV-GROUP-COUNT !
        _EXT4-JBV-GROUP-FIRST !
        _EXT4-JBV-IOR @ ?DUP IF EXIT THEN
        _EXT4-JBV-GROUP-FIRST @ _EXT4-JBV-GROUP-COUNT @
        _EXT4-FRV-RANGES-ALIAS? IF
            _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @
            _EXT4-LOAD-BLOCK-BITMAP
            _EXT4-JBV-IOR ! _EXT4-JBV-BITMAP-HOME !
            _EXT4-JBV-IOR @ ?DUP IF EXIT THEN
            _EXT4-JBV-BITMAP-HOME @ _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @
            _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
        THEN
        1 _EXT4-JBV-GROUP +!
    REPEAT
    0 ;

\ Private exact-vector entry point for plan-bound cleanup.  The complete
\ caller-supplied vector remains the authority proved above and retained in
\ the orphan certificate/checkpoint plan.  Adjacent physical members may use
\ one allocation-accounting run: clearing the same set of bits and applying
\ their summed counters does not weaken or rewrite that exact authority, and
\ avoids repeatedly checksumming the same bitmap, descriptor, and superblock.
: _EXT4-JTX-STAGE-FREE-BLOCK-RANGES
  ( ranges range-count capacity transaction -- ior )
    _EXT4-JBV-WRITER ! _EXT4-JBV-RANGE-CAP !
    _EXT4-JBV-RANGE-COUNT ! _EXT4-JBV-RANGES !
    _EXT4-JBV-RANGES @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JBV-RANGE-COUNT @ DUP 0= SWAP 0< OR
    _EXT4-JBV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-JBV-RANGE-COUNT @ _EXT4-JBV-RANGE-CAP @ U> OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JBV-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JBV-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JBV-CTX ! DROP
    _EXT4-JBV-RANGES @ _EXT4-JBV-RANGE-COUNT @
    _EXT4-JBV-RANGE-CAP @ _EXT4-JBV-CTX @
    _EXT4-VALIDATE-MUTATION-RANGES-TARGETS ?DUP IF EXIT THEN
    _EXT4-JBV-VALIDATE-BITMAP-HOMES ?DUP IF EXIT THEN
    _EXT4-JBV-RANGES @ DUP @ _EXT4-JBV-RUN-FIRST !
    CELL+ @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    _EXT4-JBV-RUN-COUNT !
    1 _EXT4-JBV-RANGE-INDEX !
    BEGIN
        _EXT4-JBV-RANGE-INDEX @ _EXT4-JBV-RANGE-COUNT @ U<
    WHILE
        _EXT4-JBV-RANGE-INDEX @ 2* CELLS _EXT4-JBV-RANGES @ +
        DUP @ _EXT4-JBV-NEXT-FIRST !
        CELL+ @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
        _EXT4-JBV-NEXT-COUNT !
        _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @ _EXT4-UADD?
        DUP IF NIP EXIT THEN DROP
        _EXT4-JBV-NEXT-FIRST @ = IF
            _EXT4-JBV-RUN-COUNT @ _EXT4-JBV-NEXT-COUNT @ _EXT4-UADD?
            DUP IF NIP EXIT THEN DROP _EXT4-JBV-RUN-COUNT !
        ELSE
            _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @
            _EXT4-JBV-WRITER @
            _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS
            ?DUP IF EXIT THEN
            _EXT4-JBV-NEXT-FIRST @ _EXT4-JBV-RUN-FIRST !
            _EXT4-JBV-NEXT-COUNT @ _EXT4-JBV-RUN-COUNT !
        THEN
        1 _EXT4-JBV-RANGE-INDEX +!
    REPEAT
    _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @ _EXT4-JBV-WRITER @
    _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS ;

\ =====================================================================
\  Exact one-block allocation accounting
\ =====================================================================

VARIABLE _EXT4-JAB-BLOCK
VARIABLE _EXT4-JAB-WRITER
VARIABLE _EXT4-JAB-CTX
VARIABLE _EXT4-JAB-GROUP
VARIABLE _EXT4-JAB-INDEX
VARIABLE _EXT4-JAB-GROUP-BLOCKS
VARIABLE _EXT4-JAB-BITMAP-HOME
VARIABLE _EXT4-JAB-GDT-HOME
VARIABLE _EXT4-JAB-GDT-OFF
VARIABLE _EXT4-JAB-IMAGE
VARIABLE _EXT4-JAB-DESC
VARIABLE _EXT4-JAB-BITMAP-CRC
VARIABLE _EXT4-JAB-NEW-BITMAP-CRC
VARIABLE _EXT4-JAB-GROUP-FREE
VARIABLE _EXT4-JAB-NEW-GROUP-FREE
VARIABLE _EXT4-JAB-SUPER-HOME
VARIABLE _EXT4-JAB-SUPER
VARIABLE _EXT4-JAB-NEW-SUPER-FREE
VARIABLE _EXT4-JAB-IOR
VARIABLE _EXT4-JAB-PUBLISHED
VARIABLE _EXT4-JAB-ABORT-IOR

\ Allocation accounting is an all-or-abort typed edit.  Once its first
\ complete after-image is retained, no caller may emit a bitmap/GDT/super
\ prefix after a later local failure.
: _EXT4-JAB-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JAB-IOR !
    _EXT4-JAB-PUBLISHED @ IF
        _EXT4-JAB-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JAB-ABORT-IOR ! IF
            _EXT4-JAB-ABORT-IOR @
            _EXT4-JAB-WRITER @ _EXT4-JWR.FAULT + !
            _EXT4-JWR-FAULTED
            _EXT4-JAB-WRITER @ _EXT4-JWR.STATE + !
        THEN
    THEN
    _EXT4-JAB-IOR @ ;

: _EXT4-JAB-LOCATE  ( -- ior )
    _EXT4-JAB-BLOCK @ _EXT4-JAB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JAB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JAB-GROUP ! _EXT4-JAB-INDEX !
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JAB-GROUP-BLOCKS !
    _EXT4-JAB-INDEX @ _EXT4-JAB-GROUP-BLOCKS @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JAB-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JAB-DESC @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-BLOCK-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JAB-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-JFB-DESC-BITMAP-CRC@
    _EXT4-JAB-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-JFB-DESC-FREE@
    DUP _EXT4-JAB-GROUP-FREE ! DUP 0= IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JAB-GROUP-BLOCKS @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    1- _EXT4-JAB-NEW-GROUP-FREE !
    0 ;

: _EXT4-JAB-ACQUIRE-DESC  ( -- ior )
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ DUP _EXT4-JAB-GDT-HOME !
    _EXT4-JAB-BITMAP-HOME @ = IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-OFF @ _EXT4-JAB-GDT-OFF !
    _EXT4-JAB-CTX @ _EXT4-C.BLOCK + _EXT4-JAB-GDT-HOME @
    _EXT4-JAB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JAB-IMAGE !
    _EXT4-JAB-GDT-OFF @ + _EXT4-JAB-DESC !
    _EXT4-JAB-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JAB-ACQUIRE-BITMAP  ( -- ior )
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JAB-IOR ! _EXT4-JAB-BITMAP-HOME !
    _EXT4-JAB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    \ The descriptor-wide home proof reused C.BLOCK.  Reload the exact raw
    \ bitmap and require both raw and retained views to keep the bit clear.
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JAB-IOR !
    _EXT4-JAB-IOR @ IF DROP _EXT4-JAB-IOR @ EXIT THEN
    _EXT4-JAB-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JAB-INDEX @ 1 _EXT4-BIT-RANGE-CLEAR? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-CTX @ _EXT4-C.BLOCK + _EXT4-JAB-BITMAP-HOME @
    _EXT4-JAB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JAB-IMAGE !
    _EXT4-JAB-INDEX @ 1 _EXT4-BIT-RANGE-CLEAR? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JAB-IMAGE @ _EXT4-JAB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JAB-BITMAP-CRC !
    0 ;

: _EXT4-JAB-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JAB-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JAB-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JAB-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JAB-IMAGE !
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    DUP 0= IF DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JAB-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    1- _EXT4-JAB-NEW-SUPER-FREE !
    0 ;

: _EXT4-JAB-PREFLIGHT  ( -- ior )
    _EXT4-JAB-LOCATE ?DUP IF EXIT THEN
    _EXT4-JAB-BLOCK @ 1 _EXT4-JAB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-SUPER ;

: _EXT4-JAB-STAGE-GROUP  ( -- ior )
    _EXT4-JAB-ACQUIRE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JAB-IMAGE @
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-INDEX @ 1 _EXT4-SET-BIT-RANGE
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JAB-NEW-BITMAP-CRC !
    _EXT4-JAB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-GROUP-FREE @
    _EXT4-JAB-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JAB-NEW-BITMAP-CRC @ _EXT4-JAB-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JAB-DESC @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    \ Retain homes in bitmap/GDT order.  This order is not a crash-safety
    \ dependency, but gives checkpoint qualification a deterministic role
    \ sequence for the new allocation topology.
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    _EXT4-JAB-IMAGE @ _EXT4-JAB-GDT-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    0 ;

: _EXT4-JAB-STAGE-SUPER  ( -- ior )
    _EXT4-JAB-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-SUPER-FREE @
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JAB-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JAB-IMAGE @ _EXT4-JAB-SUPER-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    0 ;

\ Stage allocation accounting for one exact, already owner-proved free data
\ block.  The caller still owns candidate selection, complete reverse-owner
\ proof, initialized ordered data, map insertion, and i_blocks.  This word
\ updates exactly the block bitmap, its primary descriptor, and the primary
\ superblock; it neither emits nor checkpoints the transaction.
: _EXT4-JTX-STAGE-ALLOCATE-BLOCK  ( physical-block transaction -- ior )
    _EXT4-JAB-WRITER ! _EXT4-JAB-BLOCK !
    0 _EXT4-JAB-PUBLISHED !
    _EXT4-JAB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JAB-CTX !
    _EXT4-JAB-BLOCK @ _EXT4-JAB-CTX @ _EXT4-C.FIRST + @ U<
    _EXT4-JAB-BLOCK @ _EXT4-JAB-CTX @ _EXT4-C.BLOCKS + @ U< 0= OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JAB-STAGE-GROUP ?DUP IF
        _EXT4-JAB-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JAB-STAGE-SUPER ?DUP IF
        _EXT4-JAB-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

VARIABLE _EXT4-FFB-GOAL
VARIABLE _EXT4-FFB-CTX
VARIABLE _EXT4-FFB-GROUP
VARIABLE _EXT4-FFB-VISITED
VARIABLE _EXT4-FFB-GROUP-BLOCKS
VARIABLE _EXT4-FFB-GROUP-FREE
VARIABLE _EXT4-FFB-BITMAP-HOME
VARIABLE _EXT4-FFB-INDEX
VARIABLE _EXT4-FFB-FIRST-CLEAR
VARIABLE _EXT4-FFB-CLEAR-COUNT
VARIABLE _EXT4-FFB-BLOCK
VARIABLE _EXT4-FFB-FOUND
VARIABLE _EXT4-FFB-IOR
VARIABLE _EXT4-FFB-SAW-UNINIT
VARIABLE _EXT4-FFB-EXCLUDE
VARIABLE _EXT4-FFB-EXCLUDE-GROUP
VARIABLE _EXT4-FFB-EXCLUDE-INDEX
VARIABLE _EXT4-FFB-EXCLUDE-ACTIVE

: _EXT4-FFB-ADVANCE-GROUP  ( -- )
    1 _EXT4-FFB-GROUP +!
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-C.GROUPS + @ = IF
        0 _EXT4-FFB-GROUP !
    THEN
    1 _EXT4-FFB-VISITED +! ;

: _EXT4-FFB-SCAN-BITMAP  ( -- ior )
    -1 _EXT4-FFB-FIRST-CLEAR !
    0 _EXT4-FFB-CLEAR-COUNT !
    0 _EXT4-FFB-INDEX !
    BEGIN
        _EXT4-FFB-INDEX @ _EXT4-FFB-GROUP-BLOCKS @ U<
    WHILE
        _EXT4-FFB-CTX @ _EXT4-C.BLOCK +
        _EXT4-FFB-INDEX @ 1 _EXT4-BIT-RANGE-CLEAR? IF
            _EXT4-FFB-FIRST-CLEAR @ -1 = IF
                _EXT4-FFB-EXCLUDE-ACTIVE @ 0=
                _EXT4-FFB-GROUP @ _EXT4-FFB-EXCLUDE-GROUP @ <> OR
                _EXT4-FFB-INDEX @ _EXT4-FFB-EXCLUDE-INDEX @ <> OR IF
                    _EXT4-FFB-INDEX @ _EXT4-FFB-FIRST-CLEAR !
                THEN
            THEN
            1 _EXT4-FFB-CLEAR-COUNT +!
        THEN
        1 _EXT4-FFB-INDEX +!
    REPEAT
    _EXT4-FFB-CLEAR-COUNT @ _EXT4-FFB-GROUP-FREE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-FFB-BUILD-PHYSICAL  ( -- ior )
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-C.BPG + @ _EXT4-UMUL?
    _EXT4-FFB-IOR ! _EXT4-FFB-BLOCK !
    _EXT4-FFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-FFB-BLOCK @ _EXT4-FFB-CTX @ _EXT4-C.FIRST + @ _EXT4-UADD?
    _EXT4-FFB-IOR ! _EXT4-FFB-BLOCK !
    _EXT4-FFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-FFB-BLOCK @ _EXT4-FFB-FIRST-CLEAR @ _EXT4-UADD?
    _EXT4-FFB-IOR ! _EXT4-FFB-BLOCK !
    _EXT4-FFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-FFB-BLOCK @ _EXT4-FFB-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-FFB-REQUIRE-SAME-CLEAR-BIT  ( -- ior )
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-FFB-IOR !
    _EXT4-FFB-IOR @ IF DROP _EXT4-FFB-IOR @ EXIT THEN
    _EXT4-FFB-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-FFB-FIRST-CLEAR @ 1 _EXT4-BIT-RANGE-CLEAR? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

: _EXT4-FFB-SCAN-GROUP  ( -- physical found? ior )
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    _EXT4-FFB-IOR ! _EXT4-FFB-GROUP-BLOCKS !
    _EXT4-FFB-IOR @ ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-LOAD-DESC
    ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-CTX @ _EXT4-C.DESC + _EXT4-JFB-DESC-FREE@
    DUP _EXT4-FFB-GROUP-FREE !
    _EXT4-FFB-GROUP-BLOCKS @ U> IF
        0 FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
        _EXT4-FFB-GROUP-FREE @ IF -1 _EXT4-FFB-SAW-UNINIT ! THEN
        0 FALSE 0 EXIT
    THEN
    _EXT4-FFB-GROUP @ _EXT4-FFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-FFB-IOR ! _EXT4-FFB-BITMAP-HOME !
    _EXT4-FFB-IOR @ ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-SCAN-BITMAP ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-FIRST-CLEAR @ -1 = IF 0 FALSE 0 EXIT THEN
    _EXT4-FFB-BUILD-PHYSICAL ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-BLOCK @ 1 _EXT4-FFB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS
    ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-REQUIRE-SAME-CLEAR-BIT ?DUP IF 0 FALSE ROT EXIT THEN
    _EXT4-FFB-BLOCK @ TRUE 0 ;

\ Search every authenticated initialized group exactly once, beginning with
\ the caller's locality goal and wrapping through runtime group geometry.
\ Bitmap free-bit counts must exactly match their descriptor counters.  Lazy
\ BLOCK_UNINIT groups are skipped rather than initialized implicitly; if they
\ are the only advertised free space, the current allocation capability is a
\ stable unsupported result rather than a fabricated disk-full condition.
: _EXT4-FFB-FIND  ( -- physical-block ior )
    _EXT4-FFB-CTX @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-FFB-GOAL @ 0<
    _EXT4-FFB-GOAL @ _EXT4-FFB-CTX @ _EXT4-C.GROUPS + @ U< 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-FFB-CTX @ _EXT4-C.FREE-BLOCKS + @ 0= IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-FFB-GOAL @ _EXT4-FFB-GROUP !
    0 _EXT4-FFB-VISITED !
    0 _EXT4-FFB-SAW-UNINIT !
    BEGIN
        _EXT4-FFB-VISITED @ _EXT4-FFB-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-FFB-SCAN-GROUP
        _EXT4-FFB-IOR ! _EXT4-FFB-FOUND ! _EXT4-FFB-BLOCK !
        _EXT4-FFB-IOR @ ?DUP IF 0 SWAP EXIT THEN
        _EXT4-FFB-FOUND @ IF _EXT4-FFB-BLOCK @ 0 EXIT THEN
        _EXT4-FFB-ADVANCE-GROUP
    REPEAT
    _EXT4-FFB-SAW-UNINIT @ IF
        0 EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-FFB-EXCLUDE-ACTIVE @ IF 0 VFS-E-NOSPC EXIT THEN
    0 EXT4-D-GEOMETRY _EXT4-CORRUPT ;

: _EXT4-FIND-FREE-BLOCK  ( goal-group ctx -- physical-block ior )
    _EXT4-FFB-CTX ! _EXT4-FFB-GOAL !
    0 _EXT4-FFB-EXCLUDE-ACTIVE !
    0 _EXT4-FFB-EXCLUDE !
    0 _EXT4-FFB-EXCLUDE-GROUP !
    0 _EXT4-FFB-EXCLUDE-INDEX !
    _EXT4-FFB-FIND ;

\ Select a second free block from the same geometry walk without pretending
\ that the first planned allocation is already present in the raw bitmap.
\ The excluded singleton is still included in the authenticated free-count
\ comparison; only candidate publication skips it.  If it is the sole usable
\ initialized free block, the two-block operation has a stable NOSPC result.
: _EXT4-FIND-FREE-BLOCK-EXCLUDING
  ( excluded-block goal-group ctx -- physical-block ior )
    _EXT4-FFB-CTX ! _EXT4-FFB-GOAL ! _EXT4-FFB-EXCLUDE !
    _EXT4-FFB-CTX @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-FFB-EXCLUDE @ _EXT4-FFB-CTX @ _EXT4-C.FIRST + @ U<
    _EXT4-FFB-EXCLUDE @ _EXT4-FFB-CTX @ _EXT4-C.BLOCKS + @ U< 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-FFB-EXCLUDE @ _EXT4-FFB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-FFB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-FFB-EXCLUDE-GROUP ! _EXT4-FFB-EXCLUDE-INDEX !
    -1 _EXT4-FFB-EXCLUDE-ACTIVE !
    _EXT4-FFB-FIND ;

VARIABLE _EXT4-OFR-RECORD
VARIABLE _EXT4-OFR-CTX
VARIABLE _EXT4-OFR-INDEX
VARIABLE _EXT4-OFR-RANGES
VARIABLE _EXT4-OFR-RANGE-COUNT
VARIABLE _EXT4-OFR-RANGE-CAP
VARIABLE _EXT4-OFR-EA
VARIABLE _EXT4-OFR-IOR
VARIABLE _EXT4-OFR-MAP-LIMIT
CREATE _EXT4-OFR-EA-RANGE 2 CELLS ALLOT

\ Prove that no proposed release range names any storage owned by the modern
\ orphan file.  Publish the exact candidate vector while the complete reader
\ validates the orphan inode's extent or legacy map.  The ordinary allocation
\ checks then reject aliases through leaf data, preallocation beyond EOF,
\ external extent nodes, and legacy indirect metadata without flattening that
\ geometry into another fixed table.  Check an external xattr block under the
\ same scope, authenticate every logical orphan-block tail, withdraw the scope
\ on every return, and finally restore the target plan record in C.INODE.

: _EXT4-OFR-FAIL  ( ior -- ior )
    _EXT4-OFR-IOR !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-OFR-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-OFR-IOR @ ;

: _EXT4-OFR-PUBLISH  ( -- ior )
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-OFR-RANGES @ _EXT4-OFR-RANGE-COUNT @
    _EXT4-OFR-RANGE-CAP @ _EXT4-MUTATION-OWNER-RANGES-PUBLISH ;

: _EXT4-OFR-PUBLISH-EA  ( -- ior )
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-OFR-EA @ _EXT4-OFR-EA-RANGE !
    1 _EXT4-OFR-EA-RANGE CELL+ !
    _EXT4-OFR-EA-RANGE 1 1 _EXT4-MUTATION-OWNER-RANGES-PUBLISH ;

: _EXT4-ORPHAN-FILE-RANGES-DISJOINT
  ( ranges range-count capacity plan-record ctx -- ior )
    _EXT4-OFR-CTX ! _EXT4-OFR-RECORD !
    _EXT4-OFR-RANGE-CAP ! _EXT4-OFR-RANGE-COUNT ! _EXT4-OFR-RANGES !
    _EXT4-OFR-CTX @ 0= _EXT4-OFR-RECORD @ 0= OR
    _EXT4-OFR-RANGE-COUNT @ 0< OR _EXT4-OFR-RANGE-CAP @ 0< OR
    _EXT4-OFR-RANGE-COUNT @ _EXT4-OFR-RANGE-CAP @ U> OR
    _EXT4-OFR-RANGE-COUNT @ 0<> _EXT4-OFR-RANGES @ 0= AND OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-OWNER-INO @ OR
    _EXT4-MUTATION-MAP-TARGET @ OR
    _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR
    _EXT4-MUTATION-PROTOCOL-CTX @ OR
    _EXT4-MUTATION-PROTOCOL-ACTIVE @ OR
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR
    _EXT4-MUTATION-EA-REF-HOME @ OR
    _EXT4-MUTATION-EA-REF-HITS @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-OFR-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-OFR-RANGE-COUNT @ IF
        _EXT4-OFR-PUBLISH ?DUP IF _EXT4-OFR-FAIL EXIT THEN
    THEN
    _EXT4-OFR-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF
        _EXT4-OFR-FAIL EXIT
    THEN
    _EXT4-OV-IN @ _EXT4-I.FILE-ACL-HI + W@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT _EXT4-OFR-FAIL EXIT
    THEN
    _EXT4-OV-IN @ _EXT4-I.FILE-ACL-LO + L@ DUP _EXT4-OFR-EA ! IF
        _EXT4-OFR-EA @ EXT4-D-DATA-MAP _EXT4-OFR-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF _EXT4-OFR-FAIL EXIT THEN
    THEN
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _EXT4-OFR-CTX @ _EXT4-XA-SCAN-BOTH
    ?DUP IF _EXT4-OFR-FAIL EXIT THEN
    0 _EXT4-OFR-INDEX !
    BEGIN _EXT4-OFR-INDEX @ _EXT4-OV-BLOCKS @ < WHILE
        _EXT4-OFR-INDEX @ _EXT4-OFR-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF _EXT4-OFR-FAIL EXIT THEN
        1 _EXT4-OFR-INDEX +!
    REPEAT
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    \ The xattr walker authenticates the external block, but that block must
    \ also be disjoint from every data or map-metadata reference owned by the
    \ orphan inode itself.  Check the singleton EA against the complete map in
    \ a separate scope so loading the EA does not reject its own valid owner.
    _EXT4-OFR-EA @ IF
        _EXT4-OFR-PUBLISH-EA ?DUP IF _EXT4-OFR-FAIL EXIT THEN
        _EXT4-OFR-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF
            _EXT4-OFR-FAIL EXIT
        THEN
        _EXT4-MUTATION-OWNER-RANGES-CLEAR
    THEN
    _EXT4-OFR-RECORD @ _EXT4-OFR-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD _EXT4-OFR-IOR !
    _EXT4-OFR-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-OFR-IOR @ ;

\ =====================================================================
\  Plan-bound unlinked inode allocation release
\ =====================================================================

VARIABLE _EXT4-GIC-GROUP
VARIABLE _EXT4-GIC-CTX
VARIABLE _EXT4-GIC-FIRST

: _EXT4-GROUP-INODE-COUNT  ( group ctx -- inodes ior )
    _EXT4-GIC-CTX ! DUP _EXT4-GIC-GROUP !
    _EXT4-GIC-CTX @ 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-GIC-GROUP @
    _EXT4-GIC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        DROP 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-GIC-GROUP @ _EXT4-GIC-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP DUP _EXT4-GIC-FIRST !
    _EXT4-GIC-CTX @ _EXT4-C.INODES + @ U< 0= IF
        0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GIC-CTX @ _EXT4-C.INODES + @ _EXT4-GIC-FIRST @ -
    _EXT4-GIC-CTX @ _EXT4-C.IPG + @ MIN 0 ;

VARIABLE _EXT4-JFI-RECORD
VARIABLE _EXT4-JFI-WRITER
VARIABLE _EXT4-JFI-CTX
VARIABLE _EXT4-JFI-INO
VARIABLE _EXT4-JFI-INODE
VARIABLE _EXT4-JFI-GROUP
VARIABLE _EXT4-JFI-INDEX
VARIABLE _EXT4-JFI-GROUP-INODES
VARIABLE _EXT4-JFI-INODE-TABLE
VARIABLE _EXT4-JFI-INODE-HOME
VARIABLE _EXT4-JFI-INODE-OFF
VARIABLE _EXT4-JFI-BITMAP-HOME
VARIABLE _EXT4-JFI-GDT-HOME
VARIABLE _EXT4-JFI-GDT-OFF
VARIABLE _EXT4-JFI-IMAGE
VARIABLE _EXT4-JFI-DESC
VARIABLE _EXT4-JFI-BITMAP-CRC
VARIABLE _EXT4-JFI-NEW-BITMAP-CRC
VARIABLE _EXT4-JFI-GROUP-FREE
VARIABLE _EXT4-JFI-NEW-GROUP-FREE
VARIABLE _EXT4-JFI-SUPER-HOME
VARIABLE _EXT4-JFI-SUPER
VARIABLE _EXT4-JFI-NEW-SUPER-FREE
VARIABLE _EXT4-JFI-IOR
VARIABLE _EXT4-JFI-PUBLISHED
VARIABLE _EXT4-JFI-ABORT-IOR
VARIABLE _EXT4-JFI-DATA-ENTRIES
VARIABLE _EXT4-JFI-EXTENT-ROOT
VARIABLE _EXT4-JFI-ROOT-ENTRIES
VARIABLE _EXT4-JFI-ROOT-INDEX
VARIABLE _EXT4-JFI-ROOT-ENTRY
VARIABLE _EXT4-JFI-ROOT-KEY
VARIABLE _EXT4-JFI-DATA-ROOT
VARIABLE _EXT4-JFI-DATA-ENTRY
VARIABLE _EXT4-JFI-DATA-BLOCKS
VARIABLE _EXT4-JFI-LEAF-ENTRIES
VARIABLE _EXT4-JFI-LEAF-HOME
VARIABLE _EXT4-JFI-MAP-ENTRIES
VARIABLE _EXT4-JFI-MAP-BLOCKS
VARIABLE _EXT4-JFI-MAP-INDEX
VARIABLE _EXT4-JFI-DATA-MAP-KIND
VARIABLE _EXT4-JFI-DATA-ACTUAL
VARIABLE _EXT4-JFI-DATA-PHYSICAL
VARIABLE _EXT4-JFI-DATA-LOGICAL
VARIABLE _EXT4-JFI-DATA-INDEX
VARIABLE _EXT4-JFI-LEGACY-INDIRECT-HOME
VARIABLE _EXT4-JFI-LEGACY-DOUBLE-HOME
VARIABLE _EXT4-JFI-LEGACY-TRIPLE-HOME
VARIABLE _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME
VARIABLE _EXT4-JFI-LEGACY-DOUBLE-CHILDREN
VARIABLE _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE
VARIABLE _EXT4-JFI-LEGACY-PTRS
VARIABLE _EXT4-JFI-EA
VARIABLE _EXT4-JFI-EA-ACTION
VARIABLE _EXT4-JFI-EA-REFCOUNT
VARIABLE _EXT4-JFI-EA-AFTER-CRC
VARIABLE _EXT4-JFI-EA-AFTER-VERIFIED
VARIABLE _EXT4-JFI-EA-IMAGE
VARIABLE _EXT4-JFI-RANGE-EXPECTED
CREATE _EXT4-JFI-EA-RANGE
2 CELLS ALLOT

: _EXT4-JFI-RANGES  ( -- ranges )
    _EXT4-JFI-CTX @ _EXT4-C.MUTATION-RANGES + @ ;

: _EXT4-JFI-RANGE-CAP  ( -- capacity )
    _EXT4-JFI-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @ ;

: _EXT4-JFI-RANGE  ( index -- pair-address )
    2* CELLS _EXT4-JFI-RANGES + ;

: _EXT4-JFI-MAP-RANGE  ( map-index -- pair-address )
    _EXT4-JFI-DATA-ENTRIES @ + _EXT4-JFI-RANGE ;

: _EXT4-JFI-MAP-SCRATCH-RANGE  ( map-index -- pair-address )
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-MAP-ENTRIES @ - +
    _EXT4-JFI-RANGE ;

: _EXT4-JFI-EA-RELEASE?  ( -- flag )
    _EXT4-JFI-EA-ACTION @ _EXT4-JEA-RELEASE = ;

: _EXT4-JFI-EA-REFDEC?  ( -- flag )
    _EXT4-JFI-EA-ACTION @ _EXT4-JEA-REFDEC = ;

: _EXT4-JFI-RANGE-COUNT  ( -- count )
    _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-MAP-ENTRIES @ + ;

: _EXT4-JFI-RANGE-BLOCKS  ( -- blocks )
    _EXT4-JFI-DATA-BLOCKS @ _EXT4-JFI-MAP-BLOCKS @ + ;

: _EXT4-JFI-OWNER-RANGE-COUNT  ( -- count )
    _EXT4-JFI-RANGE-COUNT
    _EXT4-JFI-EA @ IF 1+ THEN ;

: _EXT4-JFI-RELEASE-RANGE-COUNT  ( -- count )
    _EXT4-JFI-RANGE-COUNT
    _EXT4-JFI-EA-RELEASE? IF 1+ THEN ;

: _EXT4-JFI-RELEASE-RANGE  ( index -- pair-address )
    DUP _EXT4-JFI-RANGE-COUNT U< IF
        _EXT4-JFI-RANGE EXIT
    THEN
    DROP _EXT4-JFI-EA-RANGE ;

: _EXT4-JFI-ACCOUNTED-BLOCKS  ( -- blocks )
    _EXT4-JFI-RANGE-BLOCKS
    _EXT4-JFI-EA @ IF 1+ THEN ;

: _EXT4-JFI-RELEASE-BLOCKS  ( -- blocks )
    _EXT4-JFI-RANGE-BLOCKS
    _EXT4-JFI-EA-RELEASE? IF 1+ THEN ;

: _EXT4-JFI-REVOKE-COUNT  ( -- count )
    _EXT4-JFI-MAP-ENTRIES @
    _EXT4-JFI-EA-RELEASE? IF 1+ THEN ;

VARIABLE _EXT4-JRV-WRITER
VARIABLE _EXT4-JRV-INDEX

\ The map family fixes how many trailing metadata singletons the canonical
\ deletion vector owns.  Keep this typed so a forged generic range count cannot
\ manufacture or suppress revokes.
: _EXT4-JFI-TYPED-MAP-ENTRIES?  ( -- flag )
    _EXT4-JFI-DATA-MAP-KIND @ DUP _EXT4-JDM-DEPTH1-LEAVES = IF
        DROP _EXT4-JFI-MAP-ENTRIES @ DUP 0= SWAP
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR 0= EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SINGLE-INDIRECT = IF
        DROP _EXT4-JFI-MAP-ENTRIES @ 1 = EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-DOUBLE = IF
        DROP _EXT4-JFI-MAP-ENTRIES @ DUP 1 U<
        SWAP _EXT4-JFI-LEGACY-PTRS @ 2 + U> OR 0= EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-TRIPLE = IF
        DROP _EXT4-JFI-MAP-ENTRIES @ 1 =
        _EXT4-JFI-DATA-ENTRIES @
        _EXT4-LEGACY-DIRECT-RANGE-MAX U> 0= AND EXIT
    THEN
    DUP _EXT4-JDM-LEGACY-SPARSE-TRIPLE-CHILD = IF
        DROP _EXT4-JFI-MAP-ENTRIES @ 2 =
        _EXT4-JFI-DATA-ENTRIES @ 0= AND
        _EXT4-JFI-EA @ 0= AND EXIT
    THEN
    DUP _EXT4-JDM-INLINE-EXTENTS =
    SWAP _EXT4-JDM-LEGACY-DIRECT = OR IF
        _EXT4-JFI-MAP-ENTRIES @ 0= EXIT
    THEN
    FALSE ;

\ Prove the exact retained revoke vector in its deterministic insertion order:
\ every admitted map-metadata block in canonical order, then a uniquely
\ released external xattr block.  Ordinary data blocks and shared-xattr
\ decrements are never revoked by orphan cleanup.
: _EXT4-JFI-REVOKES-EXACT?  ( writer -- flag )
    _EXT4-JRV-WRITER !
    _EXT4-JFI-TYPED-MAP-ENTRIES? 0= IF FALSE EXIT THEN
    _EXT4-JFI-EA-RELEASE? _EXT4-JFI-EA @ 0= AND IF FALSE EXIT THEN
    _EXT4-JFI-REVOKE-COUNT
    DUP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        DROP FALSE EXIT
    THEN
    DUP
    _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <>
    OVER _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-USED + @ <> OR
    SWAP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
        FALSE EXIT
    THEN
    0 _EXT4-JRV-INDEX !
    BEGIN
        _EXT4-JRV-INDEX @ _EXT4-JFI-MAP-ENTRIES @ U<
    WHILE
        _EXT4-JRV-INDEX @ _EXT4-JFI-MAP-RANGE DUP
        CELL+ @ 1 <> SWAP @ 0= OR IF FALSE EXIT THEN
        _EXT4-JRV-INDEX @ _EXT4-JRV-WRITER @
        _EXT4-JWR-REVOKE-ENTRY DUP @
        _EXT4-JRV-INDEX @ _EXT4-JFI-MAP-RANGE @ <>
        SWAP CELL+ @ _EXT4-JE-ACTIVE <> OR IF FALSE EXIT THEN
        1 _EXT4-JRV-INDEX +!
    REPEAT
    _EXT4-JFI-EA-RELEASE? IF
        _EXT4-JFI-MAP-ENTRIES @ _EXT4-JRV-WRITER @
        _EXT4-JWR-REVOKE-ENTRY DUP @ _EXT4-JFI-EA @ <>
        SWAP CELL+ @ _EXT4-JE-ACTIVE <> OR IF FALSE EXIT THEN
    THEN
    TRUE ;

VARIABLE _EXT4-JFO-CTX
VARIABLE _EXT4-JFO-RECORD
VARIABLE _EXT4-JFO-TARGET-INO
VARIABLE _EXT4-JFO-GROUP
VARIABLE _EXT4-JFO-GROUP-INODES
VARIABLE _EXT4-JFO-GROUP-BASE
VARIABLE _EXT4-JFO-INO
VARIABLE _EXT4-JFO-INODE
VARIABLE _EXT4-JFO-NLINK
VARIABLE _EXT4-JFO-TYPE
VARIABLE _EXT4-JFO-IOR
VARIABLE _EXT4-JFO-MAP-LIMIT
VARIABLE _EXT4-JFO-INODE-TABLE

VARIABLE _EXT4-JFO-CERT-SCOPE
VARIABLE _EXT4-JFO-CERT-VALID
VARIABLE _EXT4-JFO-CERT-CTX
VARIABLE _EXT4-JFO-CERT-INO
VARIABLE _EXT4-JFO-CERT-GEN
1 CONSTANT _EXT4-JFO-CERT-JFI
2 CONSTANT _EXT4-JFO-CERT-JOT
VARIABLE _EXT4-JFO-CERT-KIND
VARIABLE _EXT4-JFO-CERT-RANGE-COUNT
VARIABLE _EXT4-JFO-CERT-EA
VARIABLE _EXT4-JFO-CERT-EA-ACTION
VARIABLE _EXT4-JFO-CERT-EA-REFCOUNT
VARIABLE _EXT4-JFO-CERT-DATA-MAP-KIND

: _EXT4-JFO-CERT-RANGES  ( -- ranges )
    _EXT4-JFO-CERT-CTX @ _EXT4-C.OWNER-CERT-RANGES + @ ;

: _EXT4-JFO-CERT-RANGE-CAP  ( -- capacity )
    _EXT4-JFO-CERT-CTX @ _EXT4-C.OWNER-CERT-RANGE-CAP + @ ;

: _EXT4-JFO-CERT-RANGE  ( index -- pair-address )
    2 * CELLS _EXT4-JFO-CERT-RANGES + ;

VARIABLE _EXT4-MPH-FIRST
VARIABLE _EXT4-MPH-COUNT
VARIABLE _EXT4-MPH-CTX
VARIABLE _EXT4-MPH-ROOT

\ Activation, emission, checkpoint cleanup, and deactivation may replace the
\ primary superblock and any block in the authenticated journal extent tuple.
\ Test one inode-owned range against that complete protocol-home set without
\ flattening its bounded, possibly discontiguous extents into a fixed table.
: _EXT4-MUTATION-PROTOCOL-HOME-ALIASES?  ( first count ctx -- flag )
    _EXT4-MPH-CTX ! _EXT4-MPH-COUNT ! _EXT4-MPH-FIRST !
    _EXT4-MPH-FIRST @ _EXT4-MPH-COUNT @
    _EXT4-MPH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK 1
    _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE EXIT THEN
    _EXT4-MPH-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB.JOURNAL-BLOCKS + DUP _EXT4-MPH-ROOT !
    2 + W@ 0 ?DO
        _EXT4-MPH-FIRST @ _EXT4-MPH-COUNT @
        _EXT4-MPH-ROOT @ 12 I 12 * + + DUP
        8 + L@ SWAP 4 + W@
        _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE UNLOOP EXIT THEN
    LOOP
    FALSE ;

' _EXT4-MUTATION-PROTOCOL-HOME-ALIASES?
_EXT4-MUTATION-PROTOCOL-XT !

: _EXT4-JFO-CERT-INVALIDATE  ( -- )
    0 _EXT4-JFO-CERT-VALID ! ;

: _EXT4-JFO-CERT-BEGIN  ( -- ior )
    _EXT4-JFO-CERT-SCOPE @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    -1 _EXT4-JFO-CERT-SCOPE !
    0 ;

: _EXT4-JFO-CERT-END  ( -- )
    _EXT4-JFO-CERT-INVALIDATE
    0 _EXT4-JFO-CERT-SCOPE ! ;

: _EXT4-JFO-CERT-MATCH?  ( -- flag )
    _EXT4-JFO-CERT-SCOPE @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-VALID @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-KIND @ _EXT4-JFO-CERT-JFI <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-CTX @ _EXT4-JFI-CTX @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-INO @
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-GEN @
    _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-RANGE-COUNT @ _EXT4-JFI-RANGE-COUNT <> IF
        FALSE EXIT
    THEN
    _EXT4-JFO-CERT-RANGE-COUNT @ _EXT4-JFO-CERT-RANGE-CAP U> IF
        FALSE EXIT
    THEN
    _EXT4-JFO-CERT-EA @ _EXT4-JFI-EA @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-EA-ACTION @
    _EXT4-JFI-EA-ACTION @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-EA-REFCOUNT @
    _EXT4-JFI-EA-REFCOUNT @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-DATA-MAP-KIND @
    _EXT4-JFI-DATA-MAP-KIND @ <> IF FALSE EXIT THEN
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @ I _EXT4-JFO-CERT-RANGE @ <> IF
            FALSE UNLOOP EXIT
        THEN
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFO-CERT-RANGE CELL+ @ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFO-CERT-STORE  ( -- )
    _EXT4-JFO-CERT-SCOPE @ 0= IF EXIT THEN
    0 _EXT4-JFO-CERT-VALID !
    _EXT4-JFI-CTX @ _EXT4-JFO-CERT-CTX !
    _EXT4-JFI-CTX @ _EXT4-OWNER-CERT-RANGE-WORKSPACE? 0= IF EXIT THEN
    _EXT4-JFO-CERT-RANGES 0= IF EXIT THEN
    _EXT4-JFI-RANGE-COUNT _EXT4-JFO-CERT-RANGE-CAP U> IF EXIT THEN
    _EXT4-JFO-CERT-JFI _EXT4-JFO-CERT-KIND !
    0 _EXT4-JFO-CERT-RANGE-COUNT !
    0 _EXT4-JFO-CERT-EA !
    0 _EXT4-JFO-CERT-EA-ACTION !
    0 _EXT4-JFO-CERT-EA-REFCOUNT !
    0 _EXT4-JFO-CERT-DATA-MAP-KIND !
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-CERT-INO !
    _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@ _EXT4-JFO-CERT-GEN !
    _EXT4-JFI-RANGE-COUNT _EXT4-JFO-CERT-RANGE-COUNT !
    _EXT4-JFI-EA @ _EXT4-JFO-CERT-EA !
    _EXT4-JFI-EA-ACTION @ _EXT4-JFO-CERT-EA-ACTION !
    _EXT4-JFI-EA-REFCOUNT @ _EXT4-JFO-CERT-EA-REFCOUNT !
    _EXT4-JFI-DATA-MAP-KIND @ _EXT4-JFO-CERT-DATA-MAP-KIND !
    _EXT4-JFO-CERT-RANGES
    _EXT4-JFO-CERT-RANGE-CAP 2* CELLS 0 FILL
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @ I _EXT4-JFO-CERT-RANGE !
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFO-CERT-RANGE CELL+ !
    LOOP
    -1 _EXT4-JFO-CERT-VALID ! ;

: _EXT4-JFO-REQUIRE-EMPTY-RESERVED  ( -- ior )
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-HI + W@
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-LO + L@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-LO + L@
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-HI + W@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCK + 60 _EXT4-BYTES-ZERO? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ A shared external-xattr proof keeps the candidate home in the ordinary
\ forbidden-owner vector, so every data or map-metadata reference still
\ fails closed.  The inode's single i_file_acl field is the sole semantic
\ exception: authenticate its allocation and count that exact reference.
\ The target inode is excluded from this scan and contributes the initial hit.
: _EXT4-JFO-REQUIRE-XATTR-BLOCK  ( physical-block -- ior )
    DUP _EXT4-MUTATION-EA-REF-HOME @ =
    _EXT4-MUTATION-EA-REF-ACTIVE @ AND IF
        _EXT4-JFO-CTX @ _EXT4-BLOCK-ALLOCATED?
        ?DUP IF NIP EXIT THEN
        0= IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
        _EXT4-MUTATION-EA-REF-HITS @ 1 _EXT4-UADD?
        DUP IF NIP EXIT THEN
        DROP _EXT4-MUTATION-EA-REF-HITS !
        0 EXIT
    THEN
    EXT4-D-DATA-MAP _EXT4-JFO-CTX @ _EXT4-REQUIRE-ALLOCATED-BLOCK ;

\ With the scoped owner target active, ordinary complete map validation turns
\ every reference to the candidate block into a corruption refusal.  Inode 1
\ may own a legacy bad-block map even with mode zero; other mode-zero reserved
\ records must be storage-empty.  Fast symlink and device payload bytes are
\ interpreted by the normal inode validator rather than mistaken for maps.
: _EXT4-JFO-CHECK-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-CTX @ _EXT4-C.INODE + DUP _EXT4-JFO-INODE !
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ ?DUP IF
        _EXT4-JFO-REQUIRE-XATTR-BLOCK ?DUP IF EXIT THEN
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.MODE + W@ 0xF000 AND 0= IF
        _EXT4-JFO-INO @ 1 = IF
            _EXT4-JFO-CTX @ _EXT4-VALIDATE-LEGACY-MAP EXIT
        THEN
        _EXT4-JFO-INO @
        _EXT4-JFO-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFO-REQUIRE-EMPTY-RESERVED EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.LINKS + W@ DUP _EXT4-JFO-NLINK !
    0= IF 1 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W! THEN
    _EXT4-JFO-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JFO-IOR ! _EXT4-JFO-TYPE !
    _EXT4-JFO-NLINK @ 0= IF
        0 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-JFO-IOR @ ;

\ The group bitmap copy is already checksum-authenticated and the caller only
\ reaches this word for a set bit.  Load the record directly from the retained
\ table home, then apply the orphan-aware dtime bound.  This avoids rereading
\ and rechecksumming the same inode bitmap for every allocated inode.
: _EXT4-JFO-LOAD-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-INO @ _EXT4-JFO-CTX @
    _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFO-GROUP @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE-TABLE @ _EXT4-LOAD-INODE-RECORD-RAW ?DUP IF EXIT THEN
    _EXT4-JFO-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
    _EXT4-JFO-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFO-SCAN-GROUP  ( -- ior )
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-DESC ?DUP IF
        EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF 0 EXIT THEN
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-INODES !
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-INODE-BITMAP
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JFO-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFO-INODE-TABLE !
    _EXT4-JFO-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-BASE !
    _EXT4-JFO-GROUP-INODES @ 0 ?DO
        _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK + I 8 / + C@
        1 I 8 MOD LSHIFT AND IF
            _EXT4-JFO-GROUP-BASE @ I + 1+ DUP _EXT4-JFO-INO !
            _EXT4-JFO-TARGET-INO @ <> IF
                _EXT4-JFO-LOAD-CURRENT-INODE ?DUP IF UNLOOP EXIT THEN
                _EXT4-JFO-INO @ _EXT4-MUTATION-OWNER-INO !
                _EXT4-JFO-CHECK-CURRENT-INODE _EXT4-JFO-IOR !
                0 _EXT4-MUTATION-OWNER-INO !
                _EXT4-JFO-IOR @ ?DUP IF UNLOOP EXIT THEN
            THEN
        THEN
    LOOP
    0 ;

: _EXT4-JFO-SCAN-OTHER-INODES  ( -- ior )
    0 _EXT4-JFO-GROUP !
    BEGIN
        _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JFO-SCAN-GROUP ?DUP IF EXIT THEN
        1 _EXT4-JFO-GROUP +!
    REPEAT
    0 ;

VARIABLE _EXT4-RPH-CTX
VARIABLE _EXT4-RPH-MAP-LIMIT
VARIABLE _EXT4-RPH-IOR

\ Certify every activation/emission/reset home before a clean journal becomes
\ writable.  Inode 8 is the sole excluded record: journal authentication has
\ already required its checksum-covered, self-contained exact extent tuple,
\ disjoint primary-super role, and zero external-xattr pointer.  Every other
\ allocated inode is checked through the ordinary complete map/xattr parser
\ while the protocol-home predicate is published.  The certificate lives in
\ this mounted context and is invalidated by the next mount-state reset.
: _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS-IMPL  ( ctx -- ior )
    DUP _EXT4-RPH-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    0 _EXT4-RPH-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-OWNER-INO @ OR
    _EXT4-MUTATION-MAP-TARGET @ OR
    _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR
    _EXT4-MUTATION-PROTOCOL-CTX @ OR
    _EXT4-MUTATION-PROTOCOL-ACTIVE @ OR
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR
    _EXT4-MUTATION-EA-REF-HOME @ OR
    _EXT4-MUTATION-EA-REF-HITS @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-RPH-CTX @ _EXT4-JFO-CTX !
    _EXT4-JOURNAL-INODE _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-RPH-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-RPH-CTX @ _EXT4-MUTATION-PROTOCOL-CTX !
    -1 _EXT4-MUTATION-PROTOCOL-ACTIVE !
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-RPH-IOR !
    0 _EXT4-MUTATION-PROTOCOL-ACTIVE !
    0 _EXT4-MUTATION-OWNER-INO !
    0 _EXT4-MUTATION-PROTOCOL-CTX !
    _EXT4-RPH-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-RPH-IOR @ 0= IF
        -1 _EXT4-RPH-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
    THEN
    _EXT4-RPH-IOR @ ;

' _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS-IMPL
_EXT4-MUTATION-PROTOCOL-PROOF-XT !

VARIABLE _EXT4-UOW-INO
VARIABLE _EXT4-UOW-FIRST
VARIABLE _EXT4-UOW-COUNT
VARIABLE _EXT4-UOW-FIRST-B
VARIABLE _EXT4-UOW-COUNT-B
VARIABLE _EXT4-UOW-CTX
VARIABLE _EXT4-UOW-MAP-LIMIT
VARIABLE _EXT4-UOW-IOR

\ Prove that no allocated inode other than TARGET-INO maps any part of one
\ proposed mutation range.  The caller has already authenticated the target's
\ own mapping; reload it after the scan restores that authority in C.INODE.
: _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER
  ( target-ino first count ctx -- ior )
    _EXT4-UOW-CTX ! _EXT4-UOW-COUNT !
    _EXT4-UOW-FIRST ! _EXT4-UOW-INO !
    _EXT4-UOW-CTX @ 0= _EXT4-UOW-COUNT @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-UOW-INO @ 0=
    _EXT4-UOW-INO @ _EXT4-UOW-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-CTX @ _EXT4-C.FIRST + @ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-COUNT @
    _EXT4-UOW-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-UOW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @ 0=
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @ 1 U< OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-UOW-CTX @ _EXT4-JFO-CTX !
    _EXT4-UOW-INO @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-UOW-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @
    _EXT4-MUTATION-OWNER-RANGES !
    _EXT4-UOW-FIRST @ 0 _EXT4-MUTATION-OWNER-RANGE !
    _EXT4-UOW-COUNT @ 0 _EXT4-MUTATION-OWNER-RANGE CELL+ !
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @ 1
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
    _EXT4-MUTATION-OWNER-RANGES-PUBLISH ?DUP IF
        _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT ! EXIT
    THEN
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-UOW-IOR !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-UOW-IOR @ 0= IF
        _EXT4-UOW-INO @ _EXT4-UOW-CTX @
        _EXT4-LOAD-INODE _EXT4-UOW-IOR !
    THEN
    _EXT4-UOW-IOR @ ;

\ The exact one-block write replaces two disjoint homes.  Scan all other
\ allocated inodes once while both ranges are published, rather than paying
\ for two filesystem-wide walks or conservatively merging the gap between
\ unrelated blocks.
: _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER-PAIR
  ( target-ino first-a count-a first-b count-b ctx -- ior )
    _EXT4-UOW-CTX ! _EXT4-UOW-COUNT-B ! _EXT4-UOW-FIRST-B !
    _EXT4-UOW-COUNT ! _EXT4-UOW-FIRST ! _EXT4-UOW-INO !
    _EXT4-UOW-CTX @ 0=
    _EXT4-UOW-COUNT @ 0= OR _EXT4-UOW-COUNT-B @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-UOW-INO @ 0=
    _EXT4-UOW-INO @ _EXT4-UOW-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-CTX @ _EXT4-C.FIRST + @ U<
    _EXT4-UOW-FIRST-B @ _EXT4-UOW-CTX @ _EXT4-C.FIRST + @ U< OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-COUNT @
    _EXT4-UOW-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0=
    _EXT4-UOW-FIRST-B @ _EXT4-UOW-COUNT-B @
    _EXT4-UOW-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-COUNT @
    _EXT4-UOW-FIRST-B @ _EXT4-UOW-COUNT-B @
    _EXT4-BLOCK-RANGES-OVERLAP? IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-UOW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @ 0=
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @ 2 U< OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-UOW-CTX @ _EXT4-JFO-CTX !
    _EXT4-UOW-INO @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-UOW-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @
    _EXT4-MUTATION-OWNER-RANGES !
    _EXT4-UOW-FIRST @ 0 _EXT4-MUTATION-OWNER-RANGE !
    _EXT4-UOW-COUNT @ 0 _EXT4-MUTATION-OWNER-RANGE CELL+ !
    _EXT4-UOW-FIRST-B @ 1 _EXT4-MUTATION-OWNER-RANGE !
    _EXT4-UOW-COUNT-B @ 1 _EXT4-MUTATION-OWNER-RANGE CELL+ !
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGES + @ 2
    _EXT4-UOW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
    _EXT4-MUTATION-OWNER-RANGES-PUBLISH ?DUP IF
        _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT ! EXIT
    THEN
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-UOW-IOR !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-UOW-IOR @ 0= IF
        _EXT4-UOW-INO @ _EXT4-UOW-CTX @
        _EXT4-LOAD-INODE _EXT4-UOW-IOR !
    THEN
    _EXT4-UOW-IOR @ ;

VARIABLE _EXT4-JOW-SOURCE
VARIABLE _EXT4-JOW-COUNT
VARIABLE _EXT4-JOW-OFFSET
VARIABLE _EXT4-JOW-INO
VARIABLE _EXT4-JOW-EXPECTED-GEN
VARIABLE _EXT4-JOW-SECONDS
VARIABLE _EXT4-JOW-NSEC
VARIABLE _EXT4-JOW-WRITER
VARIABLE _EXT4-JOW-CTX
VARIABLE _EXT4-JOW-BSIZE
VARIABLE _EXT4-JOW-SIZE
VARIABLE _EXT4-JOW-NEW-SIZE
VARIABLE _EXT4-JOW-GROW
VARIABLE _EXT4-JOW-LOGICAL
VARIABLE _EXT4-JOW-BLOCK-OFF
VARIABLE _EXT4-JOW-PHYS
VARIABLE _EXT4-JOW-PRESENT
VARIABLE _EXT4-JOW-TYPE
VARIABLE _EXT4-JOW-FLAGS
VARIABLE _EXT4-JOW-EA
VARIABLE _EXT4-JOW-GEN
VARIABLE _EXT4-JOW-NLINK
VARIABLE _EXT4-JOW-DEPTH
VARIABLE _EXT4-JOW-GROUP
VARIABLE _EXT4-JOW-INODE-HOME
VARIABLE _EXT4-JOW-INODE-OFF
VARIABLE _EXT4-JOW-IMAGE
VARIABLE _EXT4-JOW-RECORD
VARIABLE _EXT4-JOW-IOR
VARIABLE _EXT4-JOW-PUBLISHED
VARIABLE _EXT4-JOW-ABORT-IOR
VARIABLE _EXT4-JOW-META-IOR

\ _EXT4-STAGE-CURRENT-INODE has already authenticated the complete current
\ extent or legacy map.  Apply the narrower write-profile policy afterward so
\ malformed wider trees remain corrupt while valid out-of-profile maps are a
\ stable unsupported result.  Return the admitted root depth for later
\ reauthentication across cache-clobbering scans.
: _EXT4-JOW-QUALIFY-CURRENT-MAP  ( -- depth ior )
    _EXT4-JOW-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FLAGS + L@
    DUP _EXT4-EXTENTS-FL AND 0= IF
        2DROP 0 EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-EXTENTS-FL INVERT AND IF
        2DROP 0 EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    DROP _EXT4-I.BLOCK + 6 + W@ DUP 1 U> IF
        DROP 0 EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _EXT4-JOW-REQUIRE-FRESH-EXACT  ( -- ior )
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-CREDIT + @ 1 <>
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-CREDIT + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ 0<> OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JOW-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JOW-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-JOW-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-JOW-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

\ Once mapping identifies the selected data block, audit the complete target
\ tree.  Every data and node range must have a safe mutation role; the target
\ physical block must occur in exactly one leaf range and in no external node.
: _EXT4-JOW-REQUIRE-MAP-AUDIT  ( -- ior )
    _EXT4-MUTATION-MAP-TARGET @
    _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JOW-PHYS @ _EXT4-MUTATION-MAP-TARGET !
    0 _EXT4-MUTATION-MAP-HITS !
    -1 _EXT4-MUTATION-MAP-ACTIVE !
    _EXT4-JOW-CTX @ _EXT4-VALIDATE-EXTENT-TREE _EXT4-JOW-META-IOR !
    0 _EXT4-MUTATION-MAP-ACTIVE !
    0 _EXT4-MUTATION-MAP-TARGET !
    _EXT4-JOW-META-IOR @ 0=
    _EXT4-MUTATION-MAP-HITS @ 1 <> AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT _EXT4-JOW-META-IOR !
    THEN
    0 _EXT4-MUTATION-MAP-HITS !
    _EXT4-JOW-META-IOR @ ;

\ Authenticate the target's complete extent map before excluding that inode
\ from the global other-owner scan.  Extent validation excludes physical
\ overlap within each leaf; the scoped walk above counts the selected block
\ across the whole tree and excludes target map metadata.  The external xattr
\ pointer remains an independent target-owned reference and must not name the
\ selected block.
: _EXT4-JOW-AUTH-TARGET  ( -- ior )
    _EXT4-JOW-INO @
    _EXT4-JOW-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOW-INO @ 8 =
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-EXPECTED-GEN @ 0xFFFFFFFF U> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JOW-IOR ! _EXT4-JOW-TYPE !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-TYPE @ VFS-T-FILE <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-QUALIFY-CURRENT-MAP
    _EXT4-JOW-IOR ! _EXT4-JOW-DEPTH !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.FLAGS + L@ _EXT4-JOW-FLAGS !
    DUP _EXT4-I.GENERATION + L@ DUP _EXT4-JOW-GEN !
    _EXT4-JOW-EXPECTED-GEN @ <> IF
        DROP VFS-E-STALE EXIT
    THEN
    DUP _EXT4-I.LINKS + W@ _EXT4-JOW-NLINK !
    _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOW-EA !
    _EXT4-JOW-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JOW-SIZE !
    _EXT4-JOW-GROW @ IF
        _EXT4-JOW-OFFSET @ _EXT4-JOW-SIZE @ <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JOW-SIZE @ _EXT4-JOW-BSIZE @ MOD 0= IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JOW-OFFSET @ _EXT4-JOW-COUNT @ _EXT4-UADD?
        _EXT4-JOW-IOR ! _EXT4-JOW-NEW-SIZE !
        _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    ELSE
        _EXT4-JOW-OFFSET @ _EXT4-JOW-SIZE @ U< 0= IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JOW-COUNT @
        _EXT4-JOW-SIZE @ _EXT4-JOW-OFFSET @ - U> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JOW-SIZE @ _EXT4-JOW-NEW-SIZE !
    THEN
    _EXT4-JOW-OFFSET @ _EXT4-JOW-BSIZE @ /MOD
    _EXT4-JOW-LOGICAL ! _EXT4-JOW-BLOCK-OFF !
    _EXT4-JOW-COUNT @
    _EXT4-JOW-BSIZE @ _EXT4-JOW-BLOCK-OFF @ - U> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-LOGICAL @ _EXT4-JOW-CTX @ _EXT4-MAP-BLOCK
    _EXT4-JOW-IOR ! _EXT4-JOW-PRESENT ! _EXT4-JOW-PHYS !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-PRESENT @ 0= IF
        EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-REQUIRE-MAP-AUDIT ?DUP IF EXIT THEN
    _EXT4-JOW-EA @ IF
        _EXT4-JOW-EA @ _EXT4-JOW-PHYS @ = IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JOW-EA @ 1 _EXT4-JOW-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        _EXT4-JOW-EA @ EXT4-D-XATTR _EXT4-JOW-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOW-EA @ _EXT4-JOW-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    _EXT4-IR-GROUP @ _EXT4-JOW-GROUP !
    _EXT4-IR-BLOCK @ _EXT4-JOW-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JOW-INODE-OFF !
    0 ;

\ Reauthenticate every target property used by the after-images after a
\ descriptor walk or filesystem-wide owner scan has reused shared caches.
: _EXT4-JOW-REQUIRE-SAME-TARGET  ( -- ior )
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JOW-GROUP @ <>
    _EXT4-IR-BLOCK @ _EXT4-JOW-INODE-HOME @ <> OR
    _EXT4-IR-OFF @ _EXT4-JOW-INODE-OFF @ <> OR IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-JOW-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JOW-IOR ! _EXT4-JOW-TYPE !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-TYPE @ VFS-T-FILE <> IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-QUALIFY-CURRENT-MAP _EXT4-JOW-IOR !
    _EXT4-JOW-IOR @ ?DUP IF NIP EXIT THEN
    _EXT4-JOW-DEPTH @ <> IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.GENERATION + L@ _EXT4-JOW-GEN @ <>
    OVER _EXT4-I.FLAGS + L@ _EXT4-JOW-FLAGS @ <> OR
    OVER _EXT4-I.LINKS + W@ _EXT4-JOW-NLINK @ <> OR
    OVER _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOW-EA @ <> OR
    NIP IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JOW-SIZE @ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-JOW-LOGICAL @ _EXT4-JOW-CTX @ _EXT4-MAP-BLOCK
    _EXT4-JOW-IOR ! _EXT4-JOW-PRESENT !
    _EXT4-JOW-IOR @ ?DUP IF NIP EXIT THEN
    _EXT4-JOW-PRESENT @ 0=
    SWAP _EXT4-JOW-PHYS @ <> OR IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-REQUIRE-MAP-AUDIT ;

: _EXT4-JOW-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JOW-IOR !
    _EXT4-JOW-PUBLISHED @ IF
        _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP
            _EXT4-JOW-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JOW-ABORT-IOR ! IF
                _EXT4-JOW-ABORT-IOR @
                _EXT4-JOW-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + !
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JOW-IOR @
                _EXT4-JOW-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + !
            THEN
        THEN
    THEN
    _EXT4-JOW-IOR @ ;

: _EXT4-JOW-STAGE-SIZE  ( -- )
    _EXT4-JOW-GROW @ 0= IF EXIT THEN
    _EXT4-JOW-NEW-SIZE @ 0xFFFFFFFF AND
    _EXT4-JOW-RECORD @ _EXT4-I.SIZE-LO + L!
    _EXT4-JOW-NEW-SIZE @ 32 RSHIFT 0xFFFFFFFF AND
    _EXT4-JOW-RECORD @ _EXT4-I.SIZE-HI + L! ;

\ Stage one regular-file RMW wholly inside one already initialized extent
\ block, whether its authenticated map is inline or uses external extent-tree
\ nodes.  The selected mode is either a size-preserving overwrite or strict
\ no-gap growth from the exact partial-block EOF.  Ordered data carries the
\ full block; one checksummed inode-table after-image carries the explicit
\ size when growing plus mtime/ctime.  This word neither emits nor checkpoints.
: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-RMW
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    _EXT4-JOW-WRITER ! _EXT4-JOW-NSEC ! _EXT4-JOW-SECONDS !
    _EXT4-JOW-EXPECTED-GEN ! _EXT4-JOW-INO ! _EXT4-JOW-OFFSET !
    _EXT4-JOW-COUNT ! _EXT4-JOW-SOURCE !
    0 _EXT4-JOW-PUBLISHED !
    _EXT4-JOW-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOW-CTX !
    _EXT4-JOW-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JOW-BSIZE !
    _EXT4-JOW-COUNT @ 0> 0= _EXT4-JOW-OFFSET @ 0< OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-SOURCE @ _EXT4-JOW-COUNT @ _VFS-BUFFER? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-COUNT @ _EXT4-JOW-BSIZE @ U> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-REQUIRE-FRESH-EXACT ?DUP IF EXIT THEN
    \ Preserve caller bytes before any checked read reuses C.BLOCK.  SCRATCH-B
    \ is not used by metadata acquisition and survives until DATA-PUT copies
    \ the completed RMW block into its retained transaction image.
    _EXT4-JOW-SOURCE @
    _EXT4-JOW-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JOW-COUNT @ MOVE
    _EXT4-JOW-AUTH-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-PHYS @ 1 _EXT4-JOW-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JOW-INODE-HOME @ _EXT4-JOW-GROUP @ _EXT4-JOW-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _EXT4-JOW-INO @ _EXT4-JOW-PHYS @ 1
    _EXT4-JOW-INODE-HOME @ 1 _EXT4-JOW-CTX @
    _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER-PAIR ?DUP IF EXIT THEN
    _EXT4-JOW-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-INODE-HOME @ _EXT4-JOW-GROUP @ _EXT4-JOW-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _EXT4-JOW-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-INODE-HOME @ _EXT4-JOW-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-INODE-HOME @
    _EXT4-JOW-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JOW-IMAGE !
    _EXT4-JOW-INODE-OFF @ + DUP _EXT4-JOW-RECORD !
    _EXT4-JOW-CTX @ _EXT4-C.INODE +
    _EXT4-JOW-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JOW-STAGE-SIZE
    _EXT4-JOW-SECONDS @ _EXT4-JOW-NSEC @ _EXT4-JOW-RECORD @
    _EXT4-JOW-CTX @ _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _EXT4-JOW-RECORD @ _EXT4-JOW-INO @ _EXT4-JOW-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _EXT4-JOW-PHYS @ _EXT4-JOW-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-BLOCK-OFF @ +
    _EXT4-JOW-COUNT @ MOVE
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-PHYS @
    _EXT4-JOW-WRITER @ _EXT4-JTX-DATA-PUT ?DUP IF EXIT THEN
    -1 _EXT4-JOW-PUBLISHED !
    _EXT4-JOW-IMAGE @ _EXT4-JOW-INODE-HOME @ _EXT4-JOW-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF
        _EXT4-JOW-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-USED + @ 1 <>
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-ACTIVE + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-USED + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-USED + @ 0<> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0<> OR
    _EXT4-JOW-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT _EXT4-JOW-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    0 _EXT4-JOW-GROW !
    _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-RMW ;

: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-TAIL-APPEND
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    -1 _EXT4-JOW-GROW !
    _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-RMW ;

\ Prove filesystem-wide ownership of every target block in one inode walk.
\ Data ranges remain exclusive.  The external-xattr singleton is also kept in
\ the forbidden vector so it cannot appear as data or map metadata, while the
\ semantic i_file_acl boundary above counts exact references to it.  Requiring
\ that count (including the excluded target) to equal authenticated
\ h_refcount admits sharing without trusting a stale or forged refcount.
: _EXT4-JFI-EA-REF-SCOPE-CLEAR  ( -- )
    0 _EXT4-MUTATION-EA-REF-ACTIVE !
    0 _EXT4-MUTATION-EA-REF-HOME !
    0 _EXT4-MUTATION-EA-REF-HITS ! ;

: _EXT4-JFI-REQUIRE-UNIQUE-RELEASE-OWNER  ( -- ior )
    _EXT4-JFI-OWNER-RANGE-COUNT 0= IF 0 EXIT THEN
    _EXT4-JFI-OWNER-RANGE-COUNT _EXT4-JFI-RANGE-CAP U> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-MATCH? IF
        _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
        _EXT4-REAUTH-ORPHAN-PLAN-RECORD EXIT
    THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-JFI-CTX @ _EXT4-JFO-CTX !
    _EXT4-JFI-RECORD @ _EXT4-JFO-RECORD !
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-JFO-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    0 _EXT4-JFO-IOR !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-JFI-EA-REF-SCOPE-CLEAR
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-EA @ _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE !
        1 _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE CELL+ !
        _EXT4-JFI-EA @ _EXT4-MUTATION-EA-REF-HOME !
        1 _EXT4-MUTATION-EA-REF-HITS !
        -1 _EXT4-MUTATION-EA-REF-ACTIVE !
    THEN
    _EXT4-JFI-RANGES _EXT4-JFI-OWNER-RANGE-COUNT
    _EXT4-JFI-RANGE-CAP
    _EXT4-MUTATION-OWNER-RANGES-PUBLISH _EXT4-JFO-IOR !
    _EXT4-JFO-IOR @ 0= IF
        _EXT4-JFO-SCAN-OTHER-INODES _EXT4-JFO-IOR !
    THEN
    _EXT4-JFO-IOR @ 0= _EXT4-JFI-EA @ 0<> AND IF
        _EXT4-MUTATION-EA-REF-HITS @
        _EXT4-JFI-EA-REFCOUNT @ <> IF
            EXT4-D-XATTR _EXT4-CORRUPT _EXT4-JFO-IOR !
        THEN
    THEN
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-JFI-EA-REF-SCOPE-CLEAR
    _EXT4-JFO-IOR @ 0= IF
        _EXT4-JFO-RECORD @ _EXT4-JFO-CTX @
        _EXT4-REAUTH-ORPHAN-PLAN-RECORD _EXT4-JFO-IOR !
    THEN
    _EXT4-JFO-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JFO-IOR @ 0= IF _EXT4-JFO-CERT-STORE THEN
    _EXT4-JFO-IOR @ ;

: _EXT4-JFI-XATTR-PREFLIGHT  ( -- ior )
    \ Inline values die with the inode allocation bit.  Authenticate an
    \ external block through the ordinary read-side walker, then classify its
    \ exact disposition: refcount one releases the allocation; a larger valid
    \ refcount retains the block and stages a checksum-covered decrement.
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-RANGE-COUNT 0 ?DO
            _EXT4-JFI-EA @ 1 I _EXT4-JFI-RANGE
            DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        LOOP
    THEN
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _EXT4-JFI-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF EXIT THEN
    _EXT4-JFI-EA @ IF
        _EXT4-XB-BUF @ 4 + L@ DUP _EXT4-JFI-EA-REFCOUNT !
        DUP 0= OVER _EXT4-XATTR-REFCOUNT-MAX U> OR IF
            DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        1 = IF
            _EXT4-JEA-RELEASE
        ELSE
            _EXT4-JEA-REFDEC
        THEN _EXT4-JFI-EA-ACTION !
        _EXT4-JFI-EA-REFCOUNT @
        _EXT4-JFI-CTX @ _EXT4-C.INODES + @ U> IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-EA @ 1 _EXT4-JFI-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        _EXT4-JFI-EA-RELEASE? IF
            _EXT4-JFI-EA-RANGE 1 1
            _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
            _EXT4-ORPHAN-FILE-RANGES-DISJOINT ?DUP IF EXIT THEN
        THEN
    THEN
    0 ;

VARIABLE _EXT4-JFI-OVERLAP-INDEX
VARIABLE _EXT4-JFI-OVERLAP-OTHER

: _EXT4-JFI-RANGES-DISJOINT?  ( -- flag )
    _EXT4-JFI-RANGE-COUNT DUP 0<
    SWAP _EXT4-JFI-RANGE-CAP U> OR IF FALSE EXIT THEN
    0 _EXT4-JFI-OVERLAP-INDEX !
    BEGIN
        _EXT4-JFI-OVERLAP-INDEX @ _EXT4-JFI-RANGE-COUNT U<
    WHILE
        0 _EXT4-JFI-OVERLAP-OTHER !
        BEGIN
            _EXT4-JFI-OVERLAP-OTHER @
            _EXT4-JFI-OVERLAP-INDEX @ U<
        WHILE
            _EXT4-JFI-OVERLAP-INDEX @ _EXT4-JFI-RANGE
            DUP @ SWAP CELL+ @
            _EXT4-JFI-OVERLAP-OTHER @ _EXT4-JFI-RANGE
            DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-OVERLAP? IF
                FALSE EXIT
            THEN
            1 _EXT4-JFI-OVERLAP-OTHER +!
        REPEAT
        1 _EXT4-JFI-OVERLAP-INDEX +!
    REPEAT
    TRUE ;

: _EXT4-JFI-DATA-COMMON-PREFLIGHT  ( -- ior )
    _EXT4-JFI-RANGES-DISJOINT? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-INODE @ _EXT4-JFI-CTX @ _EXT4-DECODE-I-BLOCKS
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-DATA-ACTUAL !
    _EXT4-JFI-ACCOUNTED-BLOCKS
    _EXT4-JFI-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    _EXT4-JFI-DATA-ACTUAL @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-RANGE-COUNT IF
        _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE-CAP
        _EXT4-JFI-CTX @ _EXT4-VALIDATE-MUTATION-RANGES-TARGETS
        ?DUP IF EXIT THEN
        _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE-CAP
        _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
        _EXT4-ORPHAN-FILE-RANGES-DISJOINT ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JFI-CAPTURE-EXTENT-LEAF  ( -- ior )
    _EXT4-JFI-DATA-ROOT @ 2 + W@ _EXT4-JFI-LEAF-ENTRIES !
    _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-LEAF-ENTRIES @
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-MAP-ENTRIES @ - 1- U> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-JFI-LEAF-ENTRIES @ U<
    WHILE
        _EXT4-JFI-DATA-ROOT @ 12
        _EXT4-JFI-DATA-INDEX @ 12 * + + DUP _EXT4-JFI-DATA-ENTRY !
        L@ _EXT4-JFI-DATA-LOGICAL !
        _EXT4-JFI-DATA-ENTRY @ 4 + W@ 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-ENTRY @ _EXT4-EXTENT-LEN@
        DUP _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-RANGE CELL+ !
        _EXT4-JFI-DATA-LOGICAL @ SWAP _EXT4-UADD?
        DUP IF NIP EXIT THEN DROP 0xFFFFFFFF U> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-ENTRY @ 6 + W@ IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-ENTRY @ 8 + L@
        DUP 0= IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-RANGE !
        _EXT4-JFI-DATA-BLOCKS @
        _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-RANGE CELL+ @
        _EXT4-UADD? DUP IF NIP EXIT THEN DROP _EXT4-JFI-DATA-BLOCKS !
        1 _EXT4-JFI-DATA-ENTRIES +!
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    0 ;

: _EXT4-JFI-EXTENT-ROOT-ENTRY  ( index -- entry )
    12 * 12 + _EXT4-JFI-EXTENT-ROOT @ + ;

: _EXT4-JFI-CURRENT-LEAF-IN-ROOT-BOUNDS?  ( -- flag )
    _EXT4-JFI-ROOT-INDEX @ 1+ _EXT4-JFI-ROOT-ENTRIES @ U< 0= IF
        TRUE EXIT
    THEN
    _EXT4-JFI-DATA-ROOT @ 12
    _EXT4-JFI-LEAF-ENTRIES @ 1- 12 * + + DUP
    L@ SWAP _EXT4-EXTENT-LEN@ +
    _EXT4-JFI-ROOT-INDEX @ 1+ _EXT4-JFI-EXTENT-ROOT-ENTRY L@
    U> 0= ;

: _EXT4-JFI-COMPACT-MAP-RANGES  ( -- )
    0 _EXT4-JFI-MAP-INDEX !
    BEGIN
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-ENTRIES @ U<
    WHILE
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-SCRATCH-RANGE
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-RANGE
        2 CELLS CMOVE
        1 _EXT4-JFI-MAP-INDEX +!
    REPEAT
    _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT 2* CELLS +
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-RANGE-COUNT -
    2* CELLS 0 FILL ;

\ Admit every format-valid resident depth-one fanout.  Root and child keys,
\ child checksums, and sibling logical bounds are reauthenticated while leaf
\ homes are parked at the workspace tail.  The final canonical vector keeps
\ all data extents first and all leaf singletons in resident-root order.
: _EXT4-JFI-EXTENT-DATA-PREFLIGHT  ( -- ior )
    _EXT4-JFI-CTX @ _EXT4-VALIDATE-INLINE-EXTENTS ?DUP IF EXIT THEN
    _EXT4-JFI-INODE @ _EXT4-I.BLOCK + DUP _EXT4-JFI-EXTENT-ROOT !
    6 + W@ DUP 0= IF
        DROP
        _EXT4-JDM-INLINE-EXTENTS _EXT4-JFI-DATA-MAP-KIND !
        _EXT4-JFI-EXTENT-ROOT @ _EXT4-JFI-DATA-ROOT !
        _EXT4-JFI-CAPTURE-EXTENT-LEAF ?DUP IF EXIT THEN
        _EXT4-JFI-DATA-COMMON-PREFLIGHT EXIT
    THEN
    1 <> IF EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
    _EXT4-JFI-EXTENT-ROOT @ 2 + W@ DUP _EXT4-JFI-ROOT-ENTRIES !
    DUP 0= SWAP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDM-DEPTH1-LEAVES _EXT4-JFI-DATA-MAP-KIND !
    _EXT4-JFI-ROOT-ENTRIES @ DUP _EXT4-JFI-MAP-ENTRIES !
    _EXT4-JFI-MAP-BLOCKS !
    0 _EXT4-JFI-ROOT-INDEX !
    BEGIN
        _EXT4-JFI-ROOT-INDEX @ _EXT4-JFI-ROOT-ENTRIES @ U<
    WHILE
        _EXT4-JFI-ROOT-INDEX @ _EXT4-JFI-EXTENT-ROOT-ENTRY
        DUP _EXT4-JFI-ROOT-ENTRY !
        DUP L@ _EXT4-JFI-ROOT-KEY !
        4 + L@ DUP _EXT4-JFI-LEAF-HOME !
        _EXT4-JFI-ROOT-INDEX @ _EXT4-JFI-MAP-SCRATCH-RANGE !
        1 _EXT4-JFI-ROOT-INDEX @
        _EXT4-JFI-MAP-SCRATCH-RANGE CELL+ !
        _EXT4-JFI-LEAF-HOME @ 0 _EXT4-JFI-CTX @
        _EXT4-LOAD-EXTENT-NODE ?DUP IF EXIT THEN
        _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
        DUP _EXT4-JFI-DATA-ROOT !
        12 + L@ _EXT4-JFI-ROOT-KEY @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-CAPTURE-EXTENT-LEAF ?DUP IF EXIT THEN
        _EXT4-JFI-CURRENT-LEAF-IN-ROOT-BOUNDS? 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-JFI-ROOT-INDEX +!
    REPEAT
    _EXT4-JFI-COMPACT-MAP-RANGES
    _EXT4-JFI-DATA-COMMON-PREFLIGHT ;

\ Append one occupied legacy data pointer as a singleton while reserving all
\ trailing map homes and a range slot only for an actually present xattr.
: _EXT4-JFI-CAPTURE-LEGACY-DATA  ( physical -- ior )
    DUP 0= IF DROP 0 EXIT THEN
    _EXT4-JFI-DATA-PHYSICAL !
    _EXT4-JFI-DATA-ENTRIES @
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-MAP-ENTRIES @ -
    _EXT4-JFI-EA @ IF 1- THEN U< 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JFI-DATA-PHYSICAL @
    _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-RANGE !
    1 _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-RANGE CELL+ !
    1 _EXT4-JFI-DATA-BLOCKS +!
    1 _EXT4-JFI-DATA-ENTRIES +!
    0 ;

: _EXT4-JFI-CAPTURE-LEGACY-DIRECTS  ( -- ior )
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-NDIRECT U<
    WHILE
        _EXT4-JFI-DATA-ROOT @ _EXT4-JFI-DATA-INDEX @ 4 * + L@
        _EXT4-JFI-CAPTURE-LEGACY-DATA ?DUP IF EXIT THEN
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    0 ;

VARIABLE _EXT4-JFI-LEGACY-CHECK-HOME
VARIABLE _EXT4-JFI-LEGACY-CHECK-INDEX

: _EXT4-JFI-LEGACY-HOME-IN-DATA?  ( home -- flag )
    _EXT4-JFI-LEGACY-CHECK-HOME !
    0 _EXT4-JFI-LEGACY-CHECK-INDEX !
    BEGIN
        _EXT4-JFI-LEGACY-CHECK-INDEX @ _EXT4-JFI-DATA-ENTRIES @ U<
    WHILE
        _EXT4-JFI-LEGACY-CHECK-INDEX @ _EXT4-JFI-RANGE @
        _EXT4-JFI-LEGACY-CHECK-HOME @ = IF TRUE EXIT THEN
        1 _EXT4-JFI-LEGACY-CHECK-INDEX +!
    REPEAT
    FALSE ;

\ Check a candidate child before its contents can affect shape admission.
\ Direct and single-indirect data has already been retained, while the scalar
\ map and xattr homes survive every TREE-BLOCK reload.
: _EXT4-JFI-LEGACY-CHILD-ALIASES-KNOWN?  ( home -- flag )
    DUP _EXT4-JFI-LEGACY-HOME-IN-DATA? IF DROP TRUE EXIT THEN
    DUP _EXT4-JFI-LEGACY-INDIRECT-HOME @ =
    OVER _EXT4-JFI-LEGACY-DOUBLE-HOME @ = OR
    OVER _EXT4-JFI-LEGACY-TRIPLE-HOME @ = OR
    SWAP _EXT4-JFI-EA @ = OR ;

\ Retain the sole admitted triple-root child before loading it can replace the
\ shared tree buffer.  Known aliases and a duplicate child are corrupt; a
\ second distinct child belongs to a later fanout tier.
: _EXT4-JFI-SCAN-LEGACY-TRIPLE-ROOT  ( -- ior )
    0 _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME !
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-JFI-LEGACY-PTRS @ U<
    WHILE
        _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JFI-DATA-INDEX @ 4 * + L@ ?DUP IF
            DUP _EXT4-JFI-LEGACY-CHILD-ALIASES-KNOWN? IF
                DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME @ IF
                DUP _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME @ = IF
                    DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
                THEN
                DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
            THEN
            _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME !
        THEN
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    0 ;

: _EXT4-JFI-LEGACY-CHILD-ALIASES-PARKED?  ( home -- flag )
    _EXT4-JFI-LEGACY-CHECK-HOME !
    _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE @
    _EXT4-JFI-LEGACY-CHECK-INDEX !
    BEGIN
        _EXT4-JFI-LEGACY-CHECK-INDEX @ _EXT4-JFI-MAP-INDEX @ U<
    WHILE
        _EXT4-JFI-LEGACY-CHECK-INDEX @
        _EXT4-JFI-MAP-SCRATCH-RANGE @
        _EXT4-JFI-LEGACY-CHECK-HOME @ = IF TRUE EXIT THEN
        1 _EXT4-JFI-LEGACY-CHECK-INDEX +!
    REPEAT
    FALSE ;

\ Park map homes at the workspace tail after the exact occupied-child count is
\ known.  Data appends retain this map tail and the optional xattr reserve.
: _EXT4-JFI-PARK-LEGACY-MAP  ( home -- )
    _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-SCRATCH-RANGE !
    1 _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-SCRATCH-RANGE CELL+ !
    1 _EXT4-JFI-MAP-INDEX +! ;

: _EXT4-JFI-CAPTURE-LEGACY-POINTER-BLOCK  ( home -- ior )
    _EXT4-JFI-CTX @ _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF EXIT THEN
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-JFI-LEGACY-PTRS @ U<
    WHILE
        _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JFI-DATA-INDEX @ 4 * + L@
        _EXT4-JFI-CAPTURE-LEGACY-DATA ?DUP IF EXIT THEN
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    0 ;

\ Count every occupied double-root slot while the provisional P+2 map reserve
\ protects already captured direct and single-indirect data.  The root remains
\ resident for the ordered parking pass; duplicate children are diagnosed
\ there against the growing parked prefix.
: _EXT4-JFI-COUNT-LEGACY-DOUBLE-CHILDREN  ( -- ior )
    0 _EXT4-JFI-LEGACY-DOUBLE-CHILDREN !
    _EXT4-JFI-LEGACY-DOUBLE-HOME @ _EXT4-JFI-CTX @
    _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF EXIT THEN
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-JFI-LEGACY-PTRS @ U<
    WHILE
        _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JFI-DATA-INDEX @ 4 * + L@ ?DUP IF
            DUP _EXT4-JFI-LEGACY-CHILD-ALIASES-KNOWN? IF
                DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            DROP
            _EXT4-JFI-LEGACY-DOUBLE-CHILDREN @ 1 _EXT4-UADD?
            DUP IF NIP EXIT THEN DROP
            _EXT4-JFI-LEGACY-DOUBLE-CHILDREN !
        THEN
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    0 ;

: _EXT4-JFI-FIX-LEGACY-DOUBLE-MAPS  ( -- ior )
    _EXT4-JFI-LEGACY-DOUBLE-CHILDREN @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP
    _EXT4-JFI-LEGACY-INDIRECT-HOME @ IF
        1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    THEN
    DUP _EXT4-JFI-RANGE-CAP 1- U> IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-JFI-MAP-ENTRIES ! _EXT4-JFI-MAP-BLOCKS !
    0 ;

\ Retain every child map home in double-root slot order before loading any
\ child can overwrite TREE-BLOCK.  Known aliases and duplicate child homes are
\ corrupt rather than alternate representations of the same authority.
: _EXT4-JFI-PARK-LEGACY-DOUBLE-CHILDREN  ( -- ior )
    _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE !
    0 _EXT4-JFI-DATA-INDEX !
    BEGIN
        _EXT4-JFI-DATA-INDEX @ _EXT4-JFI-LEGACY-PTRS @ U<
    WHILE
        _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JFI-DATA-INDEX @ 4 * + L@ ?DUP IF
            DUP _EXT4-JFI-LEGACY-CHILD-ALIASES-KNOWN? IF
                DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            DUP _EXT4-JFI-LEGACY-CHILD-ALIASES-PARKED? IF
                DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JFI-PARK-LEGACY-MAP
        THEN
        1 _EXT4-JFI-DATA-INDEX +!
    REPEAT
    _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE @ -
    _EXT4-JFI-LEGACY-DOUBLE-CHILDREN @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-CAPTURE-LEGACY-DOUBLE-CHILDREN  ( -- ior )
    _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE @ _EXT4-JFI-MAP-INDEX !
    BEGIN
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-ENTRIES @ U<
    WHILE
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-SCRATCH-RANGE @
        _EXT4-JFI-CAPTURE-LEGACY-POINTER-BLOCK ?DUP IF EXIT THEN
        1 _EXT4-JFI-MAP-INDEX +!
    REPEAT
    0 ;

\ Decode every occupied direct slot, an optional complete single-indirect
\ block, and every occupied child under an optional double-indirect root whose
\ exact authority fits the caller workspace.  A triple root may be all zero and
\ coexist with direct data, or may name one all-zero level-2 child when direct
\ data and the external-xattr pointer are absent; the single- and
\ double-indirect inode slots remain zero.
\ Holes do not enter release authority.  Data remains in direct, single, then
\ double outer/inner pointer order.  Map metadata follows as optional single
\ root, double root and its children, or triple root then level-2 child.
: _EXT4-JFI-LEGACY-DATA-PREFLIGHT  ( -- ior )
    _EXT4-JDM-LEGACY-DIRECT _EXT4-JFI-DATA-MAP-KIND !
    _EXT4-JFI-INODE @ _EXT4-I.BLOCK + _EXT4-JFI-DATA-ROOT !
    _EXT4-JFI-CTX @ _EXT4-C.BSIZE + @ 4 /
    _EXT4-JFI-LEGACY-PTRS !
    _EXT4-JFI-DATA-ROOT @ _EXT4-NDIRECT 2 + 4 * + L@
    DUP _EXT4-JFI-LEGACY-TRIPLE-HOME ! IF
        _EXT4-JFI-DATA-ROOT @ _EXT4-NDIRECT 4 * + 8
        _EXT4-BYTES-ZERO? 0= IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JDM-LEGACY-SPARSE-TRIPLE _EXT4-JFI-DATA-MAP-KIND !
        _EXT4-JFI-LEGACY-TRIPLE-HOME @ _EXT4-JFI-EA @ = IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-JFI-MAP-ENTRIES !
        1 _EXT4-JFI-MAP-BLOCKS !
        _EXT4-JFI-CAPTURE-LEGACY-DIRECTS ?DUP IF EXIT THEN
        _EXT4-JFI-LEGACY-TRIPLE-HOME @
        _EXT4-JFI-LEGACY-HOME-IN-DATA? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-LEGACY-TRIPLE-HOME @ _EXT4-JFI-CTX @
        _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF EXIT THEN
        _EXT4-JFI-SCAN-LEGACY-TRIPLE-ROOT ?DUP IF EXIT THEN
        _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME @ IF
            _EXT4-JDM-LEGACY-SPARSE-TRIPLE-CHILD
            _EXT4-JFI-DATA-MAP-KIND !
            _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFI-EA @ OR IF
                EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
            THEN
            2 _EXT4-JFI-MAP-ENTRIES !
            2 _EXT4-JFI-MAP-BLOCKS !
        THEN
        0 _EXT4-JFI-MAP-INDEX !
        _EXT4-JFI-LEGACY-TRIPLE-HOME @ _EXT4-JFI-PARK-LEGACY-MAP
        _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME @ ?DUP IF
            DUP _EXT4-JFI-PARK-LEGACY-MAP
            _EXT4-JFI-CTX @ _EXT4-LOAD-LEGACY-POINTER-BLOCK ?DUP IF
                EXIT
            THEN
            _EXT4-JFI-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JFI-CTX @ _EXT4-C.BSIZE + @
            _EXT4-BYTES-ZERO? 0= IF
                EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
            THEN
        THEN
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-ENTRIES @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-COMPACT-MAP-RANGES
        _EXT4-JFI-DATA-COMMON-PREFLIGHT EXIT
    THEN
    _EXT4-NDIRECT 2 + _EXT4-JFI-CTX @
    _EXT4-I-BLOCK-ZERO-FROM? 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JFI-DATA-ROOT @ _EXT4-NDIRECT 4 * + L@
    _EXT4-JFI-LEGACY-INDIRECT-HOME !
    _EXT4-JFI-DATA-ROOT @ _EXT4-NDIRECT 1+ 4 * + L@
    _EXT4-JFI-LEGACY-DOUBLE-HOME !
    _EXT4-JFI-LEGACY-DOUBLE-HOME @ IF
        _EXT4-JDM-LEGACY-SPARSE-DOUBLE _EXT4-JFI-DATA-MAP-KIND !
        \ Reserve the maximum possible map tail while direct and optional
        \ single data is captured.  The root scan then replaces this with the
        \ exact occupied map count before any child data is appended.
        _EXT4-JFI-LEGACY-PTRS @ 2 _EXT4-UADD?
        DUP IF NIP EXIT THEN DROP _EXT4-JFI-MAP-ENTRIES !
    ELSE _EXT4-JFI-LEGACY-INDIRECT-HOME @ IF
        _EXT4-JDM-LEGACY-SINGLE-INDIRECT _EXT4-JFI-DATA-MAP-KIND !
        1 _EXT4-JFI-MAP-ENTRIES !
        1 _EXT4-JFI-MAP-BLOCKS !
    THEN THEN
    _EXT4-JFI-CAPTURE-LEGACY-DIRECTS ?DUP IF EXIT THEN
    _EXT4-JFI-LEGACY-INDIRECT-HOME @ IF
        _EXT4-JFI-LEGACY-INDIRECT-HOME @
        _EXT4-JFI-CAPTURE-LEGACY-POINTER-BLOCK ?DUP IF EXIT THEN
    THEN
    0 _EXT4-JFI-MAP-INDEX !
    _EXT4-JFI-LEGACY-DOUBLE-HOME @ IF
        _EXT4-JFI-LEGACY-DOUBLE-HOME @
        DUP _EXT4-JFI-LEGACY-HOME-IN-DATA?
        OVER _EXT4-JFI-LEGACY-INDIRECT-HOME @ = OR
        SWAP _EXT4-JFI-EA @ = OR IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-COUNT-LEGACY-DOUBLE-CHILDREN ?DUP IF EXIT THEN
        _EXT4-JFI-FIX-LEGACY-DOUBLE-MAPS ?DUP IF EXIT THEN
        _EXT4-JFI-LEGACY-INDIRECT-HOME @ ?DUP IF
            _EXT4-JFI-PARK-LEGACY-MAP
        THEN
        _EXT4-JFI-LEGACY-DOUBLE-HOME @ _EXT4-JFI-PARK-LEGACY-MAP
        _EXT4-JFI-PARK-LEGACY-DOUBLE-CHILDREN ?DUP IF EXIT THEN
        _EXT4-JFI-CAPTURE-LEGACY-DOUBLE-CHILDREN ?DUP IF EXIT THEN
    ELSE
        _EXT4-JFI-LEGACY-INDIRECT-HOME @ ?DUP IF
            _EXT4-JFI-PARK-LEGACY-MAP
        THEN
    THEN
    _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-ENTRIES @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-MAP-ENTRIES @ IF _EXT4-JFI-COMPACT-MAP-RANGES THEN
    _EXT4-JFI-DATA-COMMON-PREFLIGHT ;

: _EXT4-JFI-DATA-PREFLIGHT  ( -- ior )
    0 _EXT4-JFI-DATA-ENTRIES !
    0 _EXT4-JFI-DATA-BLOCKS !
    0 _EXT4-JFI-EXTENT-ROOT !
    0 _EXT4-JFI-ROOT-ENTRIES !
    0 _EXT4-JFI-ROOT-INDEX !
    0 _EXT4-JFI-ROOT-ENTRY !
    0 _EXT4-JFI-ROOT-KEY !
    0 _EXT4-JFI-DATA-ROOT !
    0 _EXT4-JFI-DATA-ENTRY !
    0 _EXT4-JFI-LEAF-ENTRIES !
    0 _EXT4-JFI-LEAF-HOME !
    0 _EXT4-JFI-MAP-ENTRIES !
    0 _EXT4-JFI-MAP-BLOCKS !
    0 _EXT4-JFI-MAP-INDEX !
    0 _EXT4-JFI-LEGACY-INDIRECT-HOME !
    0 _EXT4-JFI-LEGACY-DOUBLE-HOME !
    0 _EXT4-JFI-LEGACY-TRIPLE-HOME !
    0 _EXT4-JFI-LEGACY-TRIPLE-CHILD-HOME !
    0 _EXT4-JFI-LEGACY-DOUBLE-CHILDREN !
    0 _EXT4-JFI-LEGACY-DOUBLE-CHILD-BASE !
    0 _EXT4-JFI-LEGACY-PTRS !
    _EXT4-JDM-NONE _EXT4-JFI-DATA-MAP-KIND !
    _EXT4-JFI-RANGES
    _EXT4-JFI-RANGE-CAP 2* CELLS 0 FILL
    _EXT4-JFI-INODE @ _EXT4-I.FLAGS + L@
    _EXT4-EXTENTS-FL AND IF
        _EXT4-JFI-EXTENT-DATA-PREFLIGHT
    ELSE
        _EXT4-JFI-LEGACY-DATA-PREFLIGHT
    THEN ;

VARIABLE _EXT4-JFI-CP-WRITER

: _EXT4-JFI-EA-POST-REFCOUNT  ( -- count )
    _EXT4-JFI-EA-REFDEC? IF _EXT4-JFI-EA-REFCOUNT @ 1- ELSE 0 THEN ;

: _EXT4-JFI-CP-RANGES-MATCH?  ( writer -- flag )
    DUP _EXT4-JFI-CP-WRITER !
    _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    _EXT4-JFI-RANGE-COUNT U< IF
        FALSE EXIT
    THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @
    _EXT4-JFI-RANGE-COUNT <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @
    _EXT4-JFI-RANGE-BLOCKS <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @
    _EXT4-JFI-DATA-MAP-KIND @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JFI-EA @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
    _EXT4-JFI-EA-ACTION @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @
    _EXT4-JFI-EA-POST-REFCOUNT <> IF FALSE EXIT THEN
    _EXT4-JFI-EA-AFTER-VERIFIED @ IF
        _EXT4-JFI-EA-AFTER-CRC @
        _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @
        I _EXT4-JFI-CP-WRITER @ _EXT4-JWR-CP-DELETE-RANGE @ <> IF
            FALSE UNLOOP EXIT
        THEN
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFI-CP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE CELL+ @ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFI-STORE-CP-RANGES  ( writer -- )
    DUP _EXT4-JFI-CP-WRITER !
    _EXT4-JFI-RANGE-COUNT
    OVER _EXT4-JWR.CP-DELETE-RANGE-COUNT + !
    _EXT4-JFI-RANGE-BLOCKS
    SWAP _EXT4-JWR.CP-DELETE-BLOCKS + !
    _EXT4-JFI-EA @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-HOME + !
    _EXT4-JFI-EA-ACTION @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-ACTION + !
    _EXT4-JFI-EA-POST-REFCOUNT
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + !
    _EXT4-JFI-EA-AFTER-CRC @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-CRC + !
    _EXT4-JFI-DATA-MAP-KIND @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + !
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @
        I _EXT4-JFI-CP-WRITER @ _EXT4-JWR-CP-DELETE-RANGE !
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFI-CP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE CELL+ !
    LOOP ;

\ Authenticate one complete deletion shape: an inline extent root, every
\ format-valid resident depth-one leaf fanout, or all twelve legacy direct
\ slots plus optional complete single-indirect data and every occupied
\ double-indirect child whose exact authority fits the caller workspace, or
\ direct data plus one allocated all-zero triple-indirect root, or one triple
\ root naming one allocated all-zero level-2 child while direct and lower
\ indirect slots remain zero.
\ Retain each represented data and map-metadata range separately
\ and bind the map family, ordered release vector, and explicit external-xattr
\ disposition into the owner certificate.
\ Structurally valid resident inline xattrs die with the inode allocation bit.
: _EXT4-JFI-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JFI-RECORD @ 0= _EXT4-JFI-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-RANGE-EXPECTED !
    _EXT4-JFI-RANGES 0=
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-RANGE-EXPECTED @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JFI-EA !
    _EXT4-JEA-NONE _EXT4-JFI-EA-ACTION !
    0 _EXT4-JFI-EA-REFCOUNT !
    0 _EXT4-JFI-EA-AFTER-CRC !
    0 _EXT4-JFI-EA-AFTER-VERIFIED !
    _EXT4-JFI-EA-RANGE 2 CELLS 0 FILL
    _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JFI-INO !
    DUP _EXT4-JFI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-JFI-CTX @ _EXT4-C.INODE + DUP _EXT4-JFI-INODE !
    DUP _EXT4-I.LINKS + W@ IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    \ Linux recovery deletes an unlinked inode rather than truncating it to
    \ i_size.  This builder releases the complete authenticated map, so a
    \ nonzero or sparse size does not narrow its authority.  Still reject the
    \ signed-host overflow shape on every reauthentication.
    DUP _EXT4-I.SIZE-HI + L@ 0x80000000 AND IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-I.FLAGS + L@ _EXT4-JOURNAL-DATA-FL AND IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-LO + L@ DUP _EXT4-JFI-EA ! ?DUP IF
        _EXT4-JFI-EA-RANGE !
        1 _EXT4-JFI-EA-RANGE CELL+ !
    THEN
    DROP
    _EXT4-JFI-DATA-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-XATTR-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-REQUIRE-UNIQUE-RELEASE-OWNER ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFI-GROUP !
    _EXT4-IR-INDEX @ _EXT4-JFI-INDEX !
    _EXT4-IR-BLOCK @ _EXT4-JFI-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JFI-INODE-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE !
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-GROUP-INODES !
    _EXT4-JFI-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR ! _EXT4-JFI-BITMAP-HOME !
    _EXT4-JFI-IOR @ ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.INODE-CSUM-LO + W@
    SWAP _EXT4-GD.INODE-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.INODE-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.INODE-CSUM-HI + W! ;

: _EXT4-JFI-DESC-FREE@  ( descriptor -- inodes )
    DUP _EXT4-GD.FREE-INODES-LO + W@
    SWAP _EXT4-GD.FREE-INODES-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-FREE!  ( inodes descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-INODES-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-INODES-HI + W! ;

: _EXT4-JFI-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFI-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFI-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFI-NEW-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-GDT-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFI-DESC !
    _EXT4-JFI-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFI-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFI-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFI-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFI-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFI-IMAGE !
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-NEW-SUPER-FREE !
    _EXT4-JFI-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-PREFLIGHT  ( -- ior )
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-REVOKE-COUNT
    _EXT4-JFI-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-ACQUIRE-SUPER ;

: _EXT4-JFI-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFI-IOR !
    _EXT4-JFI-PUBLISHED @ IF
        _EXT4-JFI-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP _EXT4-JFI-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JFI-ABORT-IOR ! IF
                _EXT4-JFI-ABORT-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JFI-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        THEN
    THEN
    _EXT4-JFI-IOR @ ;

: _EXT4-JFI-STAGE-GROUP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    DUP _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _EXT4-JFI-BITMAP-CRC !
    DUP _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-INDEX @ 1 _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-NEW-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-GROUP-FREE @ _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JFI-NEW-BITMAP-CRC @ _EXT4-JFI-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-GDT-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-SUPER  ( -- ior )
    _EXT4-JFI-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-SUPER-FREE @
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFI-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-SUPER-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-INODE  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFI-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-INODE-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-OFF @ +
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ 0 FILL
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

\ Retain a shared external-xattr allocation and stage only its reference
\ release.  Reloading through the structural/checksum parser makes the
\ preflight refcount a conflict fence; the retained image begins as an exact
\ raw copy, then changes only h_refcount and h_checksum.
: _EXT4-JFI-STAGE-EA-REFDEC  ( -- ior )
    _EXT4-JFI-EA-REFDEC? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-EA @ _EXT4-JFI-CTX @ _EXT4-LOAD-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-XB-BUF @ 4 + L@ _EXT4-JFI-EA-REFCOUNT @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-XB-BUF @ _EXT4-JFI-EA @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-EA-IMAGE !
    4 + L@ _EXT4-JFI-EA-REFCOUNT @ <> IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JFI-EA-REFCOUNT @ 1- _EXT4-JFI-EA-IMAGE @ 4 + L!
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-EA @ _EXT4-JFI-CTX @
    _EXT4-STAMP-XATTR-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-EA @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-EA-AFTER-CRC !
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

\ Release allocation authority for one exact unlinked regular-file orphan.
\ First replace its authenticated inode record with zeros so ordinary ext4
\ tools see a clean free record; then release every block in the admitted
\ physical extent, optional unique external-xattr block, and inode allocation
\ bit in the same transaction.
: _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
  ( plan-record transaction -- ior )
    _EXT4-JFI-WRITER ! _EXT4-JFI-RECORD !
    0 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFI-CTX !
    _EXT4-JFI-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-STAGE-INODE ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-RANGE-COUNT IF
        _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE-CAP
        _EXT4-JFI-WRITER @ _EXT4-JTX-STAGE-FREE-BLOCK-RANGES
        ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
        -1 _EXT4-JFI-PUBLISHED !
    THEN
    0 _EXT4-JFI-MAP-INDEX !
    BEGIN
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-ENTRIES @ U<
    WHILE
        _EXT4-JFI-MAP-INDEX @ _EXT4-JFI-MAP-RANGE @
        _EXT4-JFI-WRITER @ _EXT4-JTX-REVOKE
        ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
        -1 _EXT4-JFI-PUBLISHED !
        1 _EXT4-JFI-MAP-INDEX +!
    REPEAT
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-EA-RELEASE? IF
            _EXT4-JFI-EA @ 1 _EXT4-JFI-WRITER @
            _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
            -1 _EXT4-JFI-PUBLISHED !
            _EXT4-JFI-EA @ _EXT4-JFI-WRITER @ _EXT4-JTX-REVOKE
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
            -1 _EXT4-JFI-PUBLISHED !
        ELSE
            _EXT4-JFI-STAGE-EA-REFDEC
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
        THEN
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JFI-REVOKES-EXACT? 0= IF
        VFS-E-CORRUPT _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-STAGE-GROUP ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-STAGE-SUPER ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ =====================================================================
\  Plan-bound linked orphan truncation after-images
\ =====================================================================

VARIABLE _EXT4-EIB-SECTORS
VARIABLE _EXT4-EIB-INODE
VARIABLE _EXT4-EIB-CTX
VARIABLE _EXT4-EIB-RAW
VARIABLE _EXT4-EIB-LIMIT

\ Encode the on-disk 48-bit i_blocks field without silently changing the
\ HUGE_FILE unit convention.  Callers supply the normalized 512-byte-sector
\ count used by the rest of this driver.
: _EXT4-ENCODE-I-BLOCKS  ( blocks-512 inode ctx -- ior )
    _EXT4-EIB-CTX ! _EXT4-EIB-INODE ! _EXT4-EIB-SECTORS !
    _EXT4-EIB-CTX @ 0= _EXT4-EIB-INODE @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-EIB-SECTORS @ 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-EIB-CTX @ _EXT4-C.SPB + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-EIB-CTX @ _EXT4-C.BLOCKS + @
    _EXT4-EIB-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-EIB-LIMIT !
    _EXT4-EIB-SECTORS @ _EXT4-EIB-LIMIT @ U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EIB-SECTORS @
    _EXT4-EIB-INODE @ _EXT4-I.FLAGS + L@
    _EXT4-HUGE-FILE-FL AND IF
        _EXT4-EIB-CTX @ _EXT4-C.SPB + @ /MOD
        SWAP IF DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    THEN
    DUP _EXT4-EIB-RAW ! 0xFFFFFFFFFFFF U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EIB-RAW @ DUP 0xFFFFFFFF AND
    _EXT4-EIB-INODE @ _EXT4-I.BLOCKS-LO + L!
    32 RSHIFT _EXT4-EIB-INODE @ _EXT4-I.BLOCKS-HI + W!
    0 ;


\ Four leaf entries are the format-defined capacity of an inline inode
\ extent root.  Each retained pair is { first physical block, block count }.
CREATE _EXT4-JOT-RANGES
_EXT4-RESIDENT-EXTENT-ENTRY-MAX 2* CELLS ALLOT

: _EXT4-JOT-RANGE  ( index -- pair-address )
    2 * CELLS _EXT4-JOT-RANGES + ;

VARIABLE _EXT4-JOT-RECORD
VARIABLE _EXT4-JOT-WRITER
VARIABLE _EXT4-JOT-CTX
VARIABLE _EXT4-JOT-INODE
VARIABLE _EXT4-JOT-ROOT
VARIABLE _EXT4-JOT-COUNT
VARIABLE _EXT4-JOT-ENTRY
VARIABLE _EXT4-JOT-LEN
VARIABLE _EXT4-JOT-PHYS
VARIABLE _EXT4-JOT-DATA-BLOCKS
VARIABLE _EXT4-JOT-EA
VARIABLE _EXT4-JOT-EXPECTED
VARIABLE _EXT4-JOT-ACTUAL
VARIABLE _EXT4-JOT-AFTERIMAGE
VARIABLE _EXT4-JOT-IOR
VARIABLE _EXT4-JOT-PUBLISHED
VARIABLE _EXT4-JOT-ABORT-IOR
VARIABLE _EXT4-JOT-OWNER-IOR
VARIABLE _EXT4-JOT-OWNER-MAP-LIMIT
CREATE _EXT4-JOT-EA-RANGE 2 CELLS ALLOT

\ A linked truncate always produces an empty data map.  Bind that after-image
\ to the representation authenticated in the raw inode: a canonical empty
\ inline extent root, or an exact all-zero legacy i_block array.  Comparing
\ the EXTENTS flag across both images prevents a staged representation switch.
: _EXT4-JOT-EMPTY-AFTERIMAGE-MAP?  ( expected-extents? after-inode -- flag )
    OVER
    OVER _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<> <> IF
        2DROP FALSE EXIT
    THEN
    OVER IF
        NIP _EXT4-I.BLOCK + DUP
        W@ _EXT4-EXTENT-MAGIC =
        OVER 2 + W@ 0= AND
        OVER 4 + W@ _EXT4-RESIDENT-EXTENT-ENTRY-MAX = AND
        OVER 6 + W@ 0= AND
        SWAP 12 + 48 _EXT4-BYTES-ZERO? AND
    ELSE
        NIP _EXT4-I.BLOCK + 60 _EXT4-BYTES-ZERO?
    THEN ;

: _EXT4-JOT-OWNER-CERT-MATCH?  ( -- flag )
    _EXT4-JFO-CERT-SCOPE @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-VALID @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-KIND @ _EXT4-JFO-CERT-JOT <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-CTX @ _EXT4-JOT-CTX @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-INO @
    _EXT4-JOT-RECORD @ _EXT4-OE.INO + @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-GEN @
    _EXT4-JOT-INODE @ _EXT4-I.GENERATION + L@ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-RANGE-COUNT @ _EXT4-JOT-COUNT @ <> IF
        FALSE EXIT
    THEN
    _EXT4-JFO-CERT-RANGE-COUNT @ _EXT4-JFO-CERT-RANGE-CAP U> IF
        FALSE EXIT
    THEN
    _EXT4-JFO-CERT-EA @ IF FALSE EXIT THEN
    _EXT4-JFO-CERT-EA-ACTION @ IF FALSE EXIT THEN
    _EXT4-JFO-CERT-EA-REFCOUNT @ IF FALSE EXIT THEN
    _EXT4-JFO-CERT-DATA-MAP-KIND @
    _EXT4-JDM-INLINE-EXTENTS <> IF FALSE EXIT THEN
    _EXT4-JOT-COUNT @ 0 ?DO
        I _EXT4-JOT-RANGE @ I _EXT4-JFO-CERT-RANGE @ <> IF
            FALSE UNLOOP EXIT
        THEN
        I _EXT4-JOT-RANGE CELL+ @
        I _EXT4-JFO-CERT-RANGE CELL+ @ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JOT-OWNER-CERT-STORE  ( -- )
    _EXT4-JFO-CERT-SCOPE @ 0= IF EXIT THEN
    0 _EXT4-JFO-CERT-VALID !
    _EXT4-JOT-CTX @ _EXT4-JFO-CERT-CTX !
    _EXT4-JOT-CTX @ _EXT4-OWNER-CERT-RANGE-WORKSPACE? 0= IF EXIT THEN
    _EXT4-JFO-CERT-RANGES 0= IF EXIT THEN
    _EXT4-JOT-COUNT @ _EXT4-JFO-CERT-RANGE-CAP U> IF EXIT THEN
    _EXT4-JFO-CERT-JOT _EXT4-JFO-CERT-KIND !
    _EXT4-JOT-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-CERT-INO !
    _EXT4-JOT-INODE @ _EXT4-I.GENERATION + L@
    _EXT4-JFO-CERT-GEN !
    _EXT4-JOT-COUNT @ _EXT4-JFO-CERT-RANGE-COUNT !
    0 _EXT4-JFO-CERT-EA !
    0 _EXT4-JFO-CERT-EA-ACTION !
    0 _EXT4-JFO-CERT-EA-REFCOUNT !
    _EXT4-JDM-INLINE-EXTENTS _EXT4-JFO-CERT-DATA-MAP-KIND !
    _EXT4-JFO-CERT-RANGES
    _EXT4-JFO-CERT-RANGE-CAP 2* CELLS 0 FILL
    _EXT4-JOT-COUNT @ 0 ?DO
        I _EXT4-JOT-RANGE @ I _EXT4-JFO-CERT-RANGE !
        I _EXT4-JOT-RANGE CELL+ @ I _EXT4-JFO-CERT-RANGE CELL+ !
    LOOP
    -1 _EXT4-JFO-CERT-VALID ! ;

\ Scan every other allocated inode once while all linked target ranges are
\ published.  The four-range table is the format capacity of a nonempty
\ inline depth-zero extent root, not a cleanup policy limit; an admitted empty
\ legacy map contributes no ranges.  A scoped certificate
\ retains the exact ctx/inode/generation/range tuple across measurement, dry
\ staging, abort, activation, restaging, and emission; checkpoint invalidates
\ it before the first home write can begin.
: _EXT4-JOT-REQUIRE-UNIQUE-DATA-OWNER  ( -- ior )
    _EXT4-JOT-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-JOT-COUNT @ _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JOT-OWNER-CERT-MATCH? IF 0 EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-JOT-CTX @ _EXT4-JFO-CTX !
    _EXT4-JOT-RECORD @ _EXT4-JFO-RECORD !
    _EXT4-JOT-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-JOT-OWNER-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-JOT-RANGES _EXT4-JOT-COUNT @
    _EXT4-RESIDENT-EXTENT-ENTRY-MAX
    _EXT4-MUTATION-OWNER-RANGES-PUBLISH
    ?DUP IF
        _EXT4-JOT-OWNER-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT ! EXIT
    THEN
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-JOT-OWNER-IOR !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-JOT-OWNER-IOR @ 0= IF
        _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
        _EXT4-REAUTH-ORPHAN-PLAN-RECORD _EXT4-JOT-OWNER-IOR !
    THEN
    _EXT4-JOT-OWNER-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JOT-OWNER-IOR @ 0= IF _EXT4-JOT-OWNER-CERT-STORE THEN
    _EXT4-JOT-OWNER-IOR @ ;

: _EXT4-JOT-CAPTURE-RANGES  ( -- ior )
    0 _EXT4-JOT-DATA-BLOCKS !
    _EXT4-JOT-COUNT @ 0 ?DO
        _EXT4-JOT-ROOT @ 12 I 12 * + + DUP _EXT4-JOT-ENTRY !
        _EXT4-EXTENT-LEN@ _EXT4-JOT-LEN !
        _EXT4-JOT-ENTRY @ 8 + L@ _EXT4-JOT-PHYS !
        _EXT4-JOT-EA @ IF
            _EXT4-JOT-PHYS @ _EXT4-JOT-LEN @
            _EXT4-JOT-EA @ 1 _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
        _EXT4-JOT-PHYS @ I _EXT4-JOT-RANGE !
        _EXT4-JOT-LEN @ I _EXT4-JOT-RANGE CELL+ !
        _EXT4-JOT-DATA-BLOCKS @ _EXT4-JOT-LEN @ _EXT4-UADD?
        DUP IF NIP UNLOOP EXIT THEN DROP _EXT4-JOT-DATA-BLOCKS !
    LOOP
    0 ;

: _EXT4-JOT-VALIDATE-ACCOUNTING  ( -- ior )
    _EXT4-JOT-DATA-BLOCKS @
    _EXT4-JOT-EA @ IF 1 ELSE 0 THEN
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    _EXT4-JOT-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-JOT-EXPECTED !
    _EXT4-JOT-INODE @ _EXT4-JOT-CTX @ _EXT4-DECODE-I-BLOCKS
    DUP IF NIP EXIT THEN DROP _EXT4-JOT-ACTUAL !
    _EXT4-JOT-ACTUAL @ _EXT4-JOT-EXPECTED @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Prove that neither a linked target's data ranges nor its retained external
\ xattr aliases any storage in the fully authenticated orphan-file map.  The
\ target root has at most four data ranges, while its independent xattr block
\ takes a second scoped pass rather than turning that format boundary into a
\ larger ambient-table policy limit.
: _EXT4-JOT-VALIDATE-ORPHAN-FILE-DISJOINT  ( -- ior )
    _EXT4-JOT-RANGES _EXT4-JOT-COUNT @
    _EXT4-RESIDENT-EXTENT-ENTRY-MAX
    _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
    _EXT4-ORPHAN-FILE-RANGES-DISJOINT ?DUP IF EXIT THEN
    _EXT4-JOT-EA @ IF
        _EXT4-JOT-EA @ _EXT4-JOT-EA-RANGE !
        1 _EXT4-JOT-EA-RANGE CELL+ !
        _EXT4-JOT-EA-RANGE 1 1
        _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
        _EXT4-ORPHAN-FILE-RANGES-DISJOINT ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JOT-PREFLIGHT  ( -- ior )
    _EXT4-JOT-INODE @ _EXT4-I.LINKS + W@ 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.SIZE-LO + L@
    _EXT4-JOT-INODE @ _EXT4-I.SIZE-HI + L@ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FLAGS + L@
    DUP _EXT4-JOURNAL-DATA-FL AND IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-EXTENTS-FL AND IF
        _EXT4-JOT-INODE @ _EXT4-I.BLOCK + DUP _EXT4-JOT-ROOT !
        DUP W@ _EXT4-EXTENT-MAGIC <> IF
            DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        DUP 4 + W@ _EXT4-RESIDENT-EXTENT-ENTRY-MAX <> IF
            DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        DUP 2 + W@ DUP _EXT4-JOT-COUNT !
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF
            DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        6 + W@ IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
    ELSE
        _EXT4-JOT-INODE @ _EXT4-I.BLOCK + DUP _EXT4-JOT-ROOT !
        60 _EXT4-BYTES-ZERO? 0= IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        0 _EXT4-JOT-COUNT !
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FILE-ACL-HI + W@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FILE-ACL-LO + L@ DUP _EXT4-JOT-EA ! IF
        _EXT4-JOT-EA @ EXT4-D-XATTR _EXT4-JOT-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOT-EA @ _EXT4-JOT-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JOT-CAPTURE-RANGES ?DUP IF EXIT THEN
    _EXT4-JOT-VALIDATE-ACCOUNTING ?DUP IF EXIT THEN
    _EXT4-JOT-VALIDATE-ORPHAN-FILE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-JOT-REQUIRE-UNIQUE-DATA-OWNER ;

\ Bind the retained record to its raw target inode and capture the complete
\ depth-zero ownership ranges without acquiring or changing a transaction.
\ The final orphan-file disjointness pass restores the target inode cache and
\ its _EXT4-IR locator before returning.
: _EXT4-JOT-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JOT-RECORD @ 0= _EXT4-JOT-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _EXT4-JOT-CTX @ _EXT4-C.INODE + _EXT4-JOT-INODE !
    _EXT4-JOT-PREFLIGHT ;

: _EXT4-JOT-BUILD-INODE  ( -- ior )
    _EXT4-JOT-WRITER @ _EXT4-JWR.SCRATCH-B + @ DUP
    _EXT4-JOT-AFTERIMAGE !
    _EXT4-JOT-INODE @ SWAP _EXT4-JOT-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOT-AFTERIMAGE @ _EXT4-I.FLAGS + L@
    _EXT4-EXTENTS-FL AND IF
        _EXT4-JOT-AFTERIMAGE @ _EXT4-I.BLOCK +
        0 OVER 2 + W!
        12 + 48 0 FILL
    THEN
    _EXT4-JOT-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0 _EXT4-JOT-AFTERIMAGE @ _EXT4-I.DTIME + L!
    THEN
    _EXT4-JOT-EA @ IF
        _EXT4-JOT-CTX @ _EXT4-C.SPB + @
    ELSE
        0
    THEN
    _EXT4-JOT-AFTERIMAGE @ _EXT4-JOT-CTX @ _EXT4-ENCODE-I-BLOCKS
    ?DUP IF EXIT THEN
    _EXT4-JOT-INODE @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<>
    _EXT4-JOT-AFTERIMAGE @
    _EXT4-JOT-EMPTY-AFTERIMAGE-MAP? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ If a lower range-free preflight fails, it has not necessarily published
\ enough state to trigger its own abort.  Once the inode image exists, this
\ outer operation owns the atomic discard boundary.  A lower auto-abort is
\ observable as IDLE and must not be aborted a second time.
: _EXT4-JOT-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JOT-IOR !
    _EXT4-JOT-PUBLISHED @ IF
        _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP
            _EXT4-JOT-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JOT-ABORT-IOR ! IF
                _EXT4-JOT-ABORT-IOR @
                _EXT4-JOT-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + !
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JOT-IOR @
                _EXT4-JOT-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + !
            THEN
        THEN
    THEN
    _EXT4-JOT-IOR @ ;

\ Complete the storage half of an interrupted linked-file truncation whose
\ new size is already zero and whose old map is either an inline depth-zero
\ extent root or an exact empty legacy i_block array.  The external xattr
\ block remains referenced.  An empty legacy map contributes no release
\ ranges or revokes, though legacy MORE still stages i_dtime clearing.  This
\ operation
\ leaves the authenticated orphan record active; the wrapper composes its
\ slot/list removal into this same transaction before the transaction seals.
: _EXT4-JTX-STAGE-LINKED-ORPHAN-TRUNCATE
  ( plan-record transaction -- ior )
    _EXT4-JOT-WRITER ! _EXT4-JOT-RECORD !
    0 _EXT4-JOT-PUBLISHED !
    _EXT4-JOT-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOT-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JOT-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOT-CTX !
    _EXT4-JOT-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JOT-COUNT @ 0= IF
        _EXT4-JOT-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN =
        _EXT4-JOT-RECORD @ _EXT4-OE.LOCATOR-A + @ 0= OR IF
            0 EXIT
        THEN
    THEN
    _EXT4-JOT-BUILD-INODE ?DUP IF EXIT THEN
    _EXT4-JOT-AFTERIMAGE @ _EXT4-JOT-RECORD @ _EXT4-JOT-WRITER @
    _EXT4-JTX-STAGE-ORPHAN-INODE ?DUP IF EXIT THEN
    -1 _EXT4-JOT-PUBLISHED !
    _EXT4-JOT-COUNT @ 0 ?DO
        I _EXT4-JOT-RANGE @
        I _EXT4-JOT-RANGE CELL+ @
        _EXT4-JOT-WRITER @ _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
        ?DUP IF _EXT4-JOT-FAIL-AFTER-PUBLISH UNLOOP EXIT THEN
    LOOP
    0 ;

VARIABLE _EXT4-JFC-RECORD
VARIABLE _EXT4-JFC-WRITER
VARIABLE _EXT4-JFC-CTX
VARIABLE _EXT4-JFC-INO
VARIABLE _EXT4-JFC-LOGICAL
VARIABLE _EXT4-JFC-SLOT
VARIABLE _EXT4-JFC-TARGET-GEN
VARIABLE _EXT4-JFC-TARGET-HOME
VARIABLE _EXT4-JFC-TARGET-OFF
VARIABLE _EXT4-JFC-TARGET-ENTRIES
VARIABLE _EXT4-JFC-O-HOME
VARIABLE _EXT4-JFC-O-GEN
VARIABLE _EXT4-JFC-INDEX
VARIABLE _EXT4-JFC-FOUND
VARIABLE _EXT4-JFC-IOR
VARIABLE _EXT4-JFC-ENTRY
VARIABLE _EXT4-JFC-IMAGE
VARIABLE _EXT4-JFC-TARGET-CRC
VARIABLE _EXT4-JFC-ORPHAN-CRC
VARIABLE _EXT4-JFC-ABORT-IOR
VARIABLE _EXT4-JFC-KIND
VARIABLE _EXT4-JFC-MODE
VARIABLE _EXT4-JFC-SUPER
VARIABLE _EXT4-JFC-TARGET
VARIABLE _EXT4-JFC-RAW-EXTENTS
VARIABLE _EXT4-JFC-DELETE
VARIABLE _EXT4-JFC-INODE-BITMAP-HOME
VARIABLE _EXT4-JFC-INODE-BITMAP-CRC
VARIABLE _EXT4-JFC-INODE-GDT-HOME
VARIABLE _EXT4-JFC-INODE-GDT-OFF
VARIABLE _EXT4-JFC-INODE-GDT-CRC
VARIABLE _EXT4-JFC-INODE-SUPER-CRC

: _EXT4-JFC-FIND-META  ( home writer -- ior )
    DUP _EXT4-JFC-WRITER ! >R
    R@ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    R@ _EXT4-JWR.META-HASH + @
    R@ _EXT4-JWR.META-SLOTS + @
    R@ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND
    _EXT4-JFC-IOR ! _EXT4-JFC-FOUND ! _EXT4-JFC-INDEX !
    R> DROP
    _EXT4-JFC-IOR @ ?DUP IF EXIT THEN
    0 _EXT4-JFC-ENTRY ! 0 _EXT4-JFC-IMAGE !
    _EXT4-JFC-FOUND @ 0= IF 0 EXIT THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JFC-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JFC-IMAGE ! _EXT4-JFC-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JFD-RECORD
VARIABLE _EXT4-JFD-WRITER
VARIABLE _EXT4-JFD-CTX
VARIABLE _EXT4-JFD-RAW-DESC
VARIABLE _EXT4-JFD-STAGED-DESC
VARIABLE _EXT4-JFD-RAW-GROUP-FREE
VARIABLE _EXT4-JFD-EXPECTED-GROUP-FREE
VARIABLE _EXT4-JFD-RAW-SUPER-FREE
VARIABLE _EXT4-JFD-EXPECTED-SUPER-FREE
VARIABLE _EXT4-JFD-BITMAP-CHECKSUM
VARIABLE _EXT4-JFD-RAW-BITMAP
VARIABLE _EXT4-JFD-STAGED-BITMAP
VARIABLE _EXT4-JFD-BITMAP-BYTE
VARIABLE _EXT4-JFD-BITMAP-MASK
VARIABLE _EXT4-JFD-COMPARE-OFF
VARIABLE _EXT4-JFD-COMPARE-LEN
VARIABLE _EXT4-JFD-RAW-GDT
VARIABLE _EXT4-JFD-STAGED-GDT
VARIABLE _EXT4-JFD-RAW-SUPER-HOME
VARIABLE _EXT4-JFD-STAGED-SUPER-HOME
VARIABLE _EXT4-JFD-RAW-SUPER
VARIABLE _EXT4-JFD-RAW-TARGET-HOME
VARIABLE _EXT4-JFD-STAGED-TARGET-HOME

: _EXT4-JFD-TARGET-HOME-EXACT?  ( -- flag )
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ 0 ?DO
        _EXT4-JFD-RAW-TARGET-HOME @ I + C@
        I _EXT4-JFI-INODE-OFF @ >=
        I _EXT4-JFI-INODE-OFF @
        _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ + U< AND IF
            DROP 0
        THEN
        _EXT4-JFD-STAGED-TARGET-HOME @ I + C@ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFD-REQUIRE-ZERO-TARGET  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JFD-RAW-TARGET-HOME !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
    _EXT4-JFC-IMAGE @ _EXT4-JFD-STAGED-TARGET-HOME !
    _EXT4-JFD-TARGET-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JFD-BITMAP-EXACT?  ( -- flag )
    _EXT4-JFI-INDEX @ DUP 8 / _EXT4-JFD-BITMAP-BYTE !
    8 MOD 1 SWAP LSHIFT _EXT4-JFD-BITMAP-MASK !
    \ The journal entry replaces the whole home block.  Bytes beyond the
    \ meaningful inode-bit count are padding, but they are still part of the
    \ after-image and therefore must remain byte-identical.
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ 0 ?DO
        _EXT4-JFD-RAW-BITMAP @ I + C@
        I _EXT4-JFD-BITMAP-BYTE @ = IF
            _EXT4-JFD-BITMAP-MASK @ INVERT AND
        THEN
        _EXT4-JFD-STAGED-BITMAP @ I + C@ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFD-DESC-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-GDT-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-GDT-EXACT?  ( -- flag )
    \ Permit only the target descriptor's free-inode count, inode-bitmap
    \ checksum, and descriptor checksum.  Other descriptors and page padding
    \ are just as authoritative as the target descriptor itself.
    0 _EXT4-JFI-GDT-OFF @ 0x0E + _EXT4-JFD-GDT-RANGE-UNCHANGED?
    _EXT4-JFI-GDT-OFF @ 0x10 + 0x0A
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x1C + 0x02
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x20 + 0x0E
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x30 + 0x0A
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x3C + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-SUPER-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-EXACT?  ( -- flag )
    \ Bytes before the embedded superblock are part of block zero on 2K/4K
    \ filesystems.  Preserve them along with every super field except the
    \ free-inode count, the legacy head transition, and the checksum stamp.
    0 _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x10 +
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?
    0x14
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xE8 0x14 -
    ELSE
        0x3FC 0x14 -
    THEN
    _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xEC 0x3FC 0xEC - _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x400 + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-DESC-UNCHANGED?  ( -- flag )
    \ The only semantic changes are the split free-inode counter and the
    \ split inode-bitmap checksum.  The descriptor checksum is restamped.
    \ Compare every remaining byte, including exclude-bitmap and reserved
    \ fields, instead of maintaining a permissive list of named fields.
    0x00 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED?
    0x10 0x0A _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x1C 0x02 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x20 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x30 0x0A _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x3C 0x04 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND ;

\ Reconstruct the sole permitted shared-xattr transition from authenticated
\ raw media and require the retained journal image to match byte for byte.
\ This binds the staged action to h_refcount-1 and the corresponding checksum,
\ while every entry, value, hash, and reserved byte remains unchanged.
: _EXT4-JFD-REQUIRE-EA-REFDEC  ( -- ior )
    _EXT4-JFI-EA-REFDEC? 0= IF
        0 _EXT4-JFI-EA-AFTER-CRC !
        -1 _EXT4-JFI-EA-AFTER-VERIFIED ! 0 EXIT
    THEN
    _EXT4-JFI-EA @ _EXT4-JFD-CTX @ _EXT4-LOAD-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-XB-BUF @ 4 + L@ _EXT4-JFI-EA-REFCOUNT @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-XB-BUF @ _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFI-EA-POST-REFCOUNT
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK + 4 + L!
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-EA @ _EXT4-JFD-CTX @ _EXT4-STAMP-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-EA @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-JFC-IMAGE @
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFD-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-JFI-EA-AFTER-CRC !
    _EXT4-JFC-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
    -1 _EXT4-JFI-EA-AFTER-VERIFIED !
    0 ;

\ Rebuild raw unlinked-inode authority, then prove the complete staged
\ allocation transition: one cleared bitmap bit, its matching descriptor
\ checksum/counter update, and the matching primary-super counter update.
: _EXT4-JFD-VERIFY-EMPTY-STAGED  ( plan-record writer -- ior )
    DUP _EXT4-JFD-WRITER ! _EXT4-JFC-WRITER !
    _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JFD-CTX !
    _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFD-WRITER @ _EXT4-JFI-REVOKES-EXACT? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + _EXT4-JFD-RAW-BITMAP !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFD-RAW-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-EXPECTED-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-INODES + L@
    DUP _EXT4-JFD-RAW-SUPER-FREE ! 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFD-EXPECTED-SUPER-FREE !
    _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-BITMAP-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-BITMAP !
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-BITMAP-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFD-BITMAP-CHECKSUM !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-GDT !
    _EXT4-JFI-GDT-OFF @ + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-GDT-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-GDT !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFD-STAGED-DESC !
    _EXT4-JFD-GDT-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-DESC-UNCHANGED? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFD-BITMAP-CHECKSUM @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-FREE@
    _EXT4-JFD-EXPECTED-GROUP-FREE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-SUPER-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFC-SUPER ! DROP
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFD-RAW-SUPER !
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-SUPER-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @
    DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JFD-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-SB.FREE-INODES + L@
    _EXT4-JFD-EXPECTED-SUPER-FREE @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-LO + L@ <>
    OVER _EXT4-SB.FREE-BLOCKS-HI + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-HI + L@ <> OR IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <>
    SWAP _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-EA-REFDEC ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        5
    ELSE
        4
    THEN
    _EXT4-JFI-EA-REFDEC? IF 1+ THEN
    DUP _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @ <>
    OVER _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @ <> OR
    SWAP _EXT4-JFD-WRITER @ _EXT4-JWR.META-ACTIVE + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JDD-EXPECTED
VARIABLE _EXT4-JDD-HOME
VARIABLE _EXT4-JDD-IOR
VARIABLE _EXT4-JDD-DATA-BITMAP-HOME
VARIABLE _EXT4-JDD-DATA-BITMAP-CRC
VARIABLE _EXT4-JDD-INODE-BITMAP-CRC
VARIABLE _EXT4-JDD-DATA-GDT-HOME
VARIABLE _EXT4-JDD-DATA-GDT-OFF
VARIABLE _EXT4-JDD-PAGE-GDT-HOME
VARIABLE _EXT4-JDD-PAGE-ACTIVE
VARIABLE _EXT4-JDD-INODE-GDT-DONE
VARIABLE _EXT4-JDD-DESC
VARIABLE _EXT4-JDD-FREE
VARIABLE _EXT4-JDD-CHANGED
VARIABLE _EXT4-JDD-GDT-CRC
VARIABLE _EXT4-JDD-SUPER-HOME
VARIABLE _EXT4-JDD-SUPER
VARIABLE _EXT4-JDD-EXPECTED-CREDIT
VARIABLE _EXT4-JDD-GROUP
VARIABLE _EXT4-JDD-GROUP-FIRST
VARIABLE _EXT4-JDD-GROUP-END
VARIABLE _EXT4-JDD-RANGE-INDEX
VARIABLE _EXT4-JDD-RANGE-FIRST
VARIABLE _EXT4-JDD-RANGE-COUNT
VARIABLE _EXT4-JDD-RANGE-END
VARIABLE _EXT4-JDD-CHUNK-FIRST
VARIABLE _EXT4-JDD-GROUP-RELEASED
VARIABLE _EXT4-JDD-RELEASED-TOTAL
VARIABLE _EXT4-JDD-GROUP-TOUCHED

: _EXT4-JDD-REQUIRE-EXPECTED  ( expected home -- crc ior )
    _EXT4-JDD-HOME ! _EXT4-JDD-EXPECTED !
    _EXT4-JDD-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-EXPECTED @ _EXT4-JFC-IMAGE @
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ 0 ;

: _EXT4-JDD-ADD-CREDIT  ( -- ior )
    _EXT4-JDD-EXPECTED-CREDIT @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-EXPECTED-CREDIT !
    0 ;

: _EXT4-JDD-SET-GROUP-RANGE  ( -- ior )
    _EXT4-JDD-GROUP @ _EXT4-JFB-GROUP !
    _EXT4-JDD-GROUP @ _EXT4-JFD-CTX @ _EXT4-GROUP-BLOCK-RANGE
    _EXT4-JDD-IOR ! _EXT4-JFB-GROUP-BLOCKS !
    _EXT4-JDD-GROUP-FIRST !
    _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JDD-GROUP-FIRST @ _EXT4-JFB-GROUP-BLOCKS @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-GROUP-END !
    0 ;

\ Intersect one retained physical range with the current group.  Publish the
\ group-local bitmap index and exact overlap count only when nonempty.
: _EXT4-JDD-SELECT-RANGE-CHUNK  ( range-index -- flag ior )
    _EXT4-JFI-RELEASE-RANGE DUP @ _EXT4-JDD-RANGE-FIRST !
    CELL+ @ DUP _EXT4-JDD-RANGE-COUNT !
    _EXT4-JDD-RANGE-FIRST @ SWAP _EXT4-UADD?
    DUP IF NIP FALSE SWAP EXIT THEN DROP _EXT4-JDD-RANGE-END !
    _EXT4-JDD-RANGE-FIRST @ _EXT4-JDD-GROUP-FIRST @ MAX
    _EXT4-JDD-CHUNK-FIRST !
    _EXT4-JDD-RANGE-END @ _EXT4-JDD-GROUP-END @ MIN
    DUP _EXT4-JDD-CHUNK-FIRST @ U<
    OVER _EXT4-JDD-CHUNK-FIRST @ = OR IF
        DROP FALSE 0 EXIT
    THEN
    _EXT4-JDD-CHUNK-FIRST @ - _EXT4-JFB-CHUNK !
    _EXT4-JDD-CHUNK-FIRST @ _EXT4-JDD-GROUP-FIRST @ -
    _EXT4-JFB-INDEX !
    TRUE 0 ;

: _EXT4-JDD-GROUP-TOUCHED?  ( -- flag ior )
    _EXT4-JDD-SET-GROUP-RANGE ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JDD-RANGE-INDEX !
    BEGIN
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JFI-RELEASE-RANGE-COUNT U<
    WHILE
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JDD-SELECT-RANGE-CHUNK
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF FALSE SWAP EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF TRUE 0 EXIT THEN
        1 _EXT4-JDD-RANGE-INDEX +!
    REPEAT
    FALSE 0 ;

\ Reconstruct one complete block-bitmap after-image for a touched group.  All
\ discontiguous target overlaps are applied to one raw copy before comparison,
\ so shared bitmap and descriptor homes are authenticated exactly once.
: _EXT4-JDD-AUTH-DATA-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR ! _EXT4-JDD-DATA-BITMAP-HOME !
    _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JFB-GROUP @
    _EXT4-JFD-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @ _EXT4-JDD-DATA-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JDD-DATA-GDT-OFF !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JDD-GROUP-RELEASED !
    0 _EXT4-JDD-RANGE-INDEX !
    BEGIN
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JFI-RELEASE-RANGE-COUNT U<
    WHILE
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JDD-SELECT-RANGE-CHUNK
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF
            _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @
            _EXT4-BIT-RANGE-SET? 0= IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @
            _EXT4-CLEAR-BIT-RANGE
            _EXT4-JDD-GROUP-RELEASED @ _EXT4-JFB-CHUNK @ _EXT4-UADD?
            DUP IF NIP EXIT THEN DROP _EXT4-JDD-GROUP-RELEASED !
        THEN
        1 _EXT4-JDD-RANGE-INDEX +!
    REPEAT
    _EXT4-JDD-GROUP-RELEASED @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-RELEASED-TOTAL @ _EXT4-JDD-GROUP-RELEASED @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-RELEASED-TOTAL !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JDD-DATA-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JDD-ADD-CREDIT ;

: _EXT4-JDD-REQUIRE-INODE-BITMAP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JDD-INODE-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-BITMAP-CRC !
    0 ;

: _EXT4-JDD-MUTATE-DATA-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE@
    _EXT4-JDD-GROUP-RELEASED @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JFB-GROUP-BLOCKS @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JDD-DATA-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JDD-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

: _EXT4-JDD-MUTATE-INODE-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JDD-INODE-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

\ Hold one raw primary-GDT page in DIR-BLOCK while every data-group
\ descriptor on that page is reconstructed.  This preserves exact whole-home
\ comparison when a multi-block extent crosses groups whose descriptors
\ coalesce into one journal after-image.
: _EXT4-JDD-BEGIN-GDT-PAGE  ( home -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JDD-PAGE-GDT-HOME !
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JDD-CHANGED !
    -1 _EXT4-JDD-PAGE-ACTIVE !
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ <> IF
        _EXT4-JDD-ADD-CREDIT EXIT
    THEN
    0 ;

: _EXT4-JDD-FINISH-GDT-PAGE  ( -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ 0= IF 0 EXIT THEN
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JDD-INODE-GDT-DONE @ IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JFI-GDT-OFF @ + _EXT4-JDD-MUTATE-INODE-DESC
        ?DUP IF EXIT THEN
        -1 _EXT4-JDD-CHANGED !
        -1 _EXT4-JDD-INODE-GDT-DONE !
    THEN
    _EXT4-JDD-CHANGED @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-PAGE-GDT-HOME @
    _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-GDT-CRC !
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JDD-GDT-CRC @ _EXT4-JFC-INODE-GDT-CRC !
    THEN
    0 _EXT4-JDD-PAGE-ACTIVE !
    0 ;

: _EXT4-JDD-REQUIRE-DATA-GDT  ( -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ 0= IF
        _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
        ?DUP IF EXIT THEN
    ELSE
        _EXT4-JDD-DATA-GDT-HOME @
        _EXT4-JDD-PAGE-GDT-HOME @ <> IF
            _EXT4-JDD-DATA-GDT-HOME @
            _EXT4-JDD-PAGE-GDT-HOME @ U< IF
                EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
            _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
            ?DUP IF EXIT THEN
        THEN
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-DATA-GDT-OFF @ + _EXT4-JDD-MUTATE-DATA-DESC
    ?DUP IF EXIT THEN
    -1 _EXT4-JDD-CHANGED !
    0 ;

: _EXT4-JDD-REQUIRE-DATA-PAGES  ( -- ior )
    0 _EXT4-JDD-PAGE-ACTIVE !
    0 _EXT4-JDD-INODE-GDT-DONE !
    0 _EXT4-JDD-RELEASED-TOTAL !
    0 _EXT4-JDD-GROUP !
    BEGIN
        _EXT4-JDD-GROUP @ _EXT4-JFD-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JDD-GROUP-TOUCHED?
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF
            _EXT4-JDD-AUTH-DATA-GROUP ?DUP IF EXIT THEN
            _EXT4-JDD-REQUIRE-DATA-GDT ?DUP IF EXIT THEN
        THEN
        1 _EXT4-JDD-GROUP +!
    REPEAT
    _EXT4-JDD-RELEASED-TOTAL @ _EXT4-JFI-RELEASE-BLOCKS <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
    _EXT4-JDD-INODE-GDT-DONE @ 0= IF
        _EXT4-JFI-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
        ?DUP IF EXIT THEN
        _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JDD-REQUIRE-SUPER  ( -- ior )
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP
    _EXT4-JDD-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF + _EXT4-JDD-SUPER !
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFI-RELEASE-BLOCKS
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JFD-RECORD @ _EXT4-OE.INO + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFD-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    THEN
    _EXT4-JDD-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JDD-SUPER @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-SUPER @ _EXT4-JFD-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-SUPER-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-SUPER-CRC !
    0 ;


: _EXT4-JDD-VERIFY-STAGED  ( -- ior )
    _EXT4-JFI-RANGE-COUNT _EXT4-JFI-RANGE-CAP U>
    _EXT4-JFI-RELEASE-RANGE-COUNT 0= OR
    _EXT4-JFI-RELEASE-BLOCKS 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        5
    ELSE
        4
    THEN _EXT4-JDD-EXPECTED-CREDIT !
    _EXT4-JDD-REQUIRE-INODE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JDD-REQUIRE-DATA-PAGES ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-EA-REFDEC ?DUP IF EXIT THEN
    _EXT4-JFI-EA-REFDEC? IF
        _EXT4-JDD-ADD-CREDIT ?DUP IF EXIT THEN
    THEN
    _EXT4-JDD-REQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JDD-EXPECTED-CREDIT @ <>
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JDD-EXPECTED-CREDIT @ <> OR
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JDD-EXPECTED-CREDIT @ <> OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JFD-VERIFY-STAGED  ( plan-record writer -- ior )
    _EXT4-JFD-WRITER ! _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JFC-WRITER !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JFD-CTX ! _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-RELEASE-RANGE-COUNT IF _EXT4-JDD-VERIFY-STAGED EXIT THEN
    _EXT4-JFD-RECORD @ _EXT4-JFD-WRITER @
    _EXT4-JFD-VERIFY-EMPTY-STAGED ;

: _EXT4-JFC-FAIL  ( ior -- ior )
    _EXT4-JFC-IOR !
    _EXT4-JFC-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = IF
        DROP _EXT4-JFC-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFC-ABORT-IOR ! IF
            _EXT4-JFC-ABORT-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    ELSE
        DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
            _EXT4-JFC-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    THEN
    _EXT4-JFC-IOR @ ;

VARIABLE _EXT4-SMO-RECORD
VARIABLE _EXT4-SMO-CTX
VARIABLE _EXT4-SMO-KIND

\ Require the exact record selected by the recovery order before dereferencing
\ any of its fields.  A legacy mutation may remove only the current raw list
\ head.  Modern records are selected only after that chain is empty; their
\ locator order is imposed by the selector below rather than hash placement.
: _EXT4-REQUIRE-SELECTED-ORPHAN
  ( plan-record ctx -- ior )
    _EXT4-SMO-CTX ! _EXT4-SMO-RECORD !
    _EXT4-SMO-RECORD @ 0= _EXT4-SMO-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-SMO-CTX @ _EXT4-C.O.ACTIVE + @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-SMO-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-SMO-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ 0=
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0<> OR IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.LAST-ORPHAN + L@ IF
            DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@ _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
            I _EXT4-SMO-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
                DUP _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
                    DUP _EXT4-OE.LOCATOR-A + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-A + @ U<
                    OVER _EXT4-OE.LOCATOR-A + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-A + @ =
                    2 PICK _EXT4-OE.LOCATOR-B + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-B + @ U< AND OR IF
                        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                        UNLOOP EXIT
                    THEN
                THEN
            THEN
            DROP
        LOOP
    ELSE
        _EXT4-SMO-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-B + @ IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-SMO-RECORD @ _EXT4-OE.INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ;

: _EXT4-JFC-REQUIRE-SELECTED  ( -- ior )
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ;

VARIABLE _EXT4-JLH-RECORD
VARIABLE _EXT4-JLH-WRITER
VARIABLE _EXT4-JLH-CTX
VARIABLE _EXT4-JLH-INO
VARIABLE _EXT4-JLH-NEXT
VARIABLE _EXT4-JLH-IMAGE
VARIABLE _EXT4-JLH-SUPER
VARIABLE _EXT4-JLH-HOME

\ Advance the current legacy-list head to its authenticated retained successor
\ in the transaction-aware primary-super after-image.  Block-free accounting
\ may have edited this same super image first; acquire composes with and
\ reauthenticates that edit.
: _EXT4-JTX-ADVANCE-LEGACY-HEAD
  ( plan-record transaction -- ior )
    _EXT4-JLH-WRITER ! _EXT4-JLH-RECORD !
    _EXT4-JLH-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JLH-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JLH-RECORD @ _EXT4-JLH-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.INO + @ _EXT4-JLH-INO !
    _EXT4-JLH-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JLH-NEXT !
    _EXT4-JLH-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JLH-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JLH-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JLH-IMAGE !
    _EXT4-JLH-HOME @ _EXT4-JLH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JLH-INO @ <> IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JLH-NEXT @ _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    _EXT4-JLH-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JLH-IMAGE @ _EXT4-JLH-HOME @ _EXT4-JLH-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JCM-RECORD
VARIABLE _EXT4-JCM-CTX
VARIABLE _EXT4-JCM-ORPHAN-HOME
VARIABLE _EXT4-JCM-INODE-HOME
VARIABLE _EXT4-JCM-SUPER-HOME
VARIABLE _EXT4-JCM-GROUP
VARIABLE _EXT4-JCM-GROUP-FIRST
VARIABLE _EXT4-JCM-GROUP-COUNT
VARIABLE _EXT4-JCM-RANGE-INDEX
VARIABLE _EXT4-JCM-TOUCHED
VARIABLE _EXT4-JCM-BITMAP-HOME
VARIABLE _EXT4-JCM-GDT-HOME
VARIABLE _EXT4-JCM-PREV-GDT
VARIABLE _EXT4-JCM-HAVE-GDT
VARIABLE _EXT4-JCM-HAVE-GROUP
VARIABLE _EXT4-JCM-CREDIT
VARIABLE _EXT4-JCM-IOR
VARIABLE _EXT4-JCM-KIND
VARIABLE _EXT4-JCM-DELETE

: _EXT4-JCM-RANGE-COUNT  ( -- count )
    _EXT4-JCM-DELETE @ IF
        _EXT4-JFI-RELEASE-RANGE-COUNT
    ELSE
        _EXT4-JOT-COUNT @
    THEN ;

: _EXT4-JCM-RANGE  ( index -- pair-address )
    _EXT4-JCM-DELETE @ IF
        _EXT4-JFI-RELEASE-RANGE
    ELSE
        _EXT4-JOT-RANGE
    THEN ;

: _EXT4-JCM-GROUP-TOUCHED?  ( group -- flag ior )
    DUP _EXT4-JCM-GROUP ! _EXT4-JCM-CTX @ _EXT4-GROUP-BLOCK-RANGE
    _EXT4-JCM-IOR ! _EXT4-JCM-GROUP-COUNT !
    _EXT4-JCM-GROUP-FIRST !
    _EXT4-JCM-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JCM-RANGE-INDEX !
    BEGIN
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JCM-RANGE-COUNT U<
    WHILE
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JCM-RANGE DUP @
        SWAP CELL+ @
        _EXT4-JCM-GROUP-FIRST @ _EXT4-JCM-GROUP-COUNT @
        _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE 0 EXIT THEN
        1 _EXT4-JCM-RANGE-INDEX +!
    REPEAT
    FALSE 0 ;

: _EXT4-JCM-ADD-CREDIT  ( -- ior )
    _EXT4-JCM-CREDIT @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JCM-CREDIT !
    0 ;

: _EXT4-JCM-BASE-DISJOINT?  ( -- flag )
    _EXT4-JCM-INODE-HOME @ _EXT4-JCM-SUPER-HOME @ = IF FALSE EXIT THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-INODE-HOME @ =
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-SUPER-HOME @ = OR 0= ;

: _EXT4-JCM-GROUP-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GDT-HOME @ =
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR IF FALSE EXIT THEN
    _EXT4-JCM-DELETE @ IF
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-BITMAP-HOME @ =
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ = OR
        _EXT4-JCM-GDT-HOME @ _EXT4-JFI-BITMAP-HOME @ = OR IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-ORPHAN-HOME @ =
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-ORPHAN-HOME @ = OR 0= ;

: _EXT4-JCM-DELETE-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ =
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JCM-SUPER-HOME @ _EXT4-JFI-INODE-HOME @ = OR IF
        FALSE EXIT
    THEN
    _EXT4-JFI-EA @ ?DUP IF
        DUP _EXT4-JFI-BITMAP-HOME @ =
        OVER _EXT4-JFI-GDT-HOME @ = OR
        OVER _EXT4-JCM-SUPER-HOME @ = OR
        SWAP _EXT4-JFI-INODE-HOME @ = OR IF FALSE EXIT THEN
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-BITMAP-HOME @ =
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-GDT-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JFI-EA @ IF
        _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-EA @ = OR
    THEN 0= ;

: _EXT4-JCM-VALIDATE-RANGES  ( -- ior )
    _EXT4-JCM-DELETE @ IF
        _EXT4-JFI-RANGE-COUNT IF
            _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT
            _EXT4-JFI-RANGE-CAP
            _EXT4-JCM-CTX @ _EXT4-VALIDATE-MUTATION-RANGES-TARGETS
            ?DUP IF EXIT THEN
        THEN
        _EXT4-JFI-EA @ IF
            _EXT4-JFI-EA @ 1 _EXT4-JCM-CTX @
            _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        THEN
        0 EXIT
    THEN
    _EXT4-JOT-RANGES _EXT4-JCM-RANGE-COUNT
    _EXT4-RESIDENT-EXTENT-ENTRY-MAX _EXT4-JCM-CTX @
    _EXT4-VALIDATE-MUTATION-RANGES-TARGETS ;

: _EXT4-JCM-COUNT-GROUP-HOMES  ( -- ior )
    0 _EXT4-JCM-GROUP !
    0 _EXT4-JCM-HAVE-GDT !
    0 _EXT4-JCM-HAVE-GROUP !
    BEGIN
        _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JCM-GROUP @ _EXT4-JCM-GROUP-TOUCHED?
        _EXT4-JCM-IOR ! _EXT4-JCM-TOUCHED !
        _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
        _EXT4-JCM-TOUCHED @ IF
            -1 _EXT4-JCM-HAVE-GROUP !
            _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @
            _EXT4-LOAD-BLOCK-BITMAP
            _EXT4-JCM-IOR ! _EXT4-JCM-BITMAP-HOME !
            _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
            _EXT4-GD-BLOCK @ _EXT4-JCM-GDT-HOME !
            _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GROUP @
            _EXT4-JCM-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME
            ?DUP IF EXIT THEN
            _EXT4-JCM-GROUP-HOMES-DISJOINT? 0= IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
            _EXT4-JCM-DELETE @
            _EXT4-JCM-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = AND 0= IF
                _EXT4-JCM-HAVE-GDT @ IF
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ U< IF
                        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ <> IF
                        _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    THEN
                ELSE
                    _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    -1 _EXT4-JCM-HAVE-GDT !
                THEN
                _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT !
            THEN
        THEN
        1 _EXT4-JCM-GROUP +!
    REPEAT
    _EXT4-JCM-HAVE-GROUP @ 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Derive the exact coalesced metadata-home credit for one authenticated orphan
\ cleanup.  Every delete includes the zeroed inode-table block,
\ inode bitmap, primary GDT, primary superblock, and (for modern authority)
\ orphan-file block.  Any released data or external-xattr allocation adds one
\ uniquely owned block bitmap per touched group and one primary GDT block per
\ distinct descriptor page.
\ The group scan is constant-space and imposes no policy capacity beyond the
\ authenticated filesystem geometry.

: _EXT4-JCM-MEASURE-DELETE  ( -- meta-credit ior )
    _EXT4-JCM-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JCM-CTX @ _EXT4-JFI-CTX !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JCM-INODE-HOME !
    _EXT4-JCM-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCM-SUPER-HOME !
    _EXT4-JCM-DELETE-HOMES-DISJOINT? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF 5 ELSE 4 THEN
    _EXT4-JCM-CREDIT !
    _EXT4-JFI-EA-REFDEC? IF
        _EXT4-JCM-ADD-CREDIT ?DUP IF 0 SWAP EXIT THEN
    THEN
    _EXT4-JFI-RELEASE-RANGE-COUNT 0= IF
        _EXT4-JCM-CREDIT @ 0 EXIT
    THEN
    _EXT4-JCM-VALIDATE-RANGES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-COUNT-GROUP-HOMES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-CREDIT @ 0 ;

: _EXT4-JCM-MEASURE-ORPHAN-META
  ( plan-record ctx -- meta-credit ior )
    _EXT4-JCM-CTX ! _EXT4-JCM-RECORD !
    _EXT4-JCM-RECORD @ 0= _EXT4-JCM-CTX @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JCM-RECORD @ _EXT4-JCM-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-RECORD @ _EXT4-OE.KIND + @ _EXT4-JCM-KIND !
    _EXT4-JCM-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0=
    _EXT4-JCM-DELETE !
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JCM-RECORD @ _EXT4-JOS-RECORD !
        _EXT4-JCM-CTX @ _EXT4-JOS-CTX !
        _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
        _EXT4-JOS-HOME @ _EXT4-JCM-ORPHAN-HOME !
    ELSE
        0 _EXT4-JCM-ORPHAN-HOME !
        _EXT4-JCM-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
        ?DUP IF 0 SWAP EXIT THEN
    THEN
    _EXT4-JCM-DELETE @ IF
        _EXT4-JCM-MEASURE-DELETE EXIT
    THEN
    _EXT4-JCM-RECORD @ _EXT4-JOT-RECORD !
    _EXT4-JCM-CTX @ _EXT4-JOT-CTX !
    _EXT4-JOT-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
    _EXT4-IR-BLOCK @ _EXT4-JCM-INODE-HOME !
    _EXT4-JCM-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCM-SUPER-HOME !
    _EXT4-JOT-COUNT @ 0= IF
        _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF
            _EXT4-JCM-BASE-DISJOINT? 0= IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JCM-RECORD @ _EXT4-OE.LOCATOR-A + @ IF
                2 0 EXIT
            THEN
        THEN
        1 0 EXIT
    THEN
    _EXT4-JCM-VALIDATE-RANGES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-BASE-DISJOINT? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF 3 ELSE 2 THEN
    _EXT4-JCM-CREDIT !
    _EXT4-JCM-COUNT-GROUP-HOMES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-CREDIT @ 0 ;

: _EXT4-MEASURE-ORPHAN-CLEANUP
  ( plan-record ctx -- meta-credit revoke-credit ior )
    _EXT4-JCM-MEASURE-ORPHAN-META
    DUP IF NIP 0 0 ROT EXIT THEN
    DROP
    _EXT4-JCM-DELETE @ IF _EXT4-JFI-REVOKE-COUNT ELSE 0 THEN
    0 ;

: _EXT4-JFC-SEAL-MODERN-PROTOCOL  ( -- ior )
    _EXT4-JFC-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFC-LOGICAL @ _EXT4-JFC-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JFC-O-HOME !
    _EXT4-OV-GEN @ _EXT4-JFC-O-GEN !
    _EXT4-JFC-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-SLOT @ 4 * + L@
    _EXT4-JFC-INO @ <> IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-SLOT @ 4 * + L@ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-O-HOME @
    _EXT4-JFC-CTX @ _EXT4-C.ORPHAN-INO + @ _EXT4-JFC-O-GEN @
    _EXT4-JFC-CTX @ _EXT4-ORPHAN-BLOCK-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
        _EXT4-JCPM-ORPHAN-MODERN-FINAL
    ELSE
        _EXT4-JCPM-ORPHAN-MODERN-MORE
    THEN _EXT4-JFC-MODE !
    0 ;

: _EXT4-JFC-SEAL-LEGACY-PROTOCOL  ( -- ior )
    0 _EXT4-JFC-SLOT !
    _EXT4-JFC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFC-O-HOME !
    _EXT4-JPS-RAW-CRC @ _EXT4-JFC-O-GEN !
    _EXT4-JPS-RAW @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-INO @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JPS-SUPER @ DUP _EXT4-JFC-SUPER !
    _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-LOGICAL @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-LOGICAL @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
        _EXT4-JCPM-ORPHAN-LEGACY-FINAL
    ELSE
        _EXT4-JCPM-ORPHAN-LEGACY-MORE
    THEN _EXT4-JFC-MODE !
    0 ;

: _EXT4-JFC-SEAL  ( -- ior )
    0 _EXT4-JFC-INODE-BITMAP-HOME !
    0 _EXT4-JFC-INODE-BITMAP-CRC !
    0 _EXT4-JFC-INODE-GDT-HOME !
    0 _EXT4-JFC-INODE-GDT-OFF !
    0 _EXT4-JFC-INODE-GDT-CRC !
    0 _EXT4-JFC-INODE-SUPER-CRC !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-ACTION + !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-CRC + !
    _EXT4-JFC-WRITER @ _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT +
    _EXT4-JWR.CP-PRE-ACTIVE _EXT4-JWR.CP-DELETE-RANGE-COUNT - 0 FILL
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-JFC-KIND !
    _EXT4-JFC-CTX @ _EXT4-C.INODE +
    _EXT4-I.LINKS + W@ 0= _EXT4-JFC-DELETE !
    _EXT4-JFC-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<>
    _EXT4-JFC-RAW-EXTENTS ! DUP
    _EXT4-I.GENERATION + L@ _EXT4-JFC-TARGET-GEN !
    _EXT4-JFC-DELETE @ IF
        DROP 0 _EXT4-JFC-TARGET-ENTRIES !
    ELSE
        _EXT4-I.BLOCK + 2 + W@ _EXT4-JFC-TARGET-ENTRIES !
    THEN
    _EXT4-IR-BLOCK @ _EXT4-JFC-TARGET-HOME !
    _EXT4-IR-OFF @ _EXT4-JFC-TARGET-OFF !
    _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JFC-SEAL-MODERN-PROTOCOL ?DUP IF EXIT THEN
    ELSE
        _EXT4-JFC-KIND @ _EXT4-OK-LEGACY <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-SEAL-LEGACY-PROTOCOL ?DUP IF EXIT THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFI-INODE-HOME @ _EXT4-JFC-TARGET-HOME @ <>
        _EXT4-JFI-INODE-OFF @ _EXT4-JFC-TARGET-OFF @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@
        _EXT4-JFC-TARGET-GEN @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFC-TARGET-ENTRIES !
        _EXT4-JFC-WRITER @ _EXT4-JFI-STORE-CP-RANGES
    THEN
    _EXT4-JFC-TARGET-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JFC-TARGET-CRC @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ +
        _EXT4-JFC-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE _EXT4-JFC-TARGET-ENTRIES @
         _EXT4-JFC-KIND @ _EXT4-OK-LEGACY =
         _EXT4-JFC-LOGICAL @ 0<> AND OR IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ + DUP _EXT4-JFC-TARGET !
        _EXT4-I.GENERATION + L@ _EXT4-JFC-TARGET-GEN @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-TARGET @ DUP _EXT4-I.SIZE-LO + L@
        SWAP _EXT4-I.SIZE-HI + L@ OR IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-RAW-EXTENTS @ _EXT4-JFC-TARGET @
        _EXT4-JOT-EMPTY-AFTERIMAGE-MAP? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-KIND @ _EXT4-OK-LEGACY = IF
            _EXT4-JFC-TARGET @ _EXT4-I.DTIME + L@ IF
                VFS-E-CORRUPT EXIT
            THEN
        THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
    ELSE
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
        0 _EXT4-JFC-TARGET-CRC !
    THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFI-RANGE-COUNT IF
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE
                THEN
            ELSE
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE
                THEN
            THEN
        ELSE
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE
                THEN
            ELSE
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE
                THEN
            THEN
        THEN _EXT4-JFC-MODE !
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JFC-INO @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JFC-LOGICAL @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JFC-SLOT @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JFC-O-GEN @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JFC-TARGET-GEN @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JFC-TARGET-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JFC-TARGET-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JFC-TARGET-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JFC-ORPHAN-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JFC-TARGET-ENTRIES @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JFC-INODE-BITMAP-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + !
    _EXT4-JFC-INODE-BITMAP-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + !
    _EXT4-JFC-INODE-GDT-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + !
    _EXT4-JFC-INODE-GDT-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + !
    _EXT4-JFC-INODE-GDT-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + !
    _EXT4-JFC-INODE-SUPER-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + !
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + !
    _EXT4-JFC-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-MODERN + !
    _EXT4-JFC-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + !
    _EXT4-JFC-MODE @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-MODE + !
    _EXT4-JFC-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF
        _EXT4-JFC-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Own one initially empty transaction, compose one selected orphan cleanup
\ and protocol-removal afterimage, then freeze it behind an exact pre-union
\ certificate.  Emit and abort remain legal; every later mutation is rejected
\ by _EXT4-JTX-MUTABLE?.
: _EXT4-JTX-STAGE-ORPHAN-CLEANUP
  ( plan-record transaction -- ior )
    _EXT4-JFC-WRITER ! _EXT4-JFC-RECORD !
    _EXT4-JFC-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-CREDIT + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFC-CTX !
    _EXT4-JFC-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFC-REQUIRE-SELECTED ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.INO + @ _EXT4-JFC-INO !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JFC-LOGICAL !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JFC-SLOT !
    _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
    _EXT4-JFC-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0= IF
        _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
    ELSE
        _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ IF
            VFS-E-INVALID
        ELSE
            _EXT4-JTX-STAGE-LINKED-ORPHAN-TRUNCATE
        THEN
    THEN
    ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
    ELSE
        _EXT4-JTX-ADVANCE-LEGACY-HEAD
    THEN
    ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ <> OR IF
        VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <>
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <> OR IF
        VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT
    THEN
    _EXT4-JFC-SEAL ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    0 ;

\ True only after the unified legacy/modern pass has authenticated an empty
\ active union and proved that its derived clear-pending state agrees with the
\ raw ORPHAN_PRESENT bit.  This does not require that bit to be set: a legacy
\ singleton may finish with no modern transient feature to clear.
: _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION?  ( ctx -- flag )
    DUP _EXT4-C.O.ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.MODERN-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.LEGACY-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-C.O.CLEAR-PENDING + @ 0<>
    SWAP _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0<> = ;

\ The empty-modern landing additionally requires the authenticated transient
\ bit whose final-super transition it is about to clear.
: _EXT4-EMPTY-ORPHAN-RECOVERY?  ( ctx -- flag )
    DUP _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF DROP FALSE EXIT THEN
    _EXT4-C.O.CLEAR-PENDING + @ 0<> ;

VARIABLE _EXT4-RS-CTX
VARIABLE _EXT4-RS-V

: _EXT4-AUTHENTICATE-REST  ( ctx -- ior )
    DUP _EXT4-C.J.STRICT + -1 SWAP !
    DUP _EXT4-VALIDATE-GROUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-VALIDATE-BACKUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF NIP EXIT THEN
    _EXT4-VALIDATE-JOURNAL ;

: _EXT4-RELOAD-AUTHENTICATED  ( ctx vfs -- ior )
    _EXT4-RS-V ! _EXT4-RS-CTX !
    _EXT4-RS-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-RS-V @ _EXT4-VALIDATE-SUPER ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-AUTHENTICATE-REST ;

: _EXT4-RELOAD-STRICT  ( ctx vfs -- ior )
    _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-C.O.ACTIVE + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

VARIABLE _EXT4-JPF-WRITER
VARIABLE _EXT4-JPF-CTX
VARIABLE _EXT4-JPF-V
VARIABLE _EXT4-JPF-RECORD
VARIABLE _EXT4-JPF-COUNT
VARIABLE _EXT4-JPF-MODE
VARIABLE _EXT4-JPF-KIND
VARIABLE _EXT4-JPF-TARGET
VARIABLE _EXT4-JPF-RAW-EXTENTS
VARIABLE _EXT4-JPF-OFF
VARIABLE _EXT4-JPF-AFTER

: _EXT4-JWR-ORPHAN-PREPLAN  ( writer ctx -- ior )
    _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JPF-MODE !
    _EXT4-JCPM-ORPHAN? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ <>
    _EXT4-JPF-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ <> OR
    _EXT4-JPF-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JPF-RECORD ! 0 _EXT4-JPF-COUNT !
    _EXT4-JPF-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JPF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            1 _EXT4-JPF-COUNT +!
            DUP _EXT4-OE.INO + @
            _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ = IF
                _EXT4-JPF-RECORD @ IF
                    DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
                THEN
                _EXT4-JPF-RECORD !
            ELSE
                DROP
            THEN
        ELSE
            DROP
        THEN
    LOOP
    _EXT4-JPF-COUNT @ _EXT4-JPF-CTX @ _EXT4-C.O.ACTIVE + @ <>
    _EXT4-JPF-RECORD @ 0= OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.INO + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JPF-KIND !
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-OK-MODERN <>
    ELSE
        _EXT4-OK-LEGACY <>
    THEN IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-B + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-C.INODE + DUP _EXT4-JPF-TARGET !
    DUP _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<>
    _EXT4-JPF-RAW-EXTENTS !
    _EXT4-I.LINKS + W@ 0=
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-TARGET @ _EXT4-I.GENERATION + L@
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-RECORD @ _EXT4-JFI-RECORD !
        _EXT4-JPF-CTX @ _EXT4-JFI-CTX !
        _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
        _EXT4-JFI-DATA-ENTRIES @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE?
        _EXT4-JFI-RANGE-COUNT 0<> <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JPF-TARGET @ _EXT4-I.BLOCK + 2 + W@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-IR-BLOCK @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
    _EXT4-IR-OFF @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JPF-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-OV-GEN @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-RECORD? 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ _EXT4-JPF-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.CHECKSUM + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            DROP EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-JPF-HOME-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JPF-AFTER ! _EXT4-JPF-OFF !
    _EXT4-JPF-CTX @ _EXT4-C.BLOCK + _EXT4-JPF-OFF @ +
    _EXT4-JFC-IMAGE @ _EXT4-JPF-OFF @ +
    _EXT4-JPF-AFTER @ _EXT4-BYTES=? ;

: _EXT4-JPF-LEGACY-SUPER-EXACT?  ( -- flag )
    0 _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x0C +
    _EXT4-JPF-HOME-RANGE-UNCHANGED?
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? 0= IF
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x10 + 4
        _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ 0= IF
            _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x0C + 4
            _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
            _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x158 + 4
            _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
        THEN
    THEN
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x14 +
    0xE8 0x14 - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0xEC +
    0x158 0xEC - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x15C +
    0x3FC 0x15C - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x400 + DUP
    _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JPF-HOME-RANGE-UNCHANGED? AND ;

: _EXT4-JWR-ORPHAN-STAGED?  ( writer -- ior )
    DUP _EXT4-JPF-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JPF-CTX !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ _EXT4-JPF-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JPF-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JPF-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
        _EXT4-OV-GEN @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 *
        DUP _EXT4-JPF-OFF !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFC-IMAGE @ ROT _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-OFF @ 4 + DUP _EXT4-JPF-AFTER !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK + OVER +
        _EXT4-JFC-IMAGE @ ROT +
        _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @ 4 -
        _EXT4-JPF-AFTER @ - _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@ IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JPF-CTX @ _EXT4-C.ORPHAN-INO + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-BLOCK-CHECKSUM?
        ?DUP IF NIP EXIT THEN 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
        _EXT4-JCPM-ORPHAN-LEGACY? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
        _EXT4-JPF-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JPF-LEGACY-SUPER-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        DUP _EXT4-JFC-SUPER !
        DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP 0 _EXT4-JPF-CTX @ _EXT4-C.SB +
        _EXT4-SUPER-INVARIANTS? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JPF-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
        ?DUP IF NIP EXIT THEN
        DUP _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-SB.INCOMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JPF-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ IF
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
        _EXT4-JPF-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP
        _EXT4-JPF-OFF !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFC-IMAGE @ ROT _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-OFF @ _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @ + DUP
        _EXT4-JPF-AFTER !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK + OVER +
        _EXT4-JFC-IMAGE @ ROT +
        _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @
        _EXT4-JPF-AFTER @ - _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
        _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @
         _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
         _EXT4-JCPM-ORPHAN-LEGACY?
         _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0<> AND OR IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
        DUP _EXT4-JPF-TARGET ! _EXT4-I.GENERATION + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-TARGET @ DUP _EXT4-I.SIZE-LO + L@
        SWAP _EXT4-I.SIZE-HI + L@ OR IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JPF-RAW-EXTENTS @ _EXT4-JPF-TARGET @
        _EXT4-JOT-EMPTY-AFTERIMAGE-MAP? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
        _EXT4-JCPM-ORPHAN-LEGACY? IF
            _EXT4-JPF-TARGET @ _EXT4-I.DTIME + L@ IF
                VFS-E-CORRUPT EXIT
            THEN
        THEN
    ELSE
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
    THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-RECORD @ _EXT4-JPF-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFC-INODE-BITMAP-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <>
        _EXT4-JFC-INODE-BITMAP-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> OR
        _EXT4-JFC-INODE-GDT-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <> OR
        _EXT4-JFC-INODE-GDT-OFF @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR
        _EXT4-JFC-INODE-GDT-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> OR
        _EXT4-JFC-INODE-SUPER-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ A nonempty-orphan reload admitted by checkpoint is bound to one sealed
\ writer, its exact checkpoint phase, and the fully authenticated pre-union.
\ It skips only the public policy refusal.
: _EXT4-RELOAD-STRICT-ORPHAN-PREPLAN  ( writer ctx vfs -- ior )
    _EXT4-JPF-V ! _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-CHECKPOINTING <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.PHASE + @
    _EXT4-JWP-CHECKPOINT-PREFLIGHT <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JPF-CTX @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-V @ _EXT4-CTX _EXT4-JPF-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JPF-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0=
    _EXT4-JPF-CTX @ _EXT4-C.RECOVERY + @ 0= OR
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-JPF-V @ _EXT4-VALIDATE-SUPER
    ?DUP IF EXIT THEN
    -1 _EXT4-JPF-CTX @ _EXT4-C.J.STRICT + !
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-GROUPS ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-BACKUPS ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JPF-CTX @
    _EXT4-JWR-ORPHAN-PREPLAN ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-VALIDATE-ROOT  ( ctx -- ior )
    DUP _EXT4-RJ-CTX ! 2 SWAP _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-STAGE-ROOT ;

VARIABLE _EXT4-JCP-WRITER
VARIABLE _EXT4-JCP-CTX
VARIABLE _EXT4-JCP-V
VARIABLE _EXT4-JCP-INDEX
VARIABLE _EXT4-JCP-ENTRY
VARIABLE _EXT4-JCP-WROTE
VARIABLE _EXT4-JCP-ENTRY-READY

: _EXT4-JCP-FAULT  ( ior -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JCP-RELOAD-PREFLIGHT  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ DUP
    _EXT4-JCPM-NONE = IF
        DROP _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-STRICT EXIT
    THEN
    _EXT4-JCPM-ORPHAN? IF
        _EXT4-JCP-WRITER @ _EXT4-JCP-CTX @ _EXT4-JCP-V @
        _EXT4-RELOAD-STRICT-ORPHAN-PREPLAN EXIT
    THEN
    VFS-E-CORRUPT ;

VARIABLE _EXT4-JCE-GROUP
VARIABLE _EXT4-JCE-INDEX
VARIABLE _EXT4-JCE-HOME
VARIABLE _EXT4-JCE-IOR
VARIABLE _EXT4-JCE-META-INDEX
VARIABLE _EXT4-JCE-META-ENTRY
VARIABLE _EXT4-JCE-META-IMAGE
VARIABLE _EXT4-JCE-DATA-BITMAP-HOME
VARIABLE _EXT4-JCE-DATA-GDT-HOME
VARIABLE _EXT4-JCE-DATA-RANGE-INDEX
VARIABLE _EXT4-JCE-DATA-BLOCKS

: _EXT4-JCP-REQUIRE-RETAINED-META-HOMES  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCE-META-INDEX !
    BEGIN
        _EXT4-JCE-META-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JCE-META-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JCE-META-ENTRY @ @ DUP 0< IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JCP-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-META-IMAGE DUP _EXT4-JCE-META-IMAGE !
        _EXT4-JCP-WRITER @ _EXT4-JTX-IMAGE-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JCE-META-ENTRY @ 2 CELLS + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-META-IMAGE @
        _EXT4-JCP-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        1 _EXT4-JCE-META-INDEX +!
    REPEAT
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-RANGE  ( first count -- ior )
    _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    _EXT4-JCE-DATA-BLOCKS @ _EXT4-JFB-COUNT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JCE-DATA-BLOCKS !
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        _EXT4-JCE-IOR ! _EXT4-JCE-DATA-BITMAP-HOME !
        _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @
        _EXT4-BIT-RANGE-CLEAR? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-GD-BLOCK @ _EXT4-JCE-DATA-GDT-HOME !
        _EXT4-JCE-DATA-BITMAP-HOME @ _EXT4-JCP-WRITER @
        _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JCE-DATA-GDT-HOME @ _EXT4-JCP-WRITER @
        _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    0 ;

: _EXT4-JCP-REQUIRE-REFDEC-EA  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
    _EXT4-JEA-REFDEC <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-CTX @ _EXT4-BLOCK-ALLOCATED?
    ?DUP IF NIP EXIT THEN
    0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JCP-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-CTX @ _EXT4-LOAD-XATTR-BLOCK ?DUP IF EXIT THEN
    _EXT4-XB-BUF @ 4 + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-XB-BUF @ _EXT4-JFC-IMAGE @
    _EXT4-JCP-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-DATA  ( -- ior )
    _EXT4-JCP-CTX @ _EXT4-JFB-CTX !
    0 _EXT4-JCE-DATA-BLOCKS !
    0 _EXT4-JCE-DATA-RANGE-INDEX !
    BEGIN
        _EXT4-JCE-DATA-RANGE-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ U<
    WHILE
        _EXT4-JCE-DATA-RANGE-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE DUP @ SWAP CELL+ @
        _EXT4-JCP-REQUIRE-DELETE-RANGE ?DUP IF EXIT THEN
        1 _EXT4-JCE-DATA-RANGE-INDEX +!
    REPEAT
    _EXT4-JCE-DATA-BLOCKS @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @ ?DUP IF
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
        _EXT4-JEA-RELEASE = IF
            1 _EXT4-JCP-REQUIRE-DELETE-RANGE ?DUP IF EXIT THEN
        ELSE
            DROP _EXT4-JCP-REQUIRE-REFDEC-EA ?DUP IF EXIT THEN
        THEN
    THEN
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-HOMES  ( -- ior )
    _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
    _EXT4-JCP-REQUIRE-DELETE-DATA ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ 1-
    _EXT4-JCP-CTX @ _EXT4-C.IPG + @ /MOD
    _EXT4-JCE-GROUP ! _EXT4-JCE-INDEX !
    _EXT4-JCE-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JCE-IOR ! _EXT4-JCE-HOME !
    _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCE-HOME @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <>
    _EXT4-GD-OFF @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-INDEX @ 1
    _EXT4-BIT-RANGE-SET? IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JCP-POST-ACTIVE
VARIABLE _EXT4-JCP-POST-COUNT

: _EXT4-JCP-REQUIRE-POSTSTATE  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCPM-NONE = IF
        DROP
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        0 EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ 1-
    DUP _EXT4-JCP-POST-ACTIVE !
    _EXT4-JCP-CTX @ _EXT4-C.O.ACTIVE + @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ 1-
        _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ <>
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @
        _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    ELSE
        DUP _EXT4-JCPM-ORPHAN-LEGACY? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ 1-
        _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ <>
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @
        _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 _EXT4-JCP-POST-COUNT !
    _EXT4-JCP-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JCP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            1 _EXT4-JCP-POST-COUNT +!
            _EXT4-OE.INO + @
            _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ = IF
                DROP VFS-E-CORRUPT UNLOOP EXIT
            THEN
        ELSE
            DROP
        THEN
    LOOP
    _EXT4-JCP-POST-COUNT @ _EXT4-JCP-POST-ACTIVE @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCP-POST-ACTIVE @ IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JCPM-ORPHAN-MODERN? IF
            _EXT4-JCP-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
                DROP VFS-E-CORRUPT EXIT
            THEN
        THEN
    ELSE
        DUP _EXT4-JCPM-ORPHAN-MORE? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-POST-ACTIVE @ 0= IF DROP VFS-E-CORRUPT EXIT THEN
    THEN
    DUP _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCP-CTX @ _EXT4-PREPARE-ORPHAN-FILE
        ?DUP IF NIP EXIT THEN
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JCP-CTX @ _EXT4-READ-ORPHAN-BLOCK
        ?DUP IF NIP EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
        _EXT4-OV-GEN @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@ IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JCP-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN
    DUP _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCP-REQUIRE-DELETE-HOMES ?DUP IF NIP EXIT THEN
    THEN
    DROP
    0 ;

\ Reauthenticate both the persisted transaction and its retained checkpoint
\ source before the first home write.  JSCAN proves the exact committed disk
\ prefix; the bounded writer tables prove the home identities and images that
\ will be consumed without allocating recovery-only revoke workspace.
: _EXT4-JTX-CHECKPOINT-PREFLIGHT  ( -- ior )
    _EXT4-JCP-RELOAD-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 1-
    _EXT4-JCP-CTX @ _EXT4-JOURNAL-ADVANCE
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    \ Root staging may use TREE-BLOCK.  Freeze inode 8 again before JSCAN and
    \ retained-image authority checks consume the retry-preservation proof.
    8 _EXT4-JCP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.INODE +
    _EXT4-JCP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    \ First prove an ordinary complete committed prefix, then repeat the same
    \ bounded scan in lockstep with retained metadata and revoke order.  The
    \ second pass cannot grant home-write authority merely because two valid
    \ but different transaction descriptions happen to have the same shape.
    _EXT4-JSCAN-PREFLIGHT _EXT4-JCP-CTX @ _EXT4-JSCAN ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JSCAN-BIND-BEGIN
    _EXT4-JSCAN-BINDING _EXT4-JCP-CTX @ _EXT4-JSCAN
    _EXT4-JSCAN-BIND-FINISH ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + @ 1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN? IF
        _EXT4-JCP-WRITER @ _EXT4-JWR-ORPHAN-STAGED?
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JTX-CHECKPOINT-HOMES  ( -- ior )
    _EXT4-JWP-CHECKPOINT-HOME
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JCP-INDEX ! 0 _EXT4-JCP-WROTE !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + !
    BEGIN
        _EXT4-JCP-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JCP-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-IMAGE
            _EXT4-JCP-ENTRY @ @ _EXT4-JCP-CTX @ _EXT4-WRITE-BLOCK
            ?DUP IF EXIT THEN
            1 _EXT4-JCP-WROTE +!
            1 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + +!
        THEN
        1 _EXT4-JCP-INDEX +!
    REPEAT
    _EXT4-JCP-WROTE @
    _EXT4-JCP-WRITER @ _EXT4-JWR.META-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-HOME-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ;

\ Checkpoint one durable transaction, release its complete log reservation,
\ and keep the mounted filesystem at a standard empty RECOVER-set journal.
\ Any failure after publication enters CHECKPOINTING is quarantined for
\ remount; same-session retry never guesses which prefix reached the medium.
: _EXT4-JTX-CHECKPOINT  ( transaction -- ior )
    DUP _EXT4-JCP-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-COMMITTED <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JCP-CTX !
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-C.J.WRITER-CURRENT + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.READY + @ DUP _EXT4-JCP-ENTRY-READY !
    DUP 0= SWAP -1 = OR 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JCP-V ! _EXT4-CTX _EXT4-JCP-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JCP-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-JWP-CHECKPOINT-PREFLIGHT
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-CHECKPOINTING
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-CHECKPOINT-PREFLIGHT ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    \ Operation-scoped range authority cannot survive the first home mutation.
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-JTX-CHECKPOINT-HOMES ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-AUTHENTICATED
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-REQUIRE-POSTSTATE ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-RESET
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RESET-JOURNAL
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-RESET-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-RETIRE
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-FINAL-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.SB + DUP
    _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP _EXT4-JCP-FAULT EXIT THEN 0= IF
        DROP VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    \ Context and writer publication are withdrawn before authenticated reload
    \ turns the in-memory active-log view into the empty write-active endpoint.
    0 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.READY + !
    _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-AUTHENTICATED
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-REQUIRE-POSTSTATE ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-JCP-FAULT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-HITS + !
    _EXT4-JCP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JCP-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JCP-CTX @ _EXT4-C.J.FIRST + @
    THEN _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + !
    _EXT4-JCP-CTX @ _EXT4-JWR-REBASE-WRITE-ACTIVE
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    -1 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    _EXT4-JCP-ENTRY-READY @ _EXT4-JCP-CTX @ _EXT4-C.READY + !
    0 ;

VARIABLE _EXT4-MOW-SOURCE
VARIABLE _EXT4-MOW-COUNT
VARIABLE _EXT4-MOW-OFFSET
VARIABLE _EXT4-MOW-INO
VARIABLE _EXT4-MOW-GEN
VARIABLE _EXT4-MOW-SECONDS
VARIABLE _EXT4-MOW-NSEC
VARIABLE _EXT4-MOW-V
VARIABLE _EXT4-MOW-CTX
VARIABLE _EXT4-MOW-WRITER
VARIABLE _EXT4-MOW-TX
VARIABLE _EXT4-MOW-CREDIT
VARIABLE _EXT4-MOW-CREDIT-XT
VARIABLE _EXT4-MOW-STAGE-XT
VARIABLE _EXT4-MOW-IOR
VARIABLE _EXT4-MOW-ACTUAL
VARIABLE _EXT4-MOW-ACTIVE
CREATE _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK ALLOT

: _EXT4-MOW-SCRUB  ( -- )
    _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK 0 FILL ;

\ A zero signed credit is an internal request for a typed, read-only
\ measurement pass.  The late-bound selector is installed by the allocation
\ builder below, after its words exist.  It returns the real nonzero signed
\ credit, preserving the ordinary positive/negative progress convention.
: _EXT4-MOW-RESOLVE-CREDIT  ( -- ior )
    _EXT4-MOW-CREDIT @ IF 0 EXIT THEN
    _EXT4-MOW-CREDIT-XT @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    EXECUTE
    DUP IF NIP EXIT THEN DROP
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    _EXT4-MOW-CREDIT !
    0 ;

: _EXT4-MOW-ENTRY  ( -- ior )
    _EXT4-MOW-V @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MOW-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ V.VOLUME @ DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN _EXT4-IO-VOL !
    _EXT4-MOW-V @ _EXT4-IO-VFS !
    _EXT4-MOW-V @ V.BCTX @ DUP _EXT4-MOW-CTX ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.START + @
    _EXT4-MOW-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-MOW-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.RECOVERY + @ 0<> DUP
    _EXT4-MOW-ACTIVE !
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0<> = 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-MOW-ACTIVE @ IF
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-MOW-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DUP _EXT4-JWR.FAULT + @ ?DUP IF NIP EXIT THEN
            DROP VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND IF
            VFS-E-BUSY EXIT
        THEN
    THEN
    _EXT4-MOW-CTX @ _EXT4-RECOVERY-MEDIA ;

\ The exact client emits one full-block ordered image.  VOL-WRITE reports a
\ contiguous prefix of fully completed 512-byte sectors; a tear inside the
\ next sector deliberately proves none of that sector.  Intersect that media
\ prefix with the caller's range to obtain the only byte prefix VFS may use
\ for cursor advancement.  EXPECTED must describe this exact block attempt.
: _EXT4-MOW-ORDERED-ACTUAL  ( -- actual )
    _EXT4-IO-EXPECTED @ _EXT4-MOW-CTX @ _EXT4-C.SPB + @ <> IF
        0 EXIT
    THEN
    _EXT4-IO-COMPLETED @ DUP 0< IF DROP 0 EXIT THEN
    DUP _EXT4-IO-EXPECTED @ U> IF DROP 0 EXIT THEN
    _EXT4-SECTOR *
    _EXT4-MOW-OFFSET @ _EXT4-MOW-CTX @ _EXT4-C.BSIZE + @ MOD -
    DUP 0< IF DROP 0 EXIT THEN
    _EXT4-MOW-COUNT @ MIN ;

\ Before ordered data, no caller byte has media authority.  Phase 8 retains
\ the sector certificate for the ordered attempt.  Every later emission or
\ checkpoint phase proves that the complete ordered block was accepted.
: _EXT4-MOW-FAULT-ACTUAL  ( -- actual )
    _EXT4-MOW-ACTUAL @ DUP IF EXIT THEN DROP
    _EXT4-MOW-WRITER @ ?DUP 0= IF 0 EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED <> IF DROP 0 EXIT THEN
    _EXT4-JWR.PHASE + @ DUP _EXT4-JWP-ORDERED-DATA = IF
        DROP _EXT4-MOW-ORDERED-ACTUAL EXIT
    THEN
    DUP _EXT4-JWP-EMISSION? SWAP _EXT4-JWP-CHECKPOINT? OR IF
        _EXT4-MOW-COUNT @ EXIT
    THEN
    0 ;

\ A quarantined writer cannot accept another mutation on this mount.  Retain
\ the first error's domain, reason, detail, and causal flags, then add the
\ read-only consequence.  PARTIAL is additionally required for every error
\ accompanied by a confirmed caller-byte prefix, including actual=count.
: _EXT4-MOW-RESULT  ( actual ior -- actual ior )
    _EXT4-MOW-IOR ! _EXT4-MOW-ACTUAL !
    _EXT4-MOW-WRITER @ ?DUP IF
        _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
            _EXT4-MOW-IOR @ VFS-IOR-F-READONLY 24 LSHIFT OR
            _EXT4-MOW-IOR !
        THEN
    THEN
    _EXT4-MOW-ACTUAL @ _EXT4-MOW-IOR @ _EXT4-PARTIAL-IOR ;

\ Clean staging errors retain no media authority.  Abort only when the
\ transaction is still mutable; the typed builder may already have aborted
\ itself after an internal ordered-data publication.  A structurally failed
\ abort is latched because the persistent workspace can no longer be reused.
\ A post-commit checkpoint-entry refusal is also terminal: give the latch a
\ valid checkpoint phase rather than leaving replayable authority retryable in
\ the same session.  Positive metadata credit admits ordered-sector prefix
\ progress for already reachable bytes; negative credit requires a successful
\ journal emit before any caller progress is authoritative.
: _EXT4-MOW-FAIL  ( ior -- actual ior )
    _EXT4-MOW-IOR !
    _EXT4-MOW-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF
                _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
                _EXT4-MOW-IOR !
            THEN
        ELSE
            DUP _EXT4-JWR.STATE + @ _EXT4-JWR-COMMITTED = IF
                DROP
                _EXT4-JWP-CHECKPOINT-PREFLIGHT
                _EXT4-MOW-WRITER @ _EXT4-JWR.PHASE + !
                _EXT4-MOW-IOR @
                _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
                _EXT4-MOW-IOR !
            ELSE DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
                _EXT4-JWR.FAULT + @ ?DUP IF _EXT4-MOW-IOR ! THEN
            ELSE
                DROP
            THEN THEN
        THEN
    THEN
    _EXT4-MOW-CREDIT @ 0> IF
        _EXT4-MOW-FAULT-ACTUAL _EXT4-MOW-ACTUAL !
    THEN
    _EXT4-MOW-SCRUB
    _EXT4-MOW-ACTUAL @ _EXT4-MOW-IOR @ _EXT4-MOW-RESULT ;

\ Common mounted engine for one typed, block-bounded transaction.  The first
\ clean call dry-stages before journal activation; successful calls checkpoint
\ synchronously and retain one scrubbed writer for reuse.  The stage XT has the
\ standard typed one-block builder shape.  A negative metadata credit selects
\ commit-granular progress (only a successful emit confirms COUNT); its
\ absolute value is the real credit.  Positive credit retains ordered-sector
\ progress for size-preserving overwrite.
: _EXT4-MOUNTED-ONEBLOCK-WRITE
  ( source count file-offset inode-number expected-generation seconds nsec vfs signed-meta-credit stage-xt -- actual ior )
    _EXT4-MOW-STAGE-XT ! _EXT4-MOW-CREDIT !
    _EXT4-MOW-V ! _EXT4-MOW-NSEC ! _EXT4-MOW-SECONDS !
    _EXT4-MOW-GEN ! _EXT4-MOW-INO ! _EXT4-MOW-OFFSET !
    _EXT4-MOW-COUNT ! _EXT4-MOW-SOURCE !
    0 _EXT4-MOW-WRITER ! 0 _EXT4-MOW-ACTUAL !
    _EXT4-MOW-ENTRY ?DUP IF 0 SWAP EXIT THEN
    _EXT4-MOW-COUNT @ 0< IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MOW-COUNT @ 0= IF 0 0 EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF 0 VFS-E-NOSPC EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER-ARENA + @ 0=
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER + @ 0= OR IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-MOW-SOURCE @ _EXT4-MOW-COUNT @ _VFS-BUFFER? 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-MOW-SOURCE @ _EXT4-MOW-COUNT @
    _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK MSPAN-OVERLAP? IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-MOW-OFFSET @ 0< IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MOW-COUNT @ _EXT4-MOW-CTX @ _EXT4-C.BSIZE + @ U> IF
        0 EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    \ Preserve caller bytes across dry-stage abort, activation cache reuse,
    \ and live-stage writer rebase, then scrub them on every later return.
    _EXT4-MOW-SOURCE @ _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ MOVE
    _EXT4-MOW-RESOLVE-CREDIT ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-CREDIT @ ABS 1 0 _EXT4-MOW-CTX @
    _EXT4-JTX-PREFLIGHT-CAPACITY
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-CREDIT @ ABS 1 0 _EXT4-MOW-CTX @ _EXT4-JWR-ENSURE
    DUP IF NIP _EXT4-MOW-FAIL EXIT THEN
    DROP _EXT4-MOW-WRITER !
    _EXT4-MOW-ACTIVE @ 0= IF
        _EXT4-MOW-CREDIT @ ABS 1 0 _EXT4-MOW-WRITER @ _EXT4-JTX-BEGIN
        DUP IF NIP _EXT4-MOW-FAIL EXIT THEN
        DROP _EXT4-MOW-TX !
        _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ _EXT4-MOW-OFFSET @
        _EXT4-MOW-INO @ _EXT4-MOW-GEN @ _EXT4-MOW-SECONDS @
        _EXT4-MOW-NSEC @ _EXT4-MOW-TX @ _EXT4-MOW-STAGE-XT @ EXECUTE
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
        _EXT4-MOW-TX @ _EXT4-JTX-ABORT
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
        _EXT4-MOW-WRITER @ _EXT4-JWR-ACTIVATE
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    THEN
    _EXT4-MOW-CREDIT @ ABS 1 0 _EXT4-MOW-WRITER @ _EXT4-JTX-BEGIN
    DUP IF NIP _EXT4-MOW-FAIL EXIT THEN
    DROP _EXT4-MOW-TX !
    _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ _EXT4-MOW-OFFSET @
    _EXT4-MOW-INO @ _EXT4-MOW-GEN @ _EXT4-MOW-SECONDS @
    _EXT4-MOW-NSEC @ _EXT4-MOW-TX @ _EXT4-MOW-STAGE-XT @ EXECUTE
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-TX @ _EXT4-JTX-EMIT
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-COUNT @ _EXT4-MOW-ACTUAL !
    _EXT4-MOW-TX @ _EXT4-JTX-CHECKPOINT
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _EXT4-MOW-FAIL EXIT
    THEN
    _EXT4-MOW-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
    _EXT4-MOW-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
        VFS-E-CORRUPT _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _EXT4-MOW-FAIL EXIT
    THEN
    _EXT4-MOW-ACTUAL @ _EXT4-MOW-SCRUB 0 ;

\ =====================================================================
\  Private VFS-shaped write boundary and trusted clock injection
\ =====================================================================
\
\ The binding ABI does not carry a timestamp.  Keep the time authority on
\ the ext4 instance instead of consulting EPOCH@ or another ambient clock.
\ The provider returns one nonnegative Unix-epoch millisecond scalar:
\
\     now-ms-xt  ( clock-context -- epoch-ms ior )
\
\ Binding is allowed once, at the authenticated clean mounted endpoint and
\ before the first mutation.  Clock and workspace-profile binding may occur
\ in either order while a dedicated writer remains untouched, idle, and
\ clean.  The XT is stored last so it is the publication word for the
\ accompanying opaque context.

VARIABLE _EXT4-BWC-XT
VARIABLE _EXT4-BWC-CLOCK-CTX
VARIABLE _EXT4-BWC-V
VARIABLE _EXT4-BWC-CTX

: EXT4-BIND-WRITE-CLOCK?  ( now-ms-xt clock-context vfs -- ior )
    _EXT4-BWC-V ! _EXT4-BWC-CLOCK-CTX ! _EXT4-BWC-XT !
    _EXT4-BWC-XT @ 0= _EXT4-BWC-V @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWC-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWC-V @ V.BCTX @ DUP _EXT4-BWC-CTX ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWC-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWC-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWC-V @ V.FLAGS @ VFS-F-DIRTY AND IF VFS-E-BUSY EXIT THEN
    _EXT4-BWC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-BWC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-BWC-CTX @ _EXT4-C.J.WRITER + @ ?DUP IF
        _EXT4-BWC-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
        _EXT4-JWR-STORE-DEDICATED <> IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DROP VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-BUSY EXIT THEN
        _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-XT + @ IF VFS-E-CONFLICT EXIT THEN
    _EXT4-BWC-CLOCK-CTX @ _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-CTX + !
    _EXT4-BWC-XT @ _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-XT + !
    0 ;

15032385535 1000 * 999 + CONSTANT _EXT4-WRITE-EPOCH-MS-MAX
1024 CONSTANT _EXT4-STAGED-WRITE-BLOCK-SIZE
256  CONSTANT _EXT4-STAGED-WRITE-INODE-SIZE

: _EXT4-STAGED-WRITE-FS-QUALIFY  ( ctx -- ior )
    DUP _EXT4-C.BSIZE + @ _EXT4-STAGED-WRITE-BLOCK-SIZE <>
    SWAP _EXT4-C.ISIZE + @ _EXT4-STAGED-WRITE-INODE-SIZE <> OR IF
        EXT4-D-GEOMETRY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

\ A mounted WRITE capability must admit at least the exact one-metadata-home,
\ one-data-home overwrite transaction implemented below.  The journal has
\ already been authenticated when this check runs; translate a valid but
\ smaller journal/profile envelope into the staged binding's fail-closed
\ unsupported result.
: _EXT4-STAGED-WRITE-JOURNAL-QUALIFY  ( ctx -- ior )
    >R 1 1 0 R> _EXT4-JTX-PREFLIGHT-JOURNAL ?DUP IF
        DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;


VARIABLE _EXT4-WR-SOURCE
VARIABLE _EXT4-WR-COUNT
VARIABLE _EXT4-WR-OFFSET
VARIABLE _EXT4-WR-D
VARIABLE _EXT4-WR-V
VARIABLE _EXT4-WR-CTX
VARIABLE _EXT4-WR-VN
VARIABLE _EXT4-WR-BID
VARIABLE _EXT4-WR-GEN
VARIABLE _EXT4-WR-REQUEST-END
VARIABLE _EXT4-WR-NEW-SIZE
VARIABLE _EXT4-WR-NEW-BLOCKS
VARIABLE _EXT4-WR-NEW-FREE
VARIABLE _EXT4-WR-CHUNK
VARIABLE _EXT4-WR-TAIL-ROOM
VARIABLE _EXT4-WR-MS
VARIABLE _EXT4-WR-SECONDS
VARIABLE _EXT4-WR-NSEC
VARIABLE _EXT4-WR-HOOK
VARIABLE _EXT4-WR-IOR
VARIABLE _EXT4-WR-ACTUAL
VARIABLE _EXT4-WR-KIND

0 CONSTANT _EXT4-WRK-IN-SIZE
1 CONSTANT _EXT4-WRK-HOLE-FILL
2 CONSTANT _EXT4-WRK-TAIL-APPEND
3 CONSTANT _EXT4-WRK-ALIGNED-APPEND

: _EXT4-WR-GROW?  ( -- flag )
    _EXT4-WR-KIND @ DUP _EXT4-WRK-TAIL-APPEND =
    SWAP _EXT4-WRK-ALIGNED-APPEND = OR ;

: _EXT4-WR-COMMIT-GRANULAR?  ( -- flag )
    _EXT4-WR-KIND @ _EXT4-WRK-HOLE-FILL =
    _EXT4-WR-GROW? OR ;

: _EXT4-WRITE-VALIDATE  ( -- ior )
    _EXT4-WR-D @ 0= _EXT4-WR-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-WR-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF VFS-E-STALE EXIT THEN
    _EXT4-WR-V @ V.BCTX @ DUP _EXT4-WR-CTX ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-WR-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-WR-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-WR-D @ _EXT4-WR-V @ _VFS-DENTRY-OWNED? 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-WR-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _EXT4-WR-D @ D.VNODE @ DUP _EXT4-WR-VN ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-WR-VN @ VN.TYPE @ VFS-T-DIR = IF VFS-E-ISDIR EXIT THEN
    _EXT4-WR-VN @ VN.TYPE @ VFS-T-FILE <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-WR-VN @ VN.FLAGS @ VFS-IF-DIRTY AND IF VFS-E-BUSY EXIT THEN
    _EXT4-WR-VN @ VN.BID @ DUP _EXT4-WR-BID ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-WR-BID @ _EXT4-WR-CTX @ _EXT4-C.INODES + @ U> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-WR-VN @ VN.GEN @ DUP _EXT4-WR-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-WR-VN @ VN.SIZE-HI @ IF VFS-E-OVERFLOW EXIT THEN
    _EXT4-WR-VN @ VN.SIZE-LO @ 0< IF VFS-E-OVERFLOW EXIT THEN
    _EXT4-WR-COUNT @ 0< _EXT4-WR-OFFSET @ 0< OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-WR-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-WR-SOURCE @ _EXT4-WR-COUNT @ _VFS-BUFFER? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-WR-OFFSET @ _EXT4-WR-COUNT @ _EXT4-UADD?
    _EXT4-WR-IOR ! _EXT4-WR-REQUEST-END !
    _EXT4-WR-IOR @ ?DUP IF EXIT THEN
    \ Nonempty staged writes currently require authenticated 1 KiB filesystem
    \ geometry with 256-byte inodes.  This is the published operation boundary
    \ for initialized overwrite, in-size hole fill, partial-tail append,
    \ allocation-backed growth from aligned EOF, and exact-write composition
    \ from a partial tail through additional allocated logical blocks.  Each
    \ callback remains block-bounded and independently checkpointed.  Other
    \ akashic-ext4-rw-v1 geometries remain available to the read/recovery path
    \ until their mutation paths pass equivalent qualification.
    _EXT4-WR-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    _EXT4-WR-REQUEST-END @ _EXT4-WR-VN @ VN.SIZE-LO @ U> IF
        _EXT4-WR-OFFSET @ _EXT4-WR-VN @ VN.SIZE-LO @ <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        \ Reject an unsupported final size before publishing any durable
        \ prefix.  Later exact-write callbacks see the same request endpoint,
        \ but the first callback owns this whole-request overflow decision.
        _EXT4-WR-REQUEST-END @ 0xFFFFFFFF U> IF
            VFS-E-OVERFLOW EXIT
        THEN
        _EXT4-WR-VN @ VN.SIZE-LO @
        _EXT4-WR-CTX @ _EXT4-C.BSIZE + @ MOD 0= IF
            _EXT4-WRK-ALIGNED-APPEND _EXT4-WR-KIND !
        ELSE
            _EXT4-WR-CTX @ _EXT4-C.BSIZE + @
            _EXT4-WR-OFFSET @
            _EXT4-WR-CTX @ _EXT4-C.BSIZE + @ MOD -
            _EXT4-WR-TAIL-ROOM !
            _EXT4-WR-COUNT @ _EXT4-WR-TAIL-ROOM @ U> IF
                \ Admit one independently checkpointed tail chunk followed by
                \ as many block-bounded allocation callbacks as the exact
                \ caller can complete.  Refuse a profile that cannot support
                \ even the ordinary following allocation before publishing
                \ the initialized tail prefix.  A later callback independently
                \ measures any five-to-seven-home root-growth topology,
                \ preserving exact write's checkpointed-prefix semantics.
                4 1 0 _EXT4-WR-CTX @ _EXT4-JTX-PREFLIGHT-CAPACITY
                ?DUP IF EXIT THEN
            THEN
            _EXT4-WRK-TAIL-APPEND _EXT4-WR-KIND !
        THEN
    ELSE
        _EXT4-WRK-IN-SIZE _EXT4-WR-KIND !
    THEN
    _EXT4-WR-COUNT @
    _EXT4-WR-CTX @ _EXT4-C.BSIZE + @
    _EXT4-WR-OFFSET @ _EXT4-WR-CTX @ _EXT4-C.BSIZE + @ MOD - MIN
    _EXT4-WR-CHUNK !
    _EXT4-WR-GROW? IF
        _EXT4-WR-OFFSET @ _EXT4-WR-CHUNK @ _EXT4-UADD?
        _EXT4-WR-IOR ! _EXT4-WR-NEW-SIZE !
        _EXT4-WR-IOR @ ?DUP IF EXIT THEN
        _EXT4-WR-NEW-SIZE @ 0xFFFFFFFF U> IF
            VFS-E-OVERFLOW EXIT
        THEN
    ELSE
        _EXT4-WR-VN @ VN.SIZE-LO @ _EXT4-WR-NEW-SIZE !
    THEN
    _EXT4-WR-VN @ VN.BLOCKS @ _EXT4-WR-NEW-BLOCKS !
    _EXT4-WR-CTX @ _EXT4-C.WCLOCK-XT + @ 0= IF
        VFS-E-UNSUPPORTED EXIT
    THEN
    0 ;

: _EXT4-WRITE-NOW  ( -- ior )
    _EXT4-WR-CTX @ _EXT4-C.WCLOCK-CTX + @
    _EXT4-WR-CTX @ _EXT4-C.WCLOCK-XT + @ EXECUTE
    _EXT4-WR-IOR ! _EXT4-WR-MS !
    _EXT4-WR-IOR @ ?DUP IF EXIT THEN
    _EXT4-WR-MS @ 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-WR-MS @ _EXT4-WRITE-EPOCH-MS-MAX U> IF
        VFS-E-OVERFLOW EXIT
    THEN
    _EXT4-WR-MS @ 1000 /MOD
    _EXT4-WR-SECONDS ! 1000000 * _EXT4-WR-NSEC !
    0 ;

\ Exact binding-callback shape for the qualified slice.  A larger admitted
\ caller range completes at most the first filesystem-block chunk and returns
\ short success; VFS-WRITE-EXACT or the caller may advance and invoke it again,
\ including through additional independently allocated EOF blocks.
\ It remains absent from the ordinary EXT4-OPS and EXT4-CAPS.  The explicit
\ staged binding below publishes only this qualified operation while broader
\ public-write gates remain.
\ Confirmed progress and quarantine flags are safe for VFS cursor semantics.
\ Successful checkpointed writes publish mtime/ctime.  Allocation-backed
\ operations additionally publish authenticated i_blocks; growth publishes
\ its committed EOF.  A checkpoint error after a growth commit publishes that
\ exact EOF, i_blocks, and time because progress is commit-granular for newly
\ reachable bytes.
: _EXT4-WR-PUBLISH-COMMITTED  ( -- )
    _EXT4-WR-SECONDS @ _EXT4-WR-VN @ VN.MTIME !
    _EXT4-WR-NSEC @ _EXT4-WR-VN @ VN.MTIME-NS !
    _EXT4-WR-SECONDS @ _EXT4-WR-VN @ VN.CTIME !
    _EXT4-WR-NSEC @ _EXT4-WR-VN @ VN.CTIME-NS !
    _EXT4-WR-KIND @ DUP _EXT4-WRK-HOLE-FILL =
    SWAP _EXT4-WRK-ALIGNED-APPEND = OR IF
        _EXT4-WR-NEW-BLOCKS @ _EXT4-WR-VN @ VN.BLOCKS !
        _EXT4-WR-NEW-FREE @ _EXT4-WR-CTX @ _EXT4-C.FREE-BLOCKS + !
    THEN
    _EXT4-WR-GROW? IF
        _EXT4-WR-NEW-SIZE @ _EXT4-WR-VN @ VN.SIZE-LO !
        0 _EXT4-WR-VN @ VN.SIZE-HI !
    THEN
    VFS-F-DIRTY _EXT4-WR-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

: _EXT4-WRITE  ( source count file-offset dentry vfs -- actual ior )
    _EXT4-WR-V ! _EXT4-WR-D ! _EXT4-WR-OFFSET !
    _EXT4-WR-COUNT ! _EXT4-WR-SOURCE !
    0 _EXT4-WR-CHUNK ! 0 _EXT4-WR-TAIL-ROOM !
    0 _EXT4-WR-ACTUAL !
    _EXT4-WRK-IN-SIZE _EXT4-WR-KIND !
    _EXT4-WRITE-VALIDATE ?DUP IF 0 SWAP EXIT THEN
    _EXT4-WR-COUNT @ 0= IF
        _EXT4-WR-SOURCE @ 0 _EXT4-WR-OFFSET @
        _EXT4-WR-BID @ _EXT4-WR-GEN @ 0 0 _EXT4-WR-V @
        1 ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
        _EXT4-MOUNTED-ONEBLOCK-WRITE EXIT
    THEN
    _EXT4-WRITE-NOW ?DUP IF 0 SWAP EXIT THEN
    _EXT4-WR-HOOK @ EXECUTE
    _EXT4-WR-IOR ! _EXT4-WR-ACTUAL !
    _EXT4-WR-ACTUAL @ 0<
    _EXT4-WR-ACTUAL @ _EXT4-WR-CHUNK @ U> OR IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-WR-IOR @ IF
        _EXT4-WR-COMMIT-GRANULAR?
        _EXT4-WR-ACTUAL @ _EXT4-WR-CHUNK @ = AND IF
            _EXT4-WR-PUBLISH-COMMITTED
        THEN
        _EXT4-WR-ACTUAL @ _EXT4-WR-IOR @ EXIT
    THEN
    _EXT4-WR-ACTUAL @ _EXT4-WR-CHUNK @ <> IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-WR-PUBLISH-COMMITTED
    _EXT4-WR-ACTUAL @ 0 ;

VARIABLE _EXT4-EL-CTX
VARIABLE _EXT4-EL-V
VARIABLE _EXT4-EL-WRITER

: _EXT4-EL-PHASE  ( phase -- )
    _EXT4-EL-WRITER @ ?DUP IF _EXT4-JWR.PHASE + ! ELSE DROP THEN ;

\ Land an exact empty checksum-v3 journal through AKR1.  RECOVER must already
\ be durable: a clean authenticated-empty-orphan mount first enters that state
\ through AKW1.  Strict reload proves the orphan file empty before the final
\ superblock endpoint clears RECOVER and ORPHAN_PRESENT together.
: _EXT4-LAND-EMPTY-JOURNAL  ( ctx vfs writer|0 -- ior )
    _EXT4-EL-WRITER ! _EXT4-EL-V ! _EXT4-EL-CTX !
    _EXT4-EL-CTX @ _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.SUPER-TORN + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.START + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.CLEANUP + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-EL-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-EL-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-EL-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-EL-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-EL-CTX @ _EXT4-C.J.CURSOR + !
    _EXT4-JWP-DEACTIVATE-PREFLIGHT _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-EL-V @ _EXT4-RELOAD-STRICT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-PREPARE-CLEAR ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-RESET _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-RESET-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-SUPER _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-SUPER-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-WITNESS-CLEAR _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-WITNESS-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-GUARD-RETIRE _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-GUARD-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-FINAL-PROOF _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-EL-V @ _EXT4-RELOAD-STRICT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    0 _EXT4-EL-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-EL-CTX @ _EXT4-C.J.REPLAYED + !
    0 ;

VARIABLE _EXT4-OEC-CTX
VARIABLE _EXT4-OEC-V
VARIABLE _EXT4-OEC-GUARD
VARIABLE _EXT4-OEC-NEXT

\ Complete an authenticated empty modern-orphan state without allocating a
\ private writer.  AKW1 first upgrades and authenticates even a feature-zero
\ clean journal while making RECOVER durable.  AKR1 can then clear both ext4
\ transient bits at its already witnessed final-super endpoint.
: _EXT4-COMPLETE-EMPTY-ORPHAN  ( ctx vfs -- ior )
    _EXT4-OEC-V ! _EXT4-OEC-CTX !
    _EXT4-OEC-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-V @ _EXT4-CTX _EXT4-OEC-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-OEC-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-OEC-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    0 _EXT4-OEC-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-OEC-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-OEC-CTX @ _EXT4-C.J.FIRST + @
    THEN DUP _EXT4-OEC-GUARD !
    DUP _EXT4-OEC-CTX @ _EXT4-C.J.FIRST + @ U<
    SWAP _EXT4-OEC-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-C.J.SEQUENCE + @ 1+
    0xFFFFFFFF AND _EXT4-OEC-NEXT !
    _EXT4-OEC-CTX @ _EXT4-C.BLOCK +
    _EXT4-OEC-CTX @
    _EXT4-OEC-GUARD @
    _EXT4-OEC-NEXT @
    _EXT4-ACTIVATION-PRIMARY? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OEC-CTX @
    _EXT4-OEC-GUARD @
    _EXT4-OEC-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-OEC-CTX @ _EXT4-C.TREE-BLOCK +
    0 _EXT4-ACTIVATE-CLEAN-JOURNAL ?DUP IF EXIT THEN
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @ 0=
    _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR
    _EXT4-OEC-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-OEC-V @ 0
    _EXT4-LAND-EMPTY-JOURNAL ?DUP IF EXIT THEN
    0 _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-OEC-CTX @ _EXT4-C.O.ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JDE-WRITER
VARIABLE _EXT4-JDE-CTX
VARIABLE _EXT4-JDE-V
VARIABLE _EXT4-JDE-IOR

: _EXT4-JDE-FAULT  ( ior -- ior )
    _EXT4-JDE-IOR !
    _EXT4-JDE-IOR @ _EXT4-JDE-WRITER @ _EXT4-JWR-LATCH-FAULT
    VFS-L-STALE _EXT4-JDE-V @ V.LIFECYCLE ! ;

\ Gracefully close one write-active mount only from the checkpointed IDLE
\ boundary.  The common AKR1 landing supplies the durable clean transition;
\ this wrapper supplies same-mount ownership, phase attribution, quarantine,
\ final publication withdrawal, and bounded-workspace scrubbing.
: _EXT4-JWR-DEACTIVATE  ( writer vfs -- ior )
    _EXT4-JDE-V ! DUP _EXT4-JDE-WRITER !
    _EXT4-JWR-VALID? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-IDLE <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JDE-CTX !
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JDE-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDE-V @ _EXT4-CTX _EXT4-JDE-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JDE-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-PREFLIGHT
    _EXT4-JDE-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-DEACTIVATING
    _EXT4-JDE-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JDE-CTX @ _EXT4-JDE-V @ _EXT4-JDE-WRITER @
    _EXT4-LAND-EMPTY-JOURNAL ?DUP IF _EXT4-JDE-FAULT EXIT THEN
    _EXT4-JDE-V @ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-JDE-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP _EXT4-JDE-FAULT EXIT THEN 0= IF
        DROP VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND IF
        VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    0 _EXT4-JDE-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JDE-CTX @ _EXT4-C.READY + !
    0 _EXT4-JDE-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-JDE-CTX @ _EXT4-JWR-REBASE-MOUNTED
    ?DUP IF _EXT4-JDE-FAULT EXIT THEN
    _EXT4-JDE-V @ V.FLAGS DUP @ VFS-F-DIRTY INVERT AND SWAP !
    0 ;

VARIABLE _EXT4-AWR-CTX
VARIABLE _EXT4-AWR-V
VARIABLE _EXT4-AWR-PHYS

\ Resolve either side, or an admitted prefix tear, of the clean-to-RECOVER
\ transition without ever reversing a torn write.  Install tears advance to
\ the exact AKW1 anchor and ext4 dirty endpoint; clear tears advance to the
\ ordinary JBD2 primary.  Once AKW1 is gone, the caller decides whether an
\ authenticated empty orphan set may land clean or a retained orphan must keep
\ RECOVER set and resume through a new transaction.
: _EXT4-RESOLVE-ACTIVATION-WITNESS  ( ctx vfs -- ior )
    _EXT4-AWR-V ! _EXT4-AWR-CTX !
    _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION <> IF VFS-E-INVALID EXIT THEN
    _EXT4-AWR-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @ DUP
    _EXT4-JC-ANCHOR U> IF DROP VFS-E-INVALID EXIT THEN
    DUP IF
        _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ 0= IF
            DROP VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-JC-STANDARD = IF
        \ C/A is reachable only after the dirty ext4 endpoint was durable.
        _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + @ 0=
        _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-AWR-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-AWR-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-STANDARD = IF
            _EXT4-AWR-CTX @ _EXT4-C.BLOCK +
            _EXT4-ZERO-JOURNAL-WITNESS
            ?DUP IF EXIT THEN
        THEN
        0 _EXT4-AWR-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-AWR-PHYS !
        _EXT4-AWR-CTX @ _EXT4-C.BLOCK + _EXT4-AWR-PHYS @ _EXT4-AWR-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        0 _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @
    _EXT4-JC-STANDARD <> IF
        \ D over a D/C prefix is idempotent, so a repeated W4 tear remains
        \ inside the exact activation-prefix proof.
        _EXT4-AWR-CTX @ _EXT4-C.SB + _EXT4-PREPARE-DIRTY-SUPER
        ?DUP IF EXIT THEN
        _EXT4-AWR-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS
        ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        -1 _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + !
        0 _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + !
        _EXT4-AWR-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-AWR-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    -1 _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + !
    0 _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + !
    _EXT4-JW-NONE _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JC-NONE _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    0 ;

VARIABLE _EXT4-RT-CTX
VARIABLE _EXT4-RT-V

: _EXT4-FINISH-RECOVERY-LANDING  ( ctx vfs -- ior )
    _EXT4-RT-V ! _EXT4-RT-CTX !
    _EXT4-RT-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION = IF
        _EXT4-RT-CTX @ _EXT4-RT-V @
        _EXT4-RESOLVE-ACTIVATION-WITNESS ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RT-V @ 0 _EXT4-LAND-EMPTY-JOURNAL EXIT
    THEN
    _EXT4-RT-CTX @ _EXT4-C.J.CLEANUP + @ DUP 0<> IF
        DUP _EXT4-JC-STANDARD = SWAP _EXT4-JC-ANCHOR = OR 0= IF
            VFS-E-INVALID EXIT
        THEN
        0 _EXT4-RT-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @ CMOVE
        _EXT4-RT-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-RT-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RT-CTX @
        _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @ CMOVE
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-ZERO-JOURNAL-WITNESS
        ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @
        _EXT4-PREFIX-MERGE? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        0 _EXT4-RT-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RT-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RT-V @ _EXT4-RELOAD-STRICT EXIT
    ELSE DROP THEN
    _EXT4-RT-CTX @ _EXT4-PREPARE-CLEAR ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-RT-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-RT-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-RT-V @ _EXT4-RELOAD-STRICT ;

: _EXT4-RECOVER-JOURNAL  ( ctx vfs -- ior )
    _EXT4-RJ-V ! _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION = IF
        \ AKW1 precedes every inode-map mutation.  A dirty-super bootstrap
        \ therefore can and must upgrade to strict whole-filesystem authority
        \ before completing any witnessed protocol write.  Ordinary committed
        \ replay keeps its independent recovery proof until its afterimages
        \ have landed and can be authenticated as one current filesystem.
        _EXT4-RJ-CTX @ _EXT4-C.J.STRICT + @ -1 <> IF
            _EXT4-RJ-CTX @ _EXT4-AUTHENTICATE-REST ?DUP IF EXIT THEN
            _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @
            _EXT4-JW-ACTIVATION <> IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-RJ-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS
        ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-RJ-V @
        _EXT4-RESOLVE-ACTIVATION-WITNESS ?DUP IF EXIT THEN
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.HOME-WRITES + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-HITS + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
    _EXT4-RJ-CTX @ _EXT4-C.J.START + @ IF
        0 _EXT4-RJ-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
        _EXT4-RJ-CTX @ _EXT4-C.J.FEATURES + @ DUP
        _EXT4-JBD2-I-RECOVERY = SWAP
        _EXT4-JBD2-I-RECOVERY-REVOKE = OR 0= IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JSCAN-PREFLIGHT _EXT4-RJ-CTX @ _EXT4-JSCAN
        ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + @ _EXT4-RJ-CTX @
        _EXT4-ENSURE-REVOKE-WORKSPACE ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + @ IF
            _EXT4-JSCAN-REVOKES _EXT4-RJ-CTX @ _EXT4-JSCAN
            ?DUP IF EXIT THEN
        THEN
        -1 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
        \ A dirty checksum-torn primary super has no authority of its own.
        \ Its latest authenticated replacement must be committed and must
        \ survive the completed revoke pass before any home write is allowed.
        _EXT4-RJ-CTX @ _EXT4-C.SUPER-TORN + @
        _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0= AND IF
            _EXT4-RJ-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + @ 0= IF
                0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
            _EXT4-RJ-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
            _EXT4-RJ-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + @ 1-
            0xFFFFFFFF AND
            _EXT4-RJ-CTX @ _EXT4-JOURNAL-REVOKED? IF
                0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-JSCAN-REPLAY _EXT4-RJ-CTX @ _EXT4-JSCAN
        0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
        ?DUP IF EXIT THEN
    ELSE
        _EXT4-RJ-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
        _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ IF
            _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
        ELSE
            _EXT4-RJ-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
                DROP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @
            THEN
        THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.CURSOR + !
    THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    \ Replay may intentionally leave a durable orphan record when no cleanup
    \ commit existed.  Authenticate that plan before deciding whether the
    \ ordinary clear is authorized; policy refusal belongs after this branch.
    _EXT4-RJ-CTX @ _EXT4-RJ-V @
    _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    \ Untrusted replay can replace inode-table afterimages, so no certificate
    \ obtained before it can authorize cleanup homes.  The current strict
    \ image must pass a fresh complete scan.  A retained orphan performs that
    \ scan itself after this routine returns.
    _EXT4-RJ-CTX @ _EXT4-C.O.ACTIVE + @ IF
        -1 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
        0 EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-PREPARE-CLEAR ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.START + @ 0=
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0<> AND
    _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + @ 0= AND 0= IF
        _EXT4-RJ-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
    0 ;

VARIABLE _EXT4-MSF-CTX VARIABLE _EXT4-MSF-INDEX
VARIABLE _EXT4-MSF-COUNT VARIABLE _EXT4-MSF-RECORD
VARIABLE _EXT4-MSF-CANDIDATE VARIABLE _EXT4-MSF-HEAD

: _EXT4-FIND-SELECTED-ORPHAN
  ( ctx -- plan-record ior )
    DUP _EXT4-MSF-CTX ! 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MSF-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-MSF-CTX @ _EXT4-C.O.ACTIVE + @ 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-MSF-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-MSF-HEAD !
    0 _EXT4-MSF-INDEX ! 0 _EXT4-MSF-COUNT ! 0 _EXT4-MSF-RECORD !
    BEGIN
        _EXT4-MSF-INDEX @ _EXT4-MSF-CTX @ _EXT4-C.O.SLOTS + @ U<
    WHILE
        _EXT4-MSF-INDEX @ _EXT4-MSF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            DUP _EXT4-MSF-CANDIDATE ! 1 _EXT4-MSF-COUNT +!
            _EXT4-MSF-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ IF
                _EXT4-MSF-CANDIDATE @ _EXT4-OE.KIND + @
                _EXT4-OK-LEGACY =
                _EXT4-MSF-CANDIDATE @ _EXT4-OE.INO + @
                _EXT4-MSF-HEAD @ = AND IF
                    _EXT4-MSF-RECORD @ IF
                        DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-MSF-CANDIDATE @ _EXT4-MSF-RECORD !
                THEN
            ELSE
                _EXT4-MSF-CANDIDATE @ _EXT4-OE.KIND + @
                _EXT4-OK-MODERN <> IF
                    DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
                THEN
                _EXT4-MSF-RECORD @ 0= IF
                    _EXT4-MSF-CANDIDATE @ _EXT4-MSF-RECORD !
                ELSE
                    _EXT4-MSF-CANDIDATE @ _EXT4-OE.LOCATOR-A + @
                    _EXT4-MSF-RECORD @ _EXT4-OE.LOCATOR-A + @ U<
                    _EXT4-MSF-CANDIDATE @ _EXT4-OE.LOCATOR-A + @
                    _EXT4-MSF-RECORD @ _EXT4-OE.LOCATOR-A + @ =
                    _EXT4-MSF-CANDIDATE @ _EXT4-OE.LOCATOR-B + @
                    _EXT4-MSF-RECORD @ _EXT4-OE.LOCATOR-B + @ U< AND OR IF
                        _EXT4-MSF-CANDIDATE @ _EXT4-MSF-RECORD !
                    THEN
                THEN
            THEN
        THEN
        DROP 1 _EXT4-MSF-INDEX +!
    REPEAT
    _EXT4-MSF-COUNT @ _EXT4-MSF-CTX @ _EXT4-C.O.ACTIVE + @ <>
    _EXT4-MSF-RECORD @ 0= OR IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-MSF-RECORD @ _EXT4-MSF-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-MSF-RECORD @ 0 ;

VARIABLE _EXT4-MQ-CTX VARIABLE _EXT4-MQ-INDEX
VARIABLE _EXT4-MQ-COUNT VARIABLE _EXT4-MQ-CREDIT VARIABLE _EXT4-MQ-REVOKE
VARIABLE _EXT4-MQ-MAX VARIABLE _EXT4-MQ-REVOKE-MAX VARIABLE _EXT4-MQ-IOR

\ A retained shared-EA after-image occupies one metadata home.  If preceding
\ orphan deletions reduce that EA to its final owner, releasing it instead can
\ occupy one block-bitmap home plus at most one new primary-GDT page.  Thus one
\ additional metadata slot is the exact topology-derived upper delta.  Keep
\ per-transaction measurement exact; this bound sizes only the reusable writer.
: _EXT4-MQ-CAPACITY-CREDIT  ( exact-credit -- capacity-credit ior )
    _EXT4-JCM-DELETE @ _EXT4-JFI-EA-REFDEC? AND IF
        1 _EXT4-UADD? EXIT
    THEN
    0 ;

: _EXT4-MQ-CAPACITY-REVOKE  ( exact-credit -- capacity-credit ior )
    _EXT4-JCM-DELETE @ _EXT4-JFI-EA-REFDEC? AND IF
        1 _EXT4-UADD? EXIT
    THEN
    0 ;

\ Qualify every retained record before the first media mutation and derive a
\ safe reusable-writer requirement from each exact current credit.  The plan's
\ geometry-derived slot count is the only loop bound.
: _EXT4-QUALIFY-ORPHAN-PLAN
  ( ctx -- max-meta-credit max-revoke-credit ior )
    DUP _EXT4-MQ-CTX ! 0= IF 0 0 VFS-E-INVALID EXIT THEN
    _EXT4-MQ-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        0 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-MQ-CTX @ _EXT4-C.O.ACTIVE + @ 0= IF
        0 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    0 _EXT4-MQ-INDEX ! 0 _EXT4-MQ-COUNT !
    0 _EXT4-MQ-MAX ! 0 _EXT4-MQ-REVOKE-MAX !
    BEGIN _EXT4-MQ-INDEX @ _EXT4-MQ-CTX @ _EXT4-C.O.SLOTS + @ U< WHILE
        _EXT4-MQ-INDEX @ _EXT4-MQ-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            DUP _EXT4-MQ-CTX @ _EXT4-MEASURE-ORPHAN-CLEANUP
            _EXT4-MQ-IOR ! _EXT4-MQ-REVOKE ! _EXT4-MQ-CREDIT !
            _EXT4-MQ-IOR @ ?DUP IF NIP 0 0 ROT EXIT THEN
            _EXT4-MQ-CREDIT @ _EXT4-MQ-CAPACITY-CREDIT
            _EXT4-MQ-IOR ! _EXT4-MQ-CREDIT !
            _EXT4-MQ-IOR @ ?DUP IF NIP 0 0 ROT EXIT THEN
            _EXT4-MQ-REVOKE @ _EXT4-MQ-CAPACITY-REVOKE
            _EXT4-MQ-IOR ! _EXT4-MQ-REVOKE !
            _EXT4-MQ-IOR @ ?DUP IF NIP 0 0 ROT EXIT THEN
            _EXT4-MQ-CREDIT @ _EXT4-MQ-MAX @ U> IF
                _EXT4-MQ-CREDIT @ _EXT4-MQ-MAX !
            THEN
            _EXT4-MQ-REVOKE @ _EXT4-MQ-REVOKE-MAX @ U> IF
                _EXT4-MQ-REVOKE @ _EXT4-MQ-REVOKE-MAX !
            THEN
            1 _EXT4-MQ-COUNT +!
        THEN
        DROP 1 _EXT4-MQ-INDEX +!
    REPEAT
    _EXT4-MQ-COUNT @ _EXT4-MQ-CTX @ _EXT4-C.O.ACTIVE + @ <>
    _EXT4-MQ-MAX @ 0= OR IF
        0 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MQ-MAX @ _EXT4-MQ-REVOKE-MAX @ 0 ;

VARIABLE _EXT4-MOC-CTX VARIABLE _EXT4-MOC-V
VARIABLE _EXT4-MOC-RECORD VARIABLE _EXT4-MOC-CREDIT VARIABLE _EXT4-MOC-CAP
VARIABLE _EXT4-MOC-REVOKE VARIABLE _EXT4-MOC-REVOKE-CAP
VARIABLE _EXT4-MOC-WRITER VARIABLE _EXT4-MOC-TX VARIABLE _EXT4-MOC-IOR
VARIABLE _EXT4-MOC-ARENA VARIABLE _EXT4-MOC-MARK VARIABLE _EXT4-MOC-END
VARIABLE _EXT4-MOC-SPAN VARIABLE _EXT4-MOC-MARK-VALID
VARIABLE _EXT4-MOC-TRANSIENT

: _EXT4-MOC@  ( -- ctx )  _EXT4-MOC-CTX @ ;
: _EXT4-MOC-V@  ( -- vfs )  _EXT4-MOC-V @ ;

\ Prove that a remounted reset prefix was derived from an active journal, not
\ from an empty-journal landing whose intended endpoint would clear the orphan
\ protocol bit.  The exact AKG1 anchor is the durable authority in either an
\ intact-witness or sequential-prefix-torn primary state.
: _EXT4-MOC-REQUIRE-ACTIVE-RESET  ( -- ior )
    _EXT4-MOC@ _EXT4-C.J.ANCHOR + @ DUP 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-MOC@ _EXT4-READ-JBLOCK ?DUP IF NIP EXIT THEN
    DUP _EXT4-MOC@ _EXT4-JBD2-ANCHOR-BLOCK?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN DROP
    _EXT4-MOC@ _EXT4-C.BLOCK + _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN 0 ;

\ Convert only an authenticated, retained orphan recovery prefix to
\ the standard empty RECOVER-set journal.  AKG1 is retired with the dirty
\ superblock still authoritative; ORPHAN_PRESENT is never prepared or cleared.
\ The caller may then emit a fresh cleanup transaction without repeating AKW1.
: _EXT4-MOC-CONVERGE-RETAINED-JOURNAL  ( -- ior )
    _EXT4-MOC@ _EXT4-C.RECOVERY + @ 0=
    _EXT4-MOC@ _EXT4-C.J.REPLAYED + @ -1 <> OR IF VFS-E-INVALID EXIT THEN
    _EXT4-MOC@ _EXT4-C.SUPER-TORN + @ IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT THEN
    0 _EXT4-MOC-TRANSIENT !
    _EXT4-MOC@ _EXT4-C.J.START + @ IF
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-MOC@ _EXT4-C.J.WITNESS + @ IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN -1 _EXT4-MOC-TRANSIENT !
    ELSE
        _EXT4-MOC@ _EXT4-C.J.WITNESS + @
        _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @ OR IF
            _EXT4-MOC@ _EXT4-C.J.WITNESS + @ DUP IF
                _EXT4-JW-RECOVERY <> IF
                    EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
            ELSE
                DROP
                _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ 0= IF
                    EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
            THEN
            _EXT4-MOC-REQUIRE-ACTIVE-RESET ?DUP IF EXIT THEN
            -1 _EXT4-MOC-TRANSIENT ! THEN
    THEN
    -1 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-MOC@ _EXT4-C.J.START + @
    _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR IF
        _EXT4-MOC@ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN THEN
    _EXT4-MOC-TRANSIENT @ IF
        _EXT4-MOC@ _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY
        ?DUP IF EXIT THEN _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-MOC@ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN THEN
    _EXT4-MOC@ _EXT4-MOC-V@ _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-MOC@ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    -1 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-MOC@ _EXT4-JWR-REBASE-WRITE-ACTIVE ?DUP IF EXIT THEN
    -1 _EXT4-MOC@ _EXT4-C.J.REPLAYED + ! 0 ;

: _EXT4-MOC-WITHDRAW  ( -- )
    0 _EXT4-MOC-RECORD !
    0 _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + !
    0 _EXT4-MOC@ _EXT4-C.J.PROTOCOL-OWNERS + ! ;

\ Mount cleanup owns every allocation after this arena mark.  All exits scrub
\ and roll back that tail, so its narrow writer geometry cannot pin the
\ capacity needed by a later public writer.
: _EXT4-MOC-MARK-ARENA  ( -- )
    _EXT4-MOC@ _EXT4-C.ARENA + @ DUP _EXT4-MOC-ARENA !
    ARENA-SNAP _EXT4-MOC-MARK !
    -1 _EXT4-MOC-MARK-VALID ! ;

: _EXT4-MOC-WRITER-ALLOCATION?  ( writer -- flag )
    DUP _EXT4-MOC-MARK @ <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.MAGIC + @ _EXT4-JWR-MAGIC <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.SELF + @ OVER <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-MOC@ <> IF DROP FALSE EXIT THEN
    _EXT4-JWR.TOTAL + @ _EXT4-MOC-SPAN @ = ;

: _EXT4-MOC-RELEASE  ( -- ior )
    _EXT4-MOC-MARK-VALID @ 0= IF 0 EXIT THEN
    _EXT4-MOC@ _EXT4-C.ARENA + @ _EXT4-MOC-ARENA @ <> IF
        VFS-E-CORRUPT EXIT THEN
    _EXT4-MOC-ARENA @ A.PTR @ _EXT4-MOC-END !
    _EXT4-MOC-MARK @ _EXT4-MOC-ARENA @ A.BASE @ U<
    _EXT4-MOC-END @ _EXT4-MOC-MARK @ U< OR
    _EXT4-MOC-END @ _EXT4-MOC-ARENA @ A.BASE @
    _EXT4-MOC-ARENA @ A.SIZE @ + U> OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-MOC-END @ _EXT4-MOC-MARK @ - _EXT4-MOC-SPAN !
    _EXT4-MOC-WRITER @ ?DUP IF
        DUP _EXT4-MOC@ _EXT4-C.J.WRITER + @ <> IF
            DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC@ _EXT4-C.J.WRITER-STORE-KIND + @
        _EXT4-JWR-STORE-MOUNT <> IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC@ _EXT4-C.J.WRITER-ARENA + @
        _EXT4-MOC-ARENA @ <> IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC-SPAN @ _EXT4-JWR-SIZE U< IF
            DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC-WRITER-ALLOCATION? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-MOC@ _EXT4-C.J.WRITER + @ IF VFS-E-CORRUPT EXIT THEN
    THEN
    0 _EXT4-MOC@ _EXT4-C.J.WRITER + !
    0 _EXT4-MOC@ _EXT4-C.J.WRITER-STORE-KIND + !
    0 _EXT4-MOC@ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-MOC-MARK @ _EXT4-MOC-SPAN @ 0 FILL
    _EXT4-MOC-ARENA @ _EXT4-MOC-MARK @ ARENA-ROLLBACK
    0 _EXT4-MOC-RECORD ! 0 _EXT4-MOC-CREDIT ! 0 _EXT4-MOC-REVOKE !
    0 _EXT4-MOC-CAP ! 0 _EXT4-MOC-REVOKE-CAP !
    0 _EXT4-MOC-WRITER ! 0 _EXT4-MOC-TX !
    0 _EXT4-MOC-MARK-VALID ! 0 ;

: _EXT4-MOC-RELEASE-RESULT  ( -- )
    _EXT4-MOC-RELEASE ?DUP IF _EXT4-MOC-IOR ! THEN ;

: _EXT4-MOC-FAIL-CLEAN  ( ior -- ior )
    _EXT4-MOC-IOR !
    _EXT4-MOC-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF _EXT4-MOC-IOR ! THEN
        ELSE
            DROP
        THEN
    THEN
    _EXT4-MOC-WITHDRAW _EXT4-MOC-RELEASE-RESULT _EXT4-MOC-IOR @ ;

: _EXT4-MOC-FAIL-DIRTY  ( ior -- ior )
    _EXT4-MOC-IOR ! _EXT4-MOC-WITHDRAW
    _EXT4-MOC-RELEASE-RESULT _EXT4-MOC-IOR @ ;

: _EXT4-MOC-FAIL-CURRENT  ( ior -- ior )
    _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + @ IF
        _EXT4-MOC-FAIL-DIRTY
    ELSE
        _EXT4-MOC-FAIL-CLEAN
    THEN ;

\ Drain one fully qualified orphan union from either an exact clean journal or
\ a crash-converged empty RECOVER-set endpoint.  One reusable writer is sized
\ to the maximum qualified per-record metadata and revoke capacities.  Each
\ selected record is dry-staged, emitted, checkpointed, and removed from a
\ freshly rebuilt plan before the next selection; only the authenticated empty
\ endpoint lands clean.
: _EXT4-COMPLETE-ORPHAN-PLAN-BODY  ( ctx vfs -- ior )
    _EXT4-MOC-V ! _EXT4-MOC-CTX !
    0 _EXT4-MOC-RECORD ! 0 _EXT4-MOC-CREDIT ! 0 _EXT4-MOC-REVOKE !
    0 _EXT4-MOC-CAP ! 0 _EXT4-MOC-REVOKE-CAP !
    0 _EXT4-MOC-WRITER ! 0 _EXT4-MOC-TX !
    0 _EXT4-MOC-MARK-VALID !
    _EXT4-MOC@ _EXT4-C.READY + @ _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITER + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITER-STORE-KIND + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITER-ARENA + @ OR IF VFS-E-INVALID EXIT THEN
    _EXT4-MOC-V@ _EXT4-CTX _EXT4-MOC@ <> IF
        VFS-E-INVALID EXIT THEN
    _EXT4-MOC-V@ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOC-V@ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT THEN
    _EXT4-MOC@ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-MOC@ _EXT4-RECOVERY-MEDIA
    ?DUP IF _EXT4-MOC-WITHDRAW EXIT THEN
    _EXT4-MOC@ _EXT4-QUALIFY-ORPHAN-PLAN
    _EXT4-MOC-IOR ! _EXT4-MOC-REVOKE-CAP ! _EXT4-MOC-CAP !
    _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-WITHDRAW EXIT THEN
    _EXT4-MOC-CAP @ 0 _EXT4-MOC-REVOKE-CAP @ _EXT4-MOC@
    _EXT4-JTX-PREFLIGHT-CAPACITY
    ?DUP IF _EXT4-MOC-WITHDRAW EXIT THEN
    _EXT4-MOC@ _EXT4-C.RECOVERY + @ IF
        _EXT4-JFO-CERT-INVALIDATE
        _EXT4-MOC-CONVERGE-RETAINED-JOURNAL DUP IF
            _EXT4-MOC-WITHDRAW EXIT
        THEN DROP
        \ Convergence reloads media and rebuilds the plan.  Requalify every
        \ survivor because no record pointer or capacity fact crosses it.
        _EXT4-MOC@ _EXT4-QUALIFY-ORPHAN-PLAN
        _EXT4-MOC-IOR ! _EXT4-MOC-REVOKE-CAP ! _EXT4-MOC-CAP !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-CAP @ 0 _EXT4-MOC-REVOKE-CAP @ _EXT4-MOC@
        _EXT4-JTX-PREFLIGHT-CAPACITY
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    ELSE
        _EXT4-MOC@ _EXT4-C.J.START + @ _EXT4-MOC@ _EXT4-C.J.WITNESS + @ OR
        _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @ OR
        _EXT4-MOC@ _EXT4-C.SUPER-TORN + @ OR IF
            VFS-E-INVALID _EXT4-MOC-WITHDRAW EXIT
        THEN
        _EXT4-MOC@ _EXT4-JWR-REBASE-MOUNTED
        ?DUP IF _EXT4-MOC-WITHDRAW EXIT THEN
    THEN
    _EXT4-MOC-MARK-ARENA
    -1 _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + !
    _EXT4-MOC-CAP @ 0 _EXT4-MOC-REVOKE-CAP @ _EXT4-MOC@
    _EXT4-JWR-ALLOCATE-MOUNT
    _EXT4-MOC-IOR ! _EXT4-MOC-WRITER !
    _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
    BEGIN _EXT4-MOC@ _EXT4-C.O.ACTIVE + @ WHILE
        _EXT4-MOC@ _EXT4-FIND-SELECTED-ORPHAN
        _EXT4-MOC-IOR ! _EXT4-MOC-RECORD !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
        _EXT4-MOC-RECORD @ _EXT4-MOC@ _EXT4-MEASURE-ORPHAN-CLEANUP
        _EXT4-MOC-IOR ! _EXT4-MOC-REVOKE ! _EXT4-MOC-CREDIT !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
        _EXT4-MOC-CREDIT @ _EXT4-MOC-CAP @ U> IF
            VFS-E-CORRUPT _EXT4-MOC-FAIL-CURRENT EXIT
        THEN
        _EXT4-MOC-REVOKE @ _EXT4-MOC-REVOKE-CAP @ U> IF
            VFS-E-CORRUPT _EXT4-MOC-FAIL-CURRENT EXIT
        THEN
        _EXT4-MOC-CREDIT @ 0 _EXT4-MOC-REVOKE @
        _EXT4-MOC-WRITER @ _EXT4-JTX-BEGIN
        _EXT4-MOC-IOR ! _EXT4-MOC-TX !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
        _EXT4-MOC-RECORD @ _EXT4-MOC-TX @
        _EXT4-JTX-STAGE-ORPHAN-CLEANUP
        ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
        _EXT4-MOC-TX @ _EXT4-JTX-ABORT
        ?DUP IF _EXT4-MOC-FAIL-CURRENT EXIT THEN
        _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
            _EXT4-MOC-WRITER @ _EXT4-JWR-ACTIVATE
            ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        THEN
        _EXT4-MOC-CREDIT @ 0 _EXT4-MOC-REVOKE @
        _EXT4-MOC-WRITER @ _EXT4-JTX-BEGIN
        _EXT4-MOC-IOR ! _EXT4-MOC-TX !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-RECORD @ _EXT4-MOC-TX @
        _EXT4-JTX-STAGE-ORPHAN-CLEANUP
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-TX @ _EXT4-JTX-EMIT
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        \ Emission has consumed the selected-record authority.  Do not retain
        \ its arena address across checkpoint's authenticated plan rebuild.
        0 _EXT4-MOC-RECORD !
        _EXT4-MOC-TX @ _EXT4-JTX-CHECKPOINT
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-WRITER @ _EXT4-JWR-VALID? 0= IF
            VFS-E-CORRUPT _EXT4-MOC-FAIL-DIRTY EXIT
        THEN
        _EXT4-MOC-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
        _EXT4-MOC-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
            VFS-E-CORRUPT _EXT4-MOC-FAIL-DIRTY EXIT
        THEN
    REPEAT
    _EXT4-MOC@ _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
        VFS-E-CORRUPT _EXT4-MOC-FAIL-DIRTY EXIT
    THEN
    _EXT4-MOC-WRITER @ _EXT4-MOC-V@ _EXT4-JWR-DEACTIVATE
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC-V@ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-MOC-FAIL-DIRTY EXIT THEN
    \ Deactivation has already withdrawn writer/current publication.  Preserve
    \ its authenticated protocol-owner proof for the mounted public writer;
    \ only a failed workspace release revokes that proof.
    _EXT4-MOC-RELEASE ?DUP IF _EXT4-MOC-WITHDRAW EXIT THEN 0 ;

\ One mount-cleanup invocation owns the proof scope.  Every exit, including a
\ media or writer failure returned by the body, clears the certificate before
\ control can return to a caller or another filesystem context.
: _EXT4-COMPLETE-ORPHAN-PLAN  ( ctx vfs -- ior )
    _EXT4-JFO-CERT-BEGIN ?DUP IF >R 2DROP R> EXIT THEN
    _EXT4-COMPLETE-ORPHAN-PLAN-BODY
    _EXT4-JFO-CERT-END ;

\ =====================================================================
\  Mount, metadata callbacks, and binding descriptors
\ =====================================================================

VARIABLE _EXT4-M-V
VARIABLE _EXT4-M-CTX
VARIABLE _EXT4-M-FRESH
VARIABLE _EXT4-M-STAGED-WRITE

: _EXT4-MOUNT-AUTHENTICATE  ( vfs staged-write? -- ior )
    _EXT4-M-STAGED-WRITE !
    DUP _EXT4-M-V !
    _EXT4-CRC-CAPABILITY ?DUP IF NIP EXIT THEN
    \ Invalidate retained transaction and protocol-write authority before any
    \ remount check or media-derived context reset can fail.
    _EXT4-M-V @ V.BCTX @ ?DUP IF
        0 OVER _EXT4-C.J.WRITER-CURRENT + !
        0 SWAP _EXT4-C.J.PROTOCOL-OWNERS + !
    THEN
    DUP _EXT4-ATTACHED? 0= IF DROP EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT THEN
    DROP
    _EXT4-M-V @ V.VOLUME @ DUP VOL.SECTOR-SIZE _EXT4-SECTOR <> IF
        DROP 0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    _EXT4-IO-VOL ! _EXT4-M-V @ _EXT4-IO-VFS !
    0 _EXT4-M-FRESH !
    _EXT4-M-V @ V.BCTX @ ?DUP IF
        _EXT4-M-CTX !
    ELSE
        _EXT4-M-V @ V.ARENA @ _EXT4-CTX-SIZE ARENA-ALLOT?
        IF DROP VFS-E-NOMEM EXIT THEN
        DUP _EXT4-M-CTX ! _EXT4-M-V @ V.BCTX !
        -1 _EXT4-M-FRESH !
    THEN
    _EXT4-M-FRESH @ IF
        _EXT4-M-CTX @ _EXT4-CTX-SIZE 0 FILL
        _EXT4-M-V @ V.ARENA @ _EXT4-M-CTX @ _EXT4-C.ARENA + !
    ELSE
        \ Preserve arena workspace allocations owned by this binding across a
        \ failed-mount retry while resetting all media-derived state.
        _EXT4-M-CTX @ _EXT4-CTX-RESET-SIZE 0 FILL
    THEN
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-HITS + !
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-READY + !
    0 _EXT4-M-CTX @ _EXT4-C.J.HEAD + !
    0 _EXT4-M-CTX @ _EXT4-C.J.MAX-TRANSACTION + !
    0 _EXT4-M-CTX @ _EXT4-C.J.MAX-TRANS-DATA + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-M-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
    0 _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.LEGACY-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.CLEAR-PENDING + !
    _EXT4-M-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    DUP IF EXIT THEN DROP
    _EXT4-M-CTX @ _EXT4-M-V @ _EXT4-VALIDATE-SUPER
    DUP IF EXIT THEN DROP
    \ Reject unsupported staged geometry immediately after its authenticated
    \ superblock is available, before journal recovery or landing can mutate
    \ media.  The ordinary binding retains its broader read/recovery geometry.
    _EXT4-M-STAGED-WRITE @ IF
        _EXT4-M-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    THEN
    _EXT4-M-CTX @ _EXT4-C.RECOVERY + @ IF
        \ Bootstrap from inode 8 without trusting mutable aggregate counters;
        \ strict whole-filesystem validation follows replay while the journal
        \ is still intact and replayable.
        _EXT4-M-CTX @ _EXT4-VALIDATE-JOURNAL ?DUP IF EXIT THEN
        _EXT4-M-STAGED-WRITE @ IF
            _EXT4-M-CTX @ _EXT4-STAGED-WRITE-JOURNAL-QUALIFY
            ?DUP IF EXIT THEN
        THEN
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-RECOVER-JOURNAL ?DUP IF EXIT THEN
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    ELSE
        _EXT4-M-CTX @ _EXT4-AUTHENTICATE-REST ?DUP IF EXIT THEN
        \ Clean/torn paths now have authenticated journal geometry but have
        \ not yet entered either mutation-capable recovery landing below.
        _EXT4-M-STAGED-WRITE @ IF
            _EXT4-M-CTX @ _EXT4-STAGED-WRITE-JOURNAL-QUALIFY
            ?DUP IF EXIT THEN
        THEN
        _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + @ IF
            _EXT4-M-CTX @ _EXT4-C.SUPER-TORN + @
            _EXT4-M-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.CLEANUP + @ OR IF
                _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @
                _EXT4-JW-ACTIVATION <> IF
                    EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
                THEN
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-RECOVER-JOURNAL ?DUP IF EXIT THEN
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
            THEN
        ELSE
            _EXT4-M-CTX @ _EXT4-C.SUPER-TORN + @
            _EXT4-M-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @ OR IF
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-FINISH-RECOVERY-LANDING ?DUP IF EXIT THEN
            THEN
        THEN
    THEN
    \ Recovery reloads the authenticated journal state.  Reassert the same
    \ minimum profile at the final mount endpoint before root publication.
    _EXT4-M-STAGED-WRITE @ IF
        _EXT4-M-CTX @ _EXT4-STAGED-WRITE-JOURNAL-QUALIFY ?DUP IF EXIT THEN
    THEN
    _EXT4-M-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
        EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-MOUNT-FINISH  ( -- ior )
    _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + @ IF
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-COMPLETE-ORPHAN-PLAN ?DUP IF EXIT THEN
        _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
            EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-M-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? IF
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-COMPLETE-EMPTY-ORPHAN ?DUP IF EXIT THEN
        _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
            EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-M-CTX @ _EXT4-JWR-REBASE-MOUNTED ?DUP IF EXIT THEN
    _EXT4-M-V @ V.FLAGS DUP @ VFS-F-DIRTY INVERT AND SWAP !
    _EXT4-M-CTX @ _EXT4-M-V @ _EXT4-PUBLISH-ROOT
    -1 _EXT4-M-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    -1 _EXT4-M-CTX @ _EXT4-C.READY + !
    0 ;

: _EXT4-MOUNT  ( vfs -- ior )
    0 _EXT4-MOUNT-AUTHENTICATE ?DUP IF EXIT THEN
    _EXT4-MOUNT-FINISH ;

\ A descriptor capability is instance-wide.  Staged authentication rejects an
\ unsupported filesystem geometry immediately after superblock validation and
\ rejects an insufficient authenticated journal before recovery mutation.
\ Thus every successfully mounted staged instance can configure the minimum
\ nonempty WRITE profile.  The ordinary binding remains available for the
\ complete read/recovery geometry.
: _EXT4-STAGED-WRITE-MOUNT  ( vfs -- ior )
    -1 _EXT4-MOUNT-AUTHENTICATE ?DUP IF EXIT THEN
    _EXT4-MOUNT-FINISH ;

VARIABLE _EXT4-GA-D
VARIABLE _EXT4-GA-V
VARIABLE _EXT4-GA-CTX
VARIABLE _EXT4-GA-TYPE
VARIABLE _EXT4-GA-IOR

: _EXT4-GETATTR  ( dentry vfs -- ior )
    _EXT4-GA-V ! _EXT4-GA-D !
    _EXT4-GA-V @ _EXT4-CTX _EXT4-GA-CTX !
    _EXT4-GA-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-GA-V @ _EXT4-IO-VFS !
    _EXT4-GA-D @ IN.BID @ _EXT4-GA-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-GA-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-GA-IOR ! _EXT4-GA-TYPE !
    _EXT4-GA-IOR @ ?DUP IF EXIT THEN
    _EXT4-GA-TYPE @ _EXT4-GA-D @ IN.TYPE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-GA-CTX @ _EXT4-C.R.GEN + @
    _EXT4-GA-D @ D.VNODE @ VN.GEN @ <> IF VFS-E-STALE EXIT THEN
    _EXT4-GA-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-GA-CTX @ _EXT4-GA-D @ _EXT4-GA-TYPE @ _EXT4-PUBLISH-STAGED
    0 ;

VARIABLE _EXT4-SF-BUF
VARIABLE _EXT4-SF-SIZE
VARIABLE _EXT4-SF-V
VARIABLE _EXT4-SF-CTX
VARIABLE _EXT4-SF-OUT
VARIABLE _EXT4-SF-AVAIL

: _EXT4-STATFS  ( buffer bytes vfs -- ior )
    _EXT4-SF-V ! _EXT4-SF-SIZE ! _EXT4-SF-BUF !
    _EXT4-SF-V @ _EXT4-CTX DUP _EXT4-SF-CTX !
    _EXT4-C.STAT + DUP _EXT4-SF-OUT ! VFS-STATFS-SIZE 0 FILL
    _EXT4-SF-CTX @ _EXT4-C.BSIZE + @ DUP
    _EXT4-SF-OUT @ VSF.BSIZE !
    _EXT4-SF-OUT @ VSF.FRSIZE !
    _EXT4-SF-CTX @ _EXT4-C.BLOCKS + @ _EXT4-SF-OUT @ VSF.BLOCKS !
    _EXT4-SF-CTX @ _EXT4-C.FREE-BLOCKS + @ DUP
    _EXT4-SF-OUT @ VSF.BFREE !
    _EXT4-SF-CTX @ _EXT4-C.RESERVED-BLOCKS + @
    2DUP U< IF 2DROP 0 ELSE - THEN DUP _EXT4-SF-AVAIL !
    _EXT4-SF-OUT @ VSF.BAVAIL !
    _EXT4-SF-CTX @ _EXT4-C.INODES + @ _EXT4-SF-OUT @ VSF.FILES !
    _EXT4-SF-CTX @ _EXT4-C.FREE-INODES + @ _EXT4-SF-OUT @ VSF.FFREE !
    255 _EXT4-SF-OUT @ VSF.NAMEMAX !
    0 _EXT4-SF-OUT @ VSF.FLAGS !
    _EXT4-SF-CTX @ _EXT4-C.UUID-LO + @ _EXT4-SF-OUT @ VSF.FSID-LO !
    _EXT4-SF-CTX @ _EXT4-C.UUID-HI + @ _EXT4-SF-OUT @ VSF.FSID-HI !
    0 _EXT4-SF-OUT @ VSF.RESERVED !
    _EXT4-SF-OUT @ _EXT4-SF-BUF @ VFS-STATFS-SIZE CMOVE
    0 ;

VARIABLE _EXT4-UM-V
VARIABLE _EXT4-UM-CTX
VARIABLE _EXT4-UM-WRITER
VARIABLE _EXT4-UM-STATE

: _EXT4-UM-QUARANTINE  ( ior -- ior )
    VFS-L-STALE _EXT4-UM-V @ V.LIFECYCLE ! ;

: _EXT4-UM-CLEAN-ENDPOINT?  ( -- flag ior )
    _EXT4-UM-V @ _EXT4-ATTACHED? 0= IF FALSE 0 EXIT THEN
    _EXT4-UM-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-UM-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-UM-CTX @ _EXT4-C.SUPER-TORN + @ OR
    _EXT4-UM-V @ V.FLAGS @ VFS-F-DIRTY AND OR IF
        FALSE 0 EXIT
    THEN
    _EXT4-UM-CTX @ _EXT4-C.SB + DUP
    _EXT4-SUPER-CHECKSUM? ?DUP IF
        >R 2DROP FALSE R> EXIT
    THEN 0= IF DROP FALSE 0 EXIT THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= 0 ;

: _EXT4-UM-PREPARE-WRITER  ( -- ior )
    _EXT4-UM-CTX @ _EXT4-C.J.WRITER + @ DUP _EXT4-UM-WRITER ! 0= IF
        0 EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-SHAPE? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR.STATE + @ DUP _EXT4-UM-STATE !
    _EXT4-JWR-FAULTED = IF
        _EXT4-UM-WRITER @ _EXT4-JWR.FAULT + @ DUP 0= IF
            DROP VFS-E-CORRUPT
        THEN
        _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-STATE @ _EXT4-JWR-STAGING =
    _EXT4-UM-STATE @ _EXT4-JWR-ACTIVATING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-EMITTING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-CHECKPOINTING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-DEACTIVATING = OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-UM-STATE @ _EXT4-JWR-COMMITTED = IF
        _EXT4-UM-WRITER @ _EXT4-JTX-CHECKPOINT
        ?DUP IF _EXT4-UM-QUARANTINE EXIT THEN
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    0 ;

VARIABLE _EXT4-SY-V
VARIABLE _EXT4-SY-CTX
VARIABLE _EXT4-SY-D

\ Prepare the global writer at the same durability boundary used by unmount,
\ but keep a live mounted instance published.  Every successful private write
\ is already checkpointed; COMMITTED support is retained so FSYNC/SYNCFS also
\ close a transaction produced by a lower-level private builder.
: _EXT4-LIVE-SYNC-PREPARE  ( vfs -- ior )
    DUP _EXT4-SY-V ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-SY-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF VFS-E-STALE EXIT THEN
    _EXT4-SY-V @ V.BCTX @ DUP _EXT4-SY-CTX ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-SY-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-SY-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-SY-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-SY-V @ _EXT4-IO-VFS !
    _EXT4-SY-V @ _EXT4-UM-V !
    _EXT4-SY-CTX @ _EXT4-UM-CTX !
    _EXT4-UM-PREPARE-WRITER ?DUP IF EXIT THEN
    _EXT4-SY-CTX @ _EXT4-C.J.START + @
    _EXT4-SY-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-SY-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-SY-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-SY-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-SY-CTX @ _EXT4-C.RECOVERY + @ 0<>
    _EXT4-SY-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0<> <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SY-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF
        _EXT4-SY-V @ V.FLAGS @ VFS-F-DIRTY AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-SY-V @ V.FLAGS @ VFS-F-DIRTY AND IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Per-file state is checkpointed synchronously, so FSYNC validates (and, for
\ a lower-level retained COMMITTED transaction, completes) the writer without
\ deactivating the filesystem-wide empty journal.
: _EXT4-FSYNC  ( dentry vfs -- ior )
    _EXT4-SY-V ! _EXT4-SY-D !
    _EXT4-SY-D @ 0= _EXT4-SY-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-SY-D @ _EXT4-SY-V @ _VFS-DENTRY-OWNED? 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-SY-D @ D.VNODE @ 0= IF VFS-E-STALE EXIT THEN
    _EXT4-SY-V @ _EXT4-LIVE-SYNC-PREPARE ;

\ Generic VFS-SYNC clears VFS-F-DIRTY after this callback returns success.
\ Therefore a live ext4 sync must first land the write-active empty journal at
\ a clean endpoint, then republish READY/current ownership for later writes.
: _EXT4-SYNCFS  ( vfs -- ior )
    DUP _EXT4-LIVE-SYNC-PREPARE ?DUP IF NIP EXIT THEN _EXT4-SY-V !
    _EXT4-SY-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF
        _EXT4-UM-WRITER @ DUP 0= IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-SY-V @ _EXT4-JWR-DEACTIVATE ?DUP IF EXIT THEN
    THEN
    _EXT4-UM-CLEAN-ENDPOINT? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    -1 _EXT4-SY-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    -1 _EXT4-SY-CTX @ _EXT4-C.READY + !
    0 ;

: _EXT4-UNMOUNT  ( flags vfs -- ior )
    _EXT4-UM-V ! DROP
    _EXT4-UM-V @ V.BCTX @ DUP 0= IF DROP 0 EXIT THEN _EXT4-UM-CTX !
    _EXT4-UM-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-UM-V @ _EXT4-IO-VFS !
    _EXT4-UM-PREPARE-WRITER ?DUP IF EXIT THEN
    _EXT4-UM-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF
        _EXT4-UM-WRITER @ DUP 0= IF
            DROP VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
        THEN
        _EXT4-UM-V @ _EXT4-JWR-DEACTIVATE
        ?DUP IF _EXT4-UM-QUARANTINE EXIT THEN
    THEN
    _EXT4-UM-CLEAN-ENDPOINT? ?DUP IF
        NIP _EXT4-UM-QUARANTINE EXIT
    THEN 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-CTX @ _EXT4-JWR-RELEASE-DEDICATED
    ?DUP IF _EXT4-UM-QUARANTINE EXIT THEN
    0 _EXT4-UM-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-UM-CTX @ _EXT4-C.READY + !
    0 _EXT4-UM-V @ V.BCTX !
    0 ;

VFS-CAP-PROBE VFS-CAP-MOUNT OR VFS-CAP-UNMOUNT OR
VFS-CAP-READDIR OR VFS-CAP-OPEN OR VFS-CAP-RELEASE OR
VFS-CAP-READ OR VFS-CAP-GETATTR OR VFS-CAP-READLINK OR
VFS-CAP-SYNCFS OR VFS-CAP-FSYNC OR VFS-CAP-STATFS OR
VFS-CAP-LISTXATTR OR VFS-CAP-GETXATTR OR
VFS-CAP-SPARSE OR VFS-CAP-STABLE-HANDLES OR CONSTANT EXT4-CAPS

CREATE EXT4-OPS VFS-OPS-SIZE ALLOT
EXT4-OPS VFS-OPS-SIZE 0 FILL
' _EXT4-PROBE   EXT4-OPS VFS-OP-PROBE   CELLS + !
' _EXT4-MOUNT   EXT4-OPS VFS-OP-MOUNT   CELLS + !
' _EXT4-UNMOUNT EXT4-OPS VFS-OP-UNMOUNT CELLS + !
' _EXT4-READDIR EXT4-OPS VFS-OP-READDIR CELLS + !
' _EXT4-OPEN    EXT4-OPS VFS-OP-OPEN    CELLS + !
' _EXT4-RELEASE EXT4-OPS VFS-OP-RELEASE CELLS + !
' _EXT4-READ    EXT4-OPS VFS-OP-READ    CELLS + !
' _EXT4-GETATTR EXT4-OPS VFS-OP-GETATTR CELLS + !
' _EXT4-READLINK EXT4-OPS VFS-OP-READLINK CELLS + !
' _EXT4-SYNCFS  EXT4-OPS VFS-OP-SYNCFS  CELLS + !
' _EXT4-FSYNC   EXT4-OPS VFS-OP-FSYNC   CELLS + !
' _EXT4-LISTXATTR EXT4-OPS VFS-OP-LISTXATTR CELLS + !
' _EXT4-GETXATTR  EXT4-OPS VFS-OP-GETXATTR  CELLS + !
' _EXT4-STATFS  EXT4-OPS VFS-OP-STATFS  CELLS + !

CREATE EXT4-BINDING
VFS-BINDING-MAGIC ,
VFS-BINDING-ABI-MAJOR ,
VFS-BINDING-ABI-MINOR ,
VFS-BINDING-DESC-SIZE ,
VFS-OPS-SIZE ,
EXT4-CAPS ,
VFS-BF-NEEDS-VOLUME VFS-BF-READ-ONLY OR VFS-BF-STABLE-IDS OR ,
EXT4-OPS ,
0 , 0 ,

: EXT4-NEW  ( arena volume -- vfs ior )
    EXT4-BINDING SWAP VFS-NEW ;

\ Explicit ABI-1 binding for the currently qualified write operations.  The
\ ordinary binding above stays read-only.  SPARSE continues to describe
\ sparse-file read/mapping semantics; WRITE can overwrite initialized blocks,
\ allocate one complete logical hole inside existing EOF, append inside an
\ initialized partial tail, and allocate one initialized block per callback at
\ aligned EOF.  VFS-WRITE-EXACT can compose a tail append and additional aligned
\ allocation callbacks, each independently checkpointed.  A dedicated 1/1/0
\ profile serves initialized RMW; ordinary allocation begins exact 4/1/0.
\ When a full unmergeable resident root must become depth one, the callback
\ measures and begins exactly 5/1/0 through 7/1/0 according to distinct bitmap
\ and primary-GDT homes.  A full unmergeable selected external leaf similarly
\ splits while the resident root has room, with exact 6/1/0 through 8/1/0
\ credit.  Both run within a caller profile large enough to contain the
\ measured topology.  CREATE additionally allocates one initialized-group
\ inode and inserts it into authenticated slack in a one-block linear
\ directory through an at-most-six-metadata-home transaction.
\ Bind a containing profile and trusted clock before the first mutation.
EXT4-CAPS VFS-CAP-WRITE OR VFS-CAP-CREATE OR
CONSTANT EXT4-STAGED-WRITE-CAPS

CREATE EXT4-STAGED-WRITE-OPS VFS-OPS-SIZE ALLOT
EXT4-OPS EXT4-STAGED-WRITE-OPS VFS-OPS-SIZE CMOVE
' _EXT4-STAGED-WRITE-MOUNT
EXT4-STAGED-WRITE-OPS VFS-OP-MOUNT CELLS + !
' _EXT4-WRITE
EXT4-STAGED-WRITE-OPS VFS-OP-WRITE CELLS + !

CREATE EXT4-STAGED-WRITE-BINDING
VFS-BINDING-MAGIC ,
VFS-BINDING-ABI-MAJOR ,
VFS-BINDING-ABI-MINOR ,
VFS-BINDING-DESC-SIZE ,
VFS-OPS-SIZE ,
EXT4-STAGED-WRITE-CAPS ,
VFS-BF-NEEDS-VOLUME VFS-BF-STABLE-IDS OR ,
EXT4-STAGED-WRITE-OPS ,
0 , 0 ,

: EXT4-STAGED-WRITE-NEW  ( arena volume -- vfs ior )
    EXT4-STAGED-WRITE-BINDING SWAP VFS-NEW ;

: EXT4-BLOCK-SIZE@  ( vfs -- bytes )  _EXT4-CTX _EXT4-C.BSIZE + @ ;
: EXT4-BLOCK-COUNT@ ( vfs -- blocks ) _EXT4-CTX _EXT4-C.BLOCKS + @ ;
: EXT4-GROUP-COUNT@ ( vfs -- groups ) _EXT4-CTX _EXT4-C.GROUPS + @ ;
: EXT4-INODE-SIZE@  ( vfs -- bytes )  _EXT4-CTX _EXT4-C.ISIZE + @ ;

\ =====================================================================
\  Allocation-backed one-block hole fill
\ =====================================================================

VARIABLE _XH-SOURCE
VARIABLE _XH-COUNT
VARIABLE _XH-OFFSET
VARIABLE _XH-INO
VARIABLE _XH-EXPECTED-GEN
VARIABLE _XH-SECONDS
VARIABLE _XH-NSEC
VARIABLE _XH-WRITER
VARIABLE _XH-CTX
VARIABLE _XH-BSIZE
VARIABLE _XH-SIZE
VARIABLE _XH-NEW-SIZE
VARIABLE _XH-GROW
VARIABLE _XH-LOGICAL
VARIABLE _XH-BLOCK-OFF
VARIABLE _XH-TYPE
VARIABLE _XH-EA
VARIABLE _XH-GROUP
VARIABLE _XH-CANDIDATE-GROUP
VARIABLE _XH-LEAF-GROUP
VARIABLE _XH-INODE-HOME
VARIABLE _XH-INODE-OFF
VARIABLE _XH-BITMAP-HOME
VARIABLE _XH-GDT-HOME
VARIABLE _XH-LEAF-BITMAP-HOME
VARIABLE _XH-LEAF-GDT-HOME
VARIABLE _XH-SUPER-HOME
VARIABLE _XH-BLOCKS
VARIABLE _XH-NEW-BLOCKS
VARIABLE _XH-NEW-FREE
VARIABLE _XH-ROOT
VARIABLE _XH-EDIT-NODE
VARIABLE _XH-TREE-DEPTH
VARIABLE _XH-ROOT-ENTRIES
VARIABLE _XH-ROOT-INDEX
VARIABLE _XH-ROOT-GENERATION
VARIABLE _XH-INODE-GENERATION
VARIABLE _XH-ENTRIES
VARIABLE _XH-ENTRY-MAX
VARIABLE _XH-INSERT
VARIABLE _XH-INDEX
VARIABLE _XH-ENTRY
VARIABLE _XH-START
VARIABLE _XH-RAW-LEN
VARIABLE _XH-LEN
VARIABLE _XH-END
VARIABLE _XH-PHYSICAL
VARIABLE _XH-DATA-BLOCKS
VARIABLE _XH-ACCOUNTED-BLOCKS
VARIABLE _XH-CANDIDATE
VARIABLE _XH-EXISTING-LEAF
VARIABLE _XH-LEAF-CANDIDATE
VARIABLE _XH-LEAF-MAX
VARIABLE _XH-LEAF-FIRST
VARIABLE _XH-LEAF-SECOND-FIRST
VARIABLE _XH-ROOT-GROW
VARIABLE _XH-LEAF-SPLIT
VARIABLE _XH-SCAN-NODE
VARIABLE _XH-SCAN-ENTRIES
VARIABLE _XH-SCAN-LEAF
VARIABLE _XH-RANGE-COUNT
VARIABLE _XH-RANGE-CAP
VARIABLE _XH-RANGE-INDEX
VARIABLE _XH-RANGE-FIRST
VARIABLE _XH-RANGE-LEN
VARIABLE _XH-META-CREDIT
VARIABLE _XH-META-HOME-COUNT
VARIABLE _XH-OWNER-RANGE-COUNT
VARIABLE _XH-IMAGE
VARIABLE _XH-RECORD
VARIABLE _XH-SHIFT
VARIABLE _XH-EDIT
VARIABLE _XH-LEFT-LEN
VARIABLE _XH-RIGHT-LEN
VARIABLE _XH-LEFT-OK
VARIABLE _XH-RIGHT-OK
VARIABLE _XH-SPLIT-FIRST
VARIABLE _XH-SPLIT-COUNT
VARIABLE _XH-SPLIT-LEFT
VARIABLE _XH-SPLIT-RIGHT
VARIABLE _XH-IOR
VARIABLE _XH-PUBLISHED
VARIABLE _XH-ABORT-IOR
CREATE _XH-INODE-SNAPSHOT _EXT4-MAX-INODE ALLOT
CREATE _XH-LEAF-SNAPSHOT _EXT4-MAX-BLOCK ALLOT
8 CONSTANT _XH-META-HOME-CAP
CREATE _XH-META-HOMES _XH-META-HOME-CAP CELLS ALLOT

0 CONSTANT _XH-EDIT-INSERT
1 CONSTANT _XH-EDIT-MERGE-LEFT
2 CONSTANT _XH-EDIT-MERGE-RIGHT
3 CONSTANT _XH-EDIT-MERGE-BOTH
4 CONSTANT _XH-EDIT-GROW-ROOT
5 CONSTANT _XH-EDIT-SPLIT-LEAF

: _XH-ENTRY-AT  ( index -- extent-entry )
    12 * 12 + _XH-EDIT-NODE @ + ;

: _XH-ROOT-ENTRY-AT  ( index -- extent-index )
    12 * 12 + _XH-ROOT @ + ;

: _XH-RANGE-AT  ( index -- range-pair )
    2* CELLS _XH-CTX @ _EXT4-C.MUTATION-RANGES + @ + ;

: _XH-NEW-LEAF?  ( -- flag )
    _XH-ROOT-GROW @ _XH-LEAF-SPLIT @ OR ;

: _XH-REQUIRE-FRESH  ( -- ior )
    _XH-WRITER @ _EXT4-JWR.META-CREDIT + @
    DUP 4 U< SWAP _XH-META-HOME-CAP U> OR
    _XH-WRITER @ _EXT4-JWR.DATA-CREDIT + @ 1 <> OR
    _XH-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ 0<> OR IF
        VFS-E-INVALID EXIT
    THEN
    _XH-WRITER @ _EXT4-JWR.META-USED + @
    _XH-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _XH-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _XH-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _XH-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _XH-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _XH-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    _XH-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-CTX @ _EXT4-C.O.ACTIVE + @
    _XH-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _XH-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _XH-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _XH-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _XH-IOR !
    _XH-PUBLISHED @ IF
        _XH-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP
            _XH-WRITER @ _EXT4-JTX-ABORT
            DUP _XH-ABORT-IOR ! IF
                _XH-ABORT-IOR @
                _XH-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _XH-WRITER @ _EXT4-JWR.STATE + !
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _XH-IOR @
                _XH-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _XH-WRITER @ _EXT4-JWR.STATE + !
            THEN
        THEN
    THEN
    _XH-IOR @ ;

: _XH-ADD-DATA-BLOCKS  ( blocks -- ior )
    _XH-DATA-BLOCKS @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _XH-DATA-BLOCKS !
    0 ;

\ Retain every target-owned data, external tree-node, and xattr range while
\ selecting an allocating edit.  The vector is private scratch rather than a
\ published ownership scope: it rejects aliases inside the excluded target
\ inode before the later filesystem-wide scan reasons about other owners.
: _XH-RANGE-ADD-DISJOINT  ( first count -- ior )
    _XH-RANGE-LEN ! _XH-RANGE-FIRST !
    _XH-RANGE-FIRST @ 0= _XH-RANGE-LEN @ 0= OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-RANGE-FIRST @ _XH-RANGE-LEN @ _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-END @ _XH-RANGE-FIRST @ U< IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-RANGE-COUNT @ DUP 0<
    SWAP _XH-RANGE-CAP @ U< 0= OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 _XH-RANGE-INDEX !
    BEGIN
        _XH-RANGE-INDEX @ _XH-RANGE-COUNT @ U<
    WHILE
        _XH-RANGE-FIRST @ _XH-RANGE-LEN @
        _XH-RANGE-INDEX @ _XH-RANGE-AT DUP @ SWAP CELL+ @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _XH-RANGE-INDEX +!
    REPEAT
    _XH-RANGE-FIRST @
    _XH-RANGE-COUNT @ _XH-RANGE-AT !
    _XH-RANGE-LEN @
    _XH-RANGE-COUNT @ _XH-RANGE-AT CELL+ !
    1 _XH-RANGE-COUNT +!
    0 ;

: _XH-CAPTURE-RANGES-BEGIN  ( -- ior )
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _XH-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-CTX @ _EXT4-C.MUTATION-RANGES + @ 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _XH-RANGE-CAP !
    _XH-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
    _XH-RANGE-CAP @ <> IF VFS-E-CORRUPT EXIT THEN
    _XH-CTX @ _EXT4-C.MUTATION-RANGES + @
    _XH-RANGE-CAP @ 2* CELLS 0 FILL
    0 _XH-RANGE-COUNT !
    0 ;

: _XH-CAPTURE-RANGES-SCRUB  ( -- )
    _XH-CTX @ _EXT4-C.MUTATION-RANGES + @
    _XH-RANGE-CAP @ 2* CELLS 0 FILL
    0 _XH-RANGE-COUNT ! ;

\ Validate every existing extent as an ordinary mutable data role before the
\ target inode is excluded from the filesystem-wide other-owner scan.  A zero
\ probe target cannot alias any admitted ext4 block, so this scoped walk uses
\ the existing mutation-map hook only for its complete role validation.
: _XH-REQUIRE-MAP-AUDIT  ( -- ior )
    _EXT4-MUTATION-MAP-TARGET @
    _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR IF VFS-E-BUSY EXIT THEN
    0 _EXT4-MUTATION-MAP-TARGET !
    0 _EXT4-MUTATION-MAP-HITS !
    -1 _EXT4-MUTATION-MAP-ACTIVE !
    _XH-CTX @ _EXT4-VALIDATE-EXTENT-TREE _XH-IOR !
    0 _EXT4-MUTATION-MAP-ACTIVE !
    0 _EXT4-MUTATION-MAP-TARGET !
    _XH-IOR @ 0= _EXT4-MUTATION-MAP-HITS @ 0<> AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT _XH-IOR !
    THEN
    0 _EXT4-MUTATION-MAP-HITS !
    _XH-IOR @ ;

\ Capture and account one member of the authenticated resident depth-one
\ fanout.  Every leaf contributes to exact i_blocks authentication.  Only the
\ selected leaf is copied into the mutable snapshot and derives an insertion
\ point; all other leaf blocks remain read-only authority.
: _XH-CAPTURE-DEPTH1-LEAF  ( -- ior )
    _XH-INDEX @ _XH-ROOT-ENTRY-AT DUP _XH-ENTRY !
    DUP 8 + W@ IF DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    DUP 10 + W@ IF DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    4 + L@ DUP _XH-SCAN-LEAF !
    0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _XH-EA @ _XH-SCAN-LEAF @ = IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-SCAN-LEAF @ 0 _XH-CTX @
    _EXT4-LOAD-EXTENT-NODE ?DUP IF EXIT THEN
    _XH-SCAN-LEAF @ 1 _XH-RANGE-ADD-DISJOINT ?DUP IF EXIT THEN
    _XH-CTX @ _EXT4-C.TREE-BLOCK + DUP _XH-SCAN-NODE !
    12 + L@ _XH-ENTRY @ L@ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-SCAN-NODE @ 2 + W@ DUP _XH-SCAN-ENTRIES !
    0= IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    _XH-BSIZE @ 12 - 12 / DUP _XH-LEAF-MAX !
    _XH-SCAN-NODE @ 4 + W@ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-SCAN-ENTRIES @ _XH-LEAF-MAX @ U> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-INDEX @ _XH-ROOT-INDEX @ = IF
        _XH-SCAN-LEAF @ _XH-EXISTING-LEAF !
        _XH-SCAN-NODE @ _XH-LEAF-SNAPSHOT _XH-BSIZE @ MOVE
        _XH-LEAF-SNAPSHOT _XH-EDIT-NODE !
        _XH-LEAF-MAX @ _XH-ENTRY-MAX !
        _XH-SCAN-ENTRIES @ DUP _XH-ENTRIES ! _XH-INSERT !
    THEN
    0 _XH-SHIFT !
    BEGIN
        _XH-SHIFT @ _XH-SCAN-ENTRIES @ U<
    WHILE
        _XH-SCAN-NODE @ 12 + _XH-SHIFT @ 12 * + DUP _XH-ENTRY !
        DUP L@ _XH-START !
        DUP 4 + W@ _XH-RAW-LEN !
        DUP _EXT4-EXTENT-LEN@ _XH-LEN !
        DUP 6 + W@ 32 LSHIFT SWAP 8 + L@ OR _XH-PHYSICAL !
        _XH-PHYSICAL @ _XH-LEN @
        _XH-RANGE-ADD-DISJOINT ?DUP IF EXIT THEN
        _XH-LEN @ _XH-ADD-DATA-BLOCKS ?DUP IF EXIT THEN
        _XH-START @ _XH-LEN @ _EXT4-UADD?
        _XH-IOR ! _XH-END !
        _XH-IOR @ ?DUP IF EXIT THEN
        _XH-END @ 0xFFFFFFFF U> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _XH-LOGICAL @ _XH-START @ >=
        _XH-LOGICAL @ _XH-END @ U< AND IF
            EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-INDEX @ _XH-ROOT-INDEX @ = IF
            _XH-INSERT @ _XH-ENTRIES @ =
            _XH-START @ _XH-LOGICAL @ U> AND IF
                _XH-SHIFT @ _XH-INSERT !
            THEN
        THEN
        1 _XH-SHIFT +!
    REPEAT
    0 ;

\ The ordinary extent validator has already authenticated every entry and
\ allocation bit.  This second pass admits either the resident depth-zero
\ root or a resident depth-one root with its complete bounded leaf fanout.
\ Depth-one selection follows ext4 index semantics: the rightmost key no
\ greater than the target wins, while the first child governs a leading hole.
\ Physical-candidate planning later decides whether the selected leaf inserts,
\ coalesces, or splits while the resident root retains index capacity.  Deeper
\ trees remain structurally valid read input but are outside this mutation.
: _XH-CAPTURE-ROOT-BODY  ( -- ior )
    _XH-EA @ ?DUP IF
        1 _XH-RANGE-ADD-DISJOINT ?DUP IF EXIT THEN
    THEN
    _XH-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK + DUP
    _XH-ROOT !
    DUP W@ _EXT4-EXTENT-MAGIC <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 4 + W@ _EXT4-RESIDENT-EXTENT-ENTRY-MAX <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 8 + L@ _XH-ROOT-GENERATION !
    DUP 6 + W@ DUP _XH-TREE-DEPTH !
    DUP 1 U> IF
        2DROP EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
    THEN
    IF
        DUP 2 + W@ DUP _XH-ROOT-ENTRIES !
        DUP 0= SWAP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR IF
            DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        DROP
        0 _XH-ROOT-INDEX !
        0 _XH-INDEX !
        BEGIN
            _XH-INDEX @ _XH-ROOT-ENTRIES @ U<
        WHILE
            _XH-INDEX @ _XH-ROOT-ENTRY-AT L@
            _XH-LOGICAL @ U> 0= IF _XH-INDEX @ _XH-ROOT-INDEX ! THEN
            1 _XH-INDEX +!
        REPEAT
        0 _XH-DATA-BLOCKS !
        0 _XH-INDEX !
        BEGIN
            _XH-INDEX @ _XH-ROOT-ENTRIES @ U<
        WHILE
            _XH-CAPTURE-DEPTH1-LEAF ?DUP IF EXIT THEN
            1 _XH-INDEX +!
        REPEAT
        _XH-EXISTING-LEAF @ 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    ELSE
        DROP
        0 _XH-ROOT-ENTRIES !
        0 _XH-ROOT-INDEX !
        0 _XH-EXISTING-LEAF !
        _XH-ROOT @ _XH-EDIT-NODE !
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX _XH-ENTRY-MAX !
        _XH-ROOT @ 2 + W@ DUP _XH-ENTRIES !
        _XH-ENTRY-MAX @ U> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _XH-TREE-DEPTH @ 0= IF
        _XH-ENTRIES @ _XH-INSERT !
        0 _XH-DATA-BLOCKS !
        0 _XH-INDEX !
        BEGIN
            _XH-INDEX @ _XH-ENTRIES @ U<
        WHILE
            _XH-INDEX @ _XH-ENTRY-AT _XH-ENTRY !
            _XH-ENTRY @ L@ _XH-START !
            _XH-ENTRY @ 4 + W@ _XH-RAW-LEN !
            _XH-ENTRY @ _EXT4-EXTENT-LEN@ _XH-LEN !
            _XH-ENTRY @ DUP 6 + W@ 32 LSHIFT
            SWAP 8 + L@ OR _XH-PHYSICAL !
            _XH-PHYSICAL @ _XH-LEN @
            _XH-RANGE-ADD-DISJOINT ?DUP IF EXIT THEN
            _XH-LEN @ _XH-ADD-DATA-BLOCKS ?DUP IF EXIT THEN
            _XH-START @ _XH-LEN @ _EXT4-UADD?
            _XH-IOR ! _XH-END !
            _XH-IOR @ ?DUP IF EXIT THEN
            _XH-END @ 0xFFFFFFFF U> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _XH-LOGICAL @ _XH-START @ >=
            _XH-LOGICAL @ _XH-END @ U< AND IF
                _XH-RAW-LEN @ 32768 > IF
                    EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
                THEN
                EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
            THEN
            _XH-INSERT @ _XH-ENTRIES @ =
            _XH-START @ _XH-LOGICAL @ U> AND IF
                _XH-INDEX @ _XH-INSERT !
            THEN
            1 _XH-INDEX +!
        REPEAT
    THEN
    _XH-DATA-BLOCKS @ _XH-EA @ IF 1+ THEN
    _XH-ROOT-ENTRIES @ +
    _XH-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    _XH-IOR ! _XH-ACCOUNTED-BLOCKS !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-ACCOUNTED-BLOCKS @ _XH-BLOCKS @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Always scrub the shared range workspace, including corrupt early exits.
\ Later reverse-owner proofs reuse it only after this complete target-local
\ disjointness check has reduced its authority to retained scalar snapshots.
: _XH-CAPTURE-ROOT  ( -- ior )
    _XH-CAPTURE-RANGES-BEGIN ?DUP IF EXIT THEN
    _XH-CAPTURE-ROOT-BODY _XH-IOR !
    _XH-CAPTURE-RANGES-SCRUB
    _XH-IOR @ ;

: _XH-AUTH-TARGET  ( -- ior )
    0 _XH-ROOT-GROW !
    0 _XH-LEAF-SPLIT !
    0 _XH-TREE-DEPTH !
    0 _XH-ROOT-ENTRIES !
    0 _XH-ROOT-INDEX !
    0 _XH-EDIT-NODE !
    0 _XH-EXISTING-LEAF !
    0 _XH-LEAF-CANDIDATE !
    0 _XH-LEAF-FIRST !
    0 _XH-LEAF-SECOND-FIRST !
    0 _XH-SPLIT-LEFT !
    0 _XH-SPLIT-RIGHT !
    0 _XH-META-CREDIT !
    _XH-INO @
    _XH-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XH-INO @ 8 =
    _XH-INO @ _XH-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XH-EXPECTED-GEN @ 0xFFFFFFFF U> IF
        VFS-E-INVALID EXIT
    THEN
    _XH-INO @ _XH-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _XH-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XH-IOR ! _XH-TYPE !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-TYPE @ VFS-T-FILE <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _XH-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL <> IF
        DROP EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.GENERATION + L@
    DUP _XH-INODE-GENERATION !
    _XH-EXPECTED-GEN @ <> IF
        DROP VFS-E-STALE EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ _XH-EA !
    _XH-CTX @ _EXT4-C.R.SIZE + @ _XH-SIZE !
    _XH-CTX @ _EXT4-C.R.BLOCKS + @ _XH-BLOCKS !
    _XH-GROW @ IF
        _XH-OFFSET @ _XH-SIZE @ <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-SIZE @ _XH-BSIZE @ MOD IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-OFFSET @ _XH-COUNT @ _EXT4-UADD?
        _XH-IOR ! _XH-NEW-SIZE !
        _XH-IOR @ ?DUP IF EXIT THEN
    ELSE
        _XH-OFFSET @ _XH-SIZE @ U< 0= IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-COUNT @
        _XH-SIZE @ _XH-OFFSET @ - U> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-SIZE @ _XH-NEW-SIZE !
    THEN
    _XH-OFFSET @ _XH-BSIZE @ /MOD
    _XH-LOGICAL ! _XH-BLOCK-OFF !
    _XH-LOGICAL @ 1 _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-END @ 0xFFFFFFFF U> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XH-COUNT @
    _XH-BSIZE @ _XH-BLOCK-OFF @ - U> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XH-GROW @ IF
        _XH-LOGICAL @
        _XH-SIZE @ _XH-BSIZE @ / <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    ELSE
        _XH-LOGICAL @
        _XH-SIZE @ _XH-BSIZE @ / U< 0= IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    THEN
    _XH-CAPTURE-ROOT ?DUP IF EXIT THEN
    _XH-REQUIRE-MAP-AUDIT ?DUP IF EXIT THEN
    _XH-EA @ IF
        _XH-EA @ 1 _XH-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        _XH-EA @ EXT4-D-XATTR _XH-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _XH-EA @ _XH-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    _XH-CTX @ _EXT4-C.INODE + _XH-INODE-SNAPSHOT
    _XH-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-IR-GROUP @ _XH-GROUP !
    _EXT4-IR-BLOCK @ _XH-INODE-HOME !
    _EXT4-IR-OFF @ _XH-INODE-OFF !
    0 ;

: _XH-REQUIRE-SAME-TARGET  ( -- ior )
    _XH-INO @ _XH-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XH-GROUP @ <>
    _EXT4-IR-BLOCK @ _XH-INODE-HOME @ <> OR
    _EXT4-IR-OFF @ _XH-INODE-OFF @ <> OR IF
        VFS-E-STALE EXIT
    THEN
    _XH-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XH-IOR ! _XH-TYPE !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-TYPE @ VFS-T-FILE <> IF VFS-E-STALE EXIT THEN
    _XH-CTX @ _EXT4-C.INODE + _XH-INODE-SNAPSHOT
    _XH-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-STALE EXIT
    THEN
    _XH-TREE-DEPTH @ IF
        _XH-ROOT-INDEX @ _XH-ROOT-ENTRIES @ U< 0= IF
            VFS-E-STALE EXIT
        THEN
        _XH-ROOT-INDEX @ _XH-ROOT-ENTRY-AT DUP
        4 + L@ _XH-EXISTING-LEAF @ <>
        OVER 8 + W@ 0<> OR
        SWAP 10 + W@ 0<> OR IF VFS-E-STALE EXIT THEN
        _XH-EXISTING-LEAF @ 0 _XH-CTX @
        _EXT4-LOAD-EXTENT-NODE ?DUP IF EXIT THEN
        _XH-CTX @ _EXT4-C.TREE-BLOCK + _XH-LEAF-SNAPSHOT
        _XH-BSIZE @ _EXT4-BYTES=? 0= IF VFS-E-STALE EXIT THEN
    THEN
    _XH-EA @ IF
        _XH-EA @ _XH-CANDIDATE @ = IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _XH-TREE-DEPTH @
        _XH-EA @ _XH-EXISTING-LEAF @ = AND IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _XH-NEW-LEAF?
        _XH-EA @ _XH-LEAF-CANDIDATE @ = AND IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _XH-EA @ _XH-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    0 ;

: _XH-LOCATE-ACCOUNTING-HOMES  ( -- ior )
    \ Candidate search begins at the inode group but may return from any
    \ initialized group.  Derive the accounting owner from the selected
    \ physical block; using the locality goal here would omit the real bitmap
    \ (and possibly GDT page) from the reverse-owner certificate.
    _XH-CANDIDATE @ _XH-CTX @ _EXT4-C.FIRST + @ -
    _XH-CTX @ _EXT4-C.BPG + @ /MOD
    _XH-CANDIDATE-GROUP ! DROP
    _XH-CANDIDATE-GROUP @ _XH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XH-CANDIDATE-GROUP @ _XH-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _XH-IOR ! _XH-BITMAP-HOME !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-CANDIDATE-GROUP @ _XH-CTX @ _EXT4-LOAD-DESC
    ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XH-GDT-HOME !
    _XH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _XH-SUPER-HOME !
    0 ;

: _XH-OWNER-RANGE!  ( block index -- )
    2* CELLS _XH-CTX @ _EXT4-C.MUTATION-RANGES + @ +
    DUP _XH-ENTRY ! !
    1 _XH-ENTRY @ CELL+ ! ;

: _XH-META-HOME-ADD  ( block -- ior )
    DUP 0< IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _XH-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _XH-META-HOME-COUNT @ 0 ?DO
        DUP I CELLS _XH-META-HOMES + @ = IF
            DROP 0 UNLOOP EXIT
        THEN
    LOOP
    _XH-META-HOME-COUNT @ _XH-META-HOME-CAP U< 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _XH-META-HOME-COUNT @ CELLS _XH-META-HOMES + !
    1 _XH-META-HOME-COUNT +!
    0 ;

\ Count the exact distinct metadata homes implied by the selected topology.
\ Ordinary inline-root allocation is the established bitmap/GDT/super/inode
\ quartet.  Editing one selected depth-one leaf adds that leaf as exactly one
\ fifth home; its siblings remain authenticated read authority.  Root growth
\ instead owns the new leaf and may add a second bitmap and primary-GDT page,
\ yielding five through seven.  Splitting also replaces the old leaf, yielding
\ six through eight distinct homes.
: _XH-MEASURE-META-CREDIT  ( -- ior )
    _XH-META-HOMES _XH-META-HOME-CAP CELLS 0 FILL
    0 _XH-META-HOME-COUNT !
    _XH-BITMAP-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
    _XH-GDT-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
    _XH-SUPER-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
    _XH-INODE-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
    _XH-LEAF-SPLIT @ IF
        _XH-EXISTING-LEAF @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-LEAF-CANDIDATE @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-LEAF-BITMAP-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-LEAF-GDT-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-META-HOME-COUNT @
        DUP 6 U< SWAP _XH-META-HOME-CAP U> OR IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE _XH-ROOT-GROW @ IF
        _XH-LEAF-CANDIDATE @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-LEAF-BITMAP-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-LEAF-GDT-HOME @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-META-HOME-COUNT @ DUP 5 U< SWAP 7 U> OR IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE _XH-TREE-DEPTH @ IF
        _XH-EXISTING-LEAF @ _XH-META-HOME-ADD ?DUP IF EXIT THEN
        _XH-META-HOME-COUNT @ 5 <> IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _XH-META-HOME-COUNT @ 4 <> IF VFS-E-CORRUPT EXIT THEN
    THEN THEN THEN
    _XH-META-HOME-COUNT @ 0 ?DO
        I CELLS _XH-META-HOMES + @ _XH-CANDIDATE @ = IF
            VFS-E-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    _XH-META-HOME-COUNT @ _XH-META-CREDIT !
    0 ;

\ Prove every proposed data, tree, inode, and accounting role in one global
\ inode walk.  The target's complete existing map was role-audited above, so
\ excluding it cannot hide an alias.  Duplicate accounting roles are harmless
\ in the proof vector and remain coalesced independently for journal credit.
: _XH-REQUIRE-UNIQUE-HOMES  ( -- ior )
    _EXT4-MUTATION-OWNER-RANGES-BUSY?
    _EXT4-MUTATION-EA-REF-ACTIVE @ OR IF VFS-E-BUSY EXIT THEN
    _XH-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-META-CREDIT @ 1+ _XH-OWNER-RANGE-COUNT !
    _XH-CTX @ _EXT4-C.MUTATION-RANGES + @ 0=
    _XH-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
    _XH-OWNER-RANGE-COUNT @ U< OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFO-CERT-INVALIDATE
    _XH-CTX @ _EXT4-JFO-CTX !
    _XH-INO @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-UOW-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _XH-CANDIDATE @ 0 _XH-OWNER-RANGE!
    _XH-META-CREDIT @ 0 ?DO
        I CELLS _XH-META-HOMES + @ I 1+ _XH-OWNER-RANGE!
    LOOP
    _XH-CTX @ _EXT4-C.MUTATION-RANGES + @
    _XH-OWNER-RANGE-COUNT @
    _XH-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
    _EXT4-MUTATION-OWNER-RANGES-PUBLISH _EXT4-UOW-IOR !
    _EXT4-UOW-IOR @ 0= IF
        _EXT4-JFO-SCAN-OTHER-INODES _EXT4-UOW-IOR !
    THEN
    _EXT4-MUTATION-OWNER-RANGES-CLEAR
    _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-UOW-IOR @ ;

: _XH-SELECT-CANDIDATE  ( -- ior )
    _XH-GROUP @ _XH-CTX @ _EXT4-FIND-FREE-BLOCK
    _XH-IOR ! _XH-CANDIDATE !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-EA @ _XH-CANDIDATE @ = IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-TREE-DEPTH @
    _XH-CANDIDATE @ _XH-EXISTING-LEAF @ = AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-INODE-HOME @ _XH-GROUP @ _XH-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XH-LOCATE-ACCOUNTING-HOMES ;

: _XH-SELECT-LEAF-CANDIDATE  ( -- ior )
    _XH-NEW-LEAF? 0= IF 0 EXIT THEN
    _XH-CANDIDATE @ _XH-CANDIDATE-GROUP @ _XH-CTX @
    _EXT4-FIND-FREE-BLOCK-EXCLUDING
    _XH-IOR ! _XH-LEAF-CANDIDATE !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-LEAF-CANDIDATE @ _XH-CANDIDATE @ = IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-EA @ _XH-LEAF-CANDIDATE @ = IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XH-LEAF-CANDIDATE @ _XH-CTX @ _EXT4-C.FIRST + @ -
    _XH-CTX @ _EXT4-C.BPG + @ /MOD
    _XH-LEAF-GROUP ! DROP
    _XH-LEAF-GROUP @ _XH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XH-LEAF-GROUP @ _XH-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _XH-IOR ! _XH-LEAF-BITMAP-HOME !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-LEAF-GROUP @ _XH-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XH-LEAF-GDT-HOME !
    0 ;

: _XH-REQUIRE-SAME-CANDIDATES  ( -- ior )
    _XH-GROUP @ _XH-CTX @ _EXT4-FIND-FREE-BLOCK
    DUP IF NIP EXIT THEN DROP
    _XH-CANDIDATE @ <> IF VFS-E-CONFLICT EXIT THEN
    _XH-CANDIDATE-GROUP @ _XH-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _XH-IOR ! _XH-ENTRY !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-ENTRY @ _XH-BITMAP-HOME @ <> IF VFS-E-CONFLICT EXIT THEN
    _XH-CANDIDATE-GROUP @ _XH-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XH-GDT-HOME @ <> IF VFS-E-CONFLICT EXIT THEN
    _XH-NEW-LEAF? IF
        _XH-CANDIDATE @ _XH-CANDIDATE-GROUP @ _XH-CTX @
        _EXT4-FIND-FREE-BLOCK-EXCLUDING
        DUP IF NIP EXIT THEN DROP
        _XH-LEAF-CANDIDATE @ <> IF VFS-E-CONFLICT EXIT THEN
        _XH-LEAF-GROUP @ _XH-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        _XH-IOR ! _XH-ENTRY !
        _XH-IOR @ ?DUP IF EXIT THEN
        _XH-ENTRY @ _XH-LEAF-BITMAP-HOME @ <> IF
            VFS-E-CONFLICT EXIT
        THEN
        _XH-LEAF-GROUP @ _XH-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
        _EXT4-GD-BLOCK @ _XH-LEAF-GDT-HOME @ <> IF
            VFS-E-CONFLICT EXIT
        THEN
    THEN
    _XH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _XH-SUPER-HOME @ <> IF VFS-E-CONFLICT EXIT THEN
    0 ;

: _XH-REVALIDATE-PLANNED-HOMES  ( -- ior )
    _XH-MEASURE-META-CREDIT ?DUP IF EXIT THEN
    _XH-REQUIRE-SAME-CANDIDATES ?DUP IF EXIT THEN
    _XH-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _XH-INODE-HOME @ _XH-GROUP @ _XH-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ;

: _XH-QUALIFY-PLANNED-HOMES  ( -- ior )
    _XH-REVALIDATE-PLANNED-HOMES ?DUP IF EXIT THEN
    _XH-REQUIRE-UNIQUE-HOMES ?DUP IF EXIT THEN
    \ The ownership walk may perform many intervening reads.  Rebind every
    \ selected role to the same authenticated geometry before publication.
    _XH-REQUIRE-SAME-CANDIDATES ?DUP IF EXIT THEN
    _XH-REQUIRE-SAME-TARGET ;

: _XH-REQUIRE-EXACT-CREDIT  ( -- ior )
    _XH-WRITER @ _EXT4-JWR.META-CREDIT + @
    _XH-META-CREDIT @ <> IF VFS-E-INVALID EXIT THEN
    0 ;

: _XH-PLAN-LEFT?  ( -- flag )
    _XH-INSERT @ 0= IF FALSE EXIT THEN
    _XH-INSERT @ 1- _XH-ENTRY-AT _XH-ENTRY !
    _XH-ENTRY @ 4 + W@ DUP _XH-LEFT-LEN !
    DUP 0= SWAP 32768 U> OR IF FALSE EXIT THEN
    _XH-ENTRY @ L@ _XH-LEFT-LEN @ _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ IF FALSE EXIT THEN
    _XH-END @ _XH-LOGICAL @ <> IF FALSE EXIT THEN
    _XH-ENTRY @ 8 + L@ _XH-LEFT-LEN @ _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ IF FALSE EXIT THEN
    _XH-END @ _XH-CANDIDATE @ <> IF FALSE EXIT THEN
    _XH-LEFT-LEN @ 1 _EXT4-UADD? _XH-IOR ! _XH-END !
    _XH-IOR @ 0= _XH-END @ 32768 U> 0= AND ;

: _XH-PLAN-RIGHT?  ( -- flag )
    _XH-INSERT @ _XH-ENTRIES @ U< 0= IF FALSE EXIT THEN
    _XH-INSERT @ _XH-ENTRY-AT _XH-ENTRY !
    _XH-ENTRY @ 4 + W@ DUP _XH-RIGHT-LEN !
    DUP 0= SWAP 32768 U> OR IF FALSE EXIT THEN
    _XH-LOGICAL @ 1 _EXT4-UADD? _XH-IOR ! _XH-END !
    _XH-IOR @ IF FALSE EXIT THEN
    _XH-END @ _XH-ENTRY @ L@ <> IF FALSE EXIT THEN
    _XH-CANDIDATE @ 1 _EXT4-UADD? _XH-IOR ! _XH-END !
    _XH-IOR @ IF FALSE EXIT THEN
    _XH-END @ _XH-ENTRY @ 8 + L@ <> IF FALSE EXIT THEN
    _XH-RIGHT-LEN @ 1 _EXT4-UADD? _XH-IOR ! _XH-END !
    _XH-IOR @ 0= _XH-END @ 32768 U> 0= AND ;

: _XH-BRIDGE-LENGTH?  ( -- flag )
    _XH-LEFT-LEN @ 1 _EXT4-UADD? _XH-IOR ! _XH-END !
    _XH-IOR @ IF FALSE EXIT THEN
    _XH-END @ _XH-RIGHT-LEN @ _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ 0= _XH-END @ 32768 U> 0= AND ;

\ Choose the editable-node operation only after the geometry-selected physical
\ block is known.  Coalescing remains valid even when the node is full.  A
\ depth-zero root with no free slot takes the qualified one-leaf transition.
\ A full external leaf takes the split transition only while its resident
\ depth-one root retains an index slot.  A full root still permits all edits
\ above that do not add an index; only full-root/full-leaf growth is refused.
: _XH-PLAN-ROOT-EDIT  ( -- ior )
    _XH-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _XH-PLAN-LEFT? _XH-LEFT-OK !
    _XH-PLAN-RIGHT? _XH-RIGHT-OK !
    _XH-LEFT-OK @ _XH-RIGHT-OK @ AND IF
        _XH-BRIDGE-LENGTH? IF
            _XH-EDIT-MERGE-BOTH _XH-EDIT ! 0 EXIT
        THEN
    THEN
    _XH-LEFT-OK @ IF
        _XH-EDIT-MERGE-LEFT _XH-EDIT ! 0 EXIT
    THEN
    _XH-RIGHT-OK @ IF
        _XH-EDIT-MERGE-RIGHT _XH-EDIT ! 0 EXIT
    THEN
    _XH-ENTRIES @ _XH-ENTRY-MAX @ U< IF
        _XH-EDIT-INSERT _XH-EDIT ! 0 EXIT
    THEN
    _XH-TREE-DEPTH @ IF
        _XH-ROOT-ENTRIES @ _EXT4-RESIDENT-EXTENT-ENTRY-MAX U< 0= IF
            EXT4-D-DATA-MAP _EXT4-UNSUPPORTED EXIT
        THEN
        _XH-ENTRY-MAX @ 1+ DUP 2/ DUP 0= IF
            2DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _XH-SPLIT-LEFT ! - DUP 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _XH-SPLIT-RIGHT !
        _XH-EDIT-SPLIT-LEAF _XH-EDIT !
        -1 _XH-LEAF-SPLIT !
        0 EXIT
    THEN
    _XH-EDIT-GROW-ROOT _XH-EDIT !
    -1 _XH-ROOT-GROW !
    0 ;

: _XH-STAGE-DATA  ( -- ior )
    _XH-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
    _XH-BSIZE @ 0 FILL
    _XH-WRITER @ _EXT4-JWR.SCRATCH-B + @
    SWAP _XH-BLOCK-OFF @ + _XH-COUNT @ MOVE
    _XH-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _XH-CANDIDATE @ _XH-WRITER @
    _EXT4-JTX-DATA-PUT ?DUP IF EXIT THEN
    -1 _XH-PUBLISHED !
    0 ;

: _XH-STAMP-LEAF  ( leaf -- ior )
    _XH-IMAGE !
    _XH-INO @ _XH-CTX @ _EXT4-C.TMP + L!
    _XH-INODE-GENERATION @ _XH-CTX @ _EXT4-C.TMP 4 + + L!
    _XH-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _XH-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _XH-IMAGE @ _XH-LEAF-MAX @ 12 * 12 + _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@
    _XH-IMAGE @ _XH-LEAF-MAX @ 12 * 12 + + L!
    0 ;

\ Copy one ordinal from the conceptual sorted sequence formed by inserting
\ the new singleton extent into the authenticated full-leaf snapshot.  This
\ avoids a second block-sized temporary and never edits the source snapshot.
: _XH-SPLIT-ENTRY>  ( ordinal destination -- )
    _XH-ENTRY !
    DUP _XH-INSERT @ = IF
        DROP
        _XH-LOGICAL @ _XH-ENTRY @ L!
        1 _XH-ENTRY @ 4 + W!
        _XH-CANDIDATE @ DUP 32 RSHIFT _XH-ENTRY @ 6 + W!
        0xFFFFFFFF AND _XH-ENTRY @ 8 + L!
    ELSE
        DUP _XH-INSERT @ U> IF 1- THEN
        12 * _XH-LEAF-SNAPSHOT 12 + +
        _XH-ENTRY @ 12 MOVE
    THEN ;

: _XH-COMPOSE-SPLIT-LEAF  ( first-ordinal count leaf -- ior )
    _XH-IMAGE ! _XH-SPLIT-COUNT ! _XH-SPLIT-FIRST !
    _XH-SPLIT-COUNT @ 0= IF VFS-E-CORRUPT EXIT THEN
    _XH-SPLIT-FIRST @ _XH-SPLIT-COUNT @ _EXT4-UADD?
    _XH-IOR ! _XH-END !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-END @ _XH-ENTRY-MAX @ 1+ U> IF VFS-E-CORRUPT EXIT THEN
    _XH-IMAGE @ _XH-BSIZE @ 0 FILL
    _EXT4-EXTENT-MAGIC _XH-IMAGE @ W!
    _XH-SPLIT-COUNT @ _XH-IMAGE @ 2 + W!
    _XH-LEAF-MAX @ _XH-IMAGE @ 4 + W!
    0 _XH-IMAGE @ 6 + W!
    _XH-ROOT-GENERATION @ _XH-IMAGE @ 8 + L!
    0 _XH-INDEX !
    BEGIN
        _XH-INDEX @ _XH-SPLIT-COUNT @ U<
    WHILE
        _XH-SPLIT-FIRST @ _XH-INDEX @ +
        _XH-IMAGE @ 12 + _XH-INDEX @ 12 * +
        _XH-SPLIT-ENTRY>
        1 _XH-INDEX +!
    REPEAT
    0 ;

\ Publish the new external node before allocation accounting reuses both
\ writer scratch blocks.  META-PUT is correct for a newly allocated home:
\ there is no authenticated old metadata image to acquire.
: _XH-STAGE-LEAF  ( -- ior )
    _XH-NEW-LEAF? 0= IF 0 EXIT THEN
    _XH-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP _XH-IMAGE !
    _XH-BSIZE @ 0 FILL
    _XH-LEAF-SPLIT @ IF
        _XH-BSIZE @ 12 - 12 / _XH-LEAF-MAX @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _XH-SPLIT-LEFT @ _XH-SPLIT-RIGHT @ _XH-IMAGE @
        _XH-COMPOSE-SPLIT-LEAF ?DUP IF EXIT THEN
        _XH-IMAGE @ 12 + L@ _XH-LEAF-SECOND-FIRST !
    ELSE
        _XH-BSIZE @ 12 - 12 / _XH-LEAF-MAX !
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX 1+
        _XH-LEAF-MAX @ U> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-EXTENT-MAGIC _XH-IMAGE @ W!
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX 1+ _XH-IMAGE @ 2 + W!
        _XH-LEAF-MAX @ _XH-IMAGE @ 4 + W!
        0 _XH-IMAGE @ 6 + W!
        _XH-ROOT-GENERATION @ _XH-IMAGE @ 8 + L!
        _XH-INODE-SNAPSHOT _EXT4-I.BLOCK + 12 + _XH-IMAGE @ 12 +
        _XH-INSERT @ 12 * MOVE
        _XH-IMAGE @ 12 + _XH-INSERT @ 12 * + _XH-ENTRY !
        _XH-LOGICAL @ _XH-ENTRY @ L!
        1 _XH-ENTRY @ 4 + W!
        _XH-CANDIDATE @ DUP 32 RSHIFT _XH-ENTRY @ 6 + W!
        0xFFFFFFFF AND _XH-ENTRY @ 8 + L!
        _XH-INODE-SNAPSHOT _EXT4-I.BLOCK + 12 +
        _XH-INSERT @ 12 * +
        _XH-ENTRY @ 12 +
        _EXT4-RESIDENT-EXTENT-ENTRY-MAX _XH-INSERT @ - 12 * MOVE
        _XH-IMAGE @ 12 + L@ _XH-LEAF-FIRST !
    THEN
    _XH-IMAGE @ _XH-STAMP-LEAF ?DUP IF EXIT THEN
    _XH-IMAGE @ _XH-LEAF-CANDIDATE @ _XH-WRITER @
    _EXT4-JTX-META-PUT ?DUP IF EXIT THEN
    -1 _XH-PUBLISHED !
    0 ;

\ Bind the allocation builder's independently derived geometry back to the
\ homes covered by the pre-mutation reverse-owner certificate.  This turns a
\ future drift between candidate planning and accounting staging into an
\ aborted transaction rather than an unproved metadata replacement.
: _XH-REQUIRE-STAGED-ACCOUNTING-HOMES  ( -- ior )
    _EXT4-JAB-GROUP @ _XH-CANDIDATE-GROUP @ <>
    _EXT4-JAB-BITMAP-HOME @ _XH-BITMAP-HOME @ <> OR
    _EXT4-JAB-GDT-HOME @ _XH-GDT-HOME @ <> OR
    _EXT4-JAB-SUPER-HOME @ _XH-SUPER-HOME @ <> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _XH-REQUIRE-STAGED-LEAF-ACCOUNTING-HOMES  ( -- ior )
    _EXT4-JAB-GROUP @ _XH-LEAF-GROUP @ <>
    _EXT4-JAB-BITMAP-HOME @ _XH-LEAF-BITMAP-HOME @ <> OR
    _EXT4-JAB-GDT-HOME @ _XH-LEAF-GDT-HOME @ <> OR
    _EXT4-JAB-SUPER-HOME @ _XH-SUPER-HOME @ <> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _XH-ENTRY-PHYSICAL!  ( physical-block extent-entry -- )
    _XH-ENTRY !
    DUP 32 RSHIFT _XH-ENTRY @ 6 + W!
    0xFFFFFFFF AND _XH-ENTRY @ 8 + L! ;

: _XH-APPLY-INSERT  ( -- ior )
    _XH-ENTRIES @ _XH-ENTRY-MAX @ U< 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-ENTRIES @ _XH-SHIFT !
    BEGIN
        _XH-SHIFT @ _XH-INSERT @ U>
    WHILE
        _XH-SHIFT @ 1- _XH-ENTRY-AT
        _XH-SHIFT @ _XH-ENTRY-AT 12 MOVE
        -1 _XH-SHIFT +!
    REPEAT
    _XH-INSERT @ _XH-ENTRY-AT _XH-ENTRY !
    _XH-LOGICAL @ _XH-ENTRY @ L!
    1 _XH-ENTRY @ 4 + W!
    _XH-CANDIDATE @ _XH-ENTRY @ _XH-ENTRY-PHYSICAL!
    _XH-ENTRIES @ 1+ DUP _XH-ENTRIES ! _XH-EDIT-NODE @ 2 + W!
    0 ;

: _XH-APPLY-MERGE-LEFT  ( -- ior )
    _XH-INSERT @ 0= IF VFS-E-CORRUPT EXIT THEN
    _XH-INSERT @ 1- _XH-ENTRY-AT
    _XH-LEFT-LEN @ 1+ SWAP 4 + W!
    0 ;

: _XH-APPLY-MERGE-RIGHT  ( -- ior )
    _XH-INSERT @ _XH-ENTRIES @ U< 0= IF VFS-E-CORRUPT EXIT THEN
    _XH-INSERT @ _XH-ENTRY-AT _XH-ENTRY !
    _XH-LOGICAL @ _XH-ENTRY @ L!
    _XH-RIGHT-LEN @ 1+ _XH-ENTRY @ 4 + W!
    _XH-CANDIDATE @ _XH-ENTRY @ _XH-ENTRY-PHYSICAL!
    0 ;

: _XH-REMOVE-RIGHT-ENTRY  ( -- )
    _XH-INSERT @ _XH-SHIFT !
    BEGIN
        _XH-SHIFT @ 1+ _XH-ENTRIES @ U<
    WHILE
        _XH-SHIFT @ 1+ _XH-ENTRY-AT
        _XH-SHIFT @ _XH-ENTRY-AT 12 MOVE
        1 _XH-SHIFT +!
    REPEAT
    _XH-ENTRIES @ 1- _XH-ENTRY-AT 12 0 FILL
    _XH-ENTRIES @ 1- DUP _XH-ENTRIES ! _XH-EDIT-NODE @ 2 + W! ;

: _XH-APPLY-MERGE-BOTH  ( -- ior )
    _XH-INSERT @ 0= _XH-INSERT @ _XH-ENTRIES @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-INSERT @ 1- _XH-ENTRY-AT
    _XH-LEFT-LEN @ 1+ _XH-RIGHT-LEN @ + SWAP 4 + W!
    _XH-REMOVE-RIGHT-ENTRY
    0 ;

: _XH-APPLY-GROW-ROOT  ( -- ior )
    _XH-ENTRIES @ _EXT4-RESIDENT-EXTENT-ENTRY-MAX <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-ROOT @ 12 + 48 0 FILL
    _EXT4-EXTENT-MAGIC _XH-ROOT @ W!
    1 _XH-ROOT @ 2 + W!
    _EXT4-RESIDENT-EXTENT-ENTRY-MAX _XH-ROOT @ 4 + W!
    1 _XH-ROOT @ 6 + W!
    _XH-ROOT-GENERATION @ _XH-ROOT @ 8 + L!
    _XH-LEAF-FIRST @ _XH-ROOT @ 12 + L!
    _XH-LEAF-CANDIDATE @ DUP 0xFFFFFFFF AND
    _XH-ROOT @ 16 + L!
    32 RSHIFT _XH-ROOT @ 20 + W!
    0 _XH-ROOT @ 22 + W!
    1 _XH-ENTRIES !
    0 ;

: _XH-APPLY-NODE-EDIT  ( -- ior )
    _XH-EDIT @ _XH-EDIT-INSERT = IF _XH-APPLY-INSERT EXIT THEN
    _XH-EDIT @ _XH-EDIT-MERGE-LEFT = IF
        _XH-APPLY-MERGE-LEFT EXIT
    THEN
    _XH-EDIT @ _XH-EDIT-MERGE-RIGHT = IF
        _XH-APPLY-MERGE-RIGHT EXIT
    THEN
    _XH-EDIT @ _XH-EDIT-MERGE-BOTH = IF
        _XH-APPLY-MERGE-BOTH EXIT
    THEN
    VFS-E-CORRUPT ;

: _XH-APPLY-EXTENT-EDIT  ( -- ior )
    _XH-RECORD @ _EXT4-I.BLOCK + DUP _XH-ROOT ! _XH-EDIT-NODE !
    _XH-EDIT @ _XH-EDIT-GROW-ROOT = IF
        _XH-APPLY-GROW-ROOT EXIT
    THEN
    _XH-APPLY-NODE-EDIT ;

\ Replace the already allocated external leaf from its authenticated snapshot.
\ An ordinary edit changes it in place.  A split composes the lower half here
\ and the upper half in the separately staged new leaf.  The inode transaction
\ later republishes the authoritative first key or both split indexes together
\ with i_blocks, size, times, and checksum.
: _XH-STAGE-EXISTING-LEAF  ( -- ior )
    _XH-TREE-DEPTH @ 0= IF 0 EXIT THEN
    _XH-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _XH-LEAF-SNAPSHOT _XH-EXISTING-LEAF @ _XH-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XH-IMAGE ! _XH-EDIT-NODE !
    _XH-LEAF-SPLIT @ IF
        0 _XH-SPLIT-LEFT @ _XH-IMAGE @
        _XH-COMPOSE-SPLIT-LEAF
    ELSE
        _XH-APPLY-NODE-EDIT
    THEN ?DUP IF EXIT THEN
    _XH-IMAGE @ 12 + L@ _XH-LEAF-FIRST !
    _XH-IMAGE @ _XH-STAMP-LEAF ?DUP IF EXIT THEN
    _XH-IMAGE @ _XH-EXISTING-LEAF @ _XH-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _XH-PUBLISHED !
    0 ;

: _XH-REQUIRE-STAGED-SELECTED-ROOT  ( -- ior )
    _XH-ROOT @ DUP W@ _EXT4-EXTENT-MAGIC <>
    OVER 2 + W@ _XH-ROOT-ENTRIES @ <> OR
    OVER 4 + W@ _EXT4-RESIDENT-EXTENT-ENTRY-MAX <> OR
    OVER 6 + W@ 1 <> OR IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DROP
    _XH-ROOT-ENTRIES @ DUP 0=
    SWAP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> OR
    _XH-ROOT-INDEX @ _XH-ROOT-ENTRIES @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-ROOT-INDEX @ _XH-ROOT-ENTRY-AT DUP
    4 + L@ _XH-EXISTING-LEAF @ <>
    OVER 8 + W@ 0<> OR
    SWAP 10 + W@ 0<> OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _XH-REQUIRE-SELECTED-FIRST-KEY-BOUNDS  ( -- ior )
    _XH-ROOT-INDEX @ IF
        _XH-ROOT-INDEX @ 1- _XH-ROOT-ENTRY-AT L@
        _XH-LEAF-FIRST @ U< 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _XH-ROOT-INDEX @ 1+ _XH-ROOT-ENTRIES @ U< IF
        _XH-LEAF-FIRST @
        _XH-ROOT-INDEX @ 1+ _XH-ROOT-ENTRY-AT L@ U< 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _XH-APPLY-EXISTING-ROOT-KEY  ( -- ior )
    _XH-REQUIRE-STAGED-SELECTED-ROOT ?DUP IF EXIT THEN
    _XH-REQUIRE-SELECTED-FIRST-KEY-BOUNDS ?DUP IF EXIT THEN
    _XH-LEAF-FIRST @
    _XH-ROOT-INDEX @ _XH-ROOT-ENTRY-AT L!
    0 ;

: _XH-APPLY-SPLIT-ROOT  ( -- ior )
    _XH-REQUIRE-STAGED-SELECTED-ROOT ?DUP IF EXIT THEN
    _XH-ROOT-ENTRIES @ _EXT4-RESIDENT-EXTENT-ENTRY-MAX U< 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-LEAF-FIRST @ _XH-LEAF-SECOND-FIRST @ U< 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XH-ROOT-INDEX @ IF
        _XH-ROOT-INDEX @ 1- _XH-ROOT-ENTRY-AT L@
        _XH-LEAF-FIRST @ U< 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _XH-ROOT-INDEX @ 1+ _XH-ROOT-ENTRIES @ U< IF
        _XH-LEAF-SECOND-FIRST @
        _XH-ROOT-INDEX @ 1+ _XH-ROOT-ENTRY-AT L@ U< 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _XH-ROOT-ENTRIES @ _XH-SHIFT !
    BEGIN
        _XH-SHIFT @ _XH-ROOT-INDEX @ 1+ U>
    WHILE
        _XH-SHIFT @ 1- _XH-ROOT-ENTRY-AT
        _XH-SHIFT @ _XH-ROOT-ENTRY-AT 12 MOVE
        -1 _XH-SHIFT +!
    REPEAT
    _XH-LEAF-FIRST @
    _XH-ROOT-INDEX @ _XH-ROOT-ENTRY-AT L!
    _XH-ROOT-INDEX @ 1+ _XH-ROOT-ENTRY-AT DUP 12 0 FILL
    DUP _XH-LEAF-SECOND-FIRST @ SWAP L!
    DUP 4 + _XH-LEAF-CANDIDATE @ 0xFFFFFFFF AND SWAP L!
    DUP 8 + _XH-LEAF-CANDIDATE @ 32 RSHIFT 0xFFFF AND SWAP W!
    10 + 0 SWAP W!
    _XH-ROOT-ENTRIES @ 1+ DUP _XH-ROOT-ENTRIES !
    _XH-ROOT @ 2 + W!
    0 ;

: _XH-STAGE-INODE  ( -- ior )
    _XH-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _XH-INODE-HOME @ _XH-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _XH-CTX @ _EXT4-C.BLOCK + _XH-INODE-HOME @
    _XH-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XH-IMAGE !
    _XH-INODE-OFF @ + DUP _XH-RECORD !
    _XH-CTX @ _EXT4-C.INODE +
    _XH-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _XH-CTX @ _EXT4-C.SPB + @
    _XH-NEW-LEAF? IF 2* THEN
    _XH-BLOCKS @ SWAP _EXT4-UADD?
    _XH-IOR ! _XH-NEW-BLOCKS !
    _XH-IOR @ ?DUP IF EXIT THEN
    _XH-NEW-BLOCKS @ _XH-RECORD @ _XH-CTX @
    _EXT4-ENCODE-I-BLOCKS ?DUP IF EXIT THEN
    _XH-TREE-DEPTH @ IF
        _XH-RECORD @ _EXT4-I.BLOCK + _XH-ROOT !
        _XH-LEAF-SPLIT @ IF
            _XH-APPLY-SPLIT-ROOT
        ELSE
            _XH-APPLY-EXISTING-ROOT-KEY
        THEN
    ELSE
        _XH-APPLY-EXTENT-EDIT
    THEN ?DUP IF EXIT THEN
    _XH-GROW @ IF
        _XH-NEW-SIZE @ 0xFFFFFFFF AND
        _XH-RECORD @ _EXT4-I.SIZE-LO + L!
        _XH-NEW-SIZE @ 32 RSHIFT 0xFFFFFFFF AND
        _XH-RECORD @ _EXT4-I.SIZE-HI + L!
    THEN
    _XH-SECONDS @ _XH-NSEC @ _XH-RECORD @
    _XH-CTX @ _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _XH-RECORD @ _XH-INO @ _XH-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XH-IMAGE @ _XH-INODE-HOME @ _XH-WRITER @
    _EXT4-JTX-META-REPLACE ;

\ Stage the common allocation-backed one-block edit.  The selected typed mode
\ is either a complete logical hole inside current EOF or strict no-gap growth
\ from an exactly block-aligned EOF.  Both modes admit an authenticated inline
\ depth-zero extent root or a resident depth-one index fanout.  An insertion
\ selects the governing leaf and uses a free entry or exact coalescing when
\ possible.  A saturated unmergeable resident root allocates a second block,
\ composes all five extents in one checksummed external leaf, and installs a
\ one-index depth-one resident root.  An existing selected leaf is replaced in
\ place; when it is full and unmergeable, it splits into two checksummed leaves
\ and a new adjacent root index is inserted if the root has capacity.  The
\ transaction increments
\ i_blocks for every newly allocated data/tree block.
\ Aligned growth additionally stages its exact new i_size.  Partial-tail RMW,
\ unwritten conversion, and sparse growth remain separate boundaries.
: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALLOCATING-WRITE
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    _XH-WRITER ! _XH-NSEC ! _XH-SECONDS !
    _XH-EXPECTED-GEN ! _XH-INO ! _XH-OFFSET !
    _XH-COUNT ! _XH-SOURCE !
    0 _XH-PUBLISHED !
    _XH-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _XH-WRITER @ _EXT4-JWR.CTX + @ _XH-CTX !
    _XH-WRITER @ _EXT4-JWR.BSIZE + @ _XH-BSIZE !
    _XH-COUNT @ 0> 0= _XH-OFFSET @ 0< OR IF
        VFS-E-INVALID EXIT
    THEN
    _XH-SOURCE @ _XH-COUNT @ _VFS-BUFFER? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _XH-COUNT @ _XH-BSIZE @ U> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XH-SOURCE @ _XH-COUNT @
    _XH-WRITER @ _EXT4-JWR.SCRATCH-B + @ _XH-BSIZE @
    MSPAN-OVERLAP? IF VFS-E-INVALID EXIT THEN
    _XH-REQUIRE-FRESH ?DUP IF EXIT THEN
    _XH-SOURCE @ _XH-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XH-COUNT @ MOVE
    _XH-AUTH-TARGET ?DUP IF EXIT THEN
    _XH-SELECT-CANDIDATE ?DUP IF EXIT THEN
    _XH-PLAN-ROOT-EDIT ?DUP IF EXIT THEN
    _XH-SELECT-LEAF-CANDIDATE ?DUP IF EXIT THEN
    _XH-QUALIFY-PLANNED-HOMES ?DUP IF EXIT THEN
    _XH-REQUIRE-EXACT-CREDIT ?DUP IF EXIT THEN
    _XH-STAGE-DATA ?DUP IF
        _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    _XH-CANDIDATE @ _XH-WRITER @
    _EXT4-JTX-STAGE-ALLOCATE-BLOCK ?DUP IF
        _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    _XH-REQUIRE-STAGED-ACCOUNTING-HOMES ?DUP IF
        _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    _XH-STAGE-EXISTING-LEAF ?DUP IF
        _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    _XH-NEW-LEAF? IF
        _XH-STAGE-LEAF ?DUP IF
            _XH-FAIL-AFTER-PUBLISH EXIT
        THEN
        _XH-LEAF-CANDIDATE @ _XH-WRITER @
        _EXT4-JTX-STAGE-ALLOCATE-BLOCK ?DUP IF
            _XH-FAIL-AFTER-PUBLISH EXIT
        THEN
        _XH-REQUIRE-STAGED-LEAF-ACCOUNTING-HOMES ?DUP IF
            _XH-FAIL-AFTER-PUBLISH EXIT
        THEN
    THEN
    _EXT4-JAB-NEW-SUPER-FREE @ _XH-NEW-FREE !
    _XH-STAGE-INODE ?DUP IF
        _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    _XH-WRITER @ _EXT4-JWR.META-USED + @ _XH-META-CREDIT @ <>
    _XH-WRITER @ _EXT4-JWR.META-ACTIVE + @ _XH-META-CREDIT @ <> OR
    _XH-WRITER @ _EXT4-JWR.DATA-USED + @ 1 <> OR
    _XH-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ 1 <> OR
    _XH-WRITER @ _EXT4-JWR.REVOKE-USED + @ 0<> OR
    _XH-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0<> OR
    _XH-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT _XH-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    0 _XH-GROW !
    _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALLOCATING-WRITE ;

: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALIGNED-APPEND
  ( source count file-offset inode-number expected-generation seconds nsec transaction -- ior )
    -1 _XH-GROW !
    _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALLOCATING-WRITE ;

\ Measure an allocation callback before the mounted engine begins a
\ transaction.  Measurement revalidates the selected geometry needed to
\ derive exact credit, while dry and live staging each perform the expensive
\ global reverse-owner proof before publication.  Repeating that proof during
\ capacity measurement would establish no additional safety property.  The
\ reusable caller profile is only a containing capacity, so a resident
\ depth-zero edit begins 4/1/0, an existing selected depth-one leaf edit begins
\ 5/1/0, root growth begins its exact 5/1/0 through 7/1/0 topology, and a
\ selected-leaf split begins its exact 6/1/0 through 8/1/0 topology.
: _XH-MEASURE-ALLOCATION-CREDIT  ( -- signed-meta-credit ior )
    0 _XH-WRITER !
    _EXT4-MOW-SNAPSHOT _XH-SOURCE !
    _EXT4-MOW-COUNT @ _XH-COUNT !
    _EXT4-MOW-OFFSET @ _XH-OFFSET !
    _EXT4-MOW-INO @ _XH-INO !
    _EXT4-MOW-GEN @ _XH-EXPECTED-GEN !
    _EXT4-MOW-SECONDS @ _XH-SECONDS !
    _EXT4-MOW-NSEC @ _XH-NSEC !
    _EXT4-MOW-CTX @ _XH-CTX !
    _EXT4-MOW-CTX @ _EXT4-C.BSIZE + @ _XH-BSIZE !
    _EXT4-MOW-STAGE-XT @
    ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALIGNED-APPEND = IF
        -1 _XH-GROW !
    ELSE
        _EXT4-MOW-STAGE-XT @
        ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL <> IF
            0 VFS-E-INVALID EXIT
        THEN
        0 _XH-GROW !
    THEN
    _XH-AUTH-TARGET ?DUP IF 0 SWAP EXIT THEN
    _XH-SELECT-CANDIDATE ?DUP IF 0 SWAP EXIT THEN
    _XH-PLAN-ROOT-EDIT ?DUP IF 0 SWAP EXIT THEN
    _XH-SELECT-LEAF-CANDIDATE ?DUP IF 0 SWAP EXIT THEN
    _XH-REVALIDATE-PLANNED-HOMES ?DUP IF 0 SWAP EXIT THEN
    _XH-META-CREDIT @ NEGATE 0 ;

' _XH-MEASURE-ALLOCATION-CREDIT _EXT4-MOW-CREDIT-XT !

CREATE _XB _EXT4-MAX-BLOCK ALLOT

: _XP
  ( source -- source count file-offset inode-number expected-generation seconds nsec vfs )
    _EXT4-WR-CHUNK @ _EXT4-WR-OFFSET @
    _EXT4-WR-BID @ _EXT4-WR-GEN @
    _EXT4-WR-SECONDS @ _EXT4-WR-NSEC @ _EXT4-WR-V @ ;

\ Preserve the public caller chunk.  Each callback's growth kind routes
\ directly to its typed builder: partial-tail append uses initialized RMW,
\ while aligned EOF uses allocation.  Neither callback can fall through to
\ another operation; VFS-WRITE-EXACT may advance after a short committed tail
\ or allocation chunk and re-enter as aligned growth.  An in-size target first
\ tries overwrite, then promotes only its exact clean unmapped refusal to hole
\ fill.
:NONAME  ( -- actual ior )
    _EXT4-WR-SOURCE @ _EXT4-WR-COUNT @
    _XB _EXT4-MAX-BLOCK MSPAN-OVERLAP?
    _EXT4-WR-SOURCE @ _EXT4-WR-COUNT @
    _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK MSPAN-OVERLAP? OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-WR-SOURCE @ _XB _EXT4-WR-CHUNK @ MOVE
    _EXT4-WR-KIND @ _EXT4-WRK-TAIL-APPEND = IF
        _XB _XP
        -1 ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-TAIL-APPEND
        _EXT4-MOUNTED-ONEBLOCK-WRITE
    ELSE _EXT4-WR-KIND @ _EXT4-WRK-ALIGNED-APPEND = IF
        _XB _XP
        0 ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-ALIGNED-APPEND
        _EXT4-MOUNTED-ONEBLOCK-WRITE
        OVER _EXT4-WR-CHUNK @ = IF
            _XH-NEW-BLOCKS @ _EXT4-WR-NEW-BLOCKS !
            _XH-NEW-FREE @ _EXT4-WR-NEW-FREE !
        THEN
    ELSE
        -1 _EXT4-JOW-IOR !
        -1 _EXT4-JOW-PRESENT !
        _XB _XP
        1 ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
        _EXT4-MOUNTED-ONEBLOCK-WRITE
        DUP EXT4-D-DATA-MAP _EXT4-UNSUPPORTED =
        _EXT4-JOW-IOR @ 0= AND _EXT4-JOW-PRESENT @ 0= AND IF
            2DROP
            _EXT4-WRK-HOLE-FILL _EXT4-WR-KIND !
            _XB _XP
            0 ['] _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-HOLE-FILL
            _EXT4-MOUNTED-ONEBLOCK-WRITE
            OVER _EXT4-WR-CHUNK @ = IF
                _XH-NEW-BLOCKS @ _EXT4-WR-NEW-BLOCKS !
                _XH-NEW-FREE @ _EXT4-WR-NEW-FREE !
            THEN
        THEN
    THEN THEN
    _XB _EXT4-MAX-BLOCK 0 FILL
; _EXT4-WR-HOOK !

\ =====================================================================
\  Atomic regular-file creation in one linear directory block
\ =====================================================================
\
\ CREATE is intentionally the next narrow namespace slice.  It allocates an
\ inode from an already initialized inode bitmap and inserts one regular-file
\ dirent into authenticated slack in an existing one-block linear directory.
\ Directory-block allocation, HTree insertion, ACL inheritance, non-root
\ credential policy, and directory growth remain explicit unsupported edges.
\ The admitted edit is nevertheless one complete journal transaction: new and
\ parent inode records, the directory block, inode bitmap, primary descriptor,
\ and primary superblock accounting are committed together.

6 CONSTANT _XC-META-HOME-MAX
CREATE _XC-META-HOMES _XC-META-HOME-MAX CELLS ALLOT
VARIABLE _XC-META-COUNT
VARIABLE _XC-META-HOME

VARIABLE _XC-D
VARIABLE _XC-V
VARIABLE _XC-CTX
VARIABLE _XC-PARENT
VARIABLE _XC-PARENT-VN
VARIABLE _XC-PARENT-INO
VARIABLE _XC-PARENT-PARENT-INO
VARIABLE _XC-PARENT-GEN
VARIABLE _XC-PARENT-GROUP
VARIABLE _XC-PARENT-INDEX
VARIABLE _XC-PARENT-HOME
VARIABLE _XC-PARENT-OFF
VARIABLE _XC-INODE
VARIABLE _XC-NAME
VARIABLE _XC-NLEN
VARIABLE _XC-NEEDED
VARIABLE _XC-MS
VARIABLE _XC-SECONDS
VARIABLE _XC-NSEC
VARIABLE _XC-DIR-HOME
VARIABLE _XC-DIR-PRESENT
VARIABLE _XC-DIR-IOR
VARIABLE _XC-DIR-OFF
VARIABLE _XC-DIR-LIMIT
VARIABLE _XC-DIR-DE
VARIABLE _XC-DIR-REC
VARIABLE _XC-DIR-NAME-LEN
VARIABLE _XC-DIR-INODE
VARIABLE _XC-DIR-USED
VARIABLE _XC-DIR-DOT
VARIABLE _XC-DIR-DOTDOT
VARIABLE _XC-INSERT-KIND
VARIABLE _XC-INSERT-OFF
VARIABLE _XC-INSERT-REC
VARIABLE _XC-INSERT-PREV-OFF
VARIABLE _XC-INSERT-PREV-USED
VARIABLE _XC-INSERT-ALLOC-REC
VARIABLE _XC-INSERT-REMAIN
VARIABLE _XC-DIR-IMAGE
VARIABLE _XC-IOR
VARIABLE _XC-WRITER
VARIABLE _XC-TX
VARIABLE _XC-ACTIVE

CREATE _XC-NAME-SNAPSHOT 256 ALLOT
CREATE _XC-DIR-SNAPSHOT _EXT4-STAGED-WRITE-BLOCK-SIZE ALLOT
CREATE _XC-PARENT-SNAPSHOT _EXT4-STAGED-WRITE-INODE-SIZE ALLOT
CREATE _XC-OLD-INODE _EXT4-STAGED-WRITE-INODE-SIZE ALLOT

: _XC-META-RESET  ( -- )
    0 _XC-META-COUNT !
    _XC-META-HOMES _XC-META-HOME-MAX CELLS 0 FILL ;

: _XC-ADD-META-HOME  ( home -- ior )
    _XC-META-HOME !
    _XC-META-HOME @ _XC-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-META-COUNT @ 0 ?DO
        I CELLS _XC-META-HOMES + @ _XC-META-HOME @ = IF
            0 UNLOOP EXIT
        THEN
    LOOP
    _XC-META-COUNT @ _XC-META-HOME-MAX U< 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-META-HOME @
    _XC-META-COUNT @ CELLS _XC-META-HOMES + !
    1 _XC-META-COUNT +!
    0 ;

VARIABLE _EXT4-RDB-BLOCK
VARIABLE _EXT4-RDB-INO
VARIABLE _EXT4-RDB-GEN
VARIABLE _EXT4-RDB-CTX
VARIABLE _EXT4-RDB-TAIL

: _EXT4-RESTAMP-DIR-BLOCK  ( block dir-inum generation ctx -- ior )
    _EXT4-RDB-CTX ! _EXT4-RDB-GEN ! _EXT4-RDB-INO !
    _EXT4-RDB-BLOCK !
    _EXT4-RDB-BLOCK @ 0= _EXT4-RDB-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-RDB-INO @ 0=
    _EXT4-RDB-INO @ _EXT4-RDB-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDB-BLOCK @ _EXT4-RDB-CTX @ _EXT4-C.BSIZE + @ 12 - +
    DUP _EXT4-RDB-TAIL !
    DUP L@ 0<>
    OVER 4 + W@ 12 <> OR
    OVER 6 + C@ 0<> OR
    OVER 7 + C@ 0xDE <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DROP
    0 _EXT4-RDB-TAIL @ 8 + L!
    _EXT4-RDB-INO @ _EXT4-RDB-CTX @ _EXT4-C.TMP + L!
    _EXT4-RDB-GEN @ _EXT4-RDB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-RDB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RDB-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-RDB-BLOCK @ _EXT4-RDB-CTX @ _EXT4-C.BSIZE + @ 12 -
    _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-RDB-TAIL @ 8 + L!
    0 ;

: _XC-DIRENT-NAME=?  ( dirent -- flag )
    DUP 6 + C@ _XC-NLEN @ <> IF DROP FALSE EXIT THEN
    8 + _XC-NAME-SNAPSHOT _XC-NLEN @ _EXT4-BYTES=? ;

: _XC-DIR-SCAN  ( -- ior )
    0 _XC-DIR-DOT ! 0 _XC-DIR-DOTDOT !
    -1 _XC-INSERT-OFF ! 0 _XC-INSERT-KIND !
    0 _XC-DIR-OFF !
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - _XC-DIR-LIMIT !
    BEGIN _XC-DIR-OFF @ _XC-DIR-LIMIT @ < WHILE
        _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-OFF @ +
        DUP _XC-DIR-DE !
        4 + W@ DUP _XC-DIR-REC !
        DUP 8 U< SWAP 3 AND 0<> OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-OFF @ _XC-DIR-REC @ + _XC-DIR-LIMIT @ > IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ 6 + C@ DUP _XC-DIR-NAME-LEN !
        _XC-DIR-REC @ 8 - U> IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ L@ DUP _XC-DIR-INODE ! IF
            _XC-DIR-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-NAME-LEN @ 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 8 + _XC-DIR-NAME-LEN @
            _EXT4-DIRENT-NAME-VALID? 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 7 + C@ _EXT4-DIRENT>TYPE 0= IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN DROP
            _XC-DIR-NAME-LEN @ 1 =
            _XC-DIR-DE @ 8 + C@ [CHAR] . = AND IF
                _XC-DIR-INODE @ _XC-PARENT-INO @ <>
                _XC-DIR-DOT @ OR IF
                    EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                THEN
                -1 _XC-DIR-DOT !
            ELSE
                _XC-DIR-NAME-LEN @ 2 =
                _XC-DIR-DE @ 8 + C@ [CHAR] . = AND
                _XC-DIR-DE @ 9 + C@ [CHAR] . = AND IF
                    _XC-DIR-INODE @ _XC-PARENT-PARENT-INO @ <>
                    _XC-DIR-DOTDOT @ OR IF
                        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN
                    -1 _XC-DIR-DOTDOT !
                ELSE
                    _XC-DIR-DE @ _XC-DIRENT-NAME=? IF
                        VFS-E-EXISTS EXIT
                    THEN
                THEN
            THEN
            _XC-DIR-NAME-LEN @ 8 + 3 + -4 AND
            DUP _XC-DIR-USED !
            _XC-DIR-REC @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-INSERT-OFF @ -1 = IF
                _XC-DIR-REC @ _XC-DIR-USED @ -
                _XC-NEEDED @ U< 0= IF
                    1 _XC-INSERT-KIND !
                    _XC-DIR-OFF @ _XC-INSERT-PREV-OFF !
                    _XC-DIR-USED @ _XC-INSERT-PREV-USED !
                    _XC-DIR-OFF @ _XC-DIR-USED @ +
                    _XC-INSERT-OFF !
                    _XC-DIR-REC @ _XC-DIR-USED @ -
                    _XC-INSERT-REC !
                THEN
            THEN
        ELSE
            _XC-DIR-NAME-LEN @
            _XC-DIR-DE @ 7 + C@ OR IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-INSERT-OFF @ -1 =
            _XC-DIR-REC @ _XC-NEEDED @ U< 0= AND IF
                2 _XC-INSERT-KIND !
                _XC-DIR-OFF @ _XC-INSERT-OFF !
                _XC-DIR-REC @ _XC-INSERT-REC !
            THEN
        THEN
        _XC-DIR-REC @ _XC-DIR-OFF +!
    REPEAT
    _XC-DIR-OFF @ _XC-DIR-LIMIT @ <>
    _XC-DIR-DOT @ 0= OR _XC-DIR-DOTDOT @ 0= OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _XC-INSERT-OFF @ -1 = IF VFS-E-NOSPC EXIT THEN
    0 ;

: _XC-DIR-APPLY  ( image -- ior )
    DUP _XC-DIR-IMAGE ! 0= IF VFS-E-INVALID EXIT THEN
    _XC-INSERT-KIND @ 1 = IF
        _XC-INSERT-PREV-USED @
        _XC-DIR-IMAGE @ _XC-INSERT-PREV-OFF @ + 4 + W!
        _XC-INSERT-REC @ _XC-INSERT-ALLOC-REC !
    ELSE
        _XC-INSERT-KIND @ 2 <> IF VFS-E-CORRUPT EXIT THEN
        _XC-INSERT-REC @ _XC-NEEDED @ - DUP _XC-INSERT-REMAIN !
        8 U< IF
            _XC-INSERT-REC @ _XC-INSERT-ALLOC-REC !
        ELSE
            _XC-NEEDED @ _XC-INSERT-ALLOC-REC !
            _XC-DIR-IMAGE @ _XC-INSERT-OFF @ + _XC-NEEDED @ +
            DUP _XC-INSERT-REMAIN @ 0 FILL
            _XC-INSERT-REMAIN @ SWAP 4 + W!
        THEN
    THEN
    _XC-DIR-IMAGE @ _XC-INSERT-OFF @ + DUP
    _XC-INSERT-ALLOC-REC @ 0 FILL
    _XC-INODE @ OVER L!
    _XC-INSERT-ALLOC-REC @ OVER 4 + W!
    _XC-NLEN @ OVER 6 + C!
    1 OVER 7 + C!
    _XC-NAME-SNAPSHOT OVER 8 + _XC-NLEN @ CMOVE
    DROP
    _XC-DIR-IMAGE @ _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-RESTAMP-DIR-BLOCK ;

VARIABLE _XC-FI-GROUP
VARIABLE _XC-FI-VISITED
VARIABLE _XC-FI-SAW-UNINIT
VARIABLE _XC-GROUP-INODES
VARIABLE _XC-GROUP-BASE
VARIABLE _XC-GROUP-FREE
VARIABLE _XC-GROUP-NEW-FREE
VARIABLE _XC-GROUP-UNUSED
VARIABLE _XC-GROUP-NEW-UNUSED
VARIABLE _XC-GROUP-HIGH-WATER
VARIABLE _XC-BITMAP-HOME
VARIABLE _XC-BITMAP-CRC
VARIABLE _XC-BITMAP-NEW-CRC
VARIABLE _XC-GDT-HOME
VARIABLE _XC-GDT-OFF
VARIABLE _XC-INODE-TABLE
VARIABLE _XC-INODE-HOME
VARIABLE _XC-INODE-OFF
VARIABLE _XC-NEW-GEN
VARIABLE _XC-CLEAR-COUNT
VARIABLE _XC-FIRST-CLEAR
VARIABLE _XC-SUPER-HOME
VARIABLE _XC-SUPER-NEW-FREE
VARIABLE _XC-DESC
VARIABLE _XC-IMAGE

: _XC-DESC-ITABLE-UNUSED@  ( descriptor -- inodes )
    DUP _EXT4-GD.ITABLE-UNUSED-LO + W@
    SWAP _EXT4-GD.ITABLE-UNUSED-HI + W@ 16 LSHIFT OR ;

: _XC-DESC-ITABLE-UNUSED!  ( inodes descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.ITABLE-UNUSED-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.ITABLE-UNUSED-HI + W! ;

: _XC-FI-ADVANCE  ( -- )
    1 _XC-FI-GROUP +!
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-C.GROUPS + @ = IF
        0 _XC-FI-GROUP !
    THEN
    1 _XC-FI-VISITED +! ;

: _XC-FI-CAPTURE-RECORD  ( -- ior )
    _XC-INODE @ _XC-CTX @ _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-FI-GROUP @ <>
    _EXT4-IR-INDEX @ _XC-FIRST-CLEAR @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-FIRST-CLEAR @ _XC-CTX @ _EXT4-C.ISIZE + @ _EXT4-UMUL?
    _XC-IOR ! DUP
    _XC-CTX @ _EXT4-C.BSIZE + @ / _XC-INODE-TABLE @ +
    _XC-INODE-HOME !
    _XC-IOR @ ?DUP IF NIP EXIT THEN
    _XC-CTX @ _EXT4-C.BSIZE + @ MOD _XC-INODE-OFF !
    _XC-INODE-OFF @ _XC-CTX @ _EXT4-C.ISIZE + @ +
    _XC-CTX @ _EXT4-C.BSIZE + @ U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-INODE-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-OFF @ +
    DUP _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-I.GENERATION + L@
    1+ 0xFFFFFFFF AND DUP 0= IF DROP 1 THEN _XC-NEW-GEN !
    0 ;

: _XC-FI-SCAN-GROUP  ( -- found? ior )
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-GROUP-INODE-COUNT
    _XC-IOR ! _XC-GROUP-INODES !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-DESC ?DUP IF
        FALSE SWAP EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF
        -1 _XC-FI-SAW-UNINIT ! FALSE 0 EXIT
    THEN
    _XC-CTX @ _EXT4-C.DESC + DUP
    _EXT4-JFI-DESC-FREE@ DUP _XC-GROUP-FREE !
    _XC-GROUP-INODES @ U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _XC-DESC-ITABLE-UNUSED@ DUP _XC-GROUP-UNUSED !
    _XC-GROUP-INODES @ U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DROP
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    _XC-IOR ! _XC-GROUP-BASE !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR ! _XC-BITMAP-HOME !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-GD-BLOCK @ _XC-GDT-HOME !
    _EXT4-GD-OFF @ _XC-GDT-OFF !
    _XC-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE !
    _XC-CTX @ _EXT4-C.BLOCK + _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    _XC-IOR ! _XC-BITMAP-CRC !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    0 _XC-CLEAR-COUNT ! -1 _XC-FIRST-CLEAR !
    _XC-GROUP-INODES @ 0 ?DO
        _XC-CTX @ _EXT4-C.BLOCK + I 1 _EXT4-BIT-RANGE-CLEAR? IF
            1 _XC-CLEAR-COUNT +!
            _XC-FIRST-CLEAR @ -1 = IF
                _XC-GROUP-BASE @ I + 1+
                _XC-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0= IF
                    I _XC-FIRST-CLEAR !
                THEN
            THEN
        THEN
    LOOP
    _XC-CLEAR-COUNT @ _XC-GROUP-FREE @ <> IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-FIRST-CLEAR @ -1 = IF FALSE 0 EXIT THEN
    _XC-BITMAP-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR !
    _XC-IOR @ IF DROP FALSE _XC-IOR @ EXIT THEN
    _XC-BITMAP-HOME @ <>
    _EXT4-GD-BLOCK @ _XC-GDT-HOME @ <> OR
    _EXT4-GD-OFF @ _XC-GDT-OFF @ <> OR
    _XC-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE @ <> OR IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-FIRST-CLEAR @ 1
    _EXT4-BIT-RANGE-CLEAR? 0= IF
        FALSE VFS-E-CONFLICT EXIT
    THEN
    _XC-GROUP-FREE @ 0= IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-GROUP-FREE @ 1- _XC-GROUP-NEW-FREE !
    _XC-GROUP-INODES @ _XC-GROUP-UNUSED @ -
    _XC-GROUP-HIGH-WATER !
    _XC-FIRST-CLEAR @ _XC-GROUP-HIGH-WATER @ U< IF
        _XC-GROUP-UNUSED @
    ELSE
        _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ 1+ -
    THEN _XC-GROUP-NEW-UNUSED !
    _XC-GROUP-BASE @ _XC-FIRST-CLEAR @ + 1+ DUP _XC-INODE !
    _XC-CTX @ _EXT4-C.INODES + @ U> IF
        FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-FI-CAPTURE-RECORD ?DUP IF FALSE SWAP EXIT THEN
    TRUE 0 ;

: _XC-FIND-FREE-INODE  ( -- ior )
    _XC-CTX @ _EXT4-C.FREE-INODES + @ 0= IF VFS-E-NOSPC EXIT THEN
    _XC-PARENT-GROUP @ _XC-FI-GROUP !
    0 _XC-FI-VISITED ! 0 _XC-FI-SAW-UNINIT !
    BEGIN
        _XC-FI-VISITED @ _XC-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _XC-FI-SCAN-GROUP _XC-IOR ! IF
            _XC-IOR @ EXIT
        THEN
        _XC-IOR @ ?DUP IF EXIT THEN
        _XC-FI-ADVANCE
    REPEAT
    _XC-FI-SAW-UNINIT @ IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    EXT4-D-GEOMETRY _EXT4-CORRUPT ;

: _XC-PARENT-CACHE-MATCH?  ( -- flag )
    _XC-CTX @ _EXT4-C.R.GEN + @ _XC-PARENT-VN @ VN.GEN @ =
    _XC-CTX @ _EXT4-C.R.SIZE + @ _XC-PARENT-VN @ VN.SIZE-LO @ = AND
    _XC-PARENT-VN @ VN.SIZE-HI @ 0= AND
    _XC-CTX @ _EXT4-C.R.MODE + @ _XC-PARENT-VN @ VN.MODE @ = AND
    _XC-CTX @ _EXT4-C.R.UID + @ _XC-PARENT-VN @ VN.UID @ = AND
    _XC-CTX @ _EXT4-C.R.GID + @ _XC-PARENT-VN @ VN.GID @ = AND
    _XC-CTX @ _EXT4-C.R.NLINK + @ _XC-PARENT-VN @ VN.NLINK @ = AND
    _XC-CTX @ _EXT4-C.R.BLOCKS + @ _XC-PARENT-VN @ VN.BLOCKS @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME + @ _XC-PARENT-VN @ VN.MTIME @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME-NS + @
        _XC-PARENT-VN @ VN.MTIME-NS @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME + @ _XC-PARENT-VN @ VN.CTIME @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME-NS + @
        _XC-PARENT-VN @ VN.CTIME-NS @ = AND ;

: _XC-LOAD-PARENT  ( -- ior )
    _XC-PARENT-INO @ _XC-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-PARENT-GROUP !
    _EXT4-IR-INDEX @ _XC-PARENT-INDEX !
    _EXT4-IR-BLOCK @ _XC-PARENT-HOME !
    _EXT4-IR-OFF @ _XC-PARENT-OFF !
    _XC-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XC-IOR ! DUP VFS-T-DIR <> IF
        DROP _XC-IOR @ ?DUP IF EXIT THEN VFS-E-NOTDIR EXIT
    THEN DROP
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-PARENT-CACHE-MATCH? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.R.UID + @
    _XC-CTX @ _EXT4-C.R.GID + @ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.R.MODE + @ 0x0800 AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.R.SIZE + @
    _XC-CTX @ _EXT4-C.BSIZE + @ <> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.R.BLOCKS + @
    _XC-CTX @ _EXT4-C.SPB + @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FLAGS + L@
    _EXT4-EXTENTS-FL <> IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-LO + L@
    OVER _EXT4-I.FILE-ACL-HI + W@ OR IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.EXTRA-SIZE + W@ 32 <> IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.PROJECT-ID + L@ IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    160 + _XC-CTX @ _EXT4-C.ISIZE + @ 160 -
    _EXT4-BYTES-ZERO? 0= IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    0 _XC-CTX @ _EXT4-MAP-BLOCK
    _XC-DIR-IOR ! _XC-DIR-PRESENT !
    _XC-DIR-IOR @ ?DUP IF NIP EXIT THEN
    _XC-DIR-PRESENT @ 0= IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _XC-DIR-HOME @ IF
        DUP _XC-DIR-HOME @ <> IF
            DROP VFS-E-CONFLICT EXIT
        THEN DROP
    ELSE
        _XC-DIR-HOME !
    THEN
    _XC-PARENT-HOME @ _XC-PARENT-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.INODE + _XC-PARENT-SNAPSHOT
    _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    0 ;

: _XC-AUTH-PARENT-DIRECTORY  ( -- ior )
    0 _XC-DIR-HOME !
    _XC-LOAD-PARENT ?DUP IF EXIT THEN
    _XC-DIR-HOME @ 1 _XC-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _XC-PARENT-INO @ _XC-DIR-HOME @ 1 _XC-CTX @
    _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER ?DUP IF EXIT THEN
    _XC-LOAD-PARENT ?DUP IF EXIT THEN
    _XC-DIR-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-CTX @ _EXT4-C.DIR-BLOCK +
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    _XC-DIR-SCAN ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-SNAPSHOT
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 ;

: _XC-PLAN  ( -- ior )
    _XC-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.SB + DUP _EXT4-SB.MIN-EXTRA + W@ 32 <>
    SWAP _EXT4-SB.WANT-EXTRA + W@ 32 <> OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-AUTH-PARENT-DIRECTORY ?DUP IF EXIT THEN
    _XC-FIND-FREE-INODE ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES ?DUP IF EXIT THEN
    _XC-META-RESET
    _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP _XC-SUPER-HOME !
    _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-GDT-HOME @ _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-BITMAP-HOME @ _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-PARENT-HOME @ _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-DIR-HOME @ _XC-ADD-META-HOME ?DUP IF EXIT THEN
    _XC-META-COUNT @ 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _XC-NEW-INODE-PTR

: _XC-SET-NEW-INODE-TIMES  ( inode -- ior )
    DUP _XC-NEW-INODE-PTR !
    _XC-SECONDS @ _XC-NSEC @ ROT _XC-CTX @
    _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _EXT4-I.CTIME + L@
    DUP _XC-NEW-INODE-PTR @ _EXT4-I.ATIME + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CRTIME + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CTIME-EXTRA + L@
    DUP _XC-NEW-INODE-PTR @ _EXT4-I.ATIME-EXTRA + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CRTIME-EXTRA + L!
    0 ;

: _XC-BUILD-NEW-INODE  ( inode -- ior )
    DUP _XC-NEW-INODE-PTR !
    _XC-CTX @ _EXT4-C.ISIZE + @ 0 FILL
    0x81B6 _XC-NEW-INODE-PTR @ _EXT4-I.MODE + W!
    1 _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W!
    _EXT4-EXTENTS-FL _XC-NEW-INODE-PTR @ _EXT4-I.FLAGS + L!
    _XC-NEW-GEN @ _XC-NEW-INODE-PTR @ _EXT4-I.GENERATION + L!
    32 _XC-NEW-INODE-PTR @ _EXT4-I.EXTRA-SIZE + W!
    0xF30A _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK + W!
    0 _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK 2 + + W!
    4 _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK 4 + + W!
    0 _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK 6 + + W!
    0 _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK 8 + + L!
    _XC-NEW-INODE-PTR @ _XC-SET-NEW-INODE-TIMES ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-INODE @ _XC-CTX @ _EXT4-RESTAMP-INODE ;

: _XC-STAGE-NEW-INODE  ( -- ior )
    _XC-INODE-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-OFF @ +
    _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    _XC-INODE-OFF @ + DUP
    _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF DROP VFS-E-CONFLICT EXIT THEN
    _XC-BUILD-NEW-INODE ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-INODE-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _XC-STAGE-PARENT-INODE  ( -- ior )
    _XC-PARENT-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-PARENT-OFF @ +
    _XC-PARENT-SNAPSHOT _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-PARENT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    _XC-PARENT-OFF @ + DUP
    _XC-PARENT-SNAPSHOT _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF DROP VFS-E-CONFLICT EXIT THEN
    DUP _XC-NEW-INODE-PTR !
    _XC-SECONDS @ _XC-NSEC @ ROT _XC-CTX @
    _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-PARENT-INO @ _XC-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-PARENT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _XC-STAGE-DIRECTORY  ( -- ior )
    _XC-DIR-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-DIR-SNAPSHOT
    _XC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-DIR-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    DUP _XC-DIR-SNAPSHOT _XC-CTX @ _EXT4-C.BSIZE + @
    _EXT4-BYTES=? 0= IF DROP VFS-E-CONFLICT EXIT THEN
    _XC-DIR-APPLY ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-DIR-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _XC-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _XC-DESC @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _XC-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _XC-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _XC-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-JFI-DESC-FREE@ _XC-GROUP-FREE @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-DESC @ _XC-DESC-ITABLE-UNUSED@
    _XC-GROUP-UNUSED @ <> IF VFS-E-CONFLICT EXIT THEN
    0 ;

: _XC-STAGE-INODE-ALLOCATION  ( -- ior )
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR !
    _XC-IOR @ IF DROP _XC-IOR @ EXIT THEN
    _XC-BITMAP-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-FIRST-CLEAR @ 1
    _EXT4-BIT-RANGE-CLEAR? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _XC-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-BITMAP-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    DUP _XC-FIRST-CLEAR @ 1 _EXT4-BIT-RANGE-CLEAR? 0= IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _XC-BITMAP-CRC @ <> IF DROP VFS-E-CONFLICT EXIT THEN
    DROP
    _XC-IMAGE @ _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-FIRST-CLEAR @ 1 _EXT4-SET-BIT-RANGE
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    _XC-IOR ! _XC-BITMAP-NEW-CRC !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XC-GDT-HOME @ <>
    _EXT4-GD-OFF @ _XC-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-GDT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    _XC-GDT-OFF @ + DUP _XC-DESC ! DROP
    _XC-VALIDATE-EFFECTIVE-DESC ?DUP IF EXIT THEN
    _XC-GROUP-NEW-FREE @ _XC-DESC @ _EXT4-JFI-DESC-FREE!
    _XC-GROUP-NEW-UNUSED @ _XC-DESC @ _XC-DESC-ITABLE-UNUSED!
    _XC-BITMAP-NEW-CRC @ _XC-DESC @ _EXT4-JFI-DESC-BITMAP-CRC!
    _XC-DESC @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-GDT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-BITMAP-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

: _XC-STAGE-SUPER  ( -- ior )
    _XC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _XC-SUPER-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.FREE-INODES + L@
    DUP _XC-CTX @ _EXT4-C.FREE-INODES + @ <> IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP 0= IF DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    1- DUP _XC-SUPER-NEW-FREE !
    _EXT4-JPS-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JPS-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JPS-IMAGE @ _XC-SUPER-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _EXT4-JTX-STAGE-CREATE-REGULAR  ( transaction -- ior )
    DUP _XC-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.CTX + @ DUP _XC-CTX @ <> IF
        DROP VFS-E-INVALID EXIT
    THEN DROP
    _XC-PLAN ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.META-CREDIT + @ _XC-META-COUNT @ <>
    _XC-WRITER @ _EXT4-JWR.DATA-CREDIT + @ 0<> OR
    _XC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ 0<> OR IF
        VFS-E-INVALID EXIT
    THEN
    _XC-STAGE-NEW-INODE ?DUP IF EXIT THEN
    _XC-STAGE-PARENT-INODE ?DUP IF EXIT THEN
    _XC-STAGE-DIRECTORY ?DUP IF EXIT THEN
    _XC-STAGE-INODE-ALLOCATION ?DUP IF EXIT THEN
    _XC-STAGE-SUPER ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.META-USED + @ _XC-META-COUNT @ <>
    _XC-WRITER @ _EXT4-JWR.META-ACTIVE + @ _XC-META-COUNT @ <> OR
    _XC-WRITER @ _EXT4-JWR.DATA-USED + @ 0<> OR
    _XC-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ 0<> OR
    _XC-WRITER @ _EXT4-JWR.REVOKE-USED + @ 0<> OR
    _XC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0<> OR
    _XC-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _XC-VN

: _XC-SCRUB  ( -- )
    _XC-NAME-SNAPSHOT 256 0 FILL
    _XC-DIR-SNAPSHOT _EXT4-STAGED-WRITE-BLOCK-SIZE 0 FILL
    _XC-PARENT-SNAPSHOT _EXT4-STAGED-WRITE-INODE-SIZE 0 FILL
    _XC-OLD-INODE _EXT4-STAGED-WRITE-INODE-SIZE 0 FILL ;

: _XC-ENTRY  ( -- ior )
    _XC-D @ 0= _XC-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _XC-V @ _EXT4-MOW-V !
    _EXT4-MOW-ENTRY ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _XC-CTX !
    _EXT4-MOW-ACTIVE @ _XC-ACTIVE !
    _XC-D @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XC-D @ D.VNODE @ DUP _XC-VN ! 0= IF VFS-E-STALE EXIT THEN
    _XC-VN @ VN.TYPE @ VFS-T-FILE <> IF VFS-E-INVALID EXIT THEN
    _XC-VN @ VN.BID @ _XC-VN @ VN.GEN @ OR
    _XC-VN @ VN.BLOCKS @ OR
    _XC-VN @ VN.SIZE-LO @ OR _XC-VN @ VN.SIZE-HI @ OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-VN @ VN.NLINK @ 1 <> IF VFS-E-CONFLICT EXIT THEN
    _XC-D @ IN.PARENT @ DUP _XC-PARENT ! 0= IF VFS-E-INVALID EXIT THEN
    _XC-PARENT @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ _XC-V @ V.CWD @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-PARENT @ D.VNODE @ DUP _XC-PARENT-VN ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-PARENT-VN @ VN.TYPE @ VFS-T-DIR <> IF VFS-E-NOTDIR EXIT THEN
    _XC-PARENT-VN @ VN.BID @ DUP _XC-PARENT-INO ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-PARENT-INO @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-PARENT-VN @ VN.GEN @ DUP _XC-PARENT-GEN !
    0xFFFFFFFF U> IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ IN.PARENT @ ?DUP IF
        IN.BID @
    ELSE
        _XC-PARENT-INO @
    THEN DUP _XC-PARENT-PARENT-INO ! 0= IF VFS-E-STALE EXIT THEN
    _XC-D @ D.NAME @ _VFS-STR-GET _XC-NLEN ! _XC-NAME !
    _XC-NAME @ _XC-NLEN @ _VFS-VALID-NAME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _XC-NLEN @ 8 + 3 + -4 AND DUP _XC-NEEDED !
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - U> IF
        VFS-E-NAMETOOLONG EXIT
    THEN
    _XC-NAME @ _XC-NAME-SNAPSHOT _XC-NLEN @ CMOVE
    _XC-CTX @ _EXT4-C.WCLOCK-XT + @ 0= IF VFS-E-UNSUPPORTED EXIT THEN
    _XC-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-NOSPC EXIT THEN
    _XC-CTX @ _EXT4-C.J.WRITER-ARENA + @ 0=
    _XC-CTX @ _EXT4-C.J.WRITER + @ 0= OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _XC-NOW  ( -- ior )
    _XC-CTX @ _EXT4-C.WCLOCK-CTX + @
    _XC-CTX @ _EXT4-C.WCLOCK-XT + @ EXECUTE
    _XC-IOR ! _XC-MS !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-MS @ 0< IF VFS-E-INVALID EXIT THEN
    _XC-MS @ _EXT4-WRITE-EPOCH-MS-MAX U> IF VFS-E-OVERFLOW EXIT THEN
    _XC-MS @ 1000 /MOD
    _XC-SECONDS ! 1000000 * _XC-NSEC !
    0 ;

: _XC-FAIL  ( ior -- ior )
    _XC-IOR !
    _XC-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF
                _XC-WRITER @ _EXT4-JWR-LATCH-FAULT _XC-IOR !
            THEN
        ELSE
            DUP _EXT4-JWR.STATE + @ _EXT4-JWR-COMMITTED = IF
                DROP
                _EXT4-JWP-CHECKPOINT-PREFLIGHT
                _XC-WRITER @ _EXT4-JWR.PHASE + !
                _XC-IOR @ _XC-WRITER @ _EXT4-JWR-LATCH-FAULT
                _XC-IOR !
            ELSE
                DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
                    _EXT4-JWR.FAULT + @ ?DUP IF _XC-IOR ! THEN
                ELSE
                    DROP
                THEN
            THEN
        THEN
    THEN
    _XC-SCRUB
    _XC-IOR @ ;

: _XC-PUBLISH-COMMITTED  ( -- )
    VFS-T-FILE _XC-VN @ VN.TYPE !
    0x81B6 _XC-VN @ VN.MODE !
    0 _XC-VN @ VN.SIZE-LO ! 0 _XC-VN @ VN.SIZE-HI !
    0 _XC-VN @ VN.UID ! 0 _XC-VN @ VN.GID !
    1 _XC-VN @ VN.NLINK !
    _XC-INODE @ DUP _XC-VN @ VN.BID !
    _XC-VN @ VN.BDATA !
    0 _XC-VN @ VN.BDATA 8 + !
    _XC-NEW-GEN @ _XC-VN @ VN.GEN !
    0 _XC-VN @ VN.BLOCKS !
    _XC-SECONDS @ _XC-VN @ VN.ATIME !
    _XC-NSEC @ _XC-VN @ VN.ATIME-NS !
    _XC-SECONDS @ _XC-VN @ VN.MTIME !
    _XC-NSEC @ _XC-VN @ VN.MTIME-NS !
    _XC-SECONDS @ _XC-VN @ VN.CTIME !
    _XC-NSEC @ _XC-VN @ VN.CTIME-NS !
    _XC-SECONDS @ _XC-PARENT-VN @ VN.MTIME !
    _XC-NSEC @ _XC-PARENT-VN @ VN.MTIME-NS !
    _XC-SECONDS @ _XC-PARENT-VN @ VN.CTIME !
    _XC-NSEC @ _XC-PARENT-VN @ VN.CTIME-NS !
    _XC-SUPER-NEW-FREE @ _XC-CTX @ _EXT4-C.FREE-INODES + !
    VFS-F-DIRTY _XC-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

: _XC-POSTCOMMIT-FAIL  ( ior -- ior )
    DUP _XC-V @ V.LAST-IOR !
    _XC-FAIL DROP
    0 ;

: _EXT4-CREATE  ( dentry vfs -- ior )
    _XC-V ! _XC-D !
    0 _XC-WRITER ! 0 _XC-TX !
    _XC-ENTRY ?DUP IF _XC-SCRUB EXIT THEN
    _XC-NOW ?DUP IF _XC-SCRUB EXIT THEN
    _XC-PLAN ?DUP IF _XC-SCRUB EXIT THEN
    _XC-META-COUNT @ 0 0 _XC-CTX @ _EXT4-JTX-PREFLIGHT-CAPACITY
    ?DUP IF _XC-SCRUB EXIT THEN
    _XC-META-COUNT @ 0 0 _XC-CTX @ _EXT4-JWR-ENSURE
    DUP IF NIP _XC-FAIL EXIT THEN
    DROP _XC-WRITER !
    _XC-ACTIVE @ 0= IF
        _XC-META-COUNT @ 0 0 _XC-WRITER @ _EXT4-JTX-BEGIN
        DUP IF NIP _XC-FAIL EXIT THEN
        DROP _XC-TX !
        _XC-TX @ _EXT4-JTX-STAGE-CREATE-REGULAR
        ?DUP IF _XC-FAIL EXIT THEN
        _XC-TX @ _EXT4-JTX-ABORT ?DUP IF _XC-FAIL EXIT THEN
        _XC-WRITER @ _EXT4-JWR-ACTIVATE ?DUP IF _XC-FAIL EXIT THEN
    THEN
    _XC-META-COUNT @ 0 0 _XC-WRITER @ _EXT4-JTX-BEGIN
    DUP IF NIP _XC-FAIL EXIT THEN
    DROP _XC-TX !
    _XC-TX @ _EXT4-JTX-STAGE-CREATE-REGULAR
    ?DUP IF _XC-FAIL EXIT THEN
    _XC-TX @ _EXT4-JTX-EMIT ?DUP IF _XC-FAIL EXIT THEN
    _XC-PUBLISH-COMMITTED
    _XC-TX @ _EXT4-JTX-CHECKPOINT
    ?DUP IF _XC-POSTCOMMIT-FAIL EXIT THEN
    _XC-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _XC-POSTCOMMIT-FAIL EXIT
    THEN
    _XC-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
    _XC-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
        VFS-E-CORRUPT _XC-POSTCOMMIT-FAIL EXIT
    THEN
    0 _XC-V @ V.LAST-IOR !
    _XC-SCRUB
    0 ;

' _EXT4-CREATE EXT4-STAGED-WRITE-OPS VFS-OP-CREATE CELLS + !
